def _iso_timestamp(value: float) -> str:
    return (
        datetime.fromtimestamp(value, tz=timezone.utc)
        .isoformat(timespec="milliseconds")
        .replace("+00:00", "Z")
    )


def _same_workspace(candidate: str, workspace: Path) -> bool:
    try:
        return Path(candidate).expanduser().resolve() == workspace
    except (OSError, RuntimeError, ValueError):
        return False


_TURN_MESSAGE_ID_FIELD = "_conversation_turn_id"


def _turn_result(
    messages: object,
    *,
    turn_id: str,
) -> tuple[str, int, int] | None:
    """Project only the result produced after this turn's user message.

    A committed Workflow intentionally ends with an authoritative
    ``tool_result`` rather than a closing assistant message.  That result is
    valid only when it is paired with the immediately preceding
    ``assistant_tool_call``; this prevents an unrelated historical tool output
    from becoming the current turn's answer.
    """
    if not isinstance(messages, list):
        return None

    user_indexes = [
        index
        for index, message in enumerate(messages)
        if isinstance(message, dict)
        and message.get("role") == "user"
        and message.get(_TURN_MESSAGE_ID_FIELD) == turn_id
    ]
    if len(user_indexes) != 1:
        return None
    user_index = user_indexes[0]

    for index in range(len(messages) - 1, user_index, -1):
        message = messages[index]
        if not isinstance(message, dict):
            continue
        content = message.get("content")
        if message.get("role") == "assistant":
            if isinstance(content, str) and content:
                return content, user_index, index
            continue
        if message.get("role") != "tool_result":
            continue
        if not isinstance(content, str) or not content:
            continue
        if index <= user_index:
            continue
        previous = messages[index - 1]
        if not isinstance(previous, dict):
            continue
        if (
            previous.get("role") == "assistant_tool_call"
            and message.get("toolUseId")
            and previous.get("toolUseId") == message.get("toolUseId")
        ):
            return content, user_index, index
    return None


def _error_for_code(code: str | None) -> ConversationError:
    errors: dict[str, type[ConversationError]] = {
        "session_not_found": ConversationSessionNotFound,
        "session_conflict": ConversationSessionConflict,
        "session_busy": ConversationSessionBusy,
        "runtime_unavailable": ConversationRuntimeUnavailable,
        "turn_failed": ConversationTurnFailed,
        "turn_interrupted": ConversationTurnInterrupted,
        "turn_cancelled": ConversationTurnCancelled,
    }
    return errors.get(code or "", ConversationTurnFailed)()


def _apply_run_outcome_memory_feedback(
    workspace: Path,
    journal: Any,
    run_id: str,
    signal: str,
) -> None:
    """Best-effort weak response feedback for exact rendered versions.

    The Dashboard signal evaluates the whole response, not an individual
    Memory claim. It can therefore update ordinary usefulness evidence but
    can never corroborate or quarantine every rendered entry. Legacy ID-only
    Runs fail closed because they cannot prove which content was evaluated.
    """
    try:
        rendered_versions = journal.get_rendered_memory_versions(run_id)
    except Exception:  # noqa: BLE001 - response attribution is optional
        return
    if not rendered_versions:
        return
    try:
        from minicode.memory import MemoryManager

        manager = MemoryManager(project_root=workspace)
        manager.record_feedback(
            list(dict.fromkeys(entry_id for entry_id, _ in rendered_versions)),
            signal == "accept",
            observation_id=run_id,
            source="explicit_run_outcome",
            expected_versions=rendered_versions,
        )
    except Exception:  # noqa: BLE001 - attribution must not fail feedback
        pass


def _apply_written_run_outcome_feedback(
    workspace: Path,
    journal: Any,
    run_id: str,
    signal: str,
) -> None:
    """Best-effort weak response feedback for exact written versions.

    A response-level signal does not prove that every lesson extracted from
    that response is true or false. Version-bound ordinary evidence is the
    strongest safe attribution until a concrete claim is shown to, and
    explicitly judged by, the user.
    """
    try:
        written_versions = journal.get_written_memory_versions(run_id)
    except Exception:  # noqa: BLE001 - the verdict is optional
        return
    if not written_versions:
        return
    try:
        from minicode.memory import MemoryManager

        manager = MemoryManager(project_root=workspace)
        manager.record_feedback(
            list(dict.fromkeys(entry_id for entry_id, _ in written_versions)),
            signal == "accept",
            observation_id=run_id,
            source="explicit_run_outcome",
            expected_versions=written_versions,
        )
    except Exception:  # noqa: BLE001 - the verdict must not fail feedback
        pass


class ConversationTurnService:
    """Execute and durably commit one synchronous Dashboard conversation turn."""

    def __init__(
        self,
        workspace: str | Path,
        *,
        runtime_factory: RuntimeFactory = create_agent_turn_runtime,
        session_loader: Callable[[str], SessionData | None] = load_session,
        session_creator: Callable[[str], SessionData] = create_new_session,
        session_saver: Callable[[SessionData], None] = save_session,
        journal_factory: JournalFactory | None = None,
        observation_enabled: bool = True,
        mcp_current_state_registry: McpCurrentStateRegistry | None = None,
        turn_store: ConversationTurnStore | None = None,
        approval_broker: PermissionApprovalBroker | None = None,
    ) -> None:
        self.workspace = Path(workspace).expanduser().resolve()
        self._runtime_factory = runtime_factory
        self._session_loader = session_loader
        self._session_creator = session_creator
        self._session_saver = session_saver
        self._journal_factory = journal_factory
        self._observation_enabled = observation_enabled
        self._mcp_current_state_registry = mcp_current_state_registry
        self._approval_broker = approval_broker
        self._turn_store = turn_store or ConversationTurnStore(
            self.workspace,
            data_dir=session_module.MINI_CODE_DIR,
        )

    def _session(self, session_id: str | None) -> tuple[SessionData, bool]:
        if session_id is None:
            return self._session_creator(str(self.workspace)), True
        session = self._session_loader(session_id)
        if session is None or not _same_workspace(session.workspace, self.workspace):
            raise ConversationSessionNotFound()
        return session, False

    @staticmethod
    def _sync_session(
        session: SessionData,
        *,
        messages: list[dict[str, Any]],
        user_message: str,
        runtime: Any,
    ) -> None:
        # Runtime-only turn identity lets the transaction relocate the current
        # user after compaction/reordering.  It must never become part of the
        # persisted or externally rendered message schema.
        session.messages = [
            {
                key: value
                for key, value in message.items()
                if key != _TURN_MESSAGE_ID_FIELD
            }
            for message in messages
        ]
        session.history = [*session.history, user_message]
        session.permissions_summary = runtime.permissions.get_summary()
        session.skills = runtime.tools.get_skills()
        session.mcp_servers = runtime.tools.get_mcp_servers()

    def _commit(
        self,
        session: SessionData,
        *,
        messages: list[dict[str, Any]],
        user_message: str,
        runtime: Any,
        turn_marker: dict[str, Any] | None = None,
    ) -> None:
        self._sync_session(
            session,
            messages=messages,
            user_message=user_message,
            runtime=runtime,
        )
        if turn_marker is not None:
            if find_turn_commit(session, str(turn_marker.get("turnId", ""))) is not None:
                raise ConversationTurnFailed()
            session.turn_commits = [*session.turn_commits, dict(turn_marker)]
        try:
            self._session_saver(session)
        except SessionWriteConflictError as error:
            raise ConversationSessionConflict() from error
        except SessionStoreBusyError as error:
            raise ConversationSessionBusy() from error
        except Exception as error:  # noqa: BLE001 - fixed safe service boundary
            raise ConversationTurnFailed() from error

    def _best_effort_user_commit(
        self,
        session: SessionData,
        *,
        messages: list[dict[str, Any]],
        user_message: str,
        runtime: Any,
        turn_id: str,
        cancellation_token: TurnCancellationToken,
    ) -> None:
        raise_if_cancelled(cancellation_token)
        try:
            gate = self._turn_store.begin_commit(turn_id)
        except Exception as error:  # noqa: BLE001
            raise ConversationTurnFailed() from error
        if not gate.commit_allowed:
            raise TurnCancellationRequested(turn_id)
        try:
            self._commit(
                session,
                messages=messages,
                user_message=user_message,
                runtime=runtime,
                turn_marker=None,
            )
        except ConversationError:
            pass

    @staticmethod
    def _runtime_execute(
        runtime: Any,
        messages: list[dict[str, Any]],
        observation: Any,
        cancellation_token: TurnCancellationToken,
        presentation: ConversationPresentation | None,
        approval_session: object | None,
    ) -> list[dict[str, Any]]:
        """Pass optional seams only to runtimes that explicitly support them."""
        try:
            parameters = tuple(inspect.signature(runtime.execute).parameters.values())
        except (TypeError, ValueError):
            parameters = ()
        has_kwargs = any(
            parameter.kind == inspect.Parameter.VAR_KEYWORD
            for parameter in parameters
        )
        names = {parameter.name for parameter in parameters}
        kwargs: dict[str, object] = {}
        if has_kwargs or "cancellation_token" in names:
            kwargs["cancellation_token"] = cancellation_token
        if presentation is not None and (has_kwargs or "presentation" in names):
            kwargs["presentation"] = presentation
        if approval_session is not None and (has_kwargs or "approval_session" in names):
            kwargs["approval_session"] = approval_session
        if has_kwargs or "defer_curator_maintenance" in names:
            # ConversationTurnService owns the Session compare-and-swap. A
            # losing pre-commit execution must not count as a completed task.
            kwargs["defer_curator_maintenance"] = True
        return runtime.execute(messages, observation, **kwargs)

    def _create_runtime(
        self,
        *,
        message: str,
        observation: Any,
        cancellation_token: TurnCancellationToken,
        intent_context: object | None = None,
        trusted_user_evidence: tuple[TrustedUserEvidenceSeed, ...] = (),
    ) -> Any:
        """Pass lifecycle seams only when an injected factory supports them."""
        try:
            parameters = tuple(
                inspect.signature(self._runtime_factory).parameters.values()
            )
        except (TypeError, ValueError):
            parameters = ()
        has_kwargs = any(
            parameter.kind == inspect.Parameter.VAR_KEYWORD
            for parameter in parameters
        )
        names = {parameter.name for parameter in parameters}
        kwargs: dict[str, object] = {
            "workspace": self.workspace,
            "prompt": message,
            "mcp_current_state_registry": self._mcp_current_state_registry,
        }
        if has_kwargs or "event_sink" in names:
            kwargs["event_sink"] = observation
        if has_kwargs or "cancellation_token" in names:
            kwargs["cancellation_token"] = cancellation_token
        if intent_context is not None and (
            has_kwargs or "intent_context" in names
        ):
            kwargs["intent_context"] = intent_context
        if trusted_user_evidence and (
            has_kwargs or "trusted_user_evidence" in names
        ):
            kwargs["trusted_user_evidence"] = trusted_user_evidence
        return self._runtime_factory(**kwargs)

    def _trusted_correction_evidence(
        self,
        *,
        session: SessionData,
        message: str,
        current_turn_id: str,
        current_run_id: str | None,
    ) -> tuple[TrustedUserEvidenceSeed, ...]:
        """Join an adjacent explicit ``correct`` signal to its follow-up text.

        Every durable identity in this chain is independently checked. Any
        stale, malformed, cross-session, non-adjacent, or non-correction state
        yields no strong evidence and never blocks the user's Turn.
        """
        if current_run_id is None:
            return ()
        try:
            from minicode.user_evidence import (
                TrustedUserEvidenceSeed,
                looks_like_correction,
            )

            if not looks_like_correction(message.strip()):
                return ()
            markers = validate_turn_commits(
                session.turn_commits,
                messages=session.messages,
            )
            if not markers:
                return ()
            marker = max(markers, key=lambda item: item["assistantMessageIndex"])
            conversational_indexes = [
                index
                for index, item in enumerate(session.messages)
                if isinstance(item, dict)
                and item.get("role") in {"user", "assistant"}
            ]
            if (
                not conversational_indexes
                or conversational_indexes[-1] != marker["assistantMessageIndex"]
            ):
                return ()
            prior_turn_id = str(marker["turnId"])
            record = self._turn_store.get(prior_turn_id)
            store_marker = self._store_marker(marker)
            if (
                record is None
                or record.status != "completed"
                or record.session_id != session.session_id
                or record.run_id is None
                or record.commit_marker != store_marker
                or self._authoritative_result(record) is None
            ):
                return ()
            journal = (
                self._journal_factory(self.workspace)
                if self._journal_factory is not None
                else RunJournal(self.workspace)
            )
            prior_run = journal.get_run(record.run_id)
            signal = journal.get_user_signal(record.run_id)
            if (
                prior_run is None
                or prior_run.id != record.run_id
                or prior_run.status != "completed"
                or prior_run.source != "gateway"
                or prior_run.session_id != session.session_id
                or signal is None
                or signal.signal != "correct"
                or signal.source != "explicit_user_action"
            ):
                return ()
            return (
                TrustedUserEvidenceSeed.followup_correction(
                    message,
                    current_turn_id=current_turn_id,
                    current_run_id=current_run_id,
                    prior_turn_id=prior_turn_id,
                    prior_run_id=record.run_id,
                ),
            )
        except Exception:  # noqa: BLE001 - strong evidence fails closed
            return ()

    @staticmethod
    def _defer_runtime_user_evidence(
        runtime: Any,
        *,
        message: str,
        turn_id: str,
        run_id: str | None,
    ) -> tuple[TrustedUserEvidenceSeed, ...]:
        """Take strong evidence out of pre-commit Agent reflection."""
        take = getattr(runtime, "take_trusted_user_evidence_for_commit", None)
        if not callable(take):
            return ()
        try:
            value = take(
                direct_user_message=message,
                current_turn_id=turn_id,
                current_run_id=run_id,
            )
        except Exception:  # noqa: BLE001 - evidence fails closed, Turn continues
            return ()
        return value if isinstance(value, tuple) else ()

    @staticmethod
    def _persist_committed_runtime_user_evidence(
        runtime: Any,
        evidence: tuple[TrustedUserEvidenceSeed, ...],
        observation: Any,
        *,
        message: str,
        turn_id: str,
        run_id: str | None,
    ) -> None:
        """Best-effort post-Session effect; committed conversation truth wins."""
        if not evidence:
            return
        persist = getattr(runtime, "persist_committed_user_evidence", None)
        if not callable(persist):
            return
        try:
            persist(
                evidence,
                observation,
                direct_user_message=message,
                current_turn_id=turn_id,
                current_run_id=run_id,
            )
        except BaseException as error:  # committed Session remains authoritative
            try:
                from minicode.agent_runtime import (
                    CommittedUserEvidencePersistenceUnavailable,
                )
                from minicode.memory_persistence_event import (
                    MEMORY_PERSISTENCE_FAILURE_EVENT_TYPE,
                    memory_persistence_failure_payload,
                )
                from minicode.user_evidence import (
                    committed_user_evidence_operation_id,
                )

                operation_id = committed_user_evidence_operation_id(turn_id, run_id)
                reason_codes = ("unexpected_failure",)
                if isinstance(
                    error,
                    CommittedUserEvidencePersistenceUnavailable,
                ):
                    operation_id = error.operation_id
                    reason_codes = error.reason_codes
                observation.emit(
                    MEMORY_PERSISTENCE_FAILURE_EVENT_TYPE,
                    payload=memory_persistence_failure_payload(
                        phase="committed_user_evidence",
                        operation_id=operation_id,
                        reason_codes=reason_codes,
                    ),
                )
            except BaseException:
                pass

    @staticmethod
    def _maintain_committed_runtime_turn(
        runtime: Any,
        observation: Any,
        *,
        turn_id: str,
        run_id: str | None,
    ) -> None:
        """Best-effort maintenance strictly after Session CAS success."""

        maintain = getattr(runtime, "maintain_committed_turn", None)
        if not callable(maintain):
            return
        try:
            parameters = tuple(inspect.signature(maintain).parameters.values())
        except (TypeError, ValueError):
            return
        supports_recorded = any(
            parameter.name == "completion_already_recorded"
            or parameter.kind is inspect.Parameter.VAR_KEYWORD
            for parameter in parameters
        )
        if not supports_recorded:
            # Calling an older implementation would make it re-record the
            # already settled Dashboard completion through the CLI facade.
            return
        try:
            maintain(
                observation,
                current_turn_id=turn_id,
                current_run_id=run_id,
                completion_already_recorded=True,
            )
        except Exception:
            # Conversation truth and its user-visible response are already
            # committed. Durable scheduler state retains or leases any debt.
            pass

    def _record_committed_curator_completion(
        self,
        *,
        turn_id: str,
        run_id: str | None,
    ) -> bool:
        """Persist the recoverable completion debt without claiming work."""

        try:
            from minicode.curator_schedule import (
                CuratorScheduleStore,
                curator_completion_id,
            )

            completion_id = curator_completion_id(run_id, turn_id)
            if completion_id is None:
                return False
            schedule = CuratorScheduleStore(self.workspace)
            with schedule.delivery_fence():
                schedule.record_completion(
                    completion_id,
                    pin=True,
                    promote_existing=True,
                )
            return True
        except Exception:
            # The committed Turn record remains a durable reconstruction
            # source. Recovery and terminal replay retry this exact receipt.
            return False

    def _reconcile_cli_curator_receipts(self, schedule: object) -> bool:
        """Drain CLI-owned workspace receipts before a Dashboard delivery."""

        try:
            from minicode.curator_outbox import reconcile_run_curator_outbox

            journal = (
                self._journal_factory(self.workspace)
                if self._journal_factory is not None
                else RunJournal(
                    self.workspace,
                    data_dir=self._turn_store.data_dir,
                )
            )
            return reconcile_run_curator_outbox(journal, schedule)
        except Exception:
            return False

    def _ensure_committed_curator_completion(
        self,
        record: TurnRecord,
    ) -> TurnRecord:
        """Deliver and acknowledge a committed Turn's durable receipt."""

        try:
            from minicode.curator_schedule import (
                CuratorScheduleStore,
                curator_completion_id,
            )

            completion_id = curator_completion_id(
                record.run_id,
                record.turn_id,
            )
            if completion_id is None:
                return record
            schedule = CuratorScheduleStore(self.workspace)
            with schedule.delivery_fence():
                if not self._reconcile_cli_curator_receipts(schedule):
                    return record
                # The caller may have scanned before another worker completed
                # the handshake. Re-read under the delivery fence so a stale
                # snapshot can never resurrect an already-settled receipt.
                current = self._turn_store.get(record.turn_id)
                if current is None:
                    return record
                if (
                    current.curator_outbox_version is None
                    or current.status not in {"committing", "completed"}
                    or current.session_id is None
                    or current.run_id is None
                    or curator_completion_id(
                        current.run_id,
                        current.turn_id,
                    )
                    != completion_id
                ):
                    return current
                if current.curator_receipt_settled:
                    return current
                if not current.curator_receipt_recorded:
                    if not self._record_committed_curator_completion(
                        turn_id=current.turn_id,
                        run_id=current.run_id,
                    ):
                        return current
                    current = self._turn_store.mark_curator_receipt_recorded(
                        current.turn_id
                    )
                schedule.acknowledge_completion(completion_id)
                return self._turn_store.mark_curator_receipt_settled(
                    current.turn_id
                )
        except Exception:
            # The unsettled Turn stays retention-protected and is retried by
            # terminal replay or the bounded release reconciler.
            return record

    def _reconcile_curator_receipts(self) -> bool:
        """Best-effort recovery of committed Dashboard completion receipts."""

        try:
            from minicode.curator_outbox import (
                reconcile_turn_curator_outbox,
                turn_recovery_scan_budget,
            )
            from minicode.curator_schedule import CuratorScheduleStore

            if not reconcile_turn_curator_outbox(
                self._turn_store,
                CuratorScheduleStore(self.workspace),
            ):
                return False
            # Bound this invocation by the store's own durable scan horizon.
            # Counting unique Turns (rather than arbitrary pages) makes a
            # complete recovery pass independent of page size while repeated
            # unresolved records fail closed instead of spinning.
            scan_budget = turn_recovery_scan_budget(self._turn_store)
            observed_turn_ids: set[str] = set()
            while True:
                remaining = scan_budget - len(observed_turn_ids)
                scan = self._turn_store.curator_receipt_recovery_records(
                    limit=min(1_000, max(1, remaining)),
                    include_settled_committing=True,
                )
                if not scan.items:
                    return bool(scan.exhaustive)
                page_turn_ids = {record.turn_id for record in scan.items}
                newly_observed = page_turn_ids - observed_turn_ids
                if len(newly_observed) > remaining:
                    return False
                observed_turn_ids.update(page_turn_ids)
                progressed = False
                actionable = False
                for record in scan.items:
                    current = record
                    if current.status == "committing":
                        # Once this fence is acquired, no live owner can still
                        # publish the Session marker for this Turn.  Resolve
                        # every stable committing record here so abandoned
                        # receipts cannot occupy the bounded recovery page and
                        # starve newer authoritative commits forever.
                        with self._turn_store.commit_fence():
                            refreshed = self._turn_store.get(current.turn_id)
                            if refreshed is None:
                                progressed = True
                                continue
                            current = refreshed
                            if current.status == "committing":
                                authoritative = self._authoritative_result(
                                    current
                                )
                                if authoritative is None:
                                    self._turn_store.mark_interrupted(
                                        current.turn_id
                                    )
                                    progressed = True
                                    continue
                                current = self._turn_store.recover_completed(
                                    current.turn_id,
                                    commit_marker=authoritative[1],
                                )
                            elif current.status != "completed":
                                progressed = True
                                continue
                        actionable = True
                    else:
                        actionable = True
                    settled = self._ensure_committed_curator_completion(
                        current
                    )
                    progressed = (
                        progressed or settled.curator_receipt_settled
                    )
                if not actionable:
                    if progressed:
                        # Terminalized stable no-marker records disappear from
                        # the next page. Continue until the bounded scan proves
                        # there is no authoritative commit hidden behind them.
                        continue
                    unsafe_diagnostics = set(scan.diagnostics) - {
                        "curator_receipt_page_limited"
                    }
                    return bool(scan.exhaustive) and not unsafe_diagnostics
                if not progressed:
                    return False
                if not newly_observed:
                    return False
        except Exception:
            # Each source record remains durable and non-retention-eligible.
            return False

    @staticmethod
    def _store_marker(session_marker: dict[str, Any]) -> dict[str, int]:
        return {
            "schemaVersion": 1,
            "userMessageIndex": int(session_marker["userMessageIndex"]),
            "assistantMessageIndex": int(session_marker["assistantMessageIndex"]),
        }

    def _authoritative_result(
        self,
        record: TurnRecord,
    ) -> tuple[ConversationTurnResult, dict[str, int]] | None:
        if record.session_id is None or record.created_session is None:
            return None
        session = self._session_loader(record.session_id)
        if session is None or not _same_workspace(session.workspace, self.workspace):
            return None
        marker = find_turn_commit(session, record.turn_id)
        if marker is None:
            return None
        store_marker = self._store_marker(marker)
        if record.commit_marker is not None and record.commit_marker != store_marker:
            return None
        assistant_index = marker["assistantMessageIndex"]
        if (
            isinstance(assistant_index, bool)
            or not isinstance(assistant_index, int)
            or assistant_index < 0
            or assistant_index >= len(session.messages)
        ):
            return None
        result_message = session.messages[assistant_index]
        assistant = result_message.get("content")
        if (
            result_message.get("role") == "assistant"
            and isinstance(assistant, str)
            and assistant
        ):
            pass
        elif (
            result_message.get("role") == "tool_result"
            and isinstance(assistant, str)
            and assistant
            and assistant_index > 0
            and isinstance(session.messages[assistant_index - 1], dict)
            and session.messages[assistant_index - 1].get("role")
            == "assistant_tool_call"
            and result_message.get("toolUseId")
            and session.messages[assistant_index - 1].get("toolUseId")
            == result_message.get("toolUseId")
        ):
            pass
        else:
            return None
        return (
            ConversationTurnResult(
                turn_id=record.turn_id,
                session_id=session.session_id,
                created=record.created_session,
                assistant=assistant,
                updated_at=_iso_timestamp(session.updated_at),
                run_id=record.run_id,
            ),
            store_marker,
        )

    def _reconcile_active(self, record: TurnRecord) -> TurnRecord:
        try:
            if record.status == "committing":
                # Status/feedback/cancel endpoints can reach this recovery
                # without the new-Turn preflight.  First close only delivery
                # work already evidenced by a producer ack or scheduler pin;
                # the shared reconciler deliberately does not count a bare
                # committing Turn.
                from minicode.curator_outbox import (
                    reconcile_turn_curator_outbox,
                )
                from minicode.curator_schedule import CuratorScheduleStore

                if not reconcile_turn_curator_outbox(
                    self._turn_store,
                    CuratorScheduleStore(self.workspace),
                ):
                    raise ConversationTurnFailed()
                # A live committer holds this fence across Session CAS and the
                # terminal Turn write. Once acquired, a missing Session marker
                # is stable and can be interrupted without racing publication.
                with self._turn_store.commit_fence():
                    current = self._turn_store.get(record.turn_id)
                    if current is None:
                        raise ConversationTurnFailed()
                    if current.status in {
                        "completed",
                        "failed",
                        "interrupted",
                        "cancelled",
                    }:
                        return current
                    authoritative = self._authoritative_result(current)
                    if authoritative is not None:
                        recovered = self._turn_store.recover_completed(
                            current.turn_id,
                            commit_marker=authoritative[1],
                        )
                        return self._ensure_committed_curator_completion(
                            recovered
                        )
                    return self._turn_store.mark_interrupted(current.turn_id)
            authoritative = self._authoritative_result(record)
            if authoritative is not None:
                recovered = self._turn_store.recover_completed(
                    record.turn_id,
                    commit_marker=authoritative[1],
                )
                return self._ensure_committed_curator_completion(recovered)
            if record.status == "cancel_requested":
                return self._turn_store.mark_cancelled(record.turn_id)
            return self._turn_store.mark_interrupted(record.turn_id)
        except Exception as error:  # noqa: BLE001 - fixed safe storage boundary
            raise ConversationTurnFailed() from error

    def _terminal_result(self, record: TurnRecord) -> ConversationTurnResult:
        if record.status == "completed":
            authoritative = self._authoritative_result(record)
            if authoritative is not None:
                self._ensure_committed_curator_completion(record)
                return authoritative[0]
            raise ConversationTurnInterrupted()
        raise _error_for_code(record.error_code)

    def _record_failure(self, turn_id: str, error: ConversationError) -> None:
        try:
            decision = self._turn_store.mark_failed(turn_id, error_code=error.code)
        except Exception as storage_error:  # noqa: BLE001
            self._turn_store.release_claim(turn_id)
            raise ConversationTurnFailed() from storage_error
        if not decision.failure_recorded:
            raise ConversationTurnCancelled()

    def status(self, turn_id: str) -> ConversationTurnStatus:
        try:
            validated = validate_turn_id(turn_id)
            record = self._turn_store.get(validated)
        except ValueError:
            raise
        except Exception as error:  # noqa: BLE001
            raise ConversationTurnFailed() from error
        if record is None:
            raise ConversationTurnNotFound()
        if (
            record.status in {"accepted", "running", "cancel_requested", "committing"}
            and (
                record.owner_id != self._turn_store.owner_id
                or not self._turn_store.is_active(record.turn_id)
            )
        ):
            try:
                live_owner = self._turn_store.has_live_owner(record.turn_id)
            except Exception as error:
                raise ConversationTurnFailed() from error
            if not live_owner:
                record = self._reconcile_active(record)
        result_available = (
            record.status == "completed"
            and self._authoritative_result(record) is not None
        )
        return ConversationTurnStatus(
            turn_id=record.turn_id,
            status=record.status,
            session_id=record.session_id,
            created_session=record.created_session,
            run_id=record.run_id,
            created_at=record.created_at,
            updated_at=record.updated_at,
            completed_at=record.completed_at,
            error_code=record.error_code,
            result_available=result_available,
        )

    def record_feedback(
        self,
        turn_id: str,
        signal: str,
    ) -> ConversationFeedbackResult:
        """Bind one explicit user action to one authoritative completed Turn."""
        if signal not in {"accept", "correct", "reject"}:
            raise ValueError("invalid feedback signal")
        try:
            validated = validate_turn_id(turn_id)
            record = self._turn_store.get(validated)
        except ValueError:
            raise
        except Exception as error:  # noqa: BLE001
            raise ConversationFeedbackUnavailable() from error
        if record is None:
            raise ConversationTurnNotFound()
        if (
            record.status in {"accepted", "running", "cancel_requested", "committing"}
            and (
                record.owner_id != self._turn_store.owner_id
                or not self._turn_store.is_active(record.turn_id)
            )
        ):
            try:
                live_owner = self._turn_store.has_live_owner(record.turn_id)
            except Exception as error:
                raise ConversationFeedbackUnavailable() from error
            if not live_owner:
                record = self._reconcile_active(record)
        if (
            record.status != "completed"
            or record.run_id is None
            or self._authoritative_result(record) is None
        ):
            raise ConversationFeedbackUnavailable()
        try:
            journal = (
                self._journal_factory(self.workspace)
                if self._journal_factory is not None
                else RunJournal(self.workspace)
            )
            stored = journal.record_user_signal(record.run_id, signal)
        except RunJournalUserSignalConflictError as error:
            raise ConversationFeedbackConflict() from error
        except RunJournalError as error:
            raise ConversationFeedbackUnavailable() from error
        except Exception as error:  # noqa: BLE001 - fixed safe domain boundary
            raise ConversationFeedbackUnavailable() from error
        # Re-apply on every idempotent Run-signal replay. Memory owns a durable
        # observation receipt, so this safely closes the crash window between
        # the immutable journal write and its best-effort Memory side effect.
        _apply_run_outcome_memory_feedback(
            self.workspace, journal, record.run_id, stored.signal
        )
        _apply_written_run_outcome_feedback(
            self.workspace, journal, record.run_id, stored.signal
        )
        return ConversationFeedbackResult(
            turn_id=record.turn_id,
            run_id=record.run_id,
            signal=stored.signal,
            source=stored.source,
            recorded_at=stored.recorded_at,
        )

    def cancel(self, turn_id: str) -> ConversationCancellationResult:
        """Request cooperative cancellation without exposing internal identity facts."""
        try:
            validated = validate_turn_id(turn_id)
            record = self._turn_store.get(validated)
        except ValueError:
            raise
        except Exception as error:  # noqa: BLE001
            raise ConversationTurnFailed() from error
        if record is None:
            raise ConversationTurnNotFound()
        if (
            record.status in {"accepted", "running", "cancel_requested", "committing"}
            and (
                record.owner_id != self._turn_store.owner_id
                or not self._turn_store.is_active(record.turn_id)
            )
        ):
            try:
                live_owner = self._turn_store.has_live_owner(record.turn_id)
            except Exception as error:
                raise ConversationTurnFailed() from error
            if not live_owner:
                record = self._reconcile_active(record)
        try:
            decision = self._turn_store.request_cancel(record.turn_id)
        except Exception as error:  # noqa: BLE001
            raise ConversationTurnFailed() from error
        decided = decision.record
        if decision.cancellation_accepted and self._approval_broker is not None:
            try:
                self._approval_broker.cancel_turn(decided.turn_id)
            except BaseException:  # noqa: BLE001 - durable cancel remains authoritative
                pass
        return ConversationCancellationResult(
            turn_id=decided.turn_id,
            status=decided.status,
            cancellation_accepted=decision.cancellation_accepted,
            session_id=decided.session_id,
            created_session=decided.created_session,
            run_id=decided.run_id,
            updated_at=decided.updated_at,
        )

    def _execute_claimed(
        self,
        *,
        message: str,
        session_id: str | None,
        turn_id: str,
        cancellation_token: TurnCancellationToken,
        presentation: ConversationPresentation | None,
        curator_backlog_safe: bool,
    ) -> ConversationTurnResult:
        raise_if_cancelled(cancellation_token)
        session, created = self._session(session_id)
        raise_if_cancelled(cancellation_token)
        try:
            self._turn_store.attach_session(
                turn_id,
                session_id=session.session_id,
                created_session=created,
            )
        except Exception as error:  # noqa: BLE001
            raise ConversationTurnFailed() from error
        raise_if_cancelled(cancellation_token)
        runtime: Any | None = None
        approval_session: Any | None = None
        try:
            with observe_run(
                workspace=self.workspace,
                source="gateway",
                title=message,
                session_id=session.session_id,
                journal_factory=self._journal_factory,
                enabled=self._observation_enabled,
            ) as observation:
                try:
                    self._turn_store.attach_run(turn_id, run_id=observation.run_id)
                except Exception as error:  # noqa: BLE001
                    raise ConversationTurnFailed() from error
                raise_if_cancelled(cancellation_token)
                if self._approval_broker is not None:
                    try:
                        approval_session = self._approval_broker.begin_turn(
                            turn_id=turn_id,
                            run_id=observation.run_id,
                            cancellation_token=cancellation_token,
                            event_sink=lambda event_type, payload: observation.emit(
                                event_type, payload=payload
                            ),
                        )
                    except (KeyboardInterrupt, SystemExit, TurnCancellationRequested):
                        raise
                    except Exception as error:  # noqa: BLE001
                        raise ConversationRuntimeUnavailable() from error
                try:
                    from minicode.intent_parser import IntentContext

                    trusted_user_evidence = self._trusted_correction_evidence(
                        session=session,
                        message=message,
                        current_turn_id=turn_id,
                        current_run_id=observation.run_id,
                    )
                    runtime = self._create_runtime(
                        message=message,
                        observation=observation,
                        cancellation_token=cancellation_token,
                        intent_context=IntentContext.from_messages(
                            session.messages
                        ),
                        trusted_user_evidence=trusted_user_evidence,
                    )
                    deferred_user_evidence = self._defer_runtime_user_evidence(
                        runtime,
                        message=message,
                        turn_id=turn_id,
                        run_id=observation.run_id,
                    )
                except (KeyboardInterrupt, SystemExit, TurnCancellationRequested):
                    raise
                except Exception as error:  # noqa: BLE001
                    raise ConversationRuntimeUnavailable() from error
                raise_if_cancelled(cancellation_token)

                previous_prompt = getattr(runtime.permissions, "prompt", None)
                previous_checkpoint = getattr(
                    runtime.permissions, "operation_checkpoint", None
                )
                if approval_session is not None:
                    runtime.permissions.prompt = approval_session.prompt
                    runtime.permissions.operation_checkpoint = (
                        approval_session.check_operation
                    )

                emit_skill_routing_safely(observation, runtime.skill_routing)
                prepared = prepare_conversation_messages(
                    session.messages,
                    system_prompt=runtime.system_prompt,
                    user_message=message,
                )
                prepared[-1][_TURN_MESSAGE_ID_FIELD] = turn_id
                try:
                    runtime.permissions.begin_turn()
                    try:
                        raise_if_cancelled(cancellation_token)
                        result_messages = self._runtime_execute(
                            runtime,
                            prepared,
                            observation,
                            cancellation_token,
                            presentation,
                            approval_session,
                        )
                        raise_if_cancelled(cancellation_token)
                    finally:
                        try:
                            runtime.permissions.end_turn()
                        except Exception:  # noqa: BLE001 - cleanup is isolated
                            pass
                        if approval_session is not None:
                            runtime.permissions.prompt = previous_prompt
                            runtime.permissions.operation_checkpoint = (
                                previous_checkpoint
                            )
                except (KeyboardInterrupt, SystemExit, TurnCancellationRequested):
                    raise
                except Exception as error:  # noqa: BLE001
                    raise_if_cancelled(cancellation_token)
                    self._best_effort_user_commit(
                        session,
                        messages=prepared,
                        user_message=message,
                        runtime=runtime,
                        turn_id=turn_id,
                        cancellation_token=cancellation_token,
                    )
                    raise ConversationTurnFailed() from error

                turn_result = _turn_result(
                    result_messages,
                    turn_id=turn_id,
                )
                if turn_result is None:
                    self._best_effort_user_commit(
                        session,
                        messages=prepared,
                        user_message=message,
                        runtime=runtime,
                        turn_id=turn_id,
                        cancellation_token=cancellation_token,
                    )
                    raise ConversationTurnFailed()
                if not isinstance(result_messages, list) or any(
                    not isinstance(item, dict) for item in result_messages
                ):
                    raise ConversationTurnFailed()
                assistant, user_index, assistant_index = turn_result
                raise_if_cancelled(cancellation_token)
                session_marker = {
                    "schemaVersion": 1,
                    "turnId": turn_id,
                    "userMessageIndex": user_index,
                    "assistantMessageIndex": assistant_index,
                }
                curator_receipt_settled = False
                # Fence the publication sequence so another Gateway cannot
                # observe ``committing`` between Session CAS and the terminal
                # Turn write, then overwrite receipt flags from a stale view.
                with self._turn_store.commit_fence():
                    try:
                        gate = self._turn_store.begin_commit(turn_id)
                    except Exception as error:  # noqa: BLE001
                        raise ConversationTurnFailed() from error
                    if not gate.commit_allowed:
                        raise TurnCancellationRequested(turn_id)
                    self._commit(
                        session,
                        messages=result_messages,
                        user_message=message,
                        runtime=runtime,
                        turn_marker=session_marker,
                    )
                    if curator_backlog_safe:
                        curator_record = (
                            self._ensure_committed_curator_completion(
                                gate.record
                            )
                        )
                        curator_receipt_settled = bool(
                            curator_record.curator_receipt_settled
                        )
                    try:
                        self._turn_store.mark_completed(
                            turn_id,
                            commit_marker=self._store_marker(session_marker),
                        )
                    except Exception as error:  # noqa: BLE001
                        raise _TurnCompletionWriteFailed() from error
                self._persist_committed_runtime_user_evidence(
                    runtime,
                    deferred_user_evidence,
                    observation,
                    message=message,
                    turn_id=turn_id,
                    run_id=observation.run_id,
                )
                if curator_backlog_safe and curator_receipt_settled:
                    self._maintain_committed_runtime_turn(
                        runtime,
                        observation,
                        turn_id=turn_id,
                        run_id=observation.run_id,
                    )
                observation.assistant_completed(
                    content_present=True,
                    content_length=len(assistant),
                )
                result = ConversationTurnResult(
                    turn_id=turn_id,
                    session_id=session.session_id,
                    created=created,
                    assistant=assistant,
                    updated_at=_iso_timestamp(session.updated_at),
                    run_id=observation.run_id,
                )
            return result
        finally:
            if approval_session is not None:
                try:
                    approval_session.close()
                except BaseException:  # noqa: BLE001 - cleanup cannot replace outcome
                    pass
            if runtime is not None:
                try:
                    runtime.dispose()
                except Exception:  # noqa: BLE001 - cleanup cannot replace outcome
                    pass

    def turn(
        self,
        *,
        message: str,
        session_id: str | None,
        turn_id: str | None = None,
        presentation: ConversationPresentation | None = None,
    ) -> ConversationTurnResult:
        curator_backlog_safe = self._reconcile_curator_receipts()
        validated_turn_id = create_turn_id() if turn_id is None else validate_turn_id(turn_id)
        fingerprint = request_fingerprint(
            workspace_id=self._turn_store.workspace_id,
            session_id=session_id,
            message=message,
        )
        try:
            claim = self._turn_store.claim(
                turn_id=validated_turn_id,
                fingerprint=fingerprint,
            )
        except Exception as error:  # noqa: BLE001
            raise ConversationTurnFailed() from error
        if claim.disposition == "conflict":
            raise ConversationTurnIdConflict()
        if claim.disposition == "in_progress":
            raise ConversationTurnInProgress()
        if claim.disposition == "recover":
            return self._terminal_result(self._reconcile_active(claim.record))
        if claim.disposition == "terminal":
            return self._terminal_result(claim.record)
        try:
            start = self._turn_store.mark_running(validated_turn_id)
            if not start.execution_started:
                raise ConversationTurnCancelled()
            cancellation_token = self._turn_store.cancellation_token(
                validated_turn_id
            )
        except ConversationTurnCancelled:
            raise
        except Exception as error:  # noqa: BLE001
            self._turn_store.release_claim(validated_turn_id)
            raise ConversationTurnFailed() from error
        try:
            return self._execute_claimed(
                message=message,
                session_id=session_id,
                turn_id=validated_turn_id,
                cancellation_token=cancellation_token,
                presentation=presentation,
                curator_backlog_safe=curator_backlog_safe,
            )
        except _TurnCompletionWriteFailed as error:
            # Preserve committing + Session marker so a new process can reconcile
            # the committed content without ever executing Agent again.
            self._turn_store.release_claim(validated_turn_id)
            raise ConversationTurnFailed() from error
        except TurnCancellationRequested as error:
            try:
                self._turn_store.mark_cancelled(validated_turn_id)
            except Exception as storage_error:  # noqa: BLE001
                self._turn_store.release_claim(validated_turn_id)
                raise ConversationTurnFailed() from storage_error
            raise ConversationTurnCancelled() from error
        except (KeyboardInterrupt, SystemExit):
            try:
                current = self._turn_store.get(validated_turn_id)
                if current is not None and current.status == "committing":
                    # Session CAS may already be durable. Reconcile under the
                    # commit fence instead of destroying the recoverable
                    # producer receipt with an ``interrupted`` transition.
                    # Execution is ending, so first relinquish its lease. This
                    # also lets the generic outbox path join an already-durable
                    # scheduler pin without replaying the producer callback.
                    self._turn_store.release_claim(validated_turn_id)
                    self._reconcile_active(current)
                elif current is not None and current.status not in {
                    "completed",
                    "failed",
                    "interrupted",
                    "cancelled",
                }:
                    self._turn_store.mark_interrupted(validated_turn_id)
            except Exception:  # noqa: BLE001 - process exit remains primary
                self._turn_store.release_claim(validated_turn_id)
            raise
        except ConversationError as error:
            self._record_failure(validated_turn_id, error)
            raise
        except Exception as error:  # noqa: BLE001
            failure = ConversationTurnFailed()
            self._record_failure(validated_turn_id, failure)
            raise failure from error


__all__ = [
    "ConversationError",
    "ConversationCancellationResult",
    "ConversationFeedbackConflict",
    "ConversationFeedbackResult",
    "ConversationFeedbackUnavailable",
    "ConversationRuntimeUnavailable",
    "ConversationSessionBusy",
    "ConversationSessionConflict",
    "ConversationSessionNotFound",
    "ConversationTurnFailed",
    "ConversationTurnCancelled",
    "ConversationTurnResult",
    "ConversationTurnService",
]

shared_files.minicode/conversation_deletion.py:
"""Workspace-scoped authority for deleting a complete saved conversation."""

from __future__ import annotations

import hashlib
import hmac
import json
import re
from datetime import datetime, timezone
from pathlib import Path
from typing import Callable

from minicode.conversation_turn_store import ConversationTurnStore, TurnStoreError
from minicode.deletion_store import (
    DeletionLedger,
    DeletionRecord,
    DeletionStoreBusy,
    DeletionStoreUnavailable,
)
from minicode.run_journal import RunJournal, RunJournalStorageError
from minicode.session import (
    delete_session,
    session_deletion_snapshot,
)


DELETION_REVISION_RE = re.compile(r"delrev_[0-9a-f]{64}")
SESSION_ID_RE = re.compile(r"[A-Za-z0-9][A-Za-z0-9_-]{0,127}")


class ConversationDeletionError(RuntimeError):
    """One fixed-vocabulary conversation deletion failure."""

    def __init__(self, code: str) -> None:
        super().__init__(code)
        self.code = code


def _utc_now() -> datetime:
    return datetime.now(timezone.utc)


def _iso_time(value: datetime) -> str:
    if not isinstance(value, datetime) or value.tzinfo is None:
        raise ConversationDeletionError("deletion_unavailable")
    return value.astimezone(timezone.utc).isoformat(timespec="milliseconds").replace(
        "+00:00", "Z"
    )


def _revision(payload: object) -> str:
    encoded = json.dumps(
        payload,
        ensure_ascii=True,
        sort_keys=True,
        separators=(",", ":"),
        allow_nan=False,
    ).encode("utf-8")
    return "delrev_" + hashlib.sha256(encoded).hexdigest()


class ConversationDeletionAuthority:
    """Preview and delete one conversation behind a two-method interface.

    Linearization happens when a content-free deletion fence is atomically
    installed under the Workspace ledger lock.  Linked writers consult that
    same fence before they can save the Session or add a Turn/Run association.
    """

    def __init__(
        self,
        workspace: str | Path,
        *,
        data_dir: str | Path,
        clock: Callable[[], datetime] = _utc_now,
        store_timeout: float = 5.0,
    ) -> None:
        self.workspace = Path(workspace).expanduser().resolve()
        self.data_dir = Path(data_dir).expanduser().resolve(strict=False)
        self._clock = clock
        self._turns = ConversationTurnStore(self.workspace, data_dir=self.data_dir)
        self._runs = RunJournal(self.workspace, data_dir=self.data_dir)
        self._ledger = DeletionLedger(
            self.workspace,
            data_dir=self.data_dir,
            clock=clock,
            timeout=store_timeout,
        )

    @staticmethod
    def _validate_id(session_id: object) -> str:
        if not isinstance(session_id, str) or SESSION_ID_RE.fullmatch(session_id) is None:
            raise ConversationDeletionError("invalid_id")
        return session_id

    @staticmethod
    def _validate_revision(deletion_revision: object) -> str:
        if (
            not isinstance(deletion_revision, str)
            or DELETION_REVISION_RE.fullmatch(deletion_revision) is None
        ):
            raise ConversationDeletionError("invalid_revision")
        return deletion_revision

    def _plan(
        self,
        session_id: str,
        *,
        fence: DeletionRecord | None = None,
    ) -> tuple[dict[str, object], object, object, object]:
        session = session_deletion_snapshot(
            session_id,
            self.workspace,
            allow_unowned_orphans=fence is not None,
        )
        turns = self._turns.deletion_snapshot(session_id)
        runs = self._runs.deletion_snapshot(session_id)
        if (
            fence is None
            and
            not session.present
            and not turns.terminal
            and not turns.active
            and not runs.terminal
            and not runs.active
        ):
            raise ConversationDeletionError("deletion_target_not_found")
        blockers = [
            *([{"code": "active_turn"}] if turns.active else []),
            *([{"code": "active_run"}] if runs.active else []),
        ]
        diagnostic_codes = sorted(
            {*session.diagnostics, *turns.diagnostics, *runs.diagnostics}
        )
        diagnostics = [{"code": code} for code in diagnostic_codes]
        if diagnostics:
            status = "unavailable"
        elif blockers:
            status = "busy"
        elif fence is not None:
            status = "partial"
        else:
            status = "ready"
        canonical = {
            "session": {
                "base": session.base_present,
                "index": session.index_present,
                "deltas": session.delta_count,
                "generation": session.generation,
            },
            "turns": [
                [item.turn_id, item.status, item.updated_at, item.run_id]
                for item in (*turns.terminal, *turns.active)
            ],
            "runs": [
                [item.id, item.status, item.updated_at, item.last_sequence]
                for item in (*runs.terminal, *runs.active)
            ],
            "diagnostics": diagnostic_codes,
            "fence": (
                ["in_progress", fence.deletion_revision]
                if fence is not None
                else ["absent"]
            ),
        }
        preview = {
            "schemaVersion": 1,
            "generatedAt": _iso_time(self._clock()),
            "mode": "read-write",
            "kind": "conversation",
            "target": {"sessionId": session_id},
            "status": status,
            "deletionRevision": (
                fence.deletion_revision if fence is not None else _revision(canonical)
            ),
            "affected": {
                "sessions": int(session.present),
                "turns": len(turns.terminal),
                "runs": len(runs.terminal),
            },
            "blockers": blockers,
            "diagnostics": diagnostics,
        }
        return preview, session, turns, runs

    def _receipt_preview(
        self,
        session_id: str,
        receipt: DeletionRecord,
    ) -> dict[str, object]:
        return {
            "schemaVersion": 1,
            "generatedAt": _iso_time(self._clock()),
            "mode": "read-write",
            "kind": "conversation",
            "target": {"sessionId": session_id},
            "status": "completed",
            "deletionRevision": receipt.deletion_revision,
            "affected": {"sessions": 0, "turns": 0, "runs": 0},
            "blockers": [],
            "diagnostics": [],
        }

    def snapshot(self, target_id: str) -> dict[str, object]:
        session_id = self._validate_id(target_id)
        try:
            receipt = self._ledger.read_receipt("conversation", session_id)
            if receipt is not None:
                return self._receipt_preview(session_id, receipt)
            fence = self._ledger.read_fence("conversation", session_id)
            preview, _, _, _ = self._plan(session_id, fence=fence)
            return preview
        except ConversationDeletionError:
            raise
        except DeletionStoreBusy as error:
            raise ConversationDeletionError("deletion_store_busy") from error
        except DeletionStoreUnavailable as error:
            raise ConversationDeletionError("deletion_unavailable") from error
        except BaseException as error:
            raise ConversationDeletionError("deletion_unavailable") from error

    def _result(
        self,
        session_id: str,
        deletion_revision: str,
        *,
        status: str,
        deleted: dict[str, int],
        remaining: dict[str, int],
        diagnostic: str | None = None,
    ) -> dict[str, object]:
        return {
            "schemaVersion": 1,
            "generatedAt": _iso_time(self._clock()),
            "mode": "read-write",
            "kind": "conversation",
            "target": {"sessionId": session_id},
            "status": status,
            "deletionRevision": deletion_revision,
            "deleted": deleted,
            "remaining": remaining,
            "diagnostics": ([{"code": diagnostic}] if diagnostic else []),
        }

    def delete(self, target_id: str, deletion_revision: str) -> dict[str, object]:
        session_id = self._validate_id(target_id)
        requested_revision = self._validate_revision(deletion_revision)
        try:
            with self._ledger.coordination():
                receipt = self._ledger.read_receipt("conversation", session_id)
                if receipt is not None:
                    if not hmac.compare_digest(
                        receipt.deletion_revision, requested_revision
                    ):
                        raise ConversationDeletionError(
                            "deletion_target_not_found"
                        )
                    return self._result(
                        session_id,
                        requested_revision,
                        status="already_absent",
                        deleted={"sessions": 0, "turns": 0, "runs": 0},
                        remaining={"sessions": 0, "turns": 0, "runs": 0},
                    )

                fence = self._ledger.read_fence("conversation", session_id)
                preview, _, _, _ = self._plan(session_id, fence=fence)
                if not hmac.compare_digest(
                    str(preview["deletionRevision"]), requested_revision
                ):
                    raise ConversationDeletionError("deletion_revision_stale")
                if preview["status"] == "busy":
                    raise ConversationDeletionError("deletion_target_busy")
                if preview["status"] not in {"ready", "partial"}:
                    raise ConversationDeletionError("deletion_unavailable")
                installed = self._ledger.start(
                    "conversation", session_id, requested_revision
                )
                if installed.deletion_revision != requested_revision:
                    raise ConversationDeletionError("deletion_revision_stale")

            deleted = {"sessions": 0, "turns": 0, "runs": 0}
            try:
                deleted["turns"] = self._turns.delete_terminal_for_session(session_id)
                deleted["runs"] = self._runs.delete_terminal_for_session(session_id)
                deleted["sessions"] = int(delete_session(session_id))
                fence = self._ledger.read_fence("conversation", session_id)
                try:
                    verification, _, _, _ = self._plan(session_id, fence=fence)
                except ConversationDeletionError as error:
                    if error.code != "deletion_target_not_found":
                        raise
                    verification = None
                if verification is not None and (
                    any(int(value) for value in verification["affected"].values())
                    or verification["blockers"]
                    or verification["diagnostics"]
                ):
                    return self._result(
                        session_id,
                        requested_revision,
                        status="partial",
                        deleted=deleted,
                        remaining=dict(verification["affected"]),
                        diagnostic="deletion_retry_required",
                    )
            except (TurnStoreError, RunJournalStorageError, OSError):
                try:
                    fence = self._ledger.read_fence("conversation", session_id)
                    remaining_preview, _, _, _ = self._plan(session_id, fence=fence)
                    remaining = dict(remaining_preview["affected"])
                except BaseException:
                    remaining = {"sessions": 1, "turns": 1, "runs": 1}
                return self._result(
                    session_id,
                    requested_revision,
                    status="partial",
                    deleted=deleted,
                    remaining=remaining,
                    diagnostic="deletion_retry_required",
                )

            with self._ledger.coordination():
                self._ledger.complete(
                    "conversation", session_id, requested_revision
                )
            return self._result(
                session_id,
                requested_revision,
                status="completed",
                deleted=deleted,
                remaining={"sessions": 0, "turns": 0, "runs": 0},
            )
        except ConversationDeletionError:
            raise
        except DeletionStoreBusy as error:
            raise ConversationDeletionError("deletion_store_busy") from error
        except DeletionStoreUnavailable as error:
            raise ConversationDeletionError("deletion_unavailable") from error
        except BaseException as error:
            raise ConversationDeletionError("deletion_failed") from error


__all__ = [
    "ConversationDeletionAuthority",
    "ConversationDeletionError",
    "DELETION_REVISION_RE",
]

shared_files.minicode/conversation_presentation.py:
"""Optional no-throw presentation seam for one synchronous conversation turn."""

from __future__ import annotations

from typing import Protocol


class ConversationPresentation(Protocol):
    """Observe temporary connection-local UI facts without becoming authority."""

    def assistant_delta(self, text: str) -> None: ...

    def tool_started(self, tool_name: str) -> None: ...

    def tool_finished(self, tool_name: str, *, is_error: bool) -> None: ...


def emit_assistant_delta_safely(
    presentation: ConversationPresentation | None,
    text: str,
) -> None:
    if presentation is None:
        return
    try:
        presentation.assistant_delta(text)
    except BaseException:  # noqa: BLE001 - UI presentation never alters execution
        pass


def emit_tool_started_safely(
    presentation: ConversationPresentation | None,
    tool_name: str,
) -> None:
    if presentation is None:
        return
    try:
        presentation.tool_started(tool_name)
    except BaseException:  # noqa: BLE001 - UI presentation never alters execution
        pass


def emit_tool_finished_safely(
    presentation: ConversationPresentation | None,
    tool_name: str,
    *,
    is_error: bool,
) -> None:
    if presentation is None:
        return
    try:
        presentation.tool_finished(tool_name, is_error=is_error)
    except BaseException:  # noqa: BLE001 - UI presentation never alters execution
        pass


__all__ = [
    "ConversationPresentation",
    "emit_assistant_delta_safely",
    "emit_tool_finished_safely",
    "emit_tool_started_safely",
]

shared_files.minicode/cron_runner.py:
"""Scheduled headless task runner for MiniCode.

Config format:

{
  "tasks": [
    {"name": "daily-check", "prompt": "Summarize the repository status"}
  ]
}

Without a config file, the runner exits cleanly with an explanatory message.
"""

from __future__ import annotations

import argparse
import json
import os
import time
from pathlib import Path
from typing import Any


def _default_config_path() -> Path:
    return Path(os.environ.get("MINI_CODE_CRON_CONFIG", ".mini-code/cron.json"))


def load_cron_config(path: str | Path | None = None) -> dict[str, Any]:
    config_path = Path(path) if path is not None else _default_config_path()
    if not config_path.exists():
        return {"tasks": []}
    data = json.loads(config_path.read_text(encoding="utf-8"))
    if not isinstance(data, dict):
        raise ValueError("cron config must be a JSON object")
    tasks = data.get("tasks", [])
    if not isinstance(tasks, list):
        raise ValueError("cron config field 'tasks' must be a list")
    return {"tasks": tasks}


def run_configured_tasks(config: dict[str, Any], *, dry_run: bool = False) -> list[dict[str, Any]]:
    from minicode.headless import run_headless

    results: list[dict[str, Any]] = []
    for index, task in enumerate(config.get("tasks", [])):
        if not isinstance(task, dict):
            results.append({"index": index, "ok": False, "error": "task must be an object"})
            continue
        prompt = str(task.get("prompt", "")).strip()
        name = str(task.get("name") or f"task-{index + 1}")
        if not prompt:
            results.append({"name": name, "ok": False, "error": "prompt is required"})
            continue
        if dry_run:
            results.append({"name": name, "ok": True, "dryRun": True})
            continue
        results.append({"name": name, "ok": True, "response": run_headless(prompt)})
    return results


def main(argv: list[str] | None = None) -> None:
    parser = argparse.ArgumentParser(description="Run CodeLoop scheduled headless tasks.")
    parser.add_argument("--config", default=None, help="Path to cron JSON config.")
    parser.add_argument("--once", action="store_true", help="Run tasks once and exit.")
    parser.add_argument("--dry-run", action="store_true", help="Validate tasks without executing prompts.")
    parser.add_argument("--interval", type=float, default=60.0, help="Polling interval in seconds.")
    args = parser.parse_args(argv)

    while True:
        config = load_cron_config(args.config)
        if not config["tasks"]:
            print(f"No cron tasks configured in {args.config or _default_config_path()}.", flush=True)
        else:
            for result in run_configured_tasks(config, dry_run=args.dry_run):
                print(json.dumps(result, ensure_ascii=False), flush=True)
        if args.once or not config["tasks"]:
            return
        time.sleep(max(args.interval, 1.0))


if __name__ == "__main__":
    main()

shared_files.minicode/curator_outbox.py:
"""Cross-entrypoint recovery for workspace-scoped curator outboxes.

CLI Runs and Dashboard Turns are separate durable producers for one shared
curator scheduler.  Recovery therefore cannot be entrypoint-local: a bounded
ring filled with receipts from an entrypoint that is never opened again would
otherwise block every other producer forever.

These helpers carry no task, prompt, Memory, or model content.  Callers receive
only a boolean exhaustive-proof result and must defer newer scheduling work on
``False``.
"""

from __future__ import annotations

from typing import Any

from minicode.curator_schedule import curator_completion_id

_MAX_RECOVERY_PAGES = 12
_PAGE_LIMIT = 1_000


def turn_recovery_scan_budget(turn_store: Any) -> int:
    """Return the store's explicit one-pass Turn recovery bound.

    ``ConversationTurnStore.scan_limit`` bounds the number of durable records
    that one scan can classify.  Consumers use the same bound for unique
    recovery records, instead of an unrelated fixed page count.  Compatibility
    stores without that contract retain one bounded page of work.
    """

    value = getattr(turn_store, "scan_limit", _PAGE_LIMIT)
    if isinstance(value, bool) or not isinstance(value, int) or value < 1:
        return _PAGE_LIMIT
    return value


def reconcile_run_curator_outbox(
    journal: Any,
    schedule: Any,
) -> bool:
    """Drain the durable CLI Run outbox through the shared scheduler."""

    scanner = getattr(journal, "scan_pending_curator_completions", None)
    beginner = getattr(journal, "begin_curator_completion_delivery", None)
    acknowledger = getattr(journal, "acknowledge_curator_completion", None)
    settler = getattr(journal, "settle_curator_completion", None)
    if not all(
        callable(method)
        for method in (scanner, beginner, acknowledger, settler)
    ):
        # Compatibility journals have no durable curator producer and cannot
        # contribute workspace pins.
        return True
    try:
        with schedule.delivery_fence():
            for _ in range(_MAX_RECOVERY_PAGES):
                scan = scanner(limit=_PAGE_LIMIT)
                release_items = tuple(getattr(scan, "release_items", ()))
                delivery_items = tuple(getattr(scan, "items", ()))
                if not release_items and not delivery_items:
                    return bool(getattr(scan, "exhaustive", False))
                progressed = False
                for run_id, completion_id in release_items:
                    schedule.acknowledge_completion(completion_id)
                    if settler(run_id, completion_id) is not True:
                        return False
                    progressed = True
                for run_id, completion_id in delivery_items:
                    if beginner(run_id, completion_id) is not True:
                        return False
                    schedule.record_completion(
                        completion_id,
                        pin=True,
                        promote_existing=True,
                    )
                    if acknowledger(run_id, completion_id) is not True:
                        return False
                    schedule.acknowledge_completion(completion_id)
                    if settler(run_id, completion_id) is not True:
                        return False
                    progressed = True
                if not progressed:
                    return False
    except Exception:
        return False
    return False


def reconcile_turn_curator_outbox(
    turn_store: Any,
    schedule: Any,
) -> bool:
    """Drain recoverable Dashboard Turn receipts through the scheduler.

    A completed Turn is itself proof that Session commit succeeded.  A
    committing Turn may be recovered here only when the scheduler still holds
    its pin (delivery happened) or the Turn already durably recorded the
    producer acknowledgement.  Other committing records remain content
    recovery concerns and do not block unrelated scheduling.
    """

    scanner = getattr(turn_store, "curator_receipt_recovery_records", None)
    mark_recorded = getattr(turn_store, "mark_curator_receipt_recorded", None)
    mark_settled = getattr(turn_store, "mark_curator_receipt_settled", None)
    if not all(callable(method) for method in (scanner, mark_recorded, mark_settled)):
        return True
    try:
        with schedule.delivery_fence():
            scan_budget = turn_recovery_scan_budget(turn_store)
            observed_turn_ids: set[str] = set()
            while True:
                remaining = scan_budget - len(observed_turn_ids)
                scan = scanner(
                    limit=min(
                        _PAGE_LIMIT,
                        max(1, remaining),
                    )
                )
                records = tuple(getattr(scan, "items", ()))
                if not records:
                    return bool(getattr(scan, "exhaustive", False))
                page_turn_ids = {
                    turn_id
                    for turn_id in (
                        getattr(record, "turn_id", None)
                        for record in records
                    )
                    if isinstance(turn_id, str)
                }
                newly_observed = page_turn_ids - observed_turn_ids
                if len(newly_observed) > remaining:
                    return False
                observed_turn_ids.update(page_turn_ids)
                pinned = frozenset(schedule.snapshot().pinned_completion_ids)
                progressed = False
                actionable = False
                for record in records:
                    if bool(
                        getattr(record, "curator_receipt_settled", False)
                    ):
                        # Session-to-Turn content recovery is independent of
                        # this already-finished scheduler handshake.
                        continue
                    completion_id = curator_completion_id(
                        getattr(record, "run_id", None),
                        getattr(record, "turn_id", None),
                    )
                    if completion_id is None:
                        return False
                    recorded = bool(
                        getattr(record, "curator_receipt_recorded", False)
                    )
                    status = getattr(record, "status", None)
                    if recorded:
                        actionable = True
                    elif status == "completed" or completion_id in pinned:
                        actionable = True
                        schedule.record_completion(
                            completion_id,
                            pin=True,
                            promote_existing=True,
                        )
                        record = mark_recorded(record.turn_id)
                    else:
                        # A committing, unrecorded Turn with no scheduler pin
                        # has not changed scheduling state. Session recovery is
                        # owned by ConversationTurnService.
                        continue
                    schedule.acknowledge_completion(completion_id)
                    settled = mark_settled(record.turn_id)
                    if not bool(
                        getattr(settled, "curator_receipt_settled", False)
                    ):
                        return False
                    progressed = True
                if not actionable:
                    unsafe = set(getattr(scan, "diagnostics", ())) - {
                        "curator_receipt_page_limited"
                    }
                    return not unsafe
                if not progressed:
                    return False
                if not newly_observed:
                    # A non-exhaustive scanner that repeats an unchanged page
                    # cannot prove forward progress. Fail closed instead of
                    # spinning inside the configured recovery bound.
                    return False
    except Exception:
        return False
    return False


__all__ = [
    "reconcile_run_curator_outbox",
    "reconcile_turn_curator_outbox",
    "turn_recovery_scan_budget",
]

shared_files.minicode/cybernetic_supervisor.py:
"""Unified cybernetic supervisor dashboard.

The supervisor does not replace individual controllers. It aggregates their
outputs into a single health/risk summary so runtime code can log, display, or
act on the combined control state.
"""

from __future__ import annotations

import json
from dataclasses import dataclass, field
from enum import Enum
from typing import Any

from minicode.config import MINI_CODE_DIR


SUPERVISOR_STATE_PATH = MINI_CODE_DIR / "cybernetic_supervisor.json"


class SupervisorRisk(str, Enum):
    LOW = "low"
    MEDIUM = "medium"
    HIGH = "high"
    CRITICAL = "critical"


@dataclass
class ControlSnapshot:
    name: str
    health: float = 1.0
    risk: float = 0.0
    action: str = "continue"
    reasons: list[str] = field(default_factory=list)
    raw: dict[str, Any] = field(default_factory=dict)

    def to_dict(self) -> dict[str, Any]:
        return {
            "name": self.name,
            "health": round(self.health, 3),
            "risk": round(self.risk, 3),
            "action": self.action,
            "reasons": list(self.reasons),
            "raw": dict(self.raw),
        }


@dataclass
class SupervisorReport:
    overall_health: float
    risk_level: SupervisorRisk
    snapshots: list[ControlSnapshot]
    recommended_actions: list[str] = field(default_factory=list)

    def to_dict(self) -> dict[str, Any]:
        return {
            "overall_health": round(self.overall_health, 3),
            "risk_level": self.risk_level.value,
            "snapshots": [s.to_dict() for s in self.snapshots],
            "recommended_actions": list(self.recommended_actions),
        }

    def format_summary(self) -> str:
        lines = [
            "Cybernetic Supervisor",
            f"  overall_health: {self.overall_health:.2f}",
            f"  risk_level: {self.risk_level.value}",
        ]
        if self.recommended_actions:
            lines.append("  actions:")
            for action in self.recommended_actions[:5]:
                lines.append(f"    - {action}")
        return "\n".join(lines)

    @classmethod
    def from_dict(cls, data: dict[str, Any]) -> "SupervisorReport":
        snapshots = [
            ControlSnapshot(
                name=str(item.get("name", "")),
                health=float(item.get("health", 1.0) or 0.0),
                risk=float(item.get("risk", 0.0) or 0.0),
                action=str(item.get("action", "continue")),
                reasons=[str(r) for r in item.get("reasons", [])],
                raw=item.get("raw", {}) if isinstance(item.get("raw"), dict) else {},
            )
            for item in data.get("snapshots", [])
            if isinstance(item, dict)
        ]
        return cls(
            overall_health=float(data.get("overall_health", 1.0) or 0.0),
            risk_level=SupervisorRisk(str(data.get("risk_level", "low"))),
            snapshots=snapshots,
            recommended_actions=[str(a) for a in data.get("recommended_actions", [])],
        )


class CyberneticSupervisor:
    """Aggregate controller outputs into a runtime health report."""

    def report(self, snapshots: list[ControlSnapshot]) -> SupervisorReport:
        if not snapshots:
            return SupervisorReport(
                overall_health=1.0,
                risk_level=SupervisorRisk.LOW,
                snapshots=[],
                recommended_actions=["continue current execution"],
            )

        health = sum(max(0.0, min(1.0, s.health)) for s in snapshots) / len(snapshots)
        max_risk = max(max(0.0, min(1.0, s.risk)) for s in snapshots)
        risk_level = self._risk_level(max_risk, health)
        actions = self._recommended_actions(snapshots, risk_level)
        return SupervisorReport(
            overall_health=health,
            risk_level=risk_level,
            snapshots=snapshots,
            recommended_actions=actions,
        )

    def snapshot_from_context(self, stats: dict[str, Any] | None) -> ControlSnapshot:
        stats = stats or {}
        sensor = stats.get("sensor", {}) if isinstance(stats.get("sensor"), dict) else {}
        predictor = stats.get("predictor", {}) if isinstance(stats.get("predictor"), dict) else {}
        usage = float(sensor.get("current_usage", 0.0) or 0.0)
        urgency = float(predictor.get("urgency", 0.0) or 0.0)
        risk = max(usage, urgency)
        action = "compact" if risk >= 0.80 else "monitor"
        return ControlSnapshot(
            name="context",
            health=1.0 - min(1.0, risk),
            risk=risk,
            action=action,
            reasons=[f"usage={usage:.2f}", f"urgency={urgency:.2f}"],
            raw=stats,
        )

    def snapshot_from_cost(self, stats: dict[str, Any] | None) -> ControlSnapshot:
        stats = stats or {}
        sensor = stats.get("sensor", {}) if isinstance(stats.get("sensor"), dict) else {}
        adjustment = stats.get("adjustment", {}) if isinstance(stats.get("adjustment"), dict) else {}
        cost_per_min = float(sensor.get("cost_per_min", 0.0) or 0.0)
        multiplier = float(adjustment.get("budget_mult", 1.0) or 1.0)
        risk = min(1.0, cost_per_min)
        action = "tighten_budget" if multiplier < 0.8 or risk >= 0.7 else "monitor"
        return ControlSnapshot(
            name="cost",
            health=1.0 - risk,
            risk=risk,
            action=action,
            reasons=[f"cost_per_min={cost_per_min:.3f}", f"budget_mult={multiplier:.2f}"],
            raw=stats,
        )

    def snapshot_from_decision(self, name: str, data: dict[str, Any] | None) -> ControlSnapshot:
        data = data or {}
        action = str(data.get("action") or data.get("mode") or "continue")
        risk = self._risk_from_decision(data)
        health = float(data.get("health_score", 1.0 - risk) or 0.0)
        reasons = data.get("reasons", [])
        if not isinstance(reasons, list):
            reasons = [str(reasons)]
        return ControlSnapshot(
            name=name,
            health=max(0.0, min(1.0, health)),
            risk=risk,
            action=action,
            reasons=[str(r) for r in reasons],
            raw=data,
        )

    def snapshot_from_tool_decision(self, data: dict[str, Any] | None) -> ControlSnapshot:
        data = data or {}
        multiplier = float(data.get("concurrency_multiplier", 1.0) or 1.0)
        cooldown = float(data.get("cooldown_seconds", 0.0) or 0.0)
        backoff = float(data.get("retry_backoff_multiplier", 1.0) or 1.0)
        risk = max(0.0, min(1.0, (1.0 - multiplier) + min(0.5, cooldown / 4.0)))
        action = "reduce_parallelism" if multiplier < 0.75 else "monitor"
        if backoff > 1.5:
            action = "increase_retry_backoff"
        reasons = data.get("reasons", [])
        if not isinstance(reasons, list):
            reasons = [str(reasons)]
        return ControlSnapshot(
            name="tool_scheduling",
            health=1.0 - risk,
            risk=risk,
            action=action,
            reasons=[str(r) for r in reasons],
            raw=data,
        )

    def _risk_from_decision(self, data: dict[str, Any]) -> float:
        if "stall_score" in data:
            return float(data.get("stall_score") or 0.0)
        risk_value = str(data.get("risk", "")).lower()
        if risk_value == "critical":
            return 1.0
        if risk_value == "high":
            return 0.75
        if risk_value == "medium":
            return 0.45
        if risk_value == "low":
            return 0.15
        mode = str(data.get("mode", "")).lower()
        if mode in {"none", "continue", "standard"}:
            return 0.10
        if mode in {"summary", "smoke", "targeted"}:
            return 0.35
        if mode in {"full", "strong"}:
            return 0.65
        return 0.0

    def _risk_level(self, max_risk: float, health: float) -> SupervisorRisk:
        if max_risk >= 0.90 or health < 0.25:
            return SupervisorRisk.CRITICAL
        if max_risk >= 0.70 or health < 0.45:
            return SupervisorRisk.HIGH
        if max_risk >= 0.40 or health < 0.70:
            return SupervisorRisk.MEDIUM
        return SupervisorRisk.LOW

    def _recommended_actions(
        self,
        snapshots: list[ControlSnapshot],
        risk_level: SupervisorRisk,
    ) -> list[str]:
        actions: list[str] = []
        for snap in sorted(snapshots, key=lambda s: s.risk, reverse=True):
            if snap.risk >= 0.40 or snap.action not in {"continue", "monitor", "standard"}:
                actions.append(f"{snap.name}: {snap.action}")
        if not actions:
            actions.append("continue current execution")
        if risk_level in {SupervisorRisk.HIGH, SupervisorRisk.CRITICAL}:
            actions.append("summarize state before further expansion")
        return self._dedupe(actions)

    def _dedupe(self, items: list[str]) -> list[str]:
        seen: set[str] = set()
        out: list[str] = []
        for item in items:
            if item not in seen:
                seen.add(item)
                out.append(item)
        return out


def save_supervisor_report(report: SupervisorReport) -> None:
    """Persist the latest supervisor report for slash-command diagnostics."""
    SUPERVISOR_STATE_PATH.parent.mkdir(parents=True, exist_ok=True)
    SUPERVISOR_STATE_PATH.write_text(
        json.dumps(report.to_dict(), indent=2, ensure_ascii=False),
        encoding="utf-8",
    )


def load_supervisor_report() -> SupervisorReport | None:
    """Load the latest persisted supervisor report, if present."""
    if not SUPERVISOR_STATE_PATH.exists():
        return None
    try:
        data = json.loads(SUPERVISOR_STATE_PATH.read_text(encoding="utf-8"))
        if not isinstance(data, dict):
            return None
        return SupervisorReport.from_dict(data)
    except (OSError, json.JSONDecodeError, ValueError):
        return None

shared_files.minicode/decoupling_controller.py:
"""Multi-variable Decoupling Controller based on Engineering Cybernetics.

钱学森工程控制论核心原理:
- 多变量系统：多个输入输出相互耦合的复杂系统
- 解耦控制：消除变量间相互影响，实现独立控制
- 前馈补偿：预测耦合效应并提前补偿

This module implements:
1. Coupling matrix analysis
2. Decoupling controller design
3. Feedforward compensation for coupling effects
4. Relative gain array (RGA) analysis
"""
from __future__ import annotations

import math
import time
from dataclasses import dataclass, field
from typing import Any


@dataclass
class CouplingMatrix:
    """Coupling strength between system variables."""
    token_usage_to_latency: float = 0.0
    context_pressure_to_errors: float = 0.0
    concurrency_to_stability: float = 0.0
    model_level_to_cost: float = 0.0
    skill_complexity_to_timeout: float = 0.0
    timestamp: float = field(default_factory=time.time)

    def to_matrix(self) -> list[list[float]]:
        return [
            [1.0, self.token_usage_to_latency, self.context_pressure_to_errors],
            [self.token_usage_to_latency, 1.0, self.concurrency_to_stability],
            [self.context_pressure_to_errors, self.concurrency_to_stability, 1.0],
        ]


@dataclass
class DecoupledCommand:
    """Decoupled control command."""
    variable_name: str
    original_command: float
    coupling_compensation: float
    final_command: float
    confidence: float = 1.0
    reasoning: str = ""


class CouplingAnalyzer:
    """Analyze coupling between system variables.

    耦合分析器:
    识别系统中变量间的相互影响关系。
    """

    def __init__(self, window_size: int = 50):
        self._window_size = window_size
        self._history_a: list[float] = []
        self._history_b: list[float] = []
        self._sample_count: int = 0

    def add_sample(self, var_a: float, var_b: float) -> None:
        self._history_a.append(var_a)
        self._history_b.append(var_b)
        self._sample_count += 1

        if len(self._history_a) > self._window_size:
            self._history_a.pop(0)
        if len(self._history_b) > self._window_size:
            self._history_b.pop(0)

    def compute_coupling(self) -> float:
        if len(self._history_a) < 5:
            return 0.0

        correlation = self._pearson_correlation(self._history_a, self._history_b)
        return abs(correlation)

    def compute_time_lagged_coupling(self, lag: int = 1) -> float:
        if len(self._history_a) < lag + 3:
            return 0.0

        var_a_lagged = self._history_a[:-lag] if lag > 0 else self._history_a
        var_b_shifted = self._history_b[lag:] if lag > 0 else self._history_b

        if len(var_a_lagged) < 3 or len(var_b_shifted) < 3:
            return 0.0

        return abs(self._pearson_correlation(var_a_lagged, var_b_shifted))

    def get_coupling_matrix(self) -> CouplingMatrix:
        return CouplingMatrix(
            token_usage_to_latency=self.compute_coupling(),
            context_pressure_to_errors=self.compute_coupling(),
            concurrency_to_stability=self.compute_coupling(),
            model_level_to_cost=self.compute_coupling(),
            skill_complexity_to_timeout=self.compute_coupling(),
        )

    def reset(self) -> None:
        self._history_a = []
        self._history_b = []
        self._sample_count = 0

    def _pearson_correlation(self, x: list[float], y: list[float]) -> float:
        n = min(len(x), len(y))
        if n < 3:
            return 0.0

        x = x[-n:]
        y = y[-n:]

        x_mean = sum(x) / n
        y_mean = sum(y) / n

        numerator = sum((x[i] - x_mean) * (y[i] - y_mean) for i in range(n))

        x_var = sum((xi - x_mean) ** 2 for xi in x)
        y_var = sum((yi - y_mean) ** 2 for yi in y)

        denominator = math.sqrt(x_var * y_var)
        if denominator == 0:
            return 0.0

        return numerator / denominator


class DecouplingController:
    """Multi-variable decoupling controller.

    多变量解耦控制器:
    ┌──────────────────────────────────────────────────────────┐
    │  控制输入 ─→ 解耦网络 ─→ 独立控制通道 ─→ 系统           │
    │    (u1, u2)     (消除耦合)     (独立调节)                │
    │                    ↓                                     │
    │              前馈耦合补偿                                 │
    └──────────────────────────────────────────────────────────┘

    Features:
    - Real-time coupling analysis
    - Decoupling matrix computation
    - Feedforward coupling compensation
    - RGA-based input-output pairing
    """

    def __init__(self):
        self._coupling_analyzers: dict[str, CouplingAnalyzer] = {}
        self._decoupling_matrix: dict[str, dict[str, float]] = {}
        self._command_history: list[DecoupledCommand] = []
        self._max_history = 50

        self._coupling_compensation: dict[str, float] = {}

        self._init_coupling_pairs()

    def _init_coupling_pairs(self) -> None:
        pairs = [
            ("token_usage", "latency"),
            ("context_pressure", "error_rate"),
            ("concurrency", "stability"),
            ("model_level", "cost"),
            ("skill_complexity", "timeout"),
        ]
        for var_a, var_b in pairs:
            key = f"{var_a}_to_{var_b}"
            self._coupling_analyzers[key] = CouplingAnalyzer()
            self._coupling_compensation[key] = 0.0

    def record_measurement(self, variable_pairs: dict[str, tuple[float, float]]) -> None:
        for key, (val_a, val_b) in variable_pairs.items():
            if key in self._coupling_analyzers:
                self._coupling_analyzers[key].add_sample(val_a, val_b)

    def compute_decoupling_matrix(self) -> dict[str, dict[str, float]]:
        self._decoupling_matrix = {}

        for key, analyzer in self._coupling_analyzers.items():
            coupling_strength = analyzer.compute_coupling()

            var_a, var_b = key.split("_to_")
            if var_a not in self._decoupling_matrix:
                self._decoupling_matrix[var_a] = {}
            if var_b not in self._decoupling_matrix:
                self._decoupling_matrix[var_b] = {}

            self._decoupling_matrix[var_a][var_b] = coupling_strength
            self._decoupling_matrix[var_b][var_a] = coupling_strength

        return self._decoupling_matrix

    def decouple_command(self, variable_name: str, raw_command: float,
                         other_variables: dict[str, float]) -> DecoupledCommand:
        coupling_compensation = 0.0

        if variable_name in self._decoupling_matrix:
            for other_var, coupling_strength in self._decoupling_matrix[variable_name].items():
                if other_var in other_variables:
                    coupling_compensation += coupling_strength * other_variables[other_var] * 0.5

        final_command = raw_command - coupling_compensation
        final_command = max(-1.0, min(1.0, final_command))

        command = DecoupledCommand(
            variable_name=variable_name,
            original_command=raw_command,
            coupling_compensation=coupling_compensation,
            final_command=final_command,
            confidence=max(0.3, 1.0 - coupling_compensation),
            reasoning=f"Decoupled {variable_name}: raw={raw_command:.2f}, "
                      f"compensation={coupling_compensation:.2f}, final={final_command:.2f}",
        )

        self._command_history.append(command)
        if len(self._command_history) > self._max_history:
            self._command_history.pop(0)

        return command

    def compute_feedforward_compensation(self, planned_changes: dict[str, float]) -> dict[str, float]:
        compensation = {}

        for var_a, change_a in planned_changes.items():
            total_coupling_effect = 0.0
            if var_a in self._decoupling_matrix:
                for var_b, coupling in self._decoupling_matrix[var_a].items():
                    if var_b in planned_changes:
                        total_coupling_effect += coupling * change_a * planned_changes[var_b]

            compensation[var_a] = total_coupling_effect

        return compensation

    def get_rga_pairing(self) -> list[tuple[str, str, float]]:
        rga_pairs = []

        for key, analyzer in self._coupling_analyzers.items():
            coupling = analyzer.compute_coupling()
            lagged = analyzer.compute_time_lagged_coupling(lag=1)

            if coupling > 0.3 or lagged > 0.3:
                var_a, var_b = key.split("_to_")
                rga_pairs.append((var_a, var_b, max(coupling, lagged)))

        rga_pairs.sort(key=lambda x: x[2], reverse=True)
        return rga_pairs

    def get_coupling_status(self) -> dict[str, Any]:
        status: dict[str, Any] = {
            "coupling_strengths": {},
            "compensation_values": self._coupling_compensation.copy(),
        }

        for key, analyzer in self._coupling_analyzers.items():
            coupling = analyzer.compute_coupling()
            status["coupling_strengths"][key] = coupling

        status["strong_couplings"] = [
            (k, v) for k, v in status["coupling_strengths"].items() if v > 0.5
        ]

        status["rga_pairing"] = self.get_rga_pairing()

        return status

    def reset(self) -> None:
        for analyzer in self._coupling_analyzers.values():
            analyzer.reset()
        self._decoupling_matrix = {}
        self._command_history = []
        self._coupling_compensation = {}

shared_files.minicode/deletion_store.py:
"""Content-free coordination fences and bounded deletion receipts."""

from __future__ import annotations

import hashlib
import json
import os
import re
import stat
import tempfile
import threading
import time
from contextlib import contextmanager
from dataclasses import dataclass
from datetime import datetime, timedelta, timezone
from pathlib import Path
from typing import Callable, Iterator

from minicode.advisory_lock import (
    acquire_advisory_lock,
    prepare_advisory_lock_file,
    release_advisory_lock,
)


_TARGET_RE = re.compile(r"[A-Za-z0-9][A-Za-z0-9._-]{0,159}")
_REVISION_RE = re.compile(r"delrev_[0-9a-f]{64}")
_KINDS = frozenset({"conversation", "project-memory"})
_MAX_RECORD_BYTES = 2_048
_MAX_RECEIPTS = 256
_MAX_SCAN = 512
_DEFAULT_TIMEOUT = 5.0
_DEFAULT_RECEIPT_TTL = timedelta(minutes=10)


class DeletionStoreError(RuntimeError):
    """Base fixed-vocabulary deletion coordination failure."""


class DeletionStoreBusy(DeletionStoreError):
    """The coordination lock could not be acquired in time."""


class DeletionStoreUnavailable(DeletionStoreError):
    """Deletion metadata could not be accessed safely."""


class DeletionFenceActive(DeletionStoreError):
    """A writer targeted an identity with an in-progress deletion."""


@dataclass(frozen=True, slots=True)
class DeletionRecord:
    kind: str
    target_id: str
    deletion_revision: str
    status: str
    created_at: str
    expires_at: str | None = None


_LOCKS_GUARD = threading.Lock()
_LOCKS: dict[str, threading.RLock] = {}


def _process_lock(path: Path) -> threading.RLock:
    key = os.path.abspath(os.fspath(path))
    with _LOCKS_GUARD:
        return _LOCKS.setdefault(key, threading.RLock())


def _workspace_id(workspace: str | Path) -> str:
    resolved = Path(workspace).expanduser().resolve()
    return "ws_" + hashlib.sha256(str(resolved).encode("utf-8")).hexdigest()[:16]


def _iso_time(value: datetime) -> str:
    if not isinstance(value, datetime) or value.tzinfo is None:
        raise DeletionStoreUnavailable("deletion clock unavailable")
    return value.astimezone(timezone.utc).isoformat(timespec="milliseconds").replace(
        "+00:00", "Z"
    )


def _parse_time(value: str) -> datetime:
    if not isinstance(value, str) or len(value) != 24 or not value.endswith("Z"):
        raise ValueError("invalid timestamp")
    parsed = datetime.fromisoformat(value[:-1] + "+00:00")
    if parsed.tzinfo is None or parsed.utcoffset() != timedelta(0):
        raise ValueError("invalid timestamp")
    return parsed.astimezone(timezone.utc)


class DeletionLedger:
    """Own one Workspace's safe deletion coordination and short receipts."""

    def __init__(
        self,
        workspace: str | Path,
        *,
        data_dir: str | Path,
        clock: Callable[[], datetime] = lambda: datetime.now(timezone.utc),
        timeout: float = _DEFAULT_TIMEOUT,
        receipt_ttl: timedelta = _DEFAULT_RECEIPT_TTL,
    ) -> None:
        if (
            isinstance(timeout, bool)
            or not isinstance(timeout, (int, float))
            or not 0 < float(timeout) <= 60
            or not isinstance(receipt_ttl, timedelta)
            or not 1 <= receipt_ttl.total_seconds() <= 86_400
        ):
            raise ValueError("invalid deletion ledger limits")
        self.workspace = Path(workspace).expanduser().resolve()
        self.data_dir = Path(data_dir).expanduser().resolve(strict=False)
        self.workspace_id = _workspace_id(self.workspace)
        self.root = (
            self.data_dir
            / "dashboard"
            / "workspaces"
            / self.workspace_id
            / "deletions"
        )
        self._lock_path = self.root / "coordination.lock"
        self._clock = clock
        self._timeout = float(timeout)
        self._receipt_ttl = receipt_ttl
        self._process_lock = _process_lock(self._lock_path)

    @staticmethod
    def _validate(kind: object, target_id: object) -> tuple[str, str]:
        if kind not in _KINDS:
            raise ValueError("invalid deletion kind")
        if not isinstance(target_id, str) or _TARGET_RE.fullmatch(target_id) is None:
            raise ValueError("invalid deletion target")
        return str(kind), target_id

    def _record_path(self, kind: str, target_id: str, suffix: str) -> Path:
        safe_kind, safe_target = self._validate(kind, target_id)
        identity = hashlib.sha256(safe_target.encode("ascii")).hexdigest()
        return self.root / f"{safe_kind}-{identity}.{suffix}.json"

    def _ensure_root(self) -> None:
        current = self.data_dir
        try:
            current.mkdir(parents=True, exist_ok=True, mode=0o700)
            for name in ("dashboard", "workspaces", self.workspace_id, "deletions"):
                target = current / name
                if target.is_symlink():
                    raise OSError("unsafe deletion root")
                target.mkdir(exist_ok=True, mode=0o700)
                info = os.lstat(target)
                if not stat.S_ISDIR(info.st_mode):
                    raise OSError("unsafe deletion root")
                resolved = target.resolve(strict=True)
                if not resolved.is_relative_to(self.data_dir):
                    raise OSError("unsafe deletion root")
                current = resolved
        except OSError as error:
            raise DeletionStoreUnavailable("deletion store unavailable") from error

    def _open_lock(self) -> int:
        self._ensure_root()
        flags = os.O_RDWR | os.O_CREAT | getattr(os, "O_CLOEXEC", 0)
        flags |= getattr(os, "O_NOFOLLOW", 0)
        try:
            descriptor = os.open(self._lock_path, flags, 0o600)
            info = os.fstat(descriptor)
            path_info = os.lstat(self._lock_path)
            if (
                not stat.S_ISREG(info.st_mode)
                or not stat.S_ISREG(path_info.st_mode)
                or info.st_dev != path_info.st_dev
                or info.st_ino != path_info.st_ino
            ):
                raise OSError("unsafe deletion lock")
            prepare_advisory_lock_file(descriptor, mode=0o600)
            return descriptor
        except OSError as error:
            try:
                os.close(descriptor)
            except (OSError, UnboundLocalError):
                pass
            raise DeletionStoreUnavailable("deletion store unavailable") from error

    @contextmanager
    def coordination(self) -> Iterator[None]:
        deadline = time.monotonic() + self._timeout
        if not self._process_lock.acquire(timeout=self._timeout):
            raise DeletionStoreBusy("deletion store busy")
        descriptor: int | None = None
        try:
            descriptor = self._open_lock()
            while True:
                try:
                    if acquire_advisory_lock(descriptor):
                        break
                except OSError as error:
                    raise DeletionStoreUnavailable(
                        "deletion store unavailable"
                    ) from error
                remaining = deadline - time.monotonic()
                if remaining <= 0:
                    raise DeletionStoreBusy("deletion store busy")
                time.sleep(min(0.01, remaining))
            yield
        finally:
            if descriptor is not None:
                try:
                    release_advisory_lock(descriptor)
                except OSError:
                    pass
                os.close(descriptor)
            self._process_lock.release()

    def _read(self, path: Path) -> DeletionRecord | None:
        flags = os.O_RDONLY | getattr(os, "O_CLOEXEC", 0)
        flags |= getattr(os, "O_NOFOLLOW", 0)
        try:
            descriptor = os.open(path, flags)
        except FileNotFoundError:
            return None
        except OSError as error:
            raise DeletionStoreUnavailable("deletion store unavailable") from error
        try:
            info = os.fstat(descriptor)
            path_info = os.lstat(path)
            if (
                not stat.S_ISREG(info.st_mode)
                or not stat.S_ISREG(path_info.st_mode)
                or info.st_dev != path_info.st_dev
                or info.st_ino != path_info.st_ino
                or info.st_size > _MAX_RECORD_BYTES
            ):
                raise DeletionStoreUnavailable("deletion store unavailable")
            raw = os.read(descriptor, _MAX_RECORD_BYTES + 1)
            parsed = json.loads(raw.decode("utf-8"))
            if not isinstance(parsed, dict) or set(parsed) not in (
                {"schemaVersion", "kind", "targetId", "deletionRevision", "status", "createdAt"},
                {"schemaVersion", "kind", "targetId", "deletionRevision", "status", "createdAt", "expiresAt"},
            ):
                raise ValueError("invalid deletion record")
            record = DeletionRecord(
                kind=parsed["kind"],
                target_id=parsed["targetId"],
                deletion_revision=parsed["deletionRevision"],
                status=parsed["status"],
                created_at=parsed["createdAt"],
                expires_at=parsed.get("expiresAt"),
            )
            if (
                parsed["schemaVersion"] != 1
                or record.kind not in _KINDS
                or _TARGET_RE.fullmatch(record.target_id) is None
                or _REVISION_RE.fullmatch(record.deletion_revision) is None
                or record.status not in {"in_progress", "completed"}
                or (record.status == "in_progress") != (record.expires_at is None)
            ):
                raise ValueError("invalid deletion record")
            _parse_time(record.created_at)
            if record.expires_at is not None:
                _parse_time(record.expires_at)
            return record
        except (KeyError, TypeError, ValueError, UnicodeDecodeError, json.JSONDecodeError) as error:
            raise DeletionStoreUnavailable("deletion store unavailable") from error
        finally:
            os.close(descriptor)

    def read_fence(self, kind: str, target_id: str) -> DeletionRecord | None:
        return self._read(self._record_path(kind, target_id, "fence"))

    def read_receipt(self, kind: str, target_id: str) -> DeletionRecord | None:
        record = self._read(self._record_path(kind, target_id, "receipt"))
        if record is None or record.expires_at is None:
            return record
        return record if _parse_time(record.expires_at) > self._clock() else None

    @staticmethod
    def _encoded(record: DeletionRecord) -> bytes:
        payload: dict[str, object] = {
            "schemaVersion": 1,
            "kind": record.kind,
            "targetId": record.target_id,
            "deletionRevision": record.deletion_revision,
            "status": record.status,
            "createdAt": record.created_at,
        }
        if record.expires_at is not None:
            payload["expiresAt"] = record.expires_at
        encoded = (json.dumps(payload, sort_keys=True, separators=(",", ":")) + "\n").encode(
            "utf-8"
        )
        if len(encoded) > _MAX_RECORD_BYTES:
            raise DeletionStoreUnavailable("deletion record too large")
        return encoded

    def _atomic_write(self, path: Path, record: DeletionRecord, *, exclusive: bool) -> None:
        self._ensure_root()
        encoded = self._encoded(record)
        if exclusive:
            flags = os.O_WRONLY | os.O_CREAT | os.O_EXCL
            flags |= getattr(os, "O_CLOEXEC", 0) | getattr(os, "O_NOFOLLOW", 0)
            descriptor = os.open(path, flags, 0o600)
            try:
                if os.write(descriptor, encoded) != len(encoded):
                    raise OSError("short deletion record write")
                os.fsync(descriptor)
            finally:
                os.close(descriptor)
            return
        descriptor, temporary = tempfile.mkstemp(
            prefix=".deletion-", suffix=".tmp", dir=self.root
        )
        try:
            if os.name == "posix":
                os.fchmod(descriptor, 0o600)
            # Atomic replacement must happen after the temporary descriptor is
            # closed: Windows does not permit replacing an open file.
            handle = os.fdopen(descriptor, "wb", closefd=True)
            descriptor = -1
            with handle:
                handle.write(encoded)
                handle.flush()
                os.fsync(handle.fileno())
            os.replace(temporary, path)
            temporary = ""
        finally:
            try:
                os.close(descriptor)
            except OSError:
                pass
            if temporary:
                try:
                    os.unlink(temporary)
                except OSError:
                    pass

    def start(self, kind: str, target_id: str, deletion_revision: str) -> DeletionRecord:
        if _REVISION_RE.fullmatch(deletion_revision) is None:
            raise ValueError("invalid deletion revision")
        existing = self.read_fence(kind, target_id)
        if existing is not None:
            return existing
        record = DeletionRecord(
            kind=kind,
            target_id=target_id,
            deletion_revision=deletion_revision,
            status="in_progress",
            created_at=_iso_time(self._clock()),
        )
        try:
            self._atomic_write(
                self._record_path(kind, target_id, "fence"), record, exclusive=True
            )
        except FileExistsError:
            existing = self.read_fence(kind, target_id)
            if existing is None:
                raise DeletionStoreUnavailable("deletion fence unavailable")
            return existing
        return record

    def abandon(self, kind: str, target_id: str) -> None:
        path = self._record_path(kind, target_id, "fence")
        try:
            if path.is_symlink():
                raise OSError("unsafe deletion fence")
            path.unlink()
        except FileNotFoundError:
            return
        except OSError as error:
            raise DeletionStoreUnavailable("deletion fence unavailable") from error

    def complete(self, kind: str, target_id: str, deletion_revision: str) -> DeletionRecord:
        now = self._clock().astimezone(timezone.utc)
        record = DeletionRecord(
            kind=kind,
            target_id=target_id,
            deletion_revision=deletion_revision,
            status="completed",
            created_at=_iso_time(now),
            expires_at=_iso_time(now + self._receipt_ttl),
        )
        self._atomic_write(
            self._record_path(kind, target_id, "receipt"), record, exclusive=False
        )
        self.abandon(kind, target_id)
        self._cleanup_receipts(now)
        return record

    def _cleanup_receipts(self, now: datetime) -> None:
        try:
            candidates = []
            with os.scandir(self.root) as scanner:
                for index, entry in enumerate(scanner):
                    if index >= _MAX_SCAN:
                        break
                    if entry.name.endswith(".receipt.json") and not entry.is_symlink():
                        candidates.append(Path(entry.path))
            live: list[tuple[datetime, Path]] = []
            for path in candidates:
                try:
                    record = self._read(path)
                    if record is None or record.expires_at is None:
                        continue
                    expiry = _parse_time(record.expires_at)
                    if expiry <= now:
                        path.unlink()
                    else:
                        live.append((expiry, path))
                except (DeletionStoreError, OSError, ValueError):
                    continue
            for _, path in sorted(live)[: max(0, len(live) - _MAX_RECEIPTS)]:
                try:
                    path.unlink()
                except OSError:
                    pass
        except OSError:
            return

    @contextmanager
    def writer_guard(self, kind: str, target_id: str) -> Iterator[None]:
        with self.coordination():
            if self.read_fence(kind, target_id) is not None:
                raise DeletionFenceActive("deletion in progress")
            yield


@contextmanager
def conversation_write_guard(
    workspace: str | Path,
    session_id: str,
    *,
    data_dir: str | Path,
) -> Iterator[None]:
    ledger = DeletionLedger(workspace, data_dir=data_dir)
    with ledger.writer_guard("conversation", session_id):
        yield


__all__ = [
    "DeletionFenceActive",
    "DeletionLedger",
    "DeletionRecord",
    "DeletionStoreBusy",
    "DeletionStoreError",
    "DeletionStoreUnavailable",
    "conversation_write_guard",
]

shared_files.minicode/env_file.py:
"""Minimal ``.env`` file loading (no third-party dependency).

The repository ships a ``.env.example`` describing its environment knobs.
This module provides bounded parsing for callers that explicitly choose a
configuration file and trust boundary; it never discovers or applies a
workspace file implicitly.

Semantics:
- ``KEY=VALUE`` lines; ``#`` comments and blank lines ignored;
- surrounding quotes on the value are stripped; a leading ``export `` is
  tolerated;
- ``read_env_files`` merges in order (later files win) without touching the
  process environment;
- ``apply_env_file`` imports values into ``os.environ`` only for keys not
  already set, so real environment variables always take precedence.
"""

from __future__ import annotations

import json
import logging
import os
import re
import stat
import tempfile
from collections.abc import Collection, Mapping
from contextlib import contextmanager
from pathlib import Path
from typing import Iterator

logger = logging.getLogger(__name__)

_MAX_FILE_BYTES = 256 * 1024
_MAX_LINES = 2_000
_PRIVATE_DIRECTORY_MODE = 0o700
_PRIVATE_FILE_MODE = 0o600
_ENV_KEY_PATTERN = re.compile(r"[A-Za-z_][A-Za-z0-9_]*\Z")


class _PrivateEnvError(RuntimeError):
    """Credential-safe failure carrying only a stable reason code."""


def _private_error(reason: str) -> _PrivateEnvError:
    return _PrivateEnvError(reason)


def _validated_allowed_keys(
    allowed_keys: Collection[str] | None,
) -> frozenset[str] | None:
    if allowed_keys is None:
        return None
    if isinstance(allowed_keys, (str, bytes)):
        raise _private_error("private_env_allowed_key_invalid")
    try:
        candidates = tuple(allowed_keys)
    except TypeError:
        raise _private_error("private_env_allowed_key_invalid") from None
    if any(
        not isinstance(key, str) or _ENV_KEY_PATTERN.fullmatch(key) is None
        for key in candidates
    ):
        raise _private_error("private_env_allowed_key_invalid")
    return frozenset(candidates)


def _check_private_directory(directory: Path) -> None:
    try:
        metadata = os.lstat(directory)
    except OSError:
        raise _private_error("private_env_directory_unavailable") from None
    if stat.S_ISLNK(metadata.st_mode):
        raise _private_error("private_env_directory_symlink")
    if not stat.S_ISDIR(metadata.st_mode):
        raise _private_error("private_env_parent_not_directory")
    if os.name == "posix":
        if metadata.st_uid != os.geteuid():
            raise _private_error("private_env_directory_owner_unsafe")
        if stat.S_IMODE(metadata.st_mode) & 0o077:
            raise _private_error("private_env_directory_permissions_unsafe")


def _check_private_file_metadata(metadata: os.stat_result) -> None:
    if stat.S_ISLNK(metadata.st_mode):
        raise _private_error("private_env_symlink")
    if not stat.S_ISREG(metadata.st_mode):
        raise _private_error("private_env_not_regular")
    if metadata.st_size > _MAX_FILE_BYTES:
        raise _private_error("private_env_too_large")
    if os.name == "posix":
        if metadata.st_uid != os.geteuid():
            raise _private_error("private_env_owner_unsafe")
        if stat.S_IMODE(metadata.st_mode) & 0o077:
            raise _private_error("private_env_permissions_unsafe")


def _read_private_bytes(path: Path) -> bytes | None:
    try:
        metadata = os.lstat(path)
    except FileNotFoundError:
        return None
    except OSError:
        raise _private_error("private_env_unreadable") from None

    _check_private_directory(path.parent)
    _check_private_file_metadata(metadata)
    flags = os.O_RDONLY
    if hasattr(os, "O_NOFOLLOW"):
        flags |= os.O_NOFOLLOW
    try:
        descriptor = os.open(path, flags)
    except OSError:
        raise _private_error("private_env_unreadable") from None
    try:
        opened_metadata = os.fstat(descriptor)
        _check_private_file_metadata(opened_metadata)
        if (
            opened_metadata.st_dev != metadata.st_dev
            or opened_metadata.st_ino != metadata.st_ino
        ):
            raise _private_error("private_env_changed_during_open")
        with os.fdopen(descriptor, "rb", closefd=True) as handle:
            descriptor = -1
            payload = handle.read(_MAX_FILE_BYTES + 1)
    except OSError:
        raise _private_error("private_env_unreadable") from None
    finally:
        if descriptor >= 0:
            os.close(descriptor)
    if len(payload) > _MAX_FILE_BYTES:
        raise _private_error("private_env_too_large")
    return payload


def _decode_private_value(raw_value: str) -> str:
    value = raw_value.strip()
    if not value:
        return ""
    if value.startswith('"') or value.endswith('"'):
        if not (value.startswith('"') and value.endswith('"')):
            raise _private_error("private_env_value_quote_invalid")
        try:
            decoded = json.loads(value)
        except (TypeError, ValueError):
            raise _private_error("private_env_value_quote_invalid") from None
        if not isinstance(decoded, str):
            raise _private_error("private_env_value_invalid")
        value = decoded
    elif value.startswith("'") or value.endswith("'"):
        if not (value.startswith("'") and value.endswith("'")):
            raise _private_error("private_env_value_quote_invalid")
        value = value[1:-1]
    if any(character in value for character in ("\x00", "\r", "\n")):
        raise _private_error("private_env_value_invalid")
    return value


def _parse_private_env(payload: bytes) -> dict[str, str]:
    if b"\x00" in payload:
        raise _private_error("private_env_value_invalid")
    try:
        text = payload.decode("utf-8", errors="strict")
    except UnicodeDecodeError:
        raise _private_error("private_env_utf8_invalid") from None
    lines = text.splitlines()
    if len(lines) > _MAX_LINES:
        raise _private_error("private_env_too_many_lines")

    values: dict[str, str] = {}
    for raw_line in lines:
        stripped = raw_line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        if stripped.startswith("export "):
            stripped = stripped[len("export "):].strip()
        if "=" not in stripped:
            raise _private_error("private_env_line_invalid")
        key, _, raw_value = stripped.partition("=")
        key = key.strip()
        if _ENV_KEY_PATTERN.fullmatch(key) is None:
            raise _private_error("private_env_key_invalid")
        if key in values:
            raise _private_error("private_env_duplicate_key")
        values[key] = _decode_private_value(raw_value)
    return values


def read_private_env_file(
    path: str | Path,
    *,
    allowed_keys: Collection[str] | None = None,
) -> dict[str, str]:
    """Read an owner-private env file without mutating ``os.environ``.

    Missing files return an empty mapping. Existing files fail closed when
    their type, ownership, permissions, encoding, grammar, or limits are
    unsafe. When ``allowed_keys`` is supplied, valid unknown entries remain
    on disk but are not returned to the caller.
    """
    allowed = _validated_allowed_keys(allowed_keys)
    payload = _read_private_bytes(Path(path))
    if payload is None:
        return {}
    values = _parse_private_env(payload)
    if allowed is None:
        return values
    return {key: value for key, value in values.items() if key in allowed}


def _ensure_private_directory(directory: Path) -> None:
    try:
        directory.mkdir(parents=True, mode=_PRIVATE_DIRECTORY_MODE, exist_ok=True)
    except OSError:
        raise _private_error("private_env_directory_unavailable") from None
    try:
        metadata = os.lstat(directory)
    except OSError:
        raise _private_error("private_env_directory_unavailable") from None
    if stat.S_ISLNK(metadata.st_mode):
        raise _private_error("private_env_directory_symlink")
    if not stat.S_ISDIR(metadata.st_mode):
        raise _private_error("private_env_parent_not_directory")
    if os.name == "posix":
        if metadata.st_uid != os.geteuid():
            raise _private_error("private_env_directory_owner_unsafe")
        try:
            os.chmod(directory, _PRIVATE_DIRECTORY_MODE)
        except OSError:
            raise _private_error("private_env_directory_permissions_unsafe") from None
    _check_private_directory(directory)


def _serialize_private_env(values: Mapping[str, str]) -> bytes:
    lines = [
        f"{key}={json.dumps(value, ensure_ascii=True)}\n"
        for key, value in sorted(values.items())
    ]
    payload = "".join(lines).encode("utf-8")
    if len(lines) > _MAX_LINES:
        raise _private_error("private_env_too_many_lines")
    if len(payload) > _MAX_FILE_BYTES:
        raise _private_error("private_env_too_large")
    return payload


def _fsync_directory(directory: Path) -> None:
    if os.name != "posix":
        return
    flags = os.O_RDONLY
    if hasattr(os, "O_DIRECTORY"):
        flags |= os.O_DIRECTORY
    try:
        descriptor = os.open(directory, flags)
        try:
            os.fsync(descriptor)
        finally:
            os.close(descriptor)
    except OSError:
        raise _private_error("private_env_directory_sync_failed") from None


@contextmanager
def _private_env_write_lock(destination: Path) -> Iterator[None]:
    lock_path = destination.parent / f".{destination.name}.lock"
    flags = os.O_CREAT | os.O_RDWR
    if hasattr(os, "O_NOFOLLOW"):
        flags |= os.O_NOFOLLOW
    try:
        descriptor = os.open(lock_path, flags, _PRIVATE_FILE_MODE)
    except OSError:
        raise _private_error("private_env_lock_unavailable") from None
    try:
        if os.name == "posix":
            import fcntl

            os.fchmod(descriptor, _PRIVATE_FILE_MODE)
            fcntl.flock(descriptor, fcntl.LOCK_EX)
        elif os.name == "nt":
            import msvcrt

            if os.fstat(descriptor).st_size == 0:
                os.write(descriptor, b"0")
                os.fsync(descriptor)
            os.lseek(descriptor, 0, os.SEEK_SET)
            msvcrt.locking(descriptor, msvcrt.LK_LOCK, 1)
        yield
    finally:
        if os.name == "posix":
            import fcntl

            fcntl.flock(descriptor, fcntl.LOCK_UN)
        elif os.name == "nt":
            import msvcrt

            os.lseek(descriptor, 0, os.SEEK_SET)
            msvcrt.locking(descriptor, msvcrt.LK_UNLCK, 1)
        os.close(descriptor)


def _validate_private_updates(
    updates: Mapping[str, str | None],
    allowed_keys: Collection[str] | None,
) -> tuple[frozenset[str] | None, dict[str, str | None]]:
    allowed = _validated_allowed_keys(allowed_keys)
    if not isinstance(updates, Mapping):
        raise _private_error("private_env_updates_invalid")
    validated: dict[str, str | None] = {}
    for key, value in updates.items():
        if not isinstance(key, str) or _ENV_KEY_PATTERN.fullmatch(key) is None:
            raise _private_error("private_env_key_invalid")
        if allowed is not None and key not in allowed:
            raise _private_error("private_env_key_not_allowed")
        if value is not None and not isinstance(value, str):
            raise _private_error("private_env_value_invalid")
        if isinstance(value, str) and any(
            character in value for character in ("\x00", "\r", "\n")
        ):
            raise _private_error("private_env_value_invalid")
        validated[key] = value
    return allowed, validated


def _update_private_env_file_unlocked(
    path: str | Path,
    updates: Mapping[str, str | None],
    *,
    allowed_keys: Collection[str] | None = None,
) -> dict[str, str]:
    """Atomically apply private env updates and return the verified values.

    A string sets a key and ``None`` removes it. Unknown existing keys are
    preserved. If ``allowed_keys`` is provided, update keys outside that set
    fail closed. The file is replaced in-place with mode 0600 after its data
    and containing directory have been synchronised.
    """
    destination = Path(path)
    allowed, validated_updates = _validate_private_updates(updates, allowed_keys)

    _ensure_private_directory(destination.parent)

    existing_payload = _read_private_bytes(destination)
    values = _parse_private_env(existing_payload) if existing_payload is not None else {}
    for key, value in validated_updates.items():
        if value is None:
            values.pop(key, None)
            continue
        values[key] = value

    payload = _serialize_private_env(values)
    temporary: str | None = None
    descriptor = -1
    try:
        descriptor, temporary = tempfile.mkstemp(
            prefix=f".{destination.name}.",
            suffix=".tmp",
            dir=destination.parent,
        )
        if os.name == "posix":
            os.fchmod(descriptor, _PRIVATE_FILE_MODE)
        with os.fdopen(descriptor, "wb", closefd=True) as handle:
            descriptor = -1
            handle.write(payload)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temporary, destination)
        temporary = None
        if os.name == "posix":
            os.chmod(destination, _PRIVATE_FILE_MODE)
        _fsync_directory(destination.parent)
    except _PrivateEnvError:
        raise
    except OSError:
        raise _private_error("private_env_write_failed") from None
    finally:
        if descriptor >= 0:
            os.close(descriptor)
        if temporary is not None:
            try:
                os.unlink(temporary)
            except OSError:
                pass

    verified = read_private_env_file(destination, allowed_keys=allowed)
    expected = (
        values
        if allowed is None
        else {key: value for key, value in values.items() if key in allowed}
    )
    if verified != expected:
        raise _private_error("private_env_verification_failed")
    return verified


def update_private_env_file(
    path: str | Path,
    updates: Mapping[str, str | None],
    *,
    allowed_keys: Collection[str] | None = None,
) -> dict[str, str]:
    """Atomically update a private env file under a cross-process lock."""
    destination = Path(path)
    # Validate before creating the private directory or lock file so malformed
    # input has no filesystem side effect.
    _validate_private_updates(updates, allowed_keys)
    _ensure_private_directory(destination.parent)
    with _private_env_write_lock(destination):
        return _update_private_env_file_unlocked(
            destination,
            updates,
            allowed_keys=allowed_keys,
        )


def parse_env_file(path: str | Path) -> dict[str, str]:
    """Parse one ``.env`` file into a dict; unreadable files yield ``{}``."""
    try:
        file_path = Path(path)
        if not file_path.is_file() or file_path.stat().st_size > _MAX_FILE_BYTES:
            return {}
        text = file_path.read_text(encoding="utf-8", errors="replace")
    except OSError:
        return {}

    values: dict[str, str] = {}
    for line in text.splitlines()[:_MAX_LINES]:
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        if stripped.startswith("export "):
            stripped = stripped[len("export "):].strip()
        if "=" not in stripped:
            continue
        key, _, value = stripped.partition("=")
        key = key.strip()
        if not key or any(character.isspace() for character in key):
            continue
        value = value.strip()
        if len(value) >= 2 and value[0] == value[-1] and value[0] in {"'", '"'}:
            value = value[1:-1]
        values[key] = value
    return values


def read_env_files(paths: list[str | Path]) -> dict[str, str]:
    """Merge several ``.env`` files in order; later files override earlier."""
    merged: dict[str, str] = {}
    for path in paths:
        merged.update(parse_env_file(path))
    return merged


def apply_env_file(paths: list[str | Path], *, override: bool = False) -> dict[str, str]:
    """Import ``.env`` values into the process environment.

    Existing variables are preserved unless ``override`` is set, so a real
    ``export`` always beats the file.
    """
    applied: dict[str, str] = {}
    for key, value in read_env_files(paths).items():
        if override or key not in os.environ:
            os.environ[key] = value
            applied[key] = value
    if applied:
        logger.debug("Loaded %d setting(s) from env file(s)", len(applied))
    return applied


__all__ = [
    "apply_env_file",
    "parse_env_file",
    "read_env_files",
    "read_private_env_file",
    "update_private_env_file",
]

