)
_PUBLIC_SOURCES = frozenset({"reflection", "curator", "user", "manual", "unknown"})


def _utc_now() -> datetime:
    return datetime.now(timezone.utc)


def _platform_name() -> str:
    return os.name


def _iso_time(value: datetime | float) -> str:
    if isinstance(value, bool):
        raise TypeError("bool is not a timestamp")
    if isinstance(value, (int, float)):
        value = datetime.fromtimestamp(float(value), tz=timezone.utc)
    if value.tzinfo is None:
        value = value.replace(tzinfo=timezone.utc)
    return value.astimezone(timezone.utc).isoformat(timespec="milliseconds").replace(
        "+00:00", "Z"
    )


def _canonical_hash(prefix: str, payload: object) -> str:
    encoded = json.dumps(
        payload,
        sort_keys=True,
        ensure_ascii=False,
        separators=(",", ":"),
    ).encode("utf-8")
    return prefix + hashlib.sha256(encoded).hexdigest()


def _truncate_utf8(value: str, budget: int) -> tuple[str, bool]:
    encoded = value.encode("utf-8")
    if len(encoded) <= budget:
        return value, False
    return encoded[:budget].decode("utf-8", errors="ignore"), True


def _contains_secret_or_path(value: str) -> bool:
    without_urls = _WEB_URL_RE.sub("[WEB_URL]", value)
    return bool(
        _BEARER_RE.search(value)
        or _KEY_RE.search(value)
        or _AWS_KEY_RE.search(value)
        or _GITHUB_TOKEN_RE.search(value)
        or _JWT_RE.search(value)
        or _PRIVATE_KEY_RE.search(value)
        or _CREDENTIAL_URL_RE.search(value)
        or _SECRET_RE.search(value)
        or _POSIX_PATH_RE.search(without_urls)
        or _WINDOWS_PATH_RE.search(without_urls)
        or _HOME_PATH_RE.search(without_urls)
    )


class MemoryApprovalError(RuntimeError):
    """Fixed-code failure safe to map to an HTTP response."""

    def __init__(self, code: str) -> None:
        self.code = code
        super().__init__(code)


@dataclass(frozen=True, slots=True)
class MemoryApprovalDecision:
    memory_id: str
    status: Literal["approved", "rejected"]
    decision: MemoryDecision
    decision_accepted: bool
    updated_at: str


@dataclass(frozen=True, slots=True)
class ScopeAuthoritySnapshot:
    """One bounded, read-only view of a Memory scope's persisted sources.

    ``memory.json`` is the entry authority.  Its embedded ``approval_audit``
    is authoritative when present; the standalone audit file is then only a
    validated projection.  Legacy stores without an embedded audit fall back
    to that projection.
    """

    scope: MemoryScope
    entries: tuple[MemoryEntry, ...] = ()
    raw_entries: tuple[dict[str, object], ...] = ()
    approval_audit: tuple[dict[str, object], ...] = ()


class MemoryApprovalAuthority:
    """Deep persistent approval boundary used by TUI-compatible core and HTTP."""

    def __init__(
        self,
        workspace: str | Path,
        *,
        clock: Callable[[], datetime] = _utc_now,
        store_timeout: float = 5.0,
    ) -> None:
        self._workspace = Path(workspace).resolve(strict=False)
        self._clock = clock
        self._store_timeout = store_timeout

    def _manager(self) -> MemoryManager:
        self._validate_candidate_paths()
        manager = MemoryManager(
            project_root=self._workspace,
            store_timeout=self._store_timeout,
            readonly_load=True,
            approval_interpretation_mode=(
                ApprovalInterpretationMode.STRICT_FAIL_CLOSED
            ),
        )
        self._validate_scope_roots(manager)
        return manager

    def _scope_roots(self) -> tuple[tuple[MemoryScope, Path], ...]:
        return (
            (MemoryScope.USER, Path(memory_module.MINI_CODE_DIR) / "memory"),
            (MemoryScope.PROJECT, self._workspace / ".mini-code-memory"),
            (MemoryScope.LOCAL, self._workspace / ".mini-code-memory-local"),
        )

    @staticmethod
    def _read_regular_file(root: Path, filename: str) -> bytes | None:
        """Read one bounded regular file without creating or following anything."""
        try:
            source = read_memory_authority_file(
                root,
                filename,
                platform_name=_platform_name(),
            )
        except MemoryAuthoritySourceError as error:
            raise MemoryApprovalError("memory_approval_unavailable") from error
        return source.data if source is not None else None

    @staticmethod
    def _decode_source(content: bytes) -> str:
        try:
            return content.decode("utf-8")
        except UnicodeDecodeError as error:
            raise MemoryApprovalError("memory_approval_failed") from error

    @staticmethod
    def _interpret_loaded_entry(
        entry: MemoryEntry,
        raw_data: dict[str, object],
        *,
        requires_complete_authority: bool = False,
    ) -> MemoryEntry:
        """Apply the write loader's compatibility rules in memory only."""
        safety = assess_memory_safety(entry.content, source=entry.source or "load")
        interpretation = _interpret_loaded_entry_approval(
            entry,
            raw_data,
            safety,
            mode=ApprovalInterpretationMode.STRICT_FAIL_CLOSED,
            transition_time=entry.approval_decided_at,
            requires_complete_authority=requires_complete_authority,
        )
        if (
            interpretation.failure
            is ApprovalInterpretationFailure.STALE_APPROVAL_HASH
        ):
            raise MemoryApprovalError("memory_approval_failed")
        if interpretation.state is None or interpretation.failure is not None:
            raise MemoryApprovalError("memory_approval_failed")
        _apply_approval_authority_state(entry, interpretation.state)
        return entry

    @staticmethod
    def _validate_audit_records(
        value: object,
        *,
        scope: MemoryScope,
        versioned: bool,
    ) -> tuple[dict[str, object], ...]:
        try:
            if versioned:
                records = decode_memory_audit_records(
                    value,
                    expected_scope=scope.value,
                    maximum_records=MAX_AUTHORITY_AUDIT_RECORDS,
                )
                return tuple(record.to_dict() for record in records)
            return tuple(
                dict(record)
                for record in decode_legacy_memory_audit_records(
                    value,
                    expected_scope=scope.value,
                )
            )
        except (TypeError, ValueError) as error:
            raise MemoryApprovalError("memory_approval_failed") from error

    def _read_audit_projection(
        self,
        content: bytes | None,
        *,
        scope: MemoryScope,
    ) -> tuple[dict[str, object], ...]:
        if content is None:
            return ()
        try:
            parsed = parse_memory_authority_json(self._decode_source(content))
        except (
            json.JSONDecodeError,
            RecursionError,
            TypeError,
            ValueError,
        ) as error:
            raise MemoryApprovalError("memory_approval_failed") from error
        if not isinstance(parsed, dict):
            raise MemoryApprovalError("memory_approval_failed")
        return self._validate_audit_records(
            parsed.get("records", []),
            scope=scope,
            versioned=False,
        )

    @staticmethod
    def _read_versioned_audit(
        scope: MemoryScope,
        parsed: dict[str, object],
        root: Path,
    ) -> tuple[dict[str, object], ...]:
        """Resolve the current audit chain without mutating its store."""

        try:
            hot = decode_memory_audit_records(
                parsed.get("approval_audit"),
                expected_scope=scope.value,
                maximum_records=MAX_AUTHORITY_AUDIT_RECORDS,
            )
            if (
                parsed.get("schemaVersion")
                != memory_module.CURRENT_MEMORY_AUTHORITY_SCHEMA_VERSION
            ):
                return tuple(record.to_dict() for record in hot)
            head = decode_memory_audit_head(parsed.get("approval_audit_head"))
            segments: list[MemoryAuditSegment] = []
            if head is not None:
                reference = head.blob
                store = MemoryBlobStore(root)
                for _ in range(head.segment_count):
                    segment = MemoryAuditSegment.from_dict(
                        store.read_json(reference),
                        expected_scope=scope.value,
                    )
                    segments.append(segment)
                    if segment.previous is None:
                        break
                    reference = segment.previous
            validate_memory_audit_segment_chain(
                head,
                segments,
                expected_scope=scope.value,
                hot_records=hot,
            )
        except Exception as error:  # noqa: BLE001 - fixed external failure code
            raise MemoryApprovalError("memory_approval_failed") from error
        return tuple(
            record.to_dict()
            for segment in reversed(segments)
            for record in segment.records
        ) + tuple(record.to_dict() for record in hot)

    @staticmethod
    def _validate_runtime_capacity(
        scope: MemoryScope,
        entries: list[MemoryEntry],
    ) -> None:
        """Apply the canonical current-store capacity to every read format."""
        runtime_file = MemoryFile(scope=scope, entries=list(entries))
        if (
            len(runtime_file.entries) > MAX_CURRENT_AUTHORITY_ENTRIES
            or runtime_file.size_bytes > MAX_CURRENT_AUTHORITY_CONTENT_BYTES
        ):
            raise MemoryApprovalError("memory_approval_failed")

    def _read_json_snapshot(
        self,
        scope: MemoryScope,
        content: bytes,
        root: Path,
    ) -> ScopeAuthoritySnapshot:
        try:
            parsed = parse_memory_authority_json(self._decode_source(content))
        except (
            json.JSONDecodeError,
            RecursionError,
            TypeError,
            ValueError,
        ) as error:
            raise MemoryApprovalError("memory_approval_failed") from error
        if (
            isinstance(parsed, dict)
            and "schemaVersion" in parsed
            and parsed.get("schemaVersion")
            != memory_module.CURRENT_MEMORY_AUTHORITY_SCHEMA_VERSION
        ):
            raise MemoryApprovalError("memory_approval_failed")
        parsed, scope_errors = memory_module._bind_memory_authority_scope(
            parsed,
            scope.value,
        )
        if scope_errors:
            raise MemoryApprovalError("memory_approval_failed")
        is_valid, _ = memory_module._validate_memory_data(parsed)
        if not is_valid or len(parsed["entries"]) > _MAX_SOURCE_ENTRIES:
            raise MemoryApprovalError("memory_approval_failed")

        entries: list[MemoryEntry] = []
        raw_entries: list[dict[str, object]] = []
        for raw_entry in parsed["entries"]:
            if not isinstance(raw_entry, dict):
                raise MemoryApprovalError("memory_approval_failed")
            if raw_entry.get("scope", scope.value) != scope.value:
                raise MemoryApprovalError("memory_approval_failed")
            normalized = dict(raw_entry)
            normalized["scope"] = scope.value
            normalized.setdefault("created_at", 0.0)
            normalized.setdefault("updated_at", normalized["created_at"])
            normalized.setdefault("last_accessed", 0.0)
            try:
                entry = MemoryEntry.from_dict(normalized)
            except (
                KeyError,
                TypeError,
                ValueError,
                OverflowError,
                RecursionError,
            ) as error:
                raise MemoryApprovalError("memory_approval_failed") from error
            if not self._valid_memory_id(entry.id) or not entry.content:
                raise MemoryApprovalError("memory_approval_failed")
            entries.append(
                self._interpret_loaded_entry(
                    entry,
                    raw_entry,
                    requires_complete_authority=(
                        parsed.get("schemaVersion")
                        == memory_module.CURRENT_MEMORY_AUTHORITY_SCHEMA_VERSION
                    ),
                )
            )
            raw_entries.append(dict(raw_entry))

        self._validate_runtime_capacity(scope, entries)

        schema_version = parsed.get("schemaVersion")
        is_versioned = schema_version in (
            {memory_module.CURRENT_MEMORY_AUTHORITY_SCHEMA_VERSION}
            | set(memory_module.MIGRATABLE_MEMORY_AUTHORITY_SCHEMA_VERSIONS)
        )
        approval_audit = (
            self._read_versioned_audit(scope, parsed, root)
            if is_versioned
            else self._validate_audit_records(
                parsed["approval_audit"],
                scope=scope,
                versioned=False,
            )
            if "approval_audit" in parsed
            else self._read_audit_projection(
                self._read_regular_file(root, "approval_audit.json"),
                scope=scope,
            )
        )
        return ScopeAuthoritySnapshot(
            scope=scope,
            entries=tuple(entries),
            raw_entries=tuple(raw_entries),
            approval_audit=approval_audit,
        )

    def _read_markdown_entries(
        self,
        scope: MemoryScope,
        content: bytes,
    ) -> list[MemoryEntry]:
        entries: list[MemoryEntry] = []
        category = "general"
        for raw_line in self._decode_source(content).splitlines():
            line = raw_line.strip()
            if line.startswith("#") or line.startswith("*") or not line:
                if line.startswith("## "):
                    category = line[3:].strip().lower()
                continue
            if not line.startswith("- "):
                continue
            if len(entries) >= _MAX_SOURCE_ENTRIES:
                raise MemoryApprovalError("memory_approval_failed")
            entry_content = line[2:]
            tags: list[str] = []
            if "`" in entry_content:
                for tag_match in re.findall(r"`([^`]+)`", entry_content):
                    tags.extend(tag_match.split())
                entry_content = re.sub(r"`[^`]+`", "", entry_content).strip()
            entry = MemoryEntry(
                id=f"{scope.value}-{len(entries) + 1}",
                scope=scope,
                category=category,
                content=entry_content,
                created_at=0.0,
                updated_at=0.0,
                last_accessed=0.0,
                tags=tags,
            )
            if not entry.content:
                raise MemoryApprovalError("memory_approval_failed")
            entries.append(self._interpret_loaded_entry(entry, {}))
        self._validate_runtime_capacity(scope, entries)
        return entries

    def _read_scope_snapshot_from_root(
        self,
        scope: MemoryScope,
        root: Path,
    ) -> ScopeAuthoritySnapshot:
        memory_json = self._read_regular_file(root, "memory.json")
        if memory_json is not None:
            return self._read_json_snapshot(
                scope,
                memory_json,
                root,
            )
        audit_projection = self._read_audit_projection(
            self._read_regular_file(root, "approval_audit.json"),
            scope=scope,
        )
        memory_md = self._read_regular_file(root, "MEMORY.md")
        entries = (
            tuple(self._read_markdown_entries(scope, memory_md))
            if memory_md is not None
            else ()
        )
        return ScopeAuthoritySnapshot(
            scope=scope,
            entries=entries,
            approval_audit=audit_projection,
        )

    def read_scope_snapshot(self, scope: MemoryScope) -> ScopeAuthoritySnapshot:
        """Read and parse each persisted source for one scope at most once."""
        if not isinstance(scope, MemoryScope):
            raise TypeError("scope must be a MemoryScope")
        self._validate_candidate_paths()
        root_by_scope = dict(self._scope_roots())
        return self._read_scope_snapshot_from_root(scope, root_by_scope[scope])

    def _read_strict_entries(self) -> list[MemoryEntry]:
        """Load every entry through the strict, bounded no-write seam."""
        self._validate_candidate_paths()
        entries: list[MemoryEntry] = []
        seen_ids: set[str] = set()
        for scope, root in self._scope_roots():
            scope_snapshot = self._read_scope_snapshot_from_root(scope, root)
            for entry in scope_snapshot.entries:
                if entry.id in seen_ids:
                    raise MemoryApprovalError("memory_approval_failed")
                seen_ids.add(entry.id)
                entries.append(entry)
        return entries

    def _read_pending_entries(self) -> list[MemoryEntry]:
        """Load pending entries through a bounded, strictly no-write seam."""
        entries = [
            entry
            for entry in self._read_strict_entries()
            if entry.approval_status == _APPROVAL_PENDING
        ]
        return sorted(entries, key=lambda entry: (entry.created_at, entry.scope.value, entry.id))

    def _validate_candidate_paths(self) -> None:
        data_root = Path(memory_module.MINI_CODE_DIR)
        roots = (
            data_root / "memory",
            self._workspace / ".mini-code-memory",
            self._workspace / ".mini-code-memory-local",
        )
        try:
            if data_root.is_symlink():
                raise MemoryApprovalError("memory_approval_unavailable")
            for root in roots:
                if root.is_symlink():
                    raise MemoryApprovalError("memory_approval_unavailable")
                for filename in ("memory.json", "MEMORY.md", "approval_audit.json"):
                    if (root / filename).is_symlink():
                        raise MemoryApprovalError("memory_approval_unavailable")
        except OSError as error:
            raise MemoryApprovalError("memory_approval_unavailable") from error

    def _validate_scope_roots(self, manager: MemoryManager) -> None:
        workspace = self._workspace
        for scope in MemoryScope:
            root = manager._get_scope_path(scope)  # one audited internal store seam
            if scope in {MemoryScope.PROJECT, MemoryScope.LOCAL}:
                try:
                    if root.parent.resolve(strict=False) != workspace:
                        raise MemoryApprovalError("memory_approval_unavailable")
                except OSError as error:
                    raise MemoryApprovalError("memory_approval_unavailable") from error
            try:
                if root.is_symlink():
                    raise MemoryApprovalError("memory_approval_unavailable")
                for filename in ("memory.json", "MEMORY.md", "approval_audit.json"):
                    if (root / filename).is_symlink():
                        raise MemoryApprovalError("memory_approval_unavailable")
            except OSError as error:
                raise MemoryApprovalError("memory_approval_unavailable") from error

    @staticmethod
    def _valid_memory_id(memory_id: object) -> bool:
        return is_memory_entry_id(memory_id)

    @staticmethod
    def _review_revision(entry: MemoryEntry) -> str:
        content_hash = hashlib.sha256(entry.content.encode("utf-8")).hexdigest()
        return _canonical_hash(
            "memoryreviewrev_",
            {
                "projectionVersion": REVIEW_PROJECTION_VERSION,
                "memoryId": entry.id,
                "scope": entry.scope.value,
                "approvalStatus": entry.approval_status,
                "lifecycleStatus": entry.lifecycle_status,
                "safetyStatus": entry.safety_status,
                "tier": entry.tier.value,
                "curatorLocked": entry.curator_locked,
                "approvalContentHash": entry.approval_content_hash,
                "contentHash": content_hash,
            },
        )

    @staticmethod
    def _safe_preview(entry: MemoryEntry) -> tuple[dict[str, object], bool]:
        original = entry.content
        persistence_sanitized = (
            entry.metadata.get("persistence_sanitized", {})
            if isinstance(entry.metadata, dict)
            else {}
        )
        if (
            isinstance(persistence_sanitized, dict)
            and persistence_sanitized.get("content") is True
        ):
            return {
                "contentPreview": _REDACTED_PREVIEW,
                "complete": False,
                "truncated": False,
                "redacted": True,
            }, False
        content = _ANSI_RE.sub("", original)
        content = _CONTROL_RE.sub("", content)
        if content != original:
            return {
                "contentPreview": _REDACTED_PREVIEW,
                "complete": False,
                "truncated": False,
                "redacted": True,
            }, False
        safety = assess_memory_safety(content, source="memory_review")
        if safety.status == _SAFETY_UNSAFE:
            return {
                "contentPreview": _UNSAFE_PREVIEW,
                "complete": False,
                "truncated": False,
                "redacted": True,
            }, False
        if _contains_secret_or_path(content):
            return {
                "contentPreview": _REDACTED_PREVIEW,
                "complete": False,
                "truncated": False,
                "redacted": True,
            }, False
        preview, truncated = _truncate_utf8(content, MAX_REVIEW_PREVIEW_BYTES)
        review = {
            "contentPreview": preview,
            "complete": not truncated,
            "truncated": truncated,
            "redacted": False,
        }
        reviewable = (
            not truncated
            and entry.lifecycle_status == "active"
            and not entry.curator_locked
            and entry.tier != MemoryTier.ARCHIVAL
            and entry.approval_content_hash == _approval_hash_for_entry(entry)
            and safety.status in {"safe", "suspicious"}
        )
        return review, reviewable

    def _public_item(self, entry: MemoryEntry) -> dict[str, object]:
        review, reviewable = self._safe_preview(entry)
        risk = {"safe": "low", "suspicious": "medium", "unsafe": "high"}.get(
            entry.safety_status, "high"
        )
        item: dict[str, object] = {
            "memoryId": entry.id,
            "scope": entry.scope.value,
            "scopeKind": "user/global" if entry.scope == MemoryScope.USER else "workspace",
            "category": entry.category if entry.category in _PUBLIC_CATEGORIES else "other",
            "tier": entry.tier.value,
            "source": entry.source if entry.source in _PUBLIC_SOURCES else "unknown",
            "createdAt": _iso_time(entry.created_at),
            "risk": risk,
            "safetyStatus": entry.safety_status if entry.safety_status in {"safe", "suspicious", "unsafe"} else "unsafe",
            "reviewable": reviewable,
            "review": review,
            "reviewRevision": self._review_revision(entry),
            "choices": ["approve", "reject"] if reviewable else ["reject"],
        }
        if len(json.dumps(item, ensure_ascii=False).encode("utf-8")) > MAX_REVIEW_ITEM_BYTES:
            item["reviewable"] = False
            item["review"] = {
                "contentPreview": _OVERSIZE_PREVIEW,
                "complete": False,
                "truncated": True,
                "redacted": False,
            }
            item["choices"] = ["reject"]
        # Final recursive/serialized defense: any projected secret/path turns the
        # content review into a fixed deny-only placeholder.
        if _contains_secret_or_path(json.dumps(item, ensure_ascii=False)):
            item["reviewable"] = False
            item["review"] = {
                "contentPreview": _REDACTED_PREVIEW,
                "complete": False,
                "truncated": False,
                "redacted": True,
            }
            item["choices"] = ["reject"]
        return item

    def snapshot(self) -> dict[str, object]:
        """Return the current bounded, safe pending-review projection."""
        try:
            pending = self._read_pending_entries()
            items: list[dict[str, object]] = []
            diagnostics: list[dict[str, str]] = []
            for entry in pending:
                if len(items) >= MAX_PENDING_ITEMS:
                    diagnostics.append({"code": "items_limited"})
                    break
                item = self._public_item(entry)
                candidate = items + [item]
                if len(json.dumps(candidate, ensure_ascii=False).encode("utf-8")) > MAX_SNAPSHOT_BYTES - 2048:
                    diagnostics.append({"code": "snapshot_limited"})
                    break
                items.append(item)
            semantic_revision = _canonical_hash(
                "memoryapprovalrev_",
                [
                    {
                        "memoryId": entry.id,
                        "reviewRevision": self._review_revision(entry),
                    }
                    for entry in pending
                ],
            )
            latest = max(
                (entry.updated_at for entry in pending),
                default=self._clock().timestamp(),
            )
            snapshot: dict[str, object] = {
                "schemaVersion": 1,
                "generatedAt": _iso_time(self._clock()),
                "mode": "read-only",
                "source": {
                    "status": "live",
                    "updatedAt": _iso_time(latest),
                    "message": None,
                },
                "revision": semantic_revision,
                "items": items,
                "diagnostics": diagnostics,
            }
            if len(json.dumps(snapshot, ensure_ascii=False).encode("utf-8")) > MAX_SNAPSHOT_BYTES:
                raise MemoryApprovalError("memory_approval_failed")
            return snapshot
        except MemoryApprovalError:
            raise
        except (MemoryStoreBusy, MemoryStoreConflict) as error:
            raise MemoryApprovalError(error.code) from error
        except BaseException as error:  # noqa: BLE001 - safe fixed authority error
            raise MemoryApprovalError("memory_approval_failed") from error

    def revision(self) -> str:
        return str(self.snapshot()["revision"])

    def decide(
        self,
        *,
        memory_id: str,
        decision: MemoryDecision,
        review_revision: str,
    ) -> MemoryApprovalDecision:
        """Commit a decision iff the review still describes current authority."""
        if not self._valid_memory_id(memory_id):
            raise MemoryApprovalError("invalid_memory_id")
        if not isinstance(decision, str) or decision not in {"approve", "reject"}:
            raise MemoryApprovalError("invalid_decision")
        if (
            not isinstance(review_revision, str)
            or MEMORY_REVIEW_REVISION_RE.fullmatch(review_revision) is None
        ):
            raise MemoryApprovalError("invalid_review_revision")
        try:
            manager = self._manager()

            def commit() -> MemoryApprovalDecision:
                self._validate_scope_roots(manager)
                # MemoryManager's read-only compatibility loader may normalize
                # legacy fields in memory.  Approval decisions instead bind to
                # a fresh STRICT_FAIL_CLOSED view while holding the store lock,
                # so a stale persisted hash can never be rebound and approved.
                strict_by_id = {
                    strict_entry.id: strict_entry
                    for strict_entry in self._read_strict_entries()
                }
                strict_entry = strict_by_id.get(memory_id)
                scope, entry = manager._find_entry_by_id(memory_id)
                if (
                    scope is None
                    or entry is None
                    or entry.scope != scope
                    or strict_entry is None
                ):
                    raise MemoryApprovalError("memory_approval_not_found")
                if (
                    strict_entry.scope != scope
                    or not hmac.compare_digest(
                        self._review_revision(strict_entry),
                        self._review_revision(entry),
                    )
                ):
                    raise MemoryApprovalError("memory_write_conflict")
                if entry.approval_status != _APPROVAL_PENDING:
                    same = (
                        entry.approval_actor == "dashboard_user"
                        and (
                            (
                                decision == "approve"
                                and entry.approval_status == _APPROVAL_APPROVED
                                and entry.approval_reason == "dashboard_approved"
                            )
                            or (
                                decision == "reject"
                                and entry.approval_status == _APPROVAL_REJECTED
                                and entry.approval_reason == "dashboard_rejected"
                            )
                        )
                    )
                    if same:
                        return MemoryApprovalDecision(
                            memory_id=entry.id,
                            status=entry.approval_status,
                            decision=decision,
                            decision_accepted=False,
                            updated_at=_iso_time(entry.approval_decided_at or entry.updated_at),
                        )
                    raise MemoryApprovalError("memory_already_decided")

                item = self._public_item(strict_entry)
                current_revision = str(item["reviewRevision"])
                if not hmac.compare_digest(current_revision, review_revision):
                    raise MemoryApprovalError("memory_review_stale")
                if decision == "approve" and (
                    item["reviewable"] is not True
                    or item["choices"] != ["approve", "reject"]
                ):
                    raise MemoryApprovalError("memory_not_reviewable")
                mutation = manager.decide_pending_entry(
                    entry.id,
                    decision,
                    actor="dashboard_user",
                    reason=(
                        "dashboard_approved"
                        if decision == "approve"
                        else "dashboard_rejected"
                    ),
                )
                expected = _APPROVAL_APPROVED if decision == "approve" else _APPROVAL_REJECTED
                if mutation.status != expected or not mutation.decision_accepted:
                    raise MemoryApprovalError("memory_not_reviewable")
                _, committed = manager._find_entry_by_id(entry.id)
                if committed is None:
                    raise MemoryApprovalError("memory_write_conflict")
                return MemoryApprovalDecision(
                    memory_id=mutation.memory_id,
                    status=mutation.status,
                    decision=decision,
                    decision_accepted=True,
                    updated_at=_iso_time(committed.approval_decided_at),
                )

            return manager.coordinated_write(tuple(MemoryScope), commit)
        except MemoryApprovalError:
            raise
        except MemoryStoreBusy as error:
            raise MemoryApprovalError("memory_store_busy") from error
        except MemoryStoreConflict as error:
            raise MemoryApprovalError("memory_write_conflict") from error
        except (MemoryStoreUnavailable, MemoryStoreUnsafePath) as error:
            raise MemoryApprovalError("memory_approval_unavailable") from error
        except BaseException as error:  # noqa: BLE001 - safe fixed authority error
            raise MemoryApprovalError("memory_approval_failed") from error


__all__ = [
    "MAX_PENDING_ITEMS",
    "MAX_REVIEW_ITEM_BYTES",
    "MAX_REVIEW_PREVIEW_BYTES",
    "MAX_SNAPSHOT_BYTES",
    "MEMORY_APPROVAL_REVISION_RE",
    "MEMORY_ID_RE",
    "MEMORY_REVIEW_REVISION_RE",
    "MemoryApprovalAuthority",
    "MemoryApprovalDecision",
    "MemoryApprovalError",
    "ScopeAuthoritySnapshot",
]

shared_files.minicode/memory_audit_contract.py:
"""Strict records and immutable hash-chain segments for Memory approval audit."""

from __future__ import annotations

import copy
import json
import math
import re
from collections.abc import Sequence
from dataclasses import dataclass, fields
from typing import Any

from minicode.memory_authority_io import (
    MAX_AUTHORITY_AUDIT_RECORDS,
    MAX_MEMORY_COUNTER,
    MAX_MEMORY_TIMESTAMP,
    is_memory_entry_id,
    validate_memory_authority_value,
)
from minicode.memory_blob_store import (
    MAX_MEMORY_BLOB_BYTES,
    MemoryBlobReference,
    canonical_memory_blob_bytes,
    memory_blob_digest,
)

MEMORY_AUDIT_SEGMENT_VERSION = 1
MEMORY_AUDIT_SEGMENT_KIND = "memory-approval-audit-segment"
MAX_MEMORY_AUDIT_RECORDS_PER_SEGMENT = 256
MAX_MEMORY_AUDIT_CHAIN_SEGMENTS = 100_000
MAX_MEMORY_AUDIT_CHAIN_RECORDS = 100_000
MAX_MEMORY_AUDIT_RECORD_BYTES = 24 * 1024
MAX_MEMORY_AUDIT_METADATA_BYTES = 12 * 1024
MAX_MEMORY_AUDIT_METADATA_DEPTH = 4
MAX_MEMORY_AUDIT_METADATA_NODES = 512
MAX_MEMORY_AUDIT_METADATA_ITEMS = 128
MAX_MEMORY_AUDIT_METADATA_TEXT_BYTES = 2 * 1024

MEMORY_AUDIT_SCOPES = frozenset({"user", "project", "local"})
MEMORY_AUDIT_APPROVAL_STATUSES = frozenset({"approved", "pending", "rejected"})
MEMORY_AUDIT_PREVIOUS_APPROVAL_STATUSES = frozenset(
    {*MEMORY_AUDIT_APPROVAL_STATUSES, "new"}
)
MEMORY_AUDIT_LIFECYCLE_STATUSES = frozenset(
    {
        "active",
        "pending",
        "held",
        "archived",
        "deprecated",
        "rejected",
        "invalid",
        "superseded",
        "archived_duplicate",
        "evicted",
    }
)
MEMORY_AUDIT_PREVIOUS_LIFECYCLE_STATUSES = frozenset(
    {*MEMORY_AUDIT_LIFECYCLE_STATUSES, "new"}
)
MEMORY_AUDIT_SAFETY_STATUSES = frozenset({"safe", "suspicious", "unsafe"})
MEMORY_AUDIT_RISKS = frozenset({"low", "medium", "high"})

_AUDIT_ID_RE = re.compile(r"^audit-[1-9][0-9]{0,20}-[0-9a-f]{8}$")
_LEGACY_AUDIT_ID_RE = re.compile(r"^[A-Za-z0-9][A-Za-z0-9_.:-]{0,127}$")
_SHA256_RE = re.compile(r"^[0-9a-f]{64}$")
_RECORD_FIELDS = frozenset(
    {
        "audit_id",
        "entry_id",
        "scope",
        "action",
        "actor",
        "created_at",
        "previous_approval_status",
        "approval_status",
        "previous_lifecycle_status",
        "lifecycle_status",
        "safety_status",
        "safety_reason",
        "risk",
        "content_hash",
        "reason",
        "source",
        "provenance",
        "extra",
    }
)
_SEGMENT_FIELDS = frozenset({"schemaVersion", "kind", "scope", "previous", "records"})
_HEAD_FIELDS = frozenset({"blob", "segmentCount", "recordCount"})


def is_memory_audit_id(value: object) -> bool:
    return isinstance(value, str) and _AUDIT_ID_RE.fullmatch(value) is not None


def _scope(value: object, expected: str | None = None) -> str:
    if not isinstance(value, str) or value not in MEMORY_AUDIT_SCOPES:
        raise ValueError("Memory audit scope is invalid")
    if expected is not None and value != expected:
        raise ValueError("Memory audit scope does not match its authority")
    return value


def _timestamp(value: object, label: str) -> int | float:
    if isinstance(value, bool) or type(value) not in {int, float}:
        raise TypeError(f"{label} must be a JSON number")
    if not math.isfinite(value) or not 0 <= value <= MAX_MEMORY_TIMESTAMP:
        raise ValueError(f"{label} is out of range")
    return value


def _count(value: object, label: str, maximum: int) -> int:
    if isinstance(value, bool) or not isinstance(value, int):
        raise TypeError(f"{label} must be an integer")
    if not 1 <= value <= maximum:
        raise ValueError(f"{label} is out of range")
    return value


def _text(
    value: object,
    label: str,
    *,
    chars: int,
    allow_empty: bool = True,
) -> str:
    if not isinstance(value, str):
        raise TypeError(f"{label} must be a string")
    try:
        encoded = value.encode("utf-8")
    except UnicodeEncodeError as error:
        raise ValueError(f"{label} is not UTF-8") from error
    if (
        (not value and not allow_empty)
        or len(value) > chars
        or len(encoded) > chars * 4
    ):
        raise ValueError(f"{label} is out of range")
    return value


def _digest(value: object, label: str) -> str:
    if not isinstance(value, str) or _SHA256_RE.fullmatch(value) is None:
        raise ValueError(f"{label} is invalid")
    return value


def _json_size(value: object) -> int:
    validate_memory_authority_value(value)
    return len(
        json.dumps(
            value,
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
            allow_nan=False,
        ).encode()
    )


def _metadata(value: object, label: str) -> dict[str, Any]:
    """Validate and detach a bounded redacted provenance/extra JSON object."""

    if not isinstance(value, dict):
        raise TypeError(f"{label} must be an object")
    active: set[int] = set()
    nodes = 0

    def visit(item: object, depth: int) -> Any:
        nonlocal nodes
        nodes += 1
        if (
            nodes > MAX_MEMORY_AUDIT_METADATA_NODES
            or depth > MAX_MEMORY_AUDIT_METADATA_DEPTH
        ):
            raise ValueError(f"{label} is too deeply nested")
        if item is None or isinstance(item, bool):
            return item
        if type(item) is int:
            if not -MAX_MEMORY_COUNTER <= item <= MAX_MEMORY_COUNTER:
                raise ValueError(f"{label} integer is out of range")
            return item
        if isinstance(item, float):
            if not math.isfinite(item):
                raise ValueError(f"{label} contains a non-finite number")
            return item
        if isinstance(item, str):
            if len(item.encode("utf-8")) > MAX_MEMORY_AUDIT_METADATA_TEXT_BYTES:
                raise ValueError(f"{label} text is too large")
            return item
        if isinstance(item, (dict, list)):
            identity = id(item)
            if identity in active:
                raise ValueError(f"{label} contains a cycle")
            if len(item) > MAX_MEMORY_AUDIT_METADATA_ITEMS:
                raise ValueError(f"{label} contains too many items")
            active.add(identity)
            try:
                if isinstance(item, list):
                    return [visit(nested, depth + 1) for nested in item]
                copied: dict[str, Any] = {}
                for key, nested in item.items():
                    if not isinstance(key, str) or len(key.encode("utf-8")) > 256:
                        raise ValueError(f"{label} key is invalid")
                    copied[key] = visit(nested, depth + 1)
                return copied
            finally:
                active.remove(identity)
        raise ValueError(f"{label} contains a non-JSON value")

    copied = visit(value, 0)
    if _json_size(copied) > MAX_MEMORY_AUDIT_METADATA_BYTES:
        raise ValueError(f"{label} is too large")
    return copied


@dataclass(frozen=True, slots=True, kw_only=True)
class MemoryAuditRecord:
    audit_id: str
    entry_id: str
    scope: str
    action: str
    actor: str
    created_at: int | float
    previous_approval_status: str
    approval_status: str
    previous_lifecycle_status: str
    lifecycle_status: str
    safety_status: str
    safety_reason: str
    risk: str
    content_hash: str
    reason: str
    source: str
    provenance: dict[str, Any]
    extra: dict[str, Any]

    def __post_init__(self) -> None:
        if not is_memory_audit_id(self.audit_id):
            raise ValueError("Memory audit ID is invalid")
        if not is_memory_entry_id(self.entry_id):
            raise ValueError("Memory audit entry ID is invalid")
        _scope(self.scope)
        _text(self.action, "Memory audit action", chars=128, allow_empty=False)
        _text(self.actor, "Memory audit actor", chars=128, allow_empty=False)
        _timestamp(self.created_at, "Memory audit timestamp")
        if self.previous_approval_status not in MEMORY_AUDIT_PREVIOUS_APPROVAL_STATUSES:
            raise ValueError("Previous Memory approval status is invalid")
        if self.approval_status not in MEMORY_AUDIT_APPROVAL_STATUSES:
            raise ValueError("Memory approval status is invalid")
        if (
            self.previous_lifecycle_status
            not in MEMORY_AUDIT_PREVIOUS_LIFECYCLE_STATUSES
        ):
            raise ValueError("Previous Memory lifecycle status is invalid")
        if self.lifecycle_status not in MEMORY_AUDIT_LIFECYCLE_STATUSES:
            raise ValueError("Memory lifecycle status is invalid")
        if self.safety_status not in MEMORY_AUDIT_SAFETY_STATUSES:
            raise ValueError("Memory safety status is invalid")
        if self.risk not in MEMORY_AUDIT_RISKS:
            raise ValueError("Memory audit risk is invalid")
        _text(self.safety_reason, "Memory audit safety reason", chars=240)
        _digest(self.content_hash, "Memory audit content hash")
        _text(self.reason, "Memory audit reason", chars=240)
        _text(self.source, "Memory audit source", chars=120)
        object.__setattr__(self, "provenance", _metadata(self.provenance, "provenance"))
        object.__setattr__(self, "extra", _metadata(self.extra, "extra"))
        if _json_size(self.to_dict()) > MAX_MEMORY_AUDIT_RECORD_BYTES:
            raise ValueError("Memory audit record is too large")

    def to_dict(self) -> dict[str, object]:
        result = {field.name: getattr(self, field.name) for field in fields(self)}
        result["provenance"] = _metadata(self.provenance, "provenance")
        result["extra"] = _metadata(self.extra, "extra")
        return result

    @classmethod
    def from_dict(
        cls,
        value: object,
        *,
        expected_scope: str | None = None,
        expected_entry_id: str | None = None,
    ) -> MemoryAuditRecord:
        if not isinstance(value, dict) or set(value) != _RECORD_FIELDS:
            raise ValueError("Memory audit record has an invalid schema")
        scope = _scope(value["scope"], expected_scope)
        if expected_entry_id is not None and value["entry_id"] != expected_entry_id:
            raise ValueError("Memory audit entry does not match its binding")
        bound = dict(value)
        bound["scope"] = scope
        return cls(**bound)  # type: ignore[arg-type]


def decode_memory_audit_records(
    value: object,
    *,
    expected_scope: str,
    expected_entry_id: str | None = None,
    maximum_records: int = MAX_AUTHORITY_AUDIT_RECORDS,
) -> tuple[MemoryAuditRecord, ...]:
    _scope(expected_scope)
    if (
        isinstance(maximum_records, bool)
        or not 0 <= maximum_records <= MAX_MEMORY_AUDIT_CHAIN_RECORDS
    ):
        raise ValueError("Memory audit record limit is invalid")
    if not isinstance(value, list) or len(value) > maximum_records:
        raise ValueError("Memory audit record list is invalid")
    records = tuple(
        MemoryAuditRecord.from_dict(
            item,
            expected_scope=expected_scope,
            expected_entry_id=expected_entry_id,
        )
        for item in value
    )
    ids = [record.audit_id for record in records]
    if len(ids) != len(set(ids)):
        raise ValueError("Memory audit ID is duplicated")
    return records


def decode_legacy_memory_audit_records(
    value: object,
    *,
    expected_scope: str,
) -> tuple[dict[str, Any], ...]:
    """Validate bounded unversioned records without pretending they are current."""

    _scope(expected_scope)
    if not isinstance(value, list) or len(value) > MAX_AUTHORITY_AUDIT_RECORDS:
        raise ValueError("Legacy Memory audit record list is invalid")
    result: list[dict[str, Any]] = []
    seen: set[str] = set()
    for item in value:
        if not isinstance(item, dict):
            raise ValueError("Legacy Memory audit record is invalid")
        validate_memory_authority_value(item)
        audit_id = item.get("audit_id")
        if (
            not isinstance(audit_id, str)
            or not _LEGACY_AUDIT_ID_RE.fullmatch(audit_id)
            or audit_id in seen
        ):
            raise ValueError("Legacy Memory audit ID is invalid")
        if item.get("entry_id") is not None and not is_memory_entry_id(
            item["entry_id"]
        ):
            raise ValueError("Legacy Memory audit entry ID is invalid")
        if item.get("scope") is not None:
            _scope(item["scope"], expected_scope)
        if "created_at" in item:
            _timestamp(item["created_at"], "Legacy Memory audit timestamp")
        if _json_size(item) > MAX_MEMORY_BLOB_BYTES:
            raise ValueError("Legacy Memory audit record is too large")
        seen.add(audit_id)
        # The strict value validator above has already excluded custom JSON
        # values. Detach containers without parsing the authority twice.
        result.append(copy.deepcopy(item))
    return tuple(result)


@dataclass(frozen=True, slots=True, kw_only=True)
class MemoryAuditSegment:
    scope: str
    previous: MemoryBlobReference | None
    records: tuple[MemoryAuditRecord, ...]
    schema_version: int = MEMORY_AUDIT_SEGMENT_VERSION
    kind: str = MEMORY_AUDIT_SEGMENT_KIND

    def __post_init__(self) -> None:
        if (
            type(self.schema_version) is not int
            or self.schema_version != MEMORY_AUDIT_SEGMENT_VERSION
        ):
            raise ValueError("Memory audit segment schema version is unsupported")
        if self.kind != MEMORY_AUDIT_SEGMENT_KIND:
            raise ValueError("Memory audit segment kind is invalid")
        _scope(self.scope)
        if self.previous is not None and not isinstance(
            self.previous, MemoryBlobReference
        ):
            raise TypeError("Previous Memory audit segment reference is invalid")
        if (
            not isinstance(self.records, tuple)
            or not 1 <= len(self.records) <= MAX_MEMORY_AUDIT_RECORDS_PER_SEGMENT
        ):
            raise ValueError("Memory audit segment record count is out of range")
        ids: set[str] = set()
        previous_time: int | float | None = None
        for record in self.records:
            if not isinstance(record, MemoryAuditRecord) or record.scope != self.scope:
                raise ValueError("Memory audit segment record binding is invalid")
            if record.audit_id in ids or (
                previous_time is not None and record.created_at < previous_time
            ):
                raise ValueError(
                    "Memory audit segment records are duplicated or out of order"
                )
            ids.add(record.audit_id)
            previous_time = record.created_at
        canonical_memory_blob_bytes(self.to_dict())

    @classmethod
    def from_records(
        cls,
        records: Sequence[MemoryAuditRecord | dict[str, object]],
        *,
        scope: str,
        previous: MemoryBlobReference | dict[str, object] | None,
    ) -> MemoryAuditSegment:
        if isinstance(records, (str, bytes)) or not isinstance(records, Sequence):
            raise TypeError("Memory audit segment records must be a sequence")
        decoded = tuple(
            item
            if isinstance(item, MemoryAuditRecord)
            else MemoryAuditRecord.from_dict(item, expected_scope=scope)
            for item in records
        )
        previous_ref = (
            MemoryBlobReference.from_dict(previous)
            if isinstance(previous, dict)
            else previous
        )
        return cls(scope=_scope(scope), previous=previous_ref, records=decoded)

    @property
    def record_count(self) -> int:
        return len(self.records)

    @property
    def first_created_at(self) -> int | float:
        return self.records[0].created_at

    @property
    def last_created_at(self) -> int | float:
        return self.records[-1].created_at

    def to_dict(self) -> dict[str, object]:
        return {
            "schemaVersion": self.schema_version,
            "kind": self.kind,
            "scope": self.scope,
            "previous": self.previous.to_dict() if self.previous else None,
            "records": [record.to_dict() for record in self.records],
        }

    @property
    def blob_reference(self) -> MemoryBlobReference:
        encoded = canonical_memory_blob_bytes(self.to_dict())
        return MemoryBlobReference(memory_blob_digest(encoded), len(encoded))

    @classmethod
    def from_dict(
        cls, value: object, *, expected_scope: str | None = None
    ) -> MemoryAuditSegment:
        if not isinstance(value, dict) or set(value) != _SEGMENT_FIELDS:
            raise ValueError("Memory audit segment has an invalid schema")
        if (
            type(value["schemaVersion"]) is not int
            or value["schemaVersion"] != MEMORY_AUDIT_SEGMENT_VERSION
        ):
            raise ValueError("Memory audit segment schema version is unsupported")
        if value["kind"] != MEMORY_AUDIT_SEGMENT_KIND:
            raise ValueError("Memory audit segment kind is invalid")
        scope = _scope(value["scope"], expected_scope)
        if not isinstance(value["records"], list):
            raise TypeError("Memory audit segment records must be a list")
        previous = (
            None
            if value["previous"] is None
            else MemoryBlobReference.from_dict(value["previous"])
        )
        return cls(
            scope=scope,
            previous=previous,
            records=decode_memory_audit_records(
                value["records"],
                expected_scope=scope,
                maximum_records=MAX_MEMORY_AUDIT_RECORDS_PER_SEGMENT,
            ),
        )


@dataclass(frozen=True, slots=True, kw_only=True)
class MemoryAuditHead:
    blob: MemoryBlobReference
    segment_count: int
    record_count: int

    def __post_init__(self) -> None:
        if not isinstance(self.blob, MemoryBlobReference):
            raise TypeError("Memory audit head blob is invalid")
        _count(
            self.segment_count,
            "Memory audit head segment count",
            MAX_MEMORY_AUDIT_CHAIN_SEGMENTS,
        )
        _count(
            self.record_count,
            "Memory audit head record count",
            MAX_MEMORY_AUDIT_CHAIN_RECORDS,
        )

    @classmethod
    def from_segment(
        cls,
        segment: MemoryAuditSegment,
        *,
        previous_head: MemoryAuditHead | None = None,
    ) -> MemoryAuditHead:
        if previous_head is None:
            if segment.previous is not None:
                raise ValueError("First Memory audit segment must end at null")
            return cls(
                blob=segment.blob_reference,
                segment_count=1,
                record_count=segment.record_count,
            )
        if segment.previous != previous_head.blob:
            raise ValueError("Memory audit segment does not extend the previous head")
        return cls(
            blob=segment.blob_reference,
            segment_count=previous_head.segment_count + 1,
            record_count=previous_head.record_count + segment.record_count,
        )

    def validate_segment(self, segment: MemoryAuditSegment) -> None:
        if segment.blob_reference != self.blob:
            raise ValueError("Memory audit head does not match its segment")

    def to_dict(self) -> dict[str, object]:
        return {
            "blob": self.blob.to_dict(),
            "segmentCount": self.segment_count,
            "recordCount": self.record_count,
        }

    @classmethod
    def from_dict(cls, value: object) -> MemoryAuditHead:
        if not isinstance(value, dict) or set(value) != _HEAD_FIELDS:
            raise ValueError("Memory audit head has an invalid schema")
        return cls(
            blob=MemoryBlobReference.from_dict(value["blob"]),
            segment_count=value["segmentCount"],  # type: ignore[arg-type]
            record_count=value["recordCount"],  # type: ignore[arg-type]
        )


def decode_memory_audit_head(value: object) -> MemoryAuditHead | None:
    return None if value is None else MemoryAuditHead.from_dict(value)


def validate_memory_audit_segment_chain(
    head: MemoryAuditHead | None,
    segments: Sequence[MemoryAuditSegment],
    *,
    expected_scope: str,
    hot_records: Sequence[MemoryAuditRecord] = (),
) -> int:
    """Validate a complete newest-first chain, returning its cold record count."""

    _scope(expected_scope)
    if head is None:
        if segments:
            raise ValueError("Memory audit segments exist without a head")
        cold_ids: set[str] = set()
    else:
        if len(segments) != head.segment_count:
            raise ValueError("Memory audit segment count does not match its head")
        expected: MemoryBlobReference | None = head.blob
        cold_ids = set()
        newer_first: int | float | None = None
        total = 0
        seen_digests: set[str] = set()
        for segment in segments:
            actual = segment.blob_reference
            if segment.scope != expected_scope or actual != expected:
                raise ValueError("Memory audit segment chain is broken")
            if actual.digest in seen_digests:
                raise ValueError("Memory audit segment chain contains a cycle")
            if newer_first is not None and segment.last_created_at > newer_first:
                raise ValueError("Memory audit segment chain is out of order")
            newer_first = segment.first_created_at
            seen_digests.add(actual.digest)
            for record in segment.records:
                if record.audit_id in cold_ids:
                    raise ValueError("Memory audit ID is duplicated across segments")
                cold_ids.add(record.audit_id)
            total += segment.record_count
            if total > MAX_MEMORY_AUDIT_CHAIN_RECORDS:
                raise ValueError("Memory audit segment chain is too large")
            expected = segment.previous
        if expected is not None:
            raise ValueError("Memory audit segment chain is incomplete")
        if total != head.record_count:
            raise ValueError("Memory audit record count does not match its head")

    previous_hot: int | float | None = None
    newest_cold = segments[0].last_created_at if segments else None
    for record in hot_records:
        if not isinstance(record, MemoryAuditRecord) or record.scope != expected_scope:
            raise ValueError("Memory audit hot record binding is invalid")
        if record.audit_id in cold_ids:
            raise ValueError("Memory audit ID collides across hot and cold history")
        if newest_cold is not None and record.created_at < newest_cold:
            raise ValueError("Memory audit hot and cold history is out of order")
        if previous_hot is not None and record.created_at < previous_hot:
            raise ValueError("Memory audit hot records are out of order")
        cold_ids.add(record.audit_id)
        previous_hot = record.created_at
    return head.record_count if head is not None else 0


__all__ = [
    "MAX_MEMORY_AUDIT_CHAIN_RECORDS",
    "MAX_MEMORY_AUDIT_CHAIN_SEGMENTS",
    "MAX_MEMORY_AUDIT_RECORDS_PER_SEGMENT",
    "MEMORY_AUDIT_SEGMENT_KIND",
    "MEMORY_AUDIT_SEGMENT_VERSION",
    "MemoryAuditHead",
    "MemoryAuditRecord",
    "MemoryAuditSegment",
    "decode_legacy_memory_audit_records",
    "decode_memory_audit_head",
    "decode_memory_audit_records",
    "is_memory_audit_id",
    "validate_memory_audit_segment_chain",
]

shared_files.minicode/memory_authority_publisher.py:
"""Crash-durable, directory-contained publication for Memory text files.

The Memory authority is a small replace-in-place JSON document.  Atomic
``rename`` prevents torn readers, but it does not by itself make the new bytes
survive power loss and a path-based temporary file can escape if the parent is
replaced between validation and publication.  This module owns the stronger
POSIX sequence:

1. open and bind the parent directory without following its final component;
2. create and write a private file relative to that directory descriptor;
3. fsync the private file;
4. replace the target relative to the same directory descriptor; and
5. fsync the directory before reporting success.

The portable fallback retains atomic replacement and file fsync.  Platforms
without directory descriptors cannot provide the same containment guarantee,
so every path component available through the portable API is revalidated
immediately before and after replacement.
"""

from __future__ import annotations

import os
import stat
import tempfile
import uuid
from contextlib import contextmanager
from contextvars import ContextVar
from pathlib import Path
from typing import TYPE_CHECKING, Callable, Iterator

from minicode.memory_store import (
    MemoryStoreConflict,
    MemoryStoreRootBinding,
    MemoryStoreUnavailable,
    MemoryStoreUnsafePath,
    _is_windows_reparse_point,
    _windows_path_has_reparse_component,
)

_BOUND_PUBLICATION_ROOT: ContextVar[MemoryStoreRootBinding | None] = ContextVar(
    "memory_authority_publication_root",
    default=None,
)

if TYPE_CHECKING:
    from minicode.memory_blob_store import MemoryBlobStore


def _same_inode(first: os.stat_result, second: os.stat_result) -> bool:
    return first.st_dev == second.st_dev and first.st_ino == second.st_ino


def _require_directory(metadata: os.stat_result) -> None:
    if not stat.S_ISDIR(metadata.st_mode):
        raise MemoryStoreUnsafePath("Memory publication directory is unsafe")


def _require_regular_target(metadata: os.stat_result) -> None:
    if not stat.S_ISREG(metadata.st_mode):
        raise MemoryStoreUnsafePath("Memory publication target is unsafe")


def _write_all(descriptor: int, content: bytes) -> None:
    position = 0
    while position < len(content):
        written = os.write(descriptor, content[position:])
        if written <= 0:
            raise OSError("short Memory authority write")
        position += written


def _safe_basename(path: Path) -> str:
    name = path.name
    if (
        not name
        or name in {".", ".."}
        or "/" in name
        or "\\" in name
        or "\x00" in name
    ):
        raise ValueError("Memory publication target must have a safe basename")
    return name


def _safe_relative_basename(value: str | Path, *, kind: str) -> str:
    """Return a single, exact child name rather than silently truncating a path."""

    try:
        raw = os.fspath(value)
    except TypeError as error:
        raise TypeError(f"Memory {kind} must be path-like") from error
    if not isinstance(raw, str):
        raise TypeError(f"Memory {kind} must be text")
    name = _safe_basename(Path(raw))
    if raw != name:
        raise MemoryStoreUnsafePath(
            f"Memory {kind} must be a safe basename"
        )
    return name


class MemoryScopePublication:
    """One root-bound POSIX publication session for a Memory scope.

    The coordinator continues to own the transaction-root descriptor.  This
    session owns one descriptor opened below that root and keeps every
    authority and blob operation relative to that exact scope inode.  The
    session deliberately refuses to follow a replacement pathname: a caller
    either commits into the scope it opened or fails closed.
    """

    __slots__ = (
        "_binding",
        "_closed",
        "_scope_fd",
        "_scope_name",
        "_scope_stat",
    )

    def __init__(
        self,
        *,
        binding: MemoryStoreRootBinding,
        scope_name: str,
        scope_fd: int,
        scope_stat: os.stat_result,
    ) -> None:
        self._binding = binding
        self._scope_name = scope_name
        self._scope_fd = scope_fd
        self._scope_stat = scope_stat
        self._closed = False

    @property
    def path(self) -> Path:
        """Return the display/path-compatibility projection for this scope."""

        return self._binding.root / self._scope_name

    @property
    def scope_identity(self) -> tuple[int, int]:
        """Return the device/inode identity held for the whole session."""

        return (self._scope_stat.st_dev, self._scope_stat.st_ino)

    def verify(self) -> None:
        """Fail closed unless root, scope pathname, and open fd still agree."""

        if self._closed:
            raise MemoryStoreConflict("Memory scope publication is closed")
        MemoryAuthorityPublisher._verify_bound_root(self._binding)
        if self._binding.root_fd is None:
            raise MemoryStoreUnavailable(
                "Memory publication root descriptor is unavailable"
            )
        try:
            path_state = os.stat(
                self._scope_name,
                dir_fd=self._binding.root_fd,
                follow_symlinks=False,
            )
            opened_state = os.fstat(self._scope_fd)
        except OSError as error:
            raise MemoryStoreUnsafePath(
                "Memory scope publication changed"
            ) from error
        _require_directory(path_state)
        _require_directory(opened_state)
        if (
            not _same_inode(self._scope_stat, opened_state)
            or not _same_inode(path_state, opened_state)
        ):
            raise MemoryStoreUnsafePath("Memory scope publication changed")

    def duplicate_scope_fd(self) -> int:
        """Return a verified duplicate for a scope-relative auxiliary API."""

        self.verify()
        duplicate: int | None = None
        try:
            duplicate = os.dup(self._scope_fd)
            opened_state = os.fstat(duplicate)
            _require_directory(opened_state)
            if not _same_inode(self._scope_stat, opened_state):
                raise MemoryStoreUnsafePath("Memory scope publication changed")
            self.verify()
            return duplicate
        except Exception:
            if duplicate is not None:
                os.close(duplicate)
            raise

    def publish_text(self, target_name: str | Path, content: str) -> None:
        """Publish one text child relative to this exact scope descriptor."""

        if not isinstance(content, str):
            raise TypeError("Memory publication content must be text")
        name = _safe_relative_basename(
            target_name,
            kind="publication target",
        )
        try:
            encoded = content.encode("utf-8")
        except UnicodeEncodeError as error:
            raise MemoryStoreConflict(
                "Memory publication content is not UTF-8"
            ) from error
        self.verify()
        MemoryAuthorityPublisher._publish_posix_directory(
            self._scope_fd,
            name,
            encoded,
            verify=self.verify,
        )

    def blob_store(self) -> MemoryBlobStore:
        """Return a blob store anchored to this session's scope descriptor."""

        self.verify()
        # Local import avoids a publisher/blob-store module cycle.
        from minicode.memory_blob_store import MemoryBlobStore

        return MemoryBlobStore.from_scope_publication(self)

    def close(self) -> None:
        """Close this session's owned scope descriptor exactly once."""

        if self._closed:
            return
        self._closed = True
        os.close(self._scope_fd)


class MemoryAuthorityPublisher:
    """Publish bounded Memory text without a path-based rename window."""

    @classmethod
    @contextmanager
    def open_scope(
        cls,
        binding: MemoryStoreRootBinding,
        scope_name: str | Path,
        *,
        create: bool = False,
    ) -> Iterator[MemoryScopePublication]:
        """Open one safe scope child through an active POSIX root binding.

        ``binding.root_fd`` is borrowed from ``MemoryStoreCoordinator`` and
        therefore must remain live until this context exits.  The returned
        session owns only its scope descriptor.  No publication performed by
        it resolves the scope again through an absolute pathname.
        """

        if not isinstance(binding, MemoryStoreRootBinding):
            raise TypeError("binding must be a MemoryStoreRootBinding")
        if not isinstance(create, bool):
            raise TypeError("create must be a bool")
        name = _safe_relative_basename(scope_name, kind="scope name")
        if os.name != "posix" or binding.root_fd is None:
            raise MemoryStoreUnavailable(
                "Root-bound Memory scope publication requires POSIX dirfd support"
            )

        scope_fd: int | None = None
        session: MemoryScopePublication | None = None
        created = False
        setup_complete = False
        try:
            cls._verify_bound_root(binding)
            try:
                scope_before = os.stat(
                    name,
                    dir_fd=binding.root_fd,
                    follow_symlinks=False,
                )
            except FileNotFoundError:
                if not create:
                    raise MemoryStoreUnavailable(
                        "Memory scope publication is unavailable"
                    )
                try:
                    os.mkdir(name, 0o700, dir_fd=binding.root_fd)
                    created = True
                except FileExistsError:
                    created = False
                scope_before = os.stat(
                    name,
                    dir_fd=binding.root_fd,
                    follow_symlinks=False,
                )
            _require_directory(scope_before)
            directory_flags = os.O_RDONLY | getattr(os, "O_DIRECTORY", 0)
            directory_flags |= getattr(os, "O_CLOEXEC", 0)
            directory_flags |= getattr(os, "O_NOFOLLOW", 0)
            scope_fd = os.open(name, directory_flags, dir_fd=binding.root_fd)
            scope_opened = os.fstat(scope_fd)
            _require_directory(scope_opened)
            if not _same_inode(scope_before, scope_opened):
                raise MemoryStoreUnsafePath("Memory scope publication changed")
            session = MemoryScopePublication(
                binding=binding,
                scope_name=name,
                scope_fd=scope_fd,
                scope_stat=scope_opened,
            )
            scope_fd = None  # session owns it from here
            session.verify()
            if created:
                os.fsync(session._scope_fd)
                os.fsync(binding.root_fd)
                session.verify()
            setup_complete = True
        except (
            MemoryStoreConflict,
            MemoryStoreUnavailable,
            MemoryStoreUnsafePath,
        ):
            raise
        except OSError as error:
            raise MemoryStoreUnavailable(
                "Memory scope publication is unavailable"
            ) from error
        finally:
            if not setup_complete and session is not None:
                session.close()
            elif not setup_complete and scope_fd is not None:
                try:
                    os.close(scope_fd)
                except OSError:
                    pass

        if session is None:  # defensive: setup either succeeds or raises
            raise MemoryStoreUnavailable(
                "Memory scope publication is unavailable"
            )
        try:
            # Exceptions from the caller's commit body retain their original
            # type. Only publisher-owned setup/verification OSErrors are
            # normalized to the Memory storage vocabulary.
            yield session
        except BaseException:
            raise
        else:
            try:
                session.verify()
            except (
                MemoryStoreConflict,
                MemoryStoreUnavailable,
                MemoryStoreUnsafePath,
            ):
                raise
            except OSError as error:
                raise MemoryStoreUnavailable(
                    "Memory scope publication is unavailable"
                ) from error
        finally:
            session.close()

    @classmethod
    @contextmanager
    def bind_transaction_root(
        cls,
        binding: MemoryStoreRootBinding,
    ) -> Iterator[None]:
        """Bind nested publications to an already-open coordinator root."""

        del cls
        if not isinstance(binding, MemoryStoreRootBinding):
            raise TypeError("binding must be a MemoryStoreRootBinding")
        token = _BOUND_PUBLICATION_ROOT.set(binding)
        try:
            yield
        finally:
            _BOUND_PUBLICATION_ROOT.reset(token)

    @classmethod
    def _publish_posix_directory(
        cls,
        directory_fd: int,
        name: str,
        encoded: bytes,
        *,
        verify: Callable[[], None],
    ) -> None:
        """Durably replace one child of a caller-owned verified directory fd."""

        temporary_fd: int | None = None
        temporary_name: str | None = None
        try:
            verify()
            cls._validate_posix_target(directory_fd, name)
            temporary_flags = os.O_WRONLY | os.O_CREAT | os.O_EXCL
            temporary_flags |= getattr(os, "O_CLOEXEC", 0)
            temporary_flags |= getattr(os, "O_NOFOLLOW", 0)
            for _attempt in range(16):
                candidate = f".{name}.{uuid.uuid4().hex}.tmp"
                try:
                    temporary_fd = os.open(
                        candidate,
                        temporary_flags,
                        0o600,
                        dir_fd=directory_fd,
                    )
                except FileExistsError:
                    continue
                temporary_name = candidate
                break
            if temporary_fd is None or temporary_name is None:
                raise MemoryStoreUnavailable(
                    "Memory publication temporary file is unavailable"
                )
            os.fchmod(temporary_fd, 0o600)
            _write_all(temporary_fd, encoded)
            os.fsync(temporary_fd)
            temporary_opened = os.fstat(temporary_fd)
            _require_regular_target(temporary_opened)
            if temporary_opened.st_size != len(encoded):
                raise MemoryStoreConflict(
                    "Memory publication temporary file has the wrong size"
                )

            verify()
            cls._validate_posix_target(directory_fd, name)
            temporary_path_state = os.stat(
                temporary_name,
                dir_fd=directory_fd,
                follow_symlinks=False,
            )
            _require_regular_target(temporary_path_state)
            if (
                not _same_inode(temporary_opened, temporary_path_state)
                or temporary_path_state.st_size != len(encoded)
            ):
                raise MemoryStoreUnsafePath(
                    "Memory publication temporary file changed"
                )
            os.replace(
                temporary_name,
                name,
                src_dir_fd=directory_fd,
                dst_dir_fd=directory_fd,
            )
            temporary_name = None
            published_state = os.stat(
                name,
                dir_fd=directory_fd,
                follow_symlinks=False,
            )
            _require_regular_target(published_state)
            if (
                not _same_inode(temporary_opened, published_state)
                or published_state.st_size != len(encoded)
            ):
                raise MemoryStoreUnsafePath("Memory publication target changed")
            os.fsync(directory_fd)
            verify()
        except (
            MemoryStoreConflict,
            MemoryStoreUnavailable,
            MemoryStoreUnsafePath,
        ):
            raise
        except OSError as error:
            raise MemoryStoreUnavailable("Memory publication failed") from error
        finally:
            if temporary_fd is not None:
                try:
                    os.close(temporary_fd)
                except OSError:
                    pass
            if temporary_name is not None:
                try:
                    os.unlink(temporary_name, dir_fd=directory_fd)
                except OSError:
                    pass

    @classmethod
    def ensure_directory(cls, directory: str | Path) -> None:
        """Create one authority directory and durably publish its name.

        The owner directory is allowed to be reached through an intentional
        workspace symlink, but the new/final child itself is never followed.
        Creation and validation are relative to one verified owner descriptor.
        """

        directory_path = Path(directory)
        _safe_basename(directory_path)
        owner = directory_path.parent
        try:
            os.stat(owner)
        except FileNotFoundError:
            if owner == directory_path:
                raise MemoryStoreUnavailable(
                    "Memory publication owner is unavailable"
                )
            # Preserve the historical ``mkdir(parents=True)`` contract while
            # making every newly introduced directory entry durable in order
            # from the nearest existing ancestor down to the scope root.
            cls.ensure_directory(owner)
        except OSError as error:
            raise MemoryStoreUnavailable(
                "Memory publication owner is unavailable"
            ) from error
        if os.name == "posix":
            cls._ensure_directory_posix(directory_path)
        else:
            cls._ensure_directory_portable(directory_path)

    @classmethod
    def publish_text(cls, target: str | Path, content: str) -> None:
        if not isinstance(content, str):
            raise TypeError("Memory publication content must be text")
        target_path = Path(target)
        _safe_basename(target_path)
        try:
            encoded = content.encode("utf-8")
        except UnicodeEncodeError as error:
            raise MemoryStoreConflict(
                "Memory publication content is not UTF-8"
            ) from error
        binding = _BOUND_PUBLICATION_ROOT.get()
        if binding is not None:
            relative_target = cls._bound_relative_target(binding, target_path)
            if os.name == "posix" and binding.root_fd is not None:
                cls._publish_posix_bound(
                    binding,
                    relative_target,
                    encoded,
                )
                return
            cls._verify_portable_bound_root(binding)
            cls._publish_portable(binding.root / relative_target, encoded)
            cls._verify_portable_bound_root(binding)
            return
        if os.name == "posix":
            cls._publish_posix(target_path, encoded)
        else:
            cls._publish_portable(target_path, encoded)

    @staticmethod
    def _bound_relative_target(
        binding: MemoryStoreRootBinding,
        target: Path,
    ) -> Path:
        root = Path(os.path.abspath(os.fspath(binding.root)))
        candidate = Path(os.path.abspath(os.fspath(target)))
        try:
            relative = candidate.relative_to(root)
        except ValueError as error:
            raise MemoryStoreUnsafePath(
                "Memory publication target escapes its transaction root"
            ) from error
        if not relative.parts or any(
            part in {"", ".", ".."} or "/" in part or "\\" in part
            for part in relative.parts
        ):
            raise MemoryStoreUnsafePath(
                "Memory publication target escapes its transaction root"
            )
        return relative

    @staticmethod
    def _verify_bound_root(binding: MemoryStoreRootBinding) -> None:
        binding.assert_active()
        if binding.root_fd is None:
            raise MemoryStoreUnavailable(
                "Memory publication root descriptor is unavailable"
            )
        try:
            path_state = os.lstat(binding.root)
            opened_state = os.fstat(binding.root_fd)
        except OSError as error:
            raise MemoryStoreUnsafePath(
                "Memory publication root changed"
            ) from error
        _require_directory(path_state)
        _require_directory(opened_state)
        if (
            not _same_inode(binding.root_stat, opened_state)
            or not _same_inode(path_state, opened_state)
        ):
            raise MemoryStoreUnsafePath("Memory publication root changed")

    @staticmethod
    def _verify_portable_bound_root(binding: MemoryStoreRootBinding) -> None:
        binding.assert_active()
        try:
            current = os.lstat(binding.root)
        except OSError as error:
            raise MemoryStoreUnsafePath(
                "Memory publication root changed"
            ) from error
        _require_directory(current)
        if (
            _is_windows_reparse_point(current)
            or not _same_inode(current, binding.root_stat)
        ):
            raise MemoryStoreUnsafePath("Memory publication root changed")

    @classmethod
    def _publish_posix_bound(
        cls,
        binding: MemoryStoreRootBinding,
        relative_target: Path,
        encoded: bytes,
    ) -> None:
        """Publish through the transaction root fd, never a replaced path."""

        name = _safe_basename(relative_target)
        directory_parts = tuple(relative_target.parts[:-1])
        directory_fds: list[int] = []
        directory_names: list[str] = []
        directory_states: list[os.stat_result] = []
        temporary_fd: int | None = None
        temporary_name: str | None = None

        def verify_chain() -> None:
            cls._verify_bound_root(binding)
            for index, component in enumerate(directory_names):
                parent_fd = directory_fds[index]
                child_fd = directory_fds[index + 1]
                expected = directory_states[index]
                path_state = os.stat(
                    component,
                    dir_fd=parent_fd,
                    follow_symlinks=False,
                )
                opened_state = os.fstat(child_fd)
                _require_directory(path_state)
                _require_directory(opened_state)
                if (
                    not _same_inode(expected, opened_state)
                    or not _same_inode(path_state, opened_state)
                ):
                    raise MemoryStoreUnsafePath(
                        "Memory publication directory changed"
                    )

        try:
            cls._verify_bound_root(binding)
            if binding.root_fd is None:  # narrowed by the check above
                raise MemoryStoreUnavailable(
                    "Memory publication root descriptor is unavailable"
                )
            directory_flags = os.O_RDONLY | getattr(os, "O_DIRECTORY", 0)
            directory_flags |= getattr(os, "O_CLOEXEC", 0)
            directory_flags |= getattr(os, "O_NOFOLLOW", 0)
            directory_fds.append(os.dup(binding.root_fd))
            for component in directory_parts:
                _safe_basename(Path(component))
                parent_fd = directory_fds[-1]
                path_state = os.stat(
                    component,
                    dir_fd=parent_fd,
                    follow_symlinks=False,
                )
                _require_directory(path_state)
                child_fd = os.open(component, directory_flags, dir_fd=parent_fd)
                opened_state = os.fstat(child_fd)
                _require_directory(opened_state)
                if not _same_inode(path_state, opened_state):
                    os.close(child_fd)
                    raise MemoryStoreUnsafePath(
                        "Memory publication directory changed"
                    )
                directory_names.append(component)
                directory_states.append(opened_state)
                directory_fds.append(child_fd)

            target_fd = directory_fds[-1]
            cls._validate_posix_target(target_fd, name)
            temporary_flags = os.O_WRONLY | os.O_CREAT | os.O_EXCL
            temporary_flags |= getattr(os, "O_CLOEXEC", 0)
            temporary_flags |= getattr(os, "O_NOFOLLOW", 0)
            for _attempt in range(16):
                candidate = f".{name}.{uuid.uuid4().hex}.tmp"
                try:
                    temporary_fd = os.open(
                        candidate,
                        temporary_flags,
                        0o600,
                        dir_fd=target_fd,
                    )
                except FileExistsError:
                    continue
                temporary_name = candidate
                break
            if temporary_fd is None or temporary_name is None:
                raise MemoryStoreUnavailable(
                    "Memory publication temporary file is unavailable"
                )
            os.fchmod(temporary_fd, 0o600)
            _write_all(temporary_fd, encoded)
            os.fsync(temporary_fd)
            temporary_opened = os.fstat(temporary_fd)
            _require_regular_target(temporary_opened)
            if temporary_opened.st_size != len(encoded):
                raise MemoryStoreConflict(
                    "Memory publication temporary file has the wrong size"
                )

            verify_chain()
            cls._validate_posix_target(target_fd, name)
            temporary_path_state = os.stat(
                temporary_name,
                dir_fd=target_fd,
                follow_symlinks=False,
            )
            _require_regular_target(temporary_path_state)
            if (
                not _same_inode(temporary_opened, temporary_path_state)
                or temporary_path_state.st_size != len(encoded)
            ):
                raise MemoryStoreUnsafePath(
                    "Memory publication temporary file changed"
                )
            os.replace(
                temporary_name,
                name,
                src_dir_fd=target_fd,
                dst_dir_fd=target_fd,
            )
            temporary_name = None
            published_state = os.stat(
                name,
                dir_fd=target_fd,
                follow_symlinks=False,
            )
            _require_regular_target(published_state)
            if (
                not _same_inode(temporary_opened, published_state)
                or published_state.st_size != len(encoded)
            ):
                raise MemoryStoreUnsafePath(
                    "Memory publication target changed"
                )
            os.fsync(target_fd)
            verify_chain()
        except (MemoryStoreConflict, MemoryStoreUnavailable, MemoryStoreUnsafePath):
            raise
        except OSError as error:
            raise MemoryStoreUnavailable("Memory publication failed") from error
        finally:
            if temporary_fd is not None:
                try:
                    os.close(temporary_fd)
                except OSError:
                    pass
            if temporary_name is not None and directory_fds:
                try:
                    os.unlink(temporary_name, dir_fd=directory_fds[-1])
                except OSError:
                    pass
            for descriptor in reversed(directory_fds):
                try:
                    os.close(descriptor)
                except OSError:
                    pass

    @staticmethod
    def _verify_posix_owner(
        owner: Path,
        descriptor: int,
        *,
        expected: os.stat_result,
    ) -> None:
        try:
            path_state = os.stat(owner)
            opened_state = os.fstat(descriptor)
        except OSError as error:
            raise MemoryStoreUnsafePath(
                "Memory publication owner changed"
            ) from error
        _require_directory(path_state)
        _require_directory(opened_state)
        if (
            not _same_inode(expected, opened_state)
            or not _same_inode(path_state, opened_state)
        ):
            raise MemoryStoreUnsafePath("Memory publication owner changed")

    @staticmethod
    def _verify_posix_child(
        owner_fd: int,
        name: str,
        child_fd: int,
        *,
        expected: os.stat_result,
    ) -> None:
        try:
            path_state = os.stat(
                name,
                dir_fd=owner_fd,
                follow_symlinks=False,
            )
            opened_state = os.fstat(child_fd)
        except OSError as error:
            raise MemoryStoreUnsafePath(
                "Memory publication directory changed"
            ) from error
        _require_directory(path_state)
        _require_directory(opened_state)
        if (
            not _same_inode(expected, opened_state)
            or not _same_inode(path_state, opened_state)
        ):
            raise MemoryStoreUnsafePath(
                "Memory publication directory changed"
            )

    @classmethod
    def _ensure_directory_posix(cls, directory: Path) -> None:
        owner = directory.parent
        name = _safe_basename(directory)
        try:
            owner_before = os.stat(owner)
        except OSError as error:
            raise MemoryStoreUnavailable(
                "Memory publication owner is unavailable"
            ) from error
        _require_directory(owner_before)

        owner_fd: int | None = None
        child_fd: int | None = None
        try:
            directory_flags = os.O_RDONLY | getattr(os, "O_DIRECTORY", 0)
            directory_flags |= getattr(os, "O_CLOEXEC", 0)
            # Do not use O_NOFOLLOW for the owner: opening a repository through
            # an intentional workspace symlink is supported.  The inode checks
            # still bind the resolved owner throughout this operation.
            owner_fd = os.open(owner, directory_flags)
            owner_opened = os.fstat(owner_fd)
            _require_directory(owner_opened)
            if not _same_inode(owner_before, owner_opened):
                raise MemoryStoreUnsafePath(
                    "Memory publication owner changed"
                )
            try:
                child_before = os.stat(
                    name,
                    dir_fd=owner_fd,
                    follow_symlinks=False,
                )
                created = False
            except FileNotFoundError:
                try:
                    os.mkdir(name, 0o700, dir_fd=owner_fd)
                    created = True
                except FileExistsError:
                    created = False
                child_before = os.stat(
                    name,
                    dir_fd=owner_fd,
                    follow_symlinks=False,
                )
            _require_directory(child_before)
            child_flags = directory_flags | getattr(os, "O_NOFOLLOW", 0)
            child_fd = os.open(name, child_flags, dir_fd=owner_fd)
            child_opened = os.fstat(child_fd)
            _require_directory(child_opened)
            if not _same_inode(child_before, child_opened):
                raise MemoryStoreUnsafePath(
                    "Memory publication directory changed"
                )
            cls._verify_posix_owner(
                owner,
                owner_fd,
                expected=owner_opened,
            )
            cls._verify_posix_child(
                owner_fd,
                name,
                child_fd,
                expected=child_opened,
            )
            if created:
                os.fsync(child_fd)
                os.fsync(owner_fd)
                cls._verify_posix_owner(
                    owner,
                    owner_fd,
                    expected=owner_opened,
                )
                cls._verify_posix_child(
                    owner_fd,
                    name,
                    child_fd,
                    expected=child_opened,
                )
        except (MemoryStoreConflict, MemoryStoreUnavailable, MemoryStoreUnsafePath):
            raise
        except OSError as error:
            raise MemoryStoreUnavailable(
                "Memory publication directory is unavailable"
            ) from error
        finally:
            if child_fd is not None:
                try:
                    os.close(child_fd)
                except OSError:
                    pass
            if owner_fd is not None:
                try:
                    os.close(owner_fd)
                except OSError:
                    pass

    @staticmethod
    def _ensure_directory_portable(directory: Path) -> None:
        try:
            if directory.is_symlink() or _windows_path_has_reparse_component(
                directory.parent
            ):
                raise MemoryStoreUnsafePath(
                    "Memory publication directory is unsafe"
                )
            directory.mkdir(mode=0o700, exist_ok=True)
            metadata = os.lstat(directory)
        except MemoryStoreUnsafePath:
            raise
        except OSError as error:
            raise MemoryStoreUnavailable(
                "Memory publication directory is unavailable"
            ) from error
        _require_directory(metadata)
        if _is_windows_reparse_point(metadata):
            raise MemoryStoreUnsafePath(
                "Memory publication directory is unsafe"
            )

    @staticmethod
    def _verify_posix_parent(
        parent: Path,
        descriptor: int,
        *,
        expected: os.stat_result,
    ) -> None:
        try:
            path_state = os.lstat(parent)
            opened_state = os.fstat(descriptor)
        except OSError as error:
            raise MemoryStoreUnsafePath(
                "Memory publication directory changed"
            ) from error
        _require_directory(path_state)
        _require_directory(opened_state)
        if (
            not _same_inode(expected, opened_state)
            or not _same_inode(path_state, opened_state)
        ):
            raise MemoryStoreUnsafePath(
                "Memory publication directory changed"
            )

    @staticmethod
    def _validate_posix_target(parent_fd: int, name: str) -> None:
        try:
            metadata = os.stat(
                name,
                dir_fd=parent_fd,
                follow_symlinks=False,
            )
        except FileNotFoundError:
            return
        _require_regular_target(metadata)

    @classmethod
    def _publish_posix(cls, target: Path, encoded: bytes) -> None:
        parent = target.parent
        name = _safe_basename(target)
        try:
            parent_before = os.lstat(parent)
