shared_files.minicode/memory_blob_store.py:
"""Immutable, content-addressed JSON blobs for Memory authority auxiliaries.

The primary ``memory.json`` authority should contain only bounded references to
large, immutable auxiliary records.  This module owns those auxiliary bytes:
each blob is canonical strict JSON, addressed by its lowercase SHA-256 digest,
and published with create-if-absent semantics below one fixed scope directory.

This is deliberately not a garbage collector.  Removing a referenced blob can
make an otherwise valid authority impossible to replay, so deletion belongs to
a future, authority-aware retention protocol.
"""

from __future__ import annotations

import hashlib
import json
import os
import re
import stat
import uuid
from dataclasses import dataclass
from pathlib import Path
from typing import TYPE_CHECKING, Any

from minicode.memory_authority_io import (
    MemoryAuthorityLimitError,
    parse_memory_authority_json,
    validate_memory_authority_value,
)
from minicode.memory_authority_publisher import MemoryAuthorityPublisher
from minicode.memory_store import (
    MemoryStoreConflict,
    MemoryStoreUnavailable,
    MemoryStoreUnsafePath,
)

if TYPE_CHECKING:
    from minicode.memory_authority_publisher import MemoryScopePublication

MAX_MEMORY_BLOB_BYTES = 64 * 1024
MEMORY_BLOB_DIRECTORY_NAME = "authority-blobs-v1"

_DIGEST_RE = re.compile(r"^[0-9a-f]{64}$")
_REFERENCE_FIELDS = frozenset({"digest", "sizeBytes"})


class MemoryBlobMissingError(MemoryStoreConflict):
    """A requested immutable blob or its not-yet-created store is absent."""


@dataclass(frozen=True, slots=True)
class MemoryBlobReference:
    """A bounded reference to one immutable canonical JSON blob."""

    digest: str
    size_bytes: int

    def __post_init__(self) -> None:
        _require_digest(self.digest)
        if (
            isinstance(self.size_bytes, bool)
            or not isinstance(self.size_bytes, int)
            or not 0 < self.size_bytes <= MAX_MEMORY_BLOB_BYTES
        ):
            raise ValueError("Memory blob size is invalid")

    @property
    def filename(self) -> str:
        """Return the only valid on-disk basename for this reference."""

        return f"{self.digest}.json"

    def to_dict(self) -> dict[str, object]:
        """Return the compact closed reference document."""

        return {"digest": self.digest, "sizeBytes": self.size_bytes}

    @classmethod
    def from_dict(cls, value: object) -> MemoryBlobReference:
        """Parse a compact reference without defaulting or repair."""

        if not isinstance(value, dict) or set(value) != _REFERENCE_FIELDS:
            raise ValueError("Memory blob reference has an invalid schema")
        return cls(
            digest=value.get("digest"),  # type: ignore[arg-type]
            size_bytes=value.get("sizeBytes"),  # type: ignore[arg-type]
        )


def canonical_memory_blob_bytes(value: Any) -> bytes:
    """Encode one bounded strict JSON value into its canonical blob bytes."""

    validate_memory_authority_value(value)
    try:
        encoded = json.dumps(
            value,
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
            allow_nan=False,
        ).encode("utf-8")
    except (TypeError, ValueError, UnicodeEncodeError) as error:
        raise ValueError("Memory blob value is not canonical JSON") from error
    if not encoded or len(encoded) > MAX_MEMORY_BLOB_BYTES:
        raise MemoryAuthorityLimitError("memory_blob_limit_exceeded")
    return encoded


def memory_blob_digest(encoded: bytes) -> str:
    """Return the lowercase SHA-256 address of canonical blob bytes."""

    if not isinstance(encoded, bytes):
        raise TypeError("Memory blob content must be bytes")
    return hashlib.sha256(encoded).hexdigest()


def _require_digest(value: object) -> str:
    if not isinstance(value, str) or _DIGEST_RE.fullmatch(value) is None:
        raise ValueError("Memory blob digest is invalid")
    return value


def _same_inode(first: os.stat_result, second: os.stat_result) -> bool:
    return first.st_dev == second.st_dev and first.st_ino == second.st_ino


def _same_file_version(first: os.stat_result, second: os.stat_result) -> bool:
    # Publishing uses a hard link followed by removal of its private temporary
    # name.  That removal legitimately changes ctime/link-count while an
    # idempotent concurrent reader may already have the immutable target open.
    # The inode, size, mtime, exact bytes, and content digest still bind the
    # version relevant to this store.
    return (
        _same_inode(first, second)
        and first.st_size == second.st_size
        and first.st_mtime_ns == second.st_mtime_ns
    )


def _require_directory(metadata: os.stat_result) -> None:
    if not stat.S_ISDIR(metadata.st_mode):
        raise MemoryStoreUnsafePath("Memory blob directory is unsafe")


def _require_blob_file(metadata: os.stat_result) -> None:
    if not stat.S_ISREG(metadata.st_mode):
        raise MemoryStoreUnsafePath("Memory blob path is unsafe")
    if not 0 < metadata.st_size <= MAX_MEMORY_BLOB_BYTES:
        raise MemoryStoreConflict("Memory blob has an invalid size")


def _fsync_directory(descriptor: int) -> None:
    try:
        os.fsync(descriptor)
    except OSError as error:
        raise MemoryStoreUnavailable("Memory blob directory is unavailable") from error


def _write_all(descriptor: int, content: bytes) -> None:
    position = 0
    while position < len(content):
        written = os.write(descriptor, content[position:])
        if written <= 0:
            raise OSError("short Memory blob write")
        position += written


def _read_all(descriptor: int) -> bytes:
    chunks: list[bytes] = []
    remaining = MAX_MEMORY_BLOB_BYTES + 1
    while remaining:
        chunk = os.read(descriptor, min(64 * 1024, remaining))
        if not chunk:
            break
        chunks.append(chunk)
        remaining -= len(chunk)
    content = b"".join(chunks)
    if not content or len(content) > MAX_MEMORY_BLOB_BYTES:
        raise MemoryStoreConflict("Memory blob has an invalid size")
    return content


def _decode_blob(
    content: bytes,
    *,
    expected_digest: str,
    expected_size: int | None,
) -> Any:
    if expected_size is not None and len(content) != expected_size:
        raise MemoryStoreConflict("Memory blob size does not match its reference")
    if memory_blob_digest(content) != expected_digest:
        raise MemoryStoreConflict("Memory blob digest does not match its address")
    try:
        text = content.decode("utf-8")
        parsed = parse_memory_authority_json(text)
        canonical = canonical_memory_blob_bytes(parsed)
    except (UnicodeDecodeError, TypeError, ValueError) as error:
        raise MemoryStoreConflict("Memory blob is not strict canonical JSON") from error
    if canonical != content:
        raise MemoryStoreConflict("Memory blob is not canonical JSON")
    return parsed


class MemoryBlobStore:
    """Store immutable JSON blobs below one Memory scope authority root."""

    def __init__(
        self,
        scope_root: str | Path,
        *,
        _scope_publication: MemoryScopePublication | None = None,
    ) -> None:
        self._scope_root = Path(scope_root)
        self._blob_root = self._scope_root / MEMORY_BLOB_DIRECTORY_NAME
        self._scope_publication = _scope_publication

    @classmethod
    def from_scope_publication(
        cls,
        publication: MemoryScopePublication,
    ) -> MemoryBlobStore:
        """Create a blob store bound to an open scope publication session."""

        from minicode.memory_authority_publisher import MemoryScopePublication

        if not isinstance(publication, MemoryScopePublication):
            raise TypeError("publication must be a MemoryScopePublication")
        publication.verify()
        return cls(
            publication.path,
            _scope_publication=publication,
        )

    @property
    def root(self) -> Path:
        """Return the fixed auxiliary directory used by this store."""

        return self._blob_root

    def put_json(self, value: Any) -> MemoryBlobReference:
        """Publish a canonical JSON value once and return its content address.

        A concurrent writer of the same bytes is idempotent.  An existing file
        at the address must contain those exact canonical bytes; any collision,
        corruption, redirect, or special file fails closed.
        """

        encoded = canonical_memory_blob_bytes(value)
        reference = MemoryBlobReference(
            digest=memory_blob_digest(encoded),
            size_bytes=len(encoded),
        )
        # Ordinary Memory telemetry rewrites the compact authority frequently.
        # Avoid manufacturing and fsyncing a temporary hard-link source for a
        # blob that was already verified in this content-addressed store.
        try:
            existing = self.read_json(reference)
        except MemoryBlobMissingError:
            pass
        else:
            if canonical_memory_blob_bytes(existing) != encoded:
                raise MemoryStoreConflict("Memory blob address is occupied")
            return reference
        if os.name == "posix":
            self._put_posix(reference, encoded)
        else:
            self._put_portable(reference, encoded)
        return reference

    def read_json(self, reference: MemoryBlobReference | str) -> Any:
        """Read and verify one blob without creating any filesystem state."""

        if isinstance(reference, MemoryBlobReference):
            digest = reference.digest
            expected_size: int | None = reference.size_bytes
        else:
            digest = _require_digest(reference)
            expected_size = None
        filename = f"{digest}.json"
        if os.name == "posix":
            root_fd, blob_fd = self._open_posix_roots(create=False)
            try:
                result = self._read_posix_blob(
                    blob_fd,
                    filename,
                    digest=digest,
                    expected_size=expected_size,
                )
                self._verify_posix_roots(root_fd, blob_fd)
                return result
            finally:
                os.close(blob_fd)
                os.close(root_fd)
        return self._read_portable_blob(
            self._blob_root / filename,
            digest=digest,
            expected_size=expected_size,
        )

    def _open_posix_roots(self, *, create: bool) -> tuple[int, int]:
        root_fd: int | None = None
        blob_fd: int | None = None
        opened = False
        try:
            directory_flags = os.O_RDONLY | getattr(os, "O_DIRECTORY", 0)
            directory_flags |= getattr(os, "O_CLOEXEC", 0)
            directory_flags |= getattr(os, "O_NOFOLLOW", 0)
            if self._scope_publication is not None:
                root_fd = self._scope_publication.duplicate_scope_fd()
                root_before = os.fstat(root_fd)
            else:
                if create:
                    MemoryAuthorityPublisher.ensure_directory(self._scope_root)
                try:
                    root_before = os.lstat(self._scope_root)
                except FileNotFoundError as error:
                    raise MemoryBlobMissingError(
                        "Memory blob scope root is missing"
                    ) from error
                except OSError as error:
                    raise MemoryStoreUnavailable(
                        "Memory blob scope root is unavailable"
                    ) from error
                _require_directory(root_before)
                root_fd = os.open(self._scope_root, directory_flags)
                root_opened = os.fstat(root_fd)
                if not _same_inode(root_before, root_opened):
                    raise MemoryStoreUnsafePath(
                        "Memory blob scope root changed"
                    )
            _require_directory(root_before)

            try:
                blob_before = os.stat(
                    MEMORY_BLOB_DIRECTORY_NAME,
                    dir_fd=root_fd,
                    follow_symlinks=False,
                )
                blob_created = False
            except FileNotFoundError:
                if not create:
                    raise MemoryBlobMissingError(
                        "Memory blob directory is missing"
                    )
                try:
                    os.mkdir(MEMORY_BLOB_DIRECTORY_NAME, 0o700, dir_fd=root_fd)
                    blob_created = True
                except FileExistsError:
                    blob_created = False
                blob_before = os.stat(
                    MEMORY_BLOB_DIRECTORY_NAME,
                    dir_fd=root_fd,
                    follow_symlinks=False,
                )
            _require_directory(blob_before)
            blob_fd = os.open(
                MEMORY_BLOB_DIRECTORY_NAME,
                directory_flags,
                dir_fd=root_fd,
            )
            blob_opened = os.fstat(blob_fd)
            if not _same_inode(blob_before, blob_opened):
                raise MemoryStoreUnsafePath("Memory blob directory changed")
            if blob_created:
                # The blob file itself and blob directory are fsynced by the
                # publish path below.  Persist this newly created directory's
                # name in the scope root before allowing a standalone
                # ``put_json`` call to report success.
                _fsync_directory(blob_fd)
                _fsync_directory(root_fd)
                if self._scope_publication is not None:
                    self._scope_publication.verify()
            self._verify_posix_roots(
                root_fd,
                blob_fd,
                root_before=root_before,
                blob_before=blob_before,
            )
            opened = True
            return root_fd, blob_fd
        except (MemoryStoreConflict, MemoryStoreUnsafePath):
            raise
        except OSError as error:
            raise MemoryStoreUnavailable(
                "Memory blob storage is unavailable"
            ) from error
        finally:
            if not opened and blob_fd is not None:
                os.close(blob_fd)
            if not opened and root_fd is not None:
                os.close(root_fd)

    def _verify_posix_roots(
        self,
        root_fd: int,
        blob_fd: int,
        *,
        root_before: os.stat_result | None = None,
        blob_before: os.stat_result | None = None,
    ) -> None:
        try:
            root_opened = os.fstat(root_fd)
            if self._scope_publication is None:
                root_path = os.lstat(self._scope_root)
            else:
                self._scope_publication.verify()
                root_path = root_opened
            blob_path = os.stat(
                MEMORY_BLOB_DIRECTORY_NAME,
                dir_fd=root_fd,
                follow_symlinks=False,
            )
            blob_opened = os.fstat(blob_fd)
        except OSError as error:
            raise MemoryStoreUnsafePath("Memory blob directory changed") from error
        _require_directory(root_path)
        _require_directory(root_opened)
        _require_directory(blob_path)
        _require_directory(blob_opened)
        if (
            not _same_inode(root_path, root_opened)
            or not _same_inode(blob_path, blob_opened)
            or (root_before is not None and not _same_inode(root_before, root_opened))
            or (blob_before is not None and not _same_inode(blob_before, blob_opened))
        ):
            raise MemoryStoreUnsafePath("Memory blob directory changed")
        if self._scope_publication is not None:
            if (
                root_opened.st_dev,
                root_opened.st_ino,
            ) != self._scope_publication.scope_identity:
                raise MemoryStoreUnsafePath("Memory blob scope root changed")

    def _put_posix(
        self,
        reference: MemoryBlobReference,
        encoded: bytes,
    ) -> None:
        root_fd, blob_fd = self._open_posix_roots(create=True)
        temporary_name: str | None = None
        temporary_fd: int | None = None
        published = False
        try:
            flags = os.O_WRONLY | os.O_CREAT | os.O_EXCL
            flags |= getattr(os, "O_CLOEXEC", 0)
            flags |= getattr(os, "O_NOFOLLOW", 0)
            for _attempt in range(16):
                candidate = f".memory-blob-{uuid.uuid4().hex}.tmp"
                try:
                    temporary_fd = os.open(candidate, flags, 0o600, dir_fd=blob_fd)
                except FileExistsError:
                    continue
                temporary_name = candidate
                break
            if temporary_fd is None or temporary_name is None:
                raise MemoryStoreUnavailable(
                    "Memory blob temporary file is unavailable"
                )
            os.fchmod(temporary_fd, 0o600)
            _write_all(temporary_fd, encoded)
            os.fsync(temporary_fd)
            os.close(temporary_fd)
            temporary_fd = None
            self._verify_posix_roots(root_fd, blob_fd)
            try:
                os.link(
                    temporary_name,
                    reference.filename,
                    src_dir_fd=blob_fd,
                    dst_dir_fd=blob_fd,
                    follow_symlinks=False,
                )
                published = True
            except FileExistsError:
                existing = self._read_posix_blob(
                    blob_fd,
                    reference.filename,
                    digest=reference.digest,
                    expected_size=reference.size_bytes,
                )
                if canonical_memory_blob_bytes(existing) != encoded:
                    raise MemoryStoreConflict("Memory blob address is occupied")
            _fsync_directory(blob_fd)
            self._verify_posix_roots(root_fd, blob_fd)
        except (
            MemoryAuthorityLimitError,
            MemoryStoreConflict,
            MemoryStoreUnavailable,
            MemoryStoreUnsafePath,
            TypeError,
            ValueError,
        ):
            raise
        except OSError as error:
            raise MemoryStoreUnavailable(
                "Memory blob could not be persisted"
            ) from error
        finally:
            if temporary_fd is not None:
                os.close(temporary_fd)
            if temporary_name is not None:
                try:
                    os.unlink(temporary_name, dir_fd=blob_fd)
                    if published:
                        _fsync_directory(blob_fd)
                except FileNotFoundError:
                    pass
                except (OSError, MemoryStoreUnavailable):
                    # The immutable target was already fsynced.  A leftover
                    # private temporary file is degraded storage health, not a
                    # reason to misreport the committed blob as absent.
                    pass
            os.close(blob_fd)
            os.close(root_fd)

    def _read_posix_blob(
        self,
        blob_fd: int,
        filename: str,
        *,
        digest: str,
        expected_size: int | None,
    ) -> Any:
        descriptor: int | None = None
        try:
            try:
                path_before = os.stat(
                    filename,
                    dir_fd=blob_fd,
                    follow_symlinks=False,
                )
            except FileNotFoundError as error:
                raise MemoryBlobMissingError("Memory blob is missing") from error
            _require_blob_file(path_before)
            flags = os.O_RDONLY | getattr(os, "O_CLOEXEC", 0)
            flags |= getattr(os, "O_NOFOLLOW", 0)
            flags |= getattr(os, "O_NONBLOCK", 0)
            descriptor = os.open(filename, flags, dir_fd=blob_fd)
            opened_before = os.fstat(descriptor)
            _require_blob_file(opened_before)
            if not _same_inode(path_before, opened_before):
                raise MemoryStoreConflict("Memory blob changed during read")
            content = _read_all(descriptor)
            opened_after = os.fstat(descriptor)
            path_after = os.stat(
                filename,
                dir_fd=blob_fd,
                follow_symlinks=False,
            )
            _require_blob_file(opened_after)
            _require_blob_file(path_after)
            if (
                not _same_file_version(path_before, path_after)
                or not _same_file_version(opened_before, opened_after)
                or not _same_inode(path_after, opened_after)
            ):
                raise MemoryStoreConflict("Memory blob changed during read")
            return _decode_blob(
                content,
                expected_digest=digest,
                expected_size=expected_size,
            )
        except (
            MemoryStoreConflict,
            MemoryStoreUnavailable,
            MemoryStoreUnsafePath,
        ):
            raise
        except OSError as error:
            raise MemoryStoreUnavailable("Memory blob is unavailable") from error
        finally:
            if descriptor is not None:
                os.close(descriptor)

    def _prepare_portable_roots(self, *, create: bool) -> None:
        if create:
            try:
                self._scope_root.mkdir(parents=True, exist_ok=True, mode=0o700)
            except FileExistsError:
                pass
            except OSError as error:
                raise MemoryStoreUnavailable(
                    "Memory blob scope root is unavailable"
                ) from error
        try:
            root_before = os.lstat(self._scope_root)
        except FileNotFoundError as error:
            raise MemoryBlobMissingError(
                "Memory blob scope root is missing"
            ) from error
        _require_directory(root_before)
        if create:
            try:
                self._blob_root.mkdir(mode=0o700)
            except FileExistsError:
                pass
            except OSError as error:
                raise MemoryStoreUnavailable(
                    "Memory blob directory is unavailable"
                ) from error
        try:
            blob_metadata = os.lstat(self._blob_root)
        except FileNotFoundError as error:
            raise MemoryBlobMissingError(
                "Memory blob directory is missing"
            ) from error
        _require_directory(blob_metadata)

    def _put_portable(
        self,
        reference: MemoryBlobReference,
        encoded: bytes,
    ) -> None:
        self._prepare_portable_roots(create=True)
        temporary = self._blob_root / f".memory-blob-{uuid.uuid4().hex}.tmp"
        target = self._blob_root / reference.filename
        descriptor: int | None = None
        try:
            flags = os.O_WRONLY | os.O_CREAT | os.O_EXCL
            flags |= getattr(os, "O_CLOEXEC", 0)
            flags |= getattr(os, "O_NOFOLLOW", 0)
            descriptor = os.open(temporary, flags, 0o600)
            _write_all(descriptor, encoded)
            os.fsync(descriptor)
            os.close(descriptor)
            descriptor = None
            try:
                os.link(temporary, target, follow_symlinks=False)
            except FileExistsError:
                existing = self._read_portable_blob(
                    target,
                    digest=reference.digest,
                    expected_size=reference.size_bytes,
                )
                if canonical_memory_blob_bytes(existing) != encoded:
                    raise MemoryStoreConflict("Memory blob address is occupied")
        except (
            MemoryStoreConflict,
            MemoryStoreUnavailable,
            MemoryStoreUnsafePath,
            TypeError,
            ValueError,
        ):
            raise
        except OSError as error:
            raise MemoryStoreUnavailable(
                "Memory blob could not be persisted"
            ) from error
        finally:
            if descriptor is not None:
                os.close(descriptor)
            try:
                temporary.unlink()
            except FileNotFoundError:
                pass

    def _read_portable_blob(
        self,
        path: Path,
        *,
        digest: str,
        expected_size: int | None,
    ) -> Any:
        self._prepare_portable_roots(create=False)
        descriptor: int | None = None
        try:
            try:
                path_before = os.lstat(path)
            except FileNotFoundError as error:
                raise MemoryBlobMissingError("Memory blob is missing") from error
            _require_blob_file(path_before)
            flags = os.O_RDONLY | getattr(os, "O_CLOEXEC", 0)
            flags |= getattr(os, "O_NOFOLLOW", 0)
            flags |= getattr(os, "O_NONBLOCK", 0)
            descriptor = os.open(path, flags)
            opened_before = os.fstat(descriptor)
            _require_blob_file(opened_before)
            if not _same_inode(path_before, opened_before):
                raise MemoryStoreConflict("Memory blob changed during read")
            content = _read_all(descriptor)
            opened_after = os.fstat(descriptor)
            path_after = os.lstat(path)
            _require_blob_file(opened_after)
            _require_blob_file(path_after)
            if (
                not _same_file_version(path_before, path_after)
                or not _same_file_version(opened_before, opened_after)
                or not _same_inode(path_after, opened_after)
            ):
                raise MemoryStoreConflict("Memory blob changed during read")
            return _decode_blob(
                content,
                expected_digest=digest,
                expected_size=expected_size,
            )
        except (
            MemoryStoreConflict,
            MemoryStoreUnavailable,
            MemoryStoreUnsafePath,
        ):
            raise
        except OSError as error:
            raise MemoryStoreUnavailable("Memory blob is unavailable") from error
        finally:
            if descriptor is not None:
                os.close(descriptor)


__all__ = [
    "MAX_MEMORY_BLOB_BYTES",
    "MEMORY_BLOB_DIRECTORY_NAME",
    "MemoryBlobMissingError",
    "MemoryBlobReference",
    "MemoryBlobStore",
    "canonical_memory_blob_bytes",
    "memory_blob_digest",
]

"""Deterministic consolidation for post-gate persistent-memory candidates."""

from __future__ import annotations

import hashlib
import itertools
import re
from dataclasses import dataclass, field
from difflib import SequenceMatcher
from enum import Enum
from typing import TYPE_CHECKING, Any, Iterable

from minicode.memory_lexical_policy import CONSOLIDATION_LEXICAL_V1

if TYPE_CHECKING:
    from minicode.memory_retrieval import MemoryRetrievalRequest, RetrievedMemory


_FILE_RE = re.compile(
    r"(?:^|[\s`'\"(])([a-zA-Z0-9_.-]+(?:/[a-zA-Z0-9_.-]+)+|"
    r"[a-zA-Z0-9_.-]+\.(?:py|pyi|js|jsx|ts|tsx|java|go|rs|rb|php|sql|"
    r"json|ya?ml|toml|ini|cfg|md|sh|css|html))(?=$|[\s`'\"),:;])",
    re.I,
)
_GENERIC_CHAIN_TERMS = {
    "api",
    "apply",
    "build",
    "change",
    "code",
    "current",
    "error",
    "failure",
    "file",
    "fix",
    "general",
    "implement",
    "memory",
    "project",
    "request",
    "review",
    "rule",
    "setting",
    "system",
    "test",
    "update",
    "use",
    "修复",
    "更新",
    "使用",
    "验证",
}
_NON_OBJECT_TERMS = _GENERIC_CHAIN_TERMS | {
    "duplicate",
    "example",
    "examples",
    "format",
    "formatting",
    "heading",
    "headings",
    "label",
    "labels",
    "page",
}
_NOISE_CATEGORIES = {
    "convention",
    "documentation",
    "frontend",
    "preference",
    "style",
}
_USER_CONSTRAINT_CATEGORIES = {
    "convention",
    "preference",
    "style",
    "testing",
}
_DOCUMENTATION_RE = re.compile(
    r"\b(background notes?|buttons?|examples?|glossary|headings?|hostnames?|"
    r"labels?|page|screenshots?|sentence case|tables?|title case|unrelated)\b",
    re.I,
)
_CONSTRAINT_RE = re.compile(
    r"\b(always|explicit|fixed|forbidden|includes?|log|must|never|prefer|requires?|"
    r"should|show|small|use|uses)\b|(?:必须|应当|应该|禁止|偏好|使用)",
    re.I,
)
_VERIFICATION_RE = re.compile(
    r"\b(assert|check|passed|regression|smoke test|test|tests|verify|verified|"
    r"verification)\b|(?:验证|测试|通过)",
    re.I,
)
_VERIFIED_AUTHORITY_RE = re.compile(
    r"\b(confirmed|passed|validated|verified)\b|(?:已经验证|已验证|验证通过|测试通过)",
    re.I,
)
_UNVERIFIED_RE = re.compile(
    r"\b(may|might|not verified|no verification|possible|unverified)\b|"
    r"(?:可能|未经验证|未验证)",
    re.I,
)
_CONFLICT_RISK_RE = re.compile(
    r"\b(all failures?|always|disable|every|forever|infinite|never|"
    r"request order|skip|without delay)\b|(?:永久|无限|全部|跳过|禁用)",
    re.I,
)
_NUMBER_WORD = (
    r"zero|one|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve|"
    r"thirteen|fourteen|fifteen|sixteen|seventeen|eighteen|nineteen|twenty|"
    r"thirty|forty|fifty|sixty|seventy|eighty|ninety|hundred|thousand"
)
_QUANTITY_RE = re.compile(
    rf"\b(?:\d+(?:\.\d+)?|(?:{_NUMBER_WORD})(?:-(?:{_NUMBER_WORD}))?)\s*"
    r"(?:ms|milliseconds?|seconds?|minutes?|hours?|days?|times?|retries?)\b",
    re.I,
)
_RELATION_KEYS = {
    "canonical": "canonical",
    "canonical_id": "canonical",
    "conflicts": "conflicts_with",
    "conflicts_with": "conflicts_with",
    "related": "related_to",
    "related_to": "related_to",
    "superseded_by": "superseded_by",
    "supersedes": "supersedes",
}


class SuppressionReason(str, Enum):
    """Stable, non-sensitive reason codes for consolidation decisions."""

    CANDIDATE_LIMIT = "candidate_limit"
    INACTIVE_FAIL_CLOSED = "inactive_fail_closed"
    SUPERSEDED = "superseded"
    UNVERIFIED_RECOVERY = "unverified_recovery"
    LOWER_AUTHORITY_CONFLICT = "lower_authority_conflict"
    UNRESOLVED_CONFLICT = "unresolved_conflict"
    NEAR_DUPLICATE = "near_duplicate"
    NO_INCREMENTAL_VALUE = "no_incremental_value"


@dataclass(frozen=True)
class CandidateSignals:
    """Bounded structured signals extracted from an entry without raw diagnostics."""

    authority_signals: tuple[str, ...] = ()
    relations: tuple[tuple[str, str], ...] = ()
    visited_nodes: int = 0
    node_limit: int = 64
    truncated: bool = False


@dataclass(frozen=True)
class CandidateSuppression:
    entry_id: str
    reason: SuppressionReason
    dominating_candidate_id: str = ""
    chain_key: str = ""
    reason_codes: tuple[str, ...] = ()

    def to_dict(self) -> dict[str, Any]:
        return {
            "entry_id": self.entry_id,
            "reason": self.reason.value,
            "dominating_candidate_id": self.dominating_candidate_id,
            "chain_key": self.chain_key,
            "reason_codes": list(self.reason_codes),
        }


@dataclass(frozen=True)
class ConsolidationResult:
    retained: tuple["RetrievedMemory", ...] = ()
    suppressed: tuple[CandidateSuppression, ...] = ()
    diagnostics: dict[str, Any] = field(default_factory=dict)

    @property
    def retained_ids(self) -> tuple[str, ...]:
        return tuple(candidate.entry_id for candidate in self.retained)

    @property
    def suppressed_ids(self) -> tuple[str, ...]:
        return tuple(item.entry_id for item in self.suppressed)


@dataclass(frozen=True)
class _Features:
    entry_id: str
    content_tokens: frozenset[str]
    matched_terms: frozenset[str]
    specific_matched_terms: frozenset[str]
    file_keys: frozenset[str]
    domains: frozenset[str]
    authority_signals: frozenset[str]
    relations: tuple[tuple[str, str], ...]
    quantities: frozenset[str]


def _normalize(value: object) -> str:
    """Compatibility wrapper for consolidation V1 scalar normalization."""
    return CONSOLIDATION_LEXICAL_V1.normalize_scalar(value)


def _stem(term: str) -> str:
    """Compatibility wrapper for consolidation V1 stemming."""
    return CONSOLIDATION_LEXICAL_V1.stem(term)


def _tokens(value: object, *, limit: int = 256) -> tuple[str, ...]:
    """Compatibility wrapper for consolidation V1 unique tokens."""
    return CONSOLIDATION_LEXICAL_V1.unique_tokens(value, limit=limit)


def _bounded_targets(value: object, *, limit: int = 16) -> tuple[str, ...]:
    pending = [value]
    targets: list[str] = []
    seen_objects: set[int] = set()
    while pending and len(targets) < limit:
        current = pending.pop(0)
        if isinstance(current, str):
            target = _normalize(current)[:160]
            if target and target not in targets:
                targets.append(target)
            continue
        if isinstance(current, (list, tuple, set, frozenset)):
            object_id = id(current)
            if object_id in seen_objects:
                continue
            seen_objects.add(object_id)
            values = list(current)[:limit]
            pending.extend(sorted(values, key=lambda item: _normalize(item)[:160]))
    return tuple(targets)


def extract_candidate_signals(entry: Any, *, node_limit: int = 64) -> CandidateSignals:
    """Extract bounded authority/relation signals from possibly malformed metadata."""
    authority: set[str] = set()
    relations: set[tuple[str, str]] = set()
    text = " ".join(
        (
            str(getattr(entry, "category", "")),
            str(getattr(entry, "source", "")),
            str(getattr(entry, "tier_reason", "")),
            " ".join(str(item) for item in getattr(entry, "tags", ())[:32]),
            str(getattr(entry, "content", ""))[:2000],
        )
    )
    normalized_text = _normalize(text)
    normalized_content = _normalize(getattr(entry, "content", ""))
    if re.match(r"^canonical\b", normalized_content):
        authority.add("canonical")
    if re.search(r"\b(current|latest)\b|(?:当前|最新)", normalized_text):
        authority.add("current")
    if re.search(r"\b(corrected|correction|user correction)\b|(?:用户纠正|已纠正|更正)", normalized_text):
        authority.add("user_correction")
    if _VERIFIED_AUTHORITY_RE.search(normalized_text):
        authority.add("verified")
    if _UNVERIFIED_RE.search(normalized_text):
        authority.discard("verified")
        authority.add("unverified")
    if re.search(r"\b(deprecated|obsolete|old|superseded)\b|(?:已废弃|旧结论|已取代)", normalized_text):
        authority.add("superseded")
    if getattr(entry, "success_count", 0) > 0:
        authority.add("successful_outcome")

    for target in getattr(entry, "related_to", ())[:32]:
        normalized = _normalize(target)[:160]
        if normalized:
            relations.add(("related_to", normalized))

    roots = (
        ("metadata", getattr(entry, "metadata", {})),
        ("provenance", getattr(entry, "provenance", {})),
    )
    pending: list[tuple[str, object, int]] = [
        (label, value, 0) for label, value in roots if value
    ]
    seen_objects: set[int] = set()
    visited = 0
    truncated = False
    while pending:
        if visited >= node_limit:
            truncated = True
            break
        path, value, depth = pending.pop(0)
        if isinstance(value, (dict, list, tuple, set, frozenset)):
            object_id = id(value)
            if object_id in seen_objects:
                continue
            seen_objects.add(object_id)
        visited += 1
        if depth > 4:
            truncated = True
            continue
        if isinstance(value, dict):
            for raw_key in sorted(value, key=lambda item: _normalize(item)[:80])[:32]:
                key = _normalize(raw_key)[:80]
                nested = value[raw_key]
                if key in {"canonical", "current", "latest", "verified"} and bool(nested):
                    authority.add("current" if key == "latest" else key)
                if key in {"correction", "corrected", "user_correction", "user_corrected"} and bool(nested):
                    authority.add("user_correction")
                if key in {"draft", "possible", "unverified"} and bool(nested):
                    authority.add("unverified")
                if key in {"deprecated", "obsolete", "old", "superseded"} and bool(nested):
                    authority.add("superseded")
                relation = _RELATION_KEYS.get(key)
                if relation:
                    for target in _bounded_targets(nested):
                        if target not in {"true", "false"}:
                            relations.add((relation, target))
                pending.append((f"{path}.{key}", nested, depth + 1))
        elif isinstance(value, (list, tuple, set, frozenset)):
            values = sorted(list(value)[:32], key=lambda item: _normalize(item)[:160])
            pending.extend((f"{path}[]", item, depth + 1) for item in values)
        elif isinstance(value, str):
            normalized = _normalize(value)[:500]
            if normalized in {"canonical", "current", "verified"}:
                authority.add(normalized)
            if normalized in {"corrected", "correction", "user_correction"}:
                authority.add("user_correction")
            if normalized in {"draft", "possible", "unverified"}:
                authority.add("unverified")
    if getattr(entry, "provenance", None):
        authority.add("explicit_provenance")
    return CandidateSignals(
        authority_signals=tuple(sorted(authority)),
        relations=tuple(sorted(relations)),
        visited_nodes=visited,
        node_limit=node_limit,
        truncated=truncated,
    )


def _stable_chain_key(evidence: Iterable[str]) -> str:
    normalized = "\x1f".join(sorted(dict.fromkeys(evidence)))
    return hashlib.sha256(normalized.encode("utf-8")).hexdigest()[:16]


def _candidate_features(candidate: "RetrievedMemory") -> _Features:
    text = " ".join(
        (
            candidate.content[:4000],
            candidate.category,
            " ".join(candidate.tags),
        )
    )
    content_tokens = frozenset(_tokens(text))
    matched_terms = frozenset(_stem(_normalize(item)) for item in candidate.score.matched_terms)
    specific = frozenset(term for term in matched_terms if term not in _GENERIC_CHAIN_TERMS)
    files = {
        _normalize(match).replace("\\", "/")
        for match in _FILE_RE.findall(text)
        if match
    }
    quantities = frozenset(_normalize(match) for match in _QUANTITY_RE.findall(candidate.content))
    return _Features(
        entry_id=candidate.entry_id,
        content_tokens=content_tokens,
        matched_terms=matched_terms,
        specific_matched_terms=specific,
        file_keys=frozenset(files),
        domains=frozenset(_normalize(domain) for domain in candidate.domains),
        authority_signals=frozenset(candidate.authority_signals),
        relations=tuple(sorted(candidate.relations)),
        quantities=quantities,
    )


def _authority_score(features: _Features) -> int:
    weights = {
        "canonical": 4,
        "current": 3,
        "explicit_provenance": 1,
        "successful_outcome": 2,
        "user_correction": 5,
        "verified": 3,
        "superseded": -5,
        "unverified": -3,
    }
    return sum(weights.get(signal, 0) for signal in features.authority_signals)


def _relation_between(first: _Features, second: _Features) -> set[str]:
    relations: set[str] = set()
    for relation, target in first.relations:
        if target == second.entry_id:
            relations.add(relation)
    for relation, target in second.relations:
        if target == first.entry_id:
            relations.add(relation)
    return relations


def _chain_evidence(first: _Features, second: _Features) -> tuple[str, ...]:
    evidence: list[str] = []
    relations = _relation_between(first, second)
    evidence.extend(f"relation:{relation}" for relation in sorted(relations))
    shared_files = first.file_keys & second.file_keys
    evidence.extend(f"file:{item}" for item in sorted(shared_files))
    shared_terms = first.specific_matched_terms & second.specific_matched_terms
    if len(shared_terms) >= 2:
        evidence.extend(f"term:{item}" for item in sorted(shared_terms))
    return tuple(evidence)


def _pair_buckets(features: tuple[_Features, ...]) -> set[tuple[str, str]]:
    buckets: dict[str, list[str]] = {}
    known_ids = {item.entry_id for item in features}
    for feature in features:
        for file_key in sorted(feature.file_keys):
            buckets.setdefault(f"file:{file_key}", []).append(feature.entry_id)
        terms = sorted(feature.specific_matched_terms)[:12]
        for first, second in itertools.combinations(terms, 2):
            buckets.setdefault(f"terms:{first}:{second}", []).append(feature.entry_id)
        for relation, target in feature.relations:
            if target in known_ids:
                pair = tuple(sorted((feature.entry_id, target)))
                buckets.setdefault(f"relation:{pair[0]}:{pair[1]}:{relation}", []).extend(pair)
    pairs: set[tuple[str, str]] = set()
    for ids in buckets.values():
        unique = sorted(dict.fromkeys(ids))
        pairs.update(itertools.combinations(unique, 2))
    return pairs


def _near_duplicate(first: _Features, second: _Features, first_text: str, second_text: str) -> bool:
    union = first.content_tokens | second.content_tokens
    jaccard = len(first.content_tokens & second.content_tokens) / len(union) if union else 0.0
    smaller = min(len(first.content_tokens), len(second.content_tokens))
    containment = len(first.content_tokens & second.content_tokens) / smaller if smaller else 0.0
    sequence = SequenceMatcher(None, _normalize(first_text)[:2000], _normalize(second_text)[:2000]).ratio()
    return (jaccard >= 0.45 and containment >= 0.65) or sequence >= 0.82


def _order_within_validated_chains(
    candidates: tuple["RetrievedMemory", ...],
    features_by_id: dict[str, _Features],
    chain_keys: dict[tuple[str, str], str],
) -> tuple["RetrievedMemory", ...]:
    """Apply authority order only inside connected, validated evidence chains."""
    original_index = {
        candidate.entry_id: index for index, candidate in enumerate(candidates)
    }
    adjacency: dict[str, set[str]] = {
        candidate.entry_id: set() for candidate in candidates
    }
    for first_id, second_id in chain_keys:
        adjacency[first_id].add(second_id)
        adjacency[second_id].add(first_id)

    result_ids = [candidate.entry_id for candidate in candidates]
    visited: set[str] = set()
    for root_id in result_ids:
        if root_id in visited or not adjacency[root_id]:
            visited.add(root_id)
            continue
        pending = [root_id]
        component: set[str] = set()
        while pending:
            entry_id = pending.pop()
            if entry_id in component:
                continue
            component.add(entry_id)
            pending.extend(sorted(adjacency[entry_id], reverse=True))
        visited.update(component)
        positions = sorted(original_index[entry_id] for entry_id in component)
        members = sorted(
            component,
            key=lambda entry_id: (
                -_authority_score(features_by_id[entry_id]),
                original_index[entry_id],
                entry_id,
            ),
        )
        for position, entry_id in zip(positions, members, strict=True):
            result_ids[position] = entry_id
    by_id = {candidate.entry_id: candidate for candidate in candidates}
    return tuple(by_id[entry_id] for entry_id in result_ids)


def _direct_conflict(
    first: _Features,
    second: _Features,
    first_text: str,
    second_text: str,
) -> bool:
    relations = _relation_between(first, second)
    if "conflicts_with" in relations:
        return True
    if first.quantities and second.quantities and first.quantities != second.quantities:
        return True
    first_risk = bool(_CONFLICT_RISK_RE.search(first_text))
    second_risk = bool(_CONFLICT_RISK_RE.search(second_text))
    if first_risk != second_risk:
        return True
    first_signals = first.authority_signals
    second_signals = second.authority_signals
    first_is_correction = "user_correction" in first_signals
    second_is_correction = "user_correction" in second_signals
    if first_is_correction != second_is_correction:
        return True
    first_is_unverified = "unverified" in first_signals
    second_is_unverified = "unverified" in second_signals
    if (
        first_is_unverified != second_is_unverified
        and "verified" in (first_signals | second_signals)
    ):
        return True
    return False


def _is_stable_user_constraint(candidate: "RetrievedMemory", features: _Features) -> bool:
    if candidate.scope != "user" or _normalize(candidate.category) not in _USER_CONSTRAINT_CATEGORIES:
        return False
    if "documentation" in features.domains or _DOCUMENTATION_RE.search(candidate.content):
        return False
    if not _CONSTRAINT_RE.search(candidate.content):
        return False
    return bool(features.matched_terms - _NON_OBJECT_TERMS)


def _has_complementary_value(
    candidate: "RetrievedMemory",
    features: _Features,
    retained_features: tuple[_Features, ...],
) -> bool:
    if _is_stable_user_constraint(candidate, features):
        return True
    if candidate.score.file_score > 0 and not any(
        features.file_keys & retained.file_keys for retained in retained_features
    ):
        return True
    covered = set().union(*(item.specific_matched_terms for item in retained_features))
    if features.specific_matched_terms - covered:
        return True
    if "verified" in features.authority_signals and _VERIFICATION_RE.search(candidate.content):
        return True
    return False


class CandidateConsolidator:
    """Consolidate post-gate candidates without retrieval, persistence, or feedback."""

    def __init__(self, *, max_candidates: int = 256) -> None:
        if isinstance(max_candidates, bool) or max_candidates <= 0:
            raise ValueError("max_candidates must be a positive integer")
        self.max_candidates = int(max_candidates)

    def consolidate(
        self,
        candidates: tuple["RetrievedMemory", ...],
        request: "MemoryRetrievalRequest",
    ) -> ConsolidationResult:
        ordered = tuple(
            sorted(
                candidates,
                key=lambda item: (
                    item.rank,
                    -item.score.final_score,
                    item.entry_id,
                ),
            )
        )
        bounded = ordered[: self.max_candidates]
        overflow = ordered[self.max_candidates :]
        by_id = {candidate.entry_id: candidate for candidate in bounded}
        features_by_id = {
            candidate.entry_id: _candidate_features(candidate) for candidate in bounded
        }
        suppressions: dict[str, CandidateSuppression] = {
            candidate.entry_id: CandidateSuppression(
                entry_id=candidate.entry_id,
                reason=SuppressionReason.CANDIDATE_LIMIT,
                reason_codes=("bounded_before_pairwise_comparison",),
            )
            for candidate in overflow
        }

        pairs = _pair_buckets(tuple(features_by_id.values()))
        chain_keys: dict[tuple[str, str], str] = {}
        for pair in sorted(pairs):
            first = features_by_id[pair[0]]
            second = features_by_id[pair[1]]
            evidence = _chain_evidence(first, second)
            if evidence:
                chain_keys[pair] = _stable_chain_key(evidence)
        bounded = _order_within_validated_chains(
            bounded,
            features_by_id,
            chain_keys,
        )

        # Structured authority/conflict/duplicate decisions are restricted to
        # pairs that passed deterministic evidence-chain validation.
        for pair, chain_key in sorted(chain_keys.items()):
            first_id, second_id = pair
            if first_id in suppressions or second_id in suppressions:
                continue
            first = features_by_id[first_id]
            second = features_by_id[second_id]
            first_candidate = by_id[first_id]
            second_candidate = by_id[second_id]
            first_score = _authority_score(first)
            second_score = _authority_score(second)

            if any(
                relation == "superseded_by" and target == second_id
                for relation, target in first.relations
            ) or any(
                relation == "supersedes" and target == first_id
                for relation, target in second.relations
            ):
                suppressions[first_id] = CandidateSuppression(
                    first_id,
                    SuppressionReason.SUPERSEDED,
                    second_id,
                    chain_key,
                    ("explicit_supersession",),
                )
                continue
            if any(
                relation == "superseded_by" and target == first_id
                for relation, target in second.relations
            ) or any(
                relation == "supersedes" and target == second_id
                for relation, target in first.relations
            ):
                suppressions[second_id] = CandidateSuppression(
                    second_id,
                    SuppressionReason.SUPERSEDED,
                    first_id,
                    chain_key,
                    ("explicit_supersession",),
                )
                continue

            conflict = _direct_conflict(
                first,
                second,
                first_candidate.content,
                second_candidate.content,
            )
            if conflict and first_score == second_score:
                suppressions[first_id] = CandidateSuppression(
                    first_id,
                    SuppressionReason.UNRESOLVED_CONFLICT,
                    "",
                    chain_key,
                    ("equal_authority_conflict",),
                )
                suppressions[second_id] = CandidateSuppression(
                    second_id,
                    SuppressionReason.UNRESOLVED_CONFLICT,
                    "",
                    chain_key,
                    ("equal_authority_conflict",),
                )
                continue
            if conflict and first_score != second_score:
                winner_id, loser_id = (
                    (first_id, second_id) if first_score > second_score else (second_id, first_id)
                )
                loser = features_by_id[loser_id]
                winner = features_by_id[winner_id]
                reason = (
                    SuppressionReason.UNVERIFIED_RECOVERY
                    if (
                        "unverified" in loser.authority_signals
                        and "verified" in winner.authority_signals
                    )
                    else SuppressionReason.LOWER_AUTHORITY_CONFLICT
                )
                suppressions[loser_id] = CandidateSuppression(
                    loser_id,
                    reason,
                    winner_id,
                    chain_key,
                    ("structured_conflict", "authority_difference"),
                )
                continue

            if (
                first_score != second_score
                and _near_duplicate(
                    first,
                    second,
                    first_candidate.content,
                    second_candidate.content,
                )
                and max(first_score, second_score) >= 3
            ):
                winner_id, loser_id = (
                    (first_id, second_id) if first_score > second_score else (second_id, first_id)
                )
                suppressions[loser_id] = CandidateSuppression(
                    loser_id,
                    SuppressionReason.NEAR_DUPLICATE,
                    winner_id,
                    chain_key,
                    ("same_chain", "higher_authority", "low_information_gain"),
                )

        retained: list["RetrievedMemory"] = []
        retained_features: list[_Features] = []
        request_files = tuple(_normalize(path).replace("\\", "/") for path in request.current_files)
        request_basenames = tuple(path.split("/")[-1] for path in request_files)
        for candidate in bounded:
            if candidate.entry_id in suppressions:
                continue
            features = features_by_id[candidate.entry_id]
            if not retained:
                retained.append(candidate)
                retained_features.append(features)
                continue

            primary = retained[0]
            primary_features = retained_features[0]
            pair = tuple(sorted((primary.entry_id, candidate.entry_id)))
            complementary = _has_complementary_value(
                candidate,
                features,
                tuple(retained_features),
            )
            file_bound_collision = (
                primary.score.file_score > 0
                and candidate.score.file_score == 0
                and candidate.scope != "user"
                and len(features.matched_terms) <= 1
                and any(
                    term in basename
                    for term in features.matched_terms
                    for basename in request_basenames
                )
            )
            domain_gap = primary.score.domain_score - candidate.score.domain_score
            weak_context = (
                candidate.score.file_score == 0
                and len(primary_features.matched_terms) >= len(features.matched_terms)
                and not complementary
                and (
                    file_bound_collision
                    or (
                        _normalize(candidate.category) in _NOISE_CATEGORIES
                        and (
                            domain_gap > 0
                            or bool(_DOCUMENTATION_RE.search(candidate.content))
                            or len(primary_features.matched_terms)
                            >= len(features.matched_terms) + 1
                        )
                    )
                )
            )
            if weak_context:
                suppressions[candidate.entry_id] = CandidateSuppression(
                    candidate.entry_id,
                    SuppressionReason.NO_INCREMENTAL_VALUE,
                    primary.entry_id,
                    chain_keys.get(pair, ""),
                    ("primary_more_task_specific", "no_independent_applicable_value"),
                )
                continue
            retained.append(candidate)
            retained_features.append(features)

        order = {candidate.entry_id: index for index, candidate in enumerate(ordered)}
        suppressed = tuple(
            sorted(
                suppressions.values(),
                key=lambda item: (order.get(item.entry_id, len(order)), item.entry_id),
            )
        )
        reason_counts: dict[str, int] = {}
        for item in suppressed:
            reason_counts[item.reason.value] = reason_counts.get(item.reason.value, 0) + 1
        return ConsolidationResult(
            retained=tuple(retained),
            suppressed=suppressed,
            diagnostics={
                "input_count": len(ordered),
                "bounded_count": len(bounded),
                "retained_count": len(retained),
                "suppressed_count": len(suppressed),
                "candidate_limit": self.max_candidates,
                "pair_bucket_count": len(pairs),
                "validated_chain_pair_count": len(chain_keys),
                "reason_counts": dict(sorted(reason_counts.items())),
                "complexity_bound": "O(B^2) after deterministic bucketing; B<=candidate_limit",
            },
        )

shared_files.minicode/memory_lexical_policy.py:
"""Versioned lexical policies used by persistent-Memory retrieval.

The canonical retriever and post-gate candidate consolidator deliberately use
different lexical semantics.  Keeping both profiles at one seam makes that
difference explicit without silently changing either production contract.
"""

from __future__ import annotations

import re
import unicodedata
from collections.abc import Iterable
from dataclasses import dataclass, field
from enum import Enum

_RETRIEVAL_SPACE_RE = re.compile(r"\s+")
_RETRIEVAL_SEPARATOR_RE = re.compile(r"[_./\\:-]+")
_CONSOLIDATION_TOKEN_RE = re.compile(
    r"[a-z0-9][a-z0-9_.:/-]*|[\u3400-\u9fff]+",
    re.IGNORECASE,
)
_CONSOLIDATION_PART_RE = re.compile(r"[._:/-]+")
_RETRIEVAL_V2_TOKEN_RE = re.compile(
    r"[a-z0-9]+|[\u3400-\u9fff]+",
    re.IGNORECASE,
)
_SINGLE_CJK_RE = re.compile(r"[\u3400-\u9fff]")
_CJK_POLARITY_MARKERS = (
    "不得",
    "不要",
    "不能",
    "不可",
    "无需",
    "禁止",
    "必须",
    "务必",
    "应当",
    "应该",
    "不",
    "无",
    "未",
    "非",
)
_ASCII_POLARITY_MARKERS = (
    "must not",
    "do not",
    "should not",
    "without",
    "never",
    "forbid",
    "prohibit",
    "must",
    "require",
)
_CJK_POLARITY_RE = re.compile(
    "|".join(re.escape(marker) for marker in _CJK_POLARITY_MARKERS)
)
_ASCII_POLARITY_RE = re.compile(
    r"\b(?:"
    + "|".join(re.escape(marker) for marker in _ASCII_POLARITY_MARKERS)
    + r")\b",
    re.IGNORECASE,
)


class MemoryLexicalProfile(str, Enum):
    """Stable identities for independently versioned lexical behavior."""

    RETRIEVAL_V1 = "canonical_retrieval_v1"
    RETRIEVAL_V2 = "canonical_retrieval_v2"
    CONSOLIDATION_V1 = "candidate_consolidation_v1"


def _stem_ascii_suffix(
    term: str,
    *,
    restore_ing_after: tuple[str, ...],
    restore_ed_after: tuple[str, ...],
) -> str:
    if not term.isascii() or len(term) < 4:
        return term
    if term.endswith("ies") and len(term) > 4:
        return term[:-3] + "y"
    if term.endswith("ing") and len(term) > 5:
        base = term[:-3]
        return base + "e" if base.endswith(restore_ing_after) else base
    if term.endswith("ed") and len(term) > 4:
        base = term[:-2]
        return base + "e" if base.endswith(restore_ed_after) else base
    if term.endswith("es") and len(term) > 4:
        return term[:-2]
    if term.endswith("s") and len(term) > 3:
        return term[:-1]
    return term


@dataclass(frozen=True, slots=True)
class RetrievalLexicalPolicyV1:
    """Canonical retrieval's frozen lexical behavior."""

    profile: MemoryLexicalProfile = field(
        default=MemoryLexicalProfile.RETRIEVAL_V1,
        init=False,
    )

    @staticmethod
    def normalize_input(value: object) -> str:
        text = unicodedata.normalize("NFKC", str(value or ""))
        return _RETRIEVAL_SPACE_RE.sub(" ", text).strip()

    def normalize_match(self, value: object) -> str:
        normalized = self.normalize_input(value).lower()
        separated = _RETRIEVAL_SEPARATOR_RE.sub(" ", normalized)
        return _RETRIEVAL_SPACE_RE.sub(" ", separated).strip()

    def tokenize_match(self, value: object) -> list[str]:
        # Import the owning module at call time.  Prepared-corpus work tests
        # intentionally monkeypatch this private compatibility seam.
        import minicode.memory as memory_module

        return memory_module._tokenize(self.normalize_match(value))

    @staticmethod
    def expand_terms(
        terms: list[str],
        *,
        active_domains: Iterable[str] | None = None,
    ) -> list[str]:
        # Keep expansion order and duplicates: manager-compatible BM25 uses
        # both as part of its established scoring contract.
        import minicode.memory as memory_module

        domains = (
            list(active_domains)
            if active_domains is not None
            else None
        )
        return memory_module._expand_query_terms(
            list(terms),
            active_domains=domains or None,
        )

    def term_set(
        self,
        value: object,
        *,
        active_domains: Iterable[str] | None = None,
    ) -> set[str]:
        expanded = self.expand_terms(
            self.tokenize_match(value),
            active_domains=active_domains,
        )
        return {
            self.stem(token.lower())
            for token in expanded
            if token.strip()
        }

    @staticmethod
    def stem(term: str) -> str:
        return _stem_ascii_suffix(
            term,
            restore_ing_after=("c", "v"),
            restore_ed_after=("c", "u", "v"),
        )


@dataclass(frozen=True, slots=True)
class RetrievalLexicalPolicyV2:
    """Offset-invariant CJK features with separate recall and gate lanes.

    Candidate terms retain individual CJK characters for broad discovery.
    Admission terms require an ASCII token or a sliding CJK bigram, preventing
    one common character from independently authorizing prompt injection.
    Polarity markers are exposed separately so that this safety filtering does
    not erase negation or obligation evidence.
    """

    profile: MemoryLexicalProfile = field(
        default=MemoryLexicalProfile.RETRIEVAL_V2,
        init=False,
    )

    @staticmethod
    def normalize_input(value: object) -> str:
        return RetrievalLexicalPolicyV1.normalize_input(value)

    def normalize_match(self, value: object) -> str:
        return RetrievalLexicalPolicyV1().normalize_match(value)

    def tokenize_match(self, value: object) -> list[str]:
        tokens: list[str] = []
        for raw in _RETRIEVAL_V2_TOKEN_RE.findall(self.normalize_match(value)):
            token = raw.lower()
            if token.isascii():
                tokens.append(token)
                continue
            tokens.extend(token)
            tokens.extend(
                token[index : index + 2]
                for index in range(len(token) - 1)
            )
        return tokens

    def admission_tokens(self, value: object) -> list[str]:
        return [
            token
            for token in self.tokenize_match(value)
            if not self._is_single_cjk(token)
        ]

    @staticmethod
    def stem(term: str) -> str:
        return RetrievalLexicalPolicyV1.stem(term)

    @staticmethod
    def expand_terms(
        terms: list[str],
        *,
        active_domains: Iterable[str] | None = None,
    ) -> list[str]:
        return RetrievalLexicalPolicyV1.expand_terms(
            terms,
            active_domains=active_domains,
        )

    @staticmethod
    def _is_single_cjk(term: str) -> bool:
        return _SINGLE_CJK_RE.fullmatch(term) is not None

    def candidate_term_set(
        self,
        value: object,
        *,
        active_domains: Iterable[str] | None = None,
    ) -> set[str]:
        """Return broad terms suitable for candidate discovery only."""
        expanded = self.expand_terms(
            self.tokenize_match(value),
            active_domains=active_domains,
        )
        return {
            self.stem(token.lower())
            for token in expanded
            if token.strip()
        }

    def admission_terms(
        self,
        value: object,
        *,
        active_domains: Iterable[str] | None = None,
    ) -> tuple[str, ...]:
        """Return ordered relevance evidence that excludes CJK singletons."""
        return self.expand_admission_tokens(
            self.admission_tokens(value),
            active_domains=active_domains,
        )

    def expand_admission_tokens(
        self,
        tokens: Iterable[str],
        *,
        active_domains: Iterable[str] | None = None,
    ) -> tuple[str, ...]:
        expanded = self.expand_terms(
            list(tokens),
            active_domains=active_domains,
        )
        result: list[str] = []
        seen: set[str] = set()
        for token in expanded:
            term = self.stem(token.lower())
            if (
                not term.strip()
                or self._is_single_cjk(term)
                or term in seen
            ):
                continue
            seen.add(term)
            result.append(term)
        return tuple(result)

    def admission_term_set(
        self,
        value: object,
        *,
        active_domains: Iterable[str] | None = None,
    ) -> set[str]:
        return set(
            self.admission_terms(
                value,
                active_domains=active_domains,
            )
        )

    def polarity_markers(self, value: object) -> tuple[str, ...]:
        """Return explicit negation/obligation lexemes in source order."""
        normalized = self.normalize_input(value).lower()
        matches = [
            (match.start(), match.group(0).lower())
            for pattern in (_CJK_POLARITY_RE, _ASCII_POLARITY_RE)
            for match in pattern.finditer(normalized)
        ]
        matches.sort(key=lambda item: (item[0], item[1]))
        return tuple(marker for _offset, marker in matches)


@dataclass(frozen=True, slots=True)
class ConsolidationLexicalPolicyV1:
    """Post-gate candidate consolidation's frozen lexical behavior."""

    profile: MemoryLexicalProfile = field(
        default=MemoryLexicalProfile.CONSOLIDATION_V1,
        init=False,
    )

    @staticmethod
    def normalize_scalar(value: object) -> str:
        return unicodedata.normalize("NFKC", str(value or "")).strip().lower()

    @staticmethod
    def stem(term: str) -> str:
        return _stem_ascii_suffix(
            term,
            restore_ing_after=(),
            restore_ed_after=(),
        )

    def unique_tokens(self, value: object, *, limit: int = 256) -> tuple[str, ...]:
        result: list[str] = []
        seen: set[str] = set()
        normalized = self.normalize_scalar(value)
        for raw in _CONSOLIDATION_TOKEN_RE.findall(normalized)[:limit]:
            for part in _CONSOLIDATION_PART_RE.split(raw):
                term = self.stem(part)
                if term and term not in seen:
                    seen.add(term)
                    result.append(term)
        return tuple(result)


RETRIEVAL_LEXICAL_V1 = RetrievalLexicalPolicyV1()
RETRIEVAL_LEXICAL_V2 = RetrievalLexicalPolicyV2()
CONSOLIDATION_LEXICAL_V1 = ConsolidationLexicalPolicyV1()


__all__ = [
    "CONSOLIDATION_LEXICAL_V1",
    "RETRIEVAL_LEXICAL_V1",
    "RETRIEVAL_LEXICAL_V2",
    "ConsolidationLexicalPolicyV1",
    "MemoryLexicalProfile",
    "RetrievalLexicalPolicyV1",
    "RetrievalLexicalPolicyV2",
]

shared_files.minicode/memory_path_identity.py:
"""Complete path-identity parsing shared by memory recall and admission."""

from __future__ import annotations

import re
import unicodedata
from dataclasses import dataclass


@dataclass(frozen=True)
class PathIdentitySpan:
    start: int
    end: int
    identity: str


_QUOTED_PATH_RE = re.compile(
    r"(?<![\w])(?P<quote>[`'\"])(?P<body>[^`'\"\r\n]*?)(?P=quote)(?![\w])"
)
_ASCII_PATH_RE = re.compile(
    r"(?:[/\\]{2}|[A-Za-z]:[/\\]|(?:\.\.?[/\\])|[/\\]|"
    r"[A-Za-z0-9_@.+-]+[/\\])"
    r"(?:[A-Za-z0-9_@.+-]+[/\\])*[A-Za-z0-9_@.+-]+"
)
_TOKEN_RE = re.compile(r"\S+")
_LEADING_WRAPPERS = "([{<"
_TRAILING_WRAPPERS = ")]}>"
_TRAILING_SENTENCE_PUNCTUATION = ",;:!?，。；：！？"


def _normalized_text(value: object) -> str:
    return unicodedata.normalize("NFKC", str(value or ""))


def normalize_path_identity(
    value: object,
    *,
    max_chars: int = 256,
    allow_spaces: bool = True,
    require_separator: bool = False,
) -> str:
    """Return one complete normalized path or ``""`` when identity is unsafe."""

    text = _normalized_text(value).strip().replace("\\", "/")
    while text.startswith("./"):
        text = text[2:]
    text = text.rstrip("/")
    if (
        not text
        or len(text) > max_chars
        or "://" in text
        or (require_separator and "/" not in text)
    ):
        return ""
    for index, character in enumerate(text):
        category = unicodedata.category(character)
        if category.startswith("C"):
            return ""
        if character == ":":
            if index != 1 or not text[0].isascii() or not text[0].isalpha():
                return ""
            continue
        if character.isspace():
            if allow_spaces and character == " ":
                continue
            return ""
        if (
            category[0] in {"L", "M", "N"}
            or character in "/._-@+"
        ):
            continue
        return ""
    if text.startswith("//"):
        components = text[2:].split("/")
        if len(components) < 3:
            return ""
    elif len(text) > 1 and text[1] == ":":
        # A drive identity must be absolute.  ``C:repo/file.py`` is relative
        # to the drive's current directory and therefore is not a stable file
        # identity for deterministic retrieval evidence.
        if len(text) < 4 or text[2] != "/":
            return ""
        components = text[3:].split("/")
    elif text.startswith("/"):
        components = text[1:].split("/")
    else:
        components = text.split("/")
    if any(not component for component in components):
        return ""
    return text


def path_identity_basename(value: object) -> str:
    """Return the basename of one already-complete cross-platform identity."""

    normalized = normalize_path_identity(value)
    if not normalized:
        return ""
    return normalized.rsplit("/", 1)[-1]


def _trim_unquoted_token(
    token: str,
    start: int,
) -> tuple[str, int, int]:
    previous = ""
    while token and token != previous:
        previous = token
        while token and token[0] in _LEADING_WRAPPERS:
            token = token[1:]
            start += 1
        while token and token[-1] in _TRAILING_WRAPPERS:
            token = token[:-1]
        while token and token[-1] in _TRAILING_SENTENCE_PUNCTUATION:
            token = token[:-1]
        # A final ASCII period is prose punctuation; an internal period remains
        # part of the filename and is validated as identity.
        while token.endswith("."):
            token = token[:-1]
    return token, start, start + len(token)


def complete_path_spans(
    value: object,
    *,
    max_text_chars: int = 4_000,
    max_path_chars: int = 256,
) -> tuple[PathIdentitySpan, ...]:
    """Extract complete path spans without restarting after an invalid prefix."""

    text = _normalized_text(value)
    if not text or len(text) > max_text_chars:
        return ()
    spans: list[PathIdentitySpan] = []
    quoted_ranges: list[tuple[int, int]] = []
    command_prefix_ranges: list[tuple[int, int]] = []
    for match in _QUOTED_PATH_RE.finditer(text):
        body = match.group("body")
        whitespace_indexes = [
            index for index, character in enumerate(body) if character.isspace()
        ]
        if whitespace_indexes and match.group("quote") == "`":
            # A code span containing spaces is ambiguous between a path with
            # spaces and a command plus arguments.  Never erase the full span:
            # doing so could remove decisive operation or polarity text such
            # as ``./bin/tool disable retries``.  Treat the first token as a
            # possible executable and let the bounded ASCII scanner discover
            # only later, independently delimited path arguments.  Paths with
            # spaces remain supported by structured metadata, where the value
            # is unambiguously one identity.
            parts = body.split()
            first = parts[0] if parts else ""
            if first:
                command_prefix_ranges.append(
                    (match.start("body"), match.start("body") + len(first))
                )
            continue
        if whitespace_indexes:
            # Natural-language quotations frequently contain a path.  Treating
            # the whole quotation as one filename would erase action and
            # polarity evidence during redaction. The inner scanner may still
            # recover independently delimited, unambiguous path tokens.
            continue
        quoted_ranges.append(match.span())
        identity = normalize_path_identity(
            body,
            max_chars=max_path_chars,
            allow_spaces=True,
            require_separator=True,
        )
        if identity:
            spans.append(PathIdentitySpan(match.start(), match.end(), identity))

    ascii_ranges: list[tuple[int, int]] = []
    for match in _ASCII_PATH_RE.finditer(text):
        if any(match.start() < end and match.end() > start for start, end in quoted_ranges):
            continue
        if any(
            match.start() < end and match.end() > start
            for start, end in command_prefix_ranges
        ):
            continue
        token, start, end = _trim_unquoted_token(match.group(0), match.start())
        identity = normalize_path_identity(
            token,
            max_chars=max_path_chars,
            allow_spaces=False,
            require_separator=True,
        )
        if not identity:
            continue
        left_is_safe = _safe_left_boundary(
            text,
            start,
            basename=False,
        ) or (start > 0 and "\u3400" <= text[start - 1] <= "\u9fff")
        right_is_safe = _safe_right_boundary(text, end) or text.startswith("的", end)
        if not left_is_safe or not right_is_safe:
            continue
        ascii_ranges.append((start, end))
        spans.append(PathIdentitySpan(start, end, identity))

    for match in _TOKEN_RE.finditer(text):
        if any(match.start() < end and match.end() > start for start, end in quoted_ranges):
            continue
        if any(match.start() < end and match.end() > start for start, end in ascii_ranges):
            continue
        token, start, end = _trim_unquoted_token(match.group(0), match.start())
        # ASCII paths are handled by the bounded scanner above.  This fallback
        # is only for an isolated Unicode path token.  Requiring a terminal
        # file extension prevents adjacent CJK prose such as
        # ``源码/配置.py的逻辑`` from becoming part of the identity; callers can
        # quote extensionless or otherwise ambiguous Unicode paths.
        non_ascii = tuple(character for character in token if not character.isascii())
        if (
            not non_ascii
            or any(not ("\u3400" <= character <= "\u9fff") for character in non_ascii)
            or not re.search(r"\.[A-Za-z0-9]{1,16}$", token)
        ):
            continue
        identity = normalize_path_identity(
            token,
            max_chars=max_path_chars,
            allow_spaces=False,
            require_separator=True,
        )
        if identity:
            spans.append(PathIdentitySpan(start, end, identity))

    spans.sort(key=lambda item: (item.start, item.end, item.identity))
    return tuple(spans)


def extract_complete_path_identities(
    value: object,
    *,
    max_text_chars: int = 4_000,
    max_path_chars: int = 256,
) -> tuple[str, ...]:
    """Return unique normalized path identities in source order."""

    return tuple(
        dict.fromkeys(
            span.identity
            for span in complete_path_spans(
                value,
                max_text_chars=max_text_chars,
                max_path_chars=max_path_chars,
            )
        )
    )


def redact_complete_paths(value: object, *, max_text_chars: int = 4_000) -> str:
    """Replace complete path spans with spaces for relation-token analysis."""

    text = _normalized_text(value)
    if not text or len(text) > max_text_chars:
        return text
    characters = list(text)
    for span in complete_path_spans(text, max_text_chars=max_text_chars):
        characters[span.start : span.end] = " " * (span.end - span.start)
    return "".join(characters)


_LEFT_IDENTITY_DELIMITERS = frozenset("`'\"([{<")
_RIGHT_IDENTITY_DELIMITERS = frozenset("`'\")]}>")
_RIGHT_SENTENCE_DELIMITERS = frozenset(".,;:!?，。；：！？")


def _safe_left_boundary(text: str, position: int, *, basename: bool) -> bool:
    if position == 0:
        return True
    before = text[position - 1]
    if basename and before == "/":
        return True
    if before.isspace():
        return True
    if before not in _LEFT_IDENTITY_DELIMITERS:
        return False
    # Do not split a path out of a glued token such as ``name(src/a.py)``.
    return position == 1 or text[position - 2].isspace()


def _safe_right_boundary(text: str, position: int) -> bool:
    if position == len(text) or text[position].isspace():
        return True
    cursor = position
    while cursor < len(text) and (
        text[cursor] in _RIGHT_IDENTITY_DELIMITERS
        or text[cursor] in _RIGHT_SENTENCE_DELIMITERS
    ):
        cursor += 1
    # Punctuation is a delimiter only when it actually terminates a token.
    # Glued variants such as ``config.py:backup`` or ``config.py,backup`` are
    # different identities and must not grant deterministic file authority.
    return cursor > position and (cursor == len(text) or text[cursor].isspace())


def complete_identity_occurs(
    identity: object,
    text: object,
    *,
    case_sensitive: bool = True,
    basename: bool = False,
    max_text_chars: int = 12_000,
) -> bool:
    """Match one identity without accepting descendants, suffixes, or marks."""

    return bool(
        complete_identity_occurrence_spans(
            identity,
            text,
            case_sensitive=case_sensitive,
            basename=basename,
            max_text_chars=max_text_chars,
        )
    )


def complete_identity_occurrence_spans(
    identity: object,
    text: object,
    *,
    case_sensitive: bool = True,
    basename: bool = False,
    max_text_chars: int = 12_000,
) -> tuple[tuple[int, int], ...]:
    """Return complete identity spans in normalized text source order.

    Callers that use span offsets for relation proofs must keep
    ``case_sensitive=True``. Unicode case-folding can change string length; the
    insensitive mode is retained only for boolean approximate-recall checks.
    """

    normalized_identity = normalize_path_identity(identity)
    if not normalized_identity:
        return ()
    if "/" in normalized_identity:
        expected = (
            normalized_identity
            if case_sensitive
            else normalized_identity.casefold()
        )
        return tuple(
            (span.start, span.end)
            for span in complete_path_spans(text, max_text_chars=max_text_chars)
            if (
                span.identity if case_sensitive else span.identity.casefold()
            )
            == expected
        )

    needle = _normalized_text(identity).replace("\\", "/")
    haystack = _normalized_text(text).replace("\\", "/")
    if not case_sensitive:
        needle = needle.casefold()
        haystack = haystack.casefold()
    cursor = 0
    spans: list[tuple[int, int]] = []
    while (position := haystack.find(needle, cursor)) >= 0:
        after_index = position + len(needle)
        if _safe_left_boundary(
            haystack,
            position,
            basename=basename,
        ) and _safe_right_boundary(haystack, after_index):
            spans.append((position, after_index))
        cursor = position + 1
    return tuple(spans)

shared_files.minicode/memory_provenance.py:
"""Strict, content-free Memory provenance transport contract.

The contract crosses subprocess and Run-observation boundaries, so malformed
input is rejected instead of repaired.  It carries only opaque Memory entry
identities and their exact approval-content authority digests; prompts,
queries, paths, sub-agent identities, and other model-controlled content are
deliberately outside this payload.
"""

from __future__ import annotations

import re
from collections.abc import Mapping
from dataclasses import dataclass

from minicode.memory_authority_io import (
    MEMORY_ENTRY_ID_PATTERN,
    is_memory_entry_id,
)

MEMORY_PROVENANCE_SCHEMA_VERSION = 1
MAX_MEMORY_PROVENANCE_VERSIONS = 64
MAX_MEMORY_PROVENANCE_BATCHES = 128

MEMORY_PROVENANCE_EFFECTS = frozenset({"rendered", "written"})
MEMORY_PROVENANCE_ORIGINS = frozenset(
    {"task_start", "context_compaction", "reflection"}
)
MEMORY_PROVENANCE_COVERAGE = frozenset({"complete", "partial", "unknown"})

_AUTHORITY_DIGEST_RE = re.compile(r"^[0-9a-f]{64}$")
_RECEIPT_ID_RE = re.compile(r"^[0-9a-f]{32}$")
_CONTEXT_OPERATION_ID_RE = re.compile(r"^ctxop_[0-9a-f]{32}$")

_REQUIRED_FIELDS = frozenset(
    {
        "schemaVersion",
        "effect",
        "origin",
        "authorityVersions",
        "coverage",
    }
)
_OPTIONAL_FIELDS = frozenset({"receiptId", "contextOperationId"})

AuthorityVersion = tuple[str, str]


@dataclass(frozen=True, slots=True, kw_only=True)
class MemoryProvenanceBatch:
    """One bounded provenance observation from a single Memory operation."""

    schema_version: int = MEMORY_PROVENANCE_SCHEMA_VERSION
    effect: str
    origin: str
    authority_versions: tuple[AuthorityVersion, ...] = ()
    receipt_id: str | None = None
    context_operation_id: str | None = None
    coverage: str = "complete"

    def __post_init__(self) -> None:
        if isinstance(self.schema_version, bool) or not isinstance(
            self.schema_version, int
        ):
            raise TypeError("Memory provenance schema_version must be an integer")
        if self.schema_version != MEMORY_PROVENANCE_SCHEMA_VERSION:
            raise ValueError("Memory provenance schema_version is unsupported")
        if not isinstance(self.effect, str):
            raise TypeError("Memory provenance effect must be a string")
        if self.effect not in MEMORY_PROVENANCE_EFFECTS:
            raise ValueError("Memory provenance effect is invalid")
        if not isinstance(self.origin, str):
            raise TypeError("Memory provenance origin must be a string")
        if self.origin not in MEMORY_PROVENANCE_ORIGINS:
            raise ValueError("Memory provenance origin is invalid")
        if not isinstance(self.coverage, str):
            raise TypeError("Memory provenance coverage must be a string")
        if self.coverage not in MEMORY_PROVENANCE_COVERAGE:
            raise ValueError("Memory provenance coverage is invalid")
        if not isinstance(self.authority_versions, tuple):
            raise TypeError("Memory provenance authority_versions must be a tuple")
        if len(self.authority_versions) > MAX_MEMORY_PROVENANCE_VERSIONS:
            raise ValueError("Memory provenance contains too many authority versions")

        seen: set[AuthorityVersion] = set()
        for version in self.authority_versions:
            if not isinstance(version, tuple) or len(version) != 2:
                raise TypeError("Memory provenance authority version must be a pair")
            entry_id, digest = version
            if not isinstance(entry_id, str) or not isinstance(digest, str):
                raise TypeError(
                    "Memory provenance authority version values must be strings"
                )
            if not is_memory_entry_id(entry_id):
                raise ValueError("Memory provenance entry ID is invalid")
            if _AUTHORITY_DIGEST_RE.fullmatch(digest) is None:
                raise ValueError("Memory provenance authority digest is invalid")
            if version in seen:
                raise ValueError(
                    "Memory provenance contains a duplicate authority version"
                )
            seen.add(version)

        if self.coverage == "unknown":
            if self.authority_versions:
                raise ValueError("Unknown Memory provenance cannot contain versions")
        elif not self.authority_versions:
            raise ValueError(
                "Complete or partial Memory provenance requires an authority version"
            )

        if self.receipt_id is not None:
            if not isinstance(self.receipt_id, str):
                raise TypeError("Memory provenance receipt_id must be a string or None")
            if _RECEIPT_ID_RE.fullmatch(self.receipt_id) is None:
                raise ValueError("Memory provenance receipt_id is invalid")
        if self.context_operation_id is not None:
            if not isinstance(self.context_operation_id, str):
                raise TypeError(
                    "Memory provenance context_operation_id must be a string or None"
                )
            if _CONTEXT_OPERATION_ID_RE.fullmatch(self.context_operation_id) is None:
                raise ValueError("Memory provenance context_operation_id is invalid")

    def to_dict(self) -> dict[str, object]:
        """Return the canonical JSON-safe, content-free representation."""
        payload: dict[str, object] = {
            "schemaVersion": self.schema_version,
            "effect": self.effect,
            "origin": self.origin,
            "authorityVersions": [
                [entry_id, digest] for entry_id, digest in self.authority_versions
            ],
            "coverage": self.coverage,
        }
        if self.receipt_id is not None:
            payload["receiptId"] = self.receipt_id
        if self.context_operation_id is not None:
            payload["contextOperationId"] = self.context_operation_id
        return payload

    @classmethod
    def from_dict(cls, value: object) -> MemoryProvenanceBatch:
        """Parse one canonical payload, rejecting unknown or missing fields."""
        if not isinstance(value, Mapping):
            raise TypeError("Memory provenance payload must be a mapping")
        fields = set(value)
        if not _REQUIRED_FIELDS.issubset(fields):
            raise ValueError("Memory provenance payload is missing required fields")
        if not fields.issubset(_REQUIRED_FIELDS | _OPTIONAL_FIELDS):
            raise ValueError("Memory provenance payload contains unknown fields")

        raw_versions = value.get("authorityVersions")
        if not isinstance(raw_versions, (list, tuple)):
            raise TypeError("Memory provenance authorityVersions must be a list")
        versions: list[AuthorityVersion] = []
        for raw_version in raw_versions:
            if not isinstance(raw_version, (list, tuple)) or len(raw_version) != 2:
                raise TypeError("Memory provenance authorityVersion must be a pair")
            entry_id, digest = raw_version
            if not isinstance(entry_id, str) or not isinstance(digest, str):
                raise TypeError(
                    "Memory provenance authorityVersion values must be strings"
                )
            versions.append((entry_id, digest))

        return cls(
            schema_version=value.get("schemaVersion"),  # type: ignore[arg-type]
            effect=value.get("effect"),  # type: ignore[arg-type]
            origin=value.get("origin"),  # type: ignore[arg-type]
            authority_versions=tuple(versions),
            receipt_id=value.get("receiptId"),  # type: ignore[arg-type]
            context_operation_id=value.get(  # type: ignore[arg-type]
                "contextOperationId"
            ),
            coverage=value.get("coverage"),  # type: ignore[arg-type]
        )


def normalize_memory_provenance_batches(
    value: object,
    *,
    max_batches: int = MAX_MEMORY_PROVENANCE_BATCHES,
) -> tuple[MemoryProvenanceBatch, ...]:
    """Validate a hostile batch collection with all-or-nothing semantics.

    Subprocess payloads must never be partially trusted: if the collection or
    any member is malformed, the whole observation degrades to an empty tuple.
    ``max_batches`` is trusted caller configuration and therefore raises when
    its own type or value is invalid.
    """
    if isinstance(max_batches, bool) or not isinstance(max_batches, int):
        raise TypeError("max_batches must be an integer")
    if max_batches < 0:
        raise ValueError("max_batches must be non-negative")
    if not isinstance(value, (list, tuple)) or len(value) > max_batches:
        return ()
    try:
        return tuple(MemoryProvenanceBatch.from_dict(item) for item in value)
    except (TypeError, ValueError):
        return ()


__all__ = [
    "MAX_MEMORY_PROVENANCE_BATCHES",
    "MAX_MEMORY_PROVENANCE_VERSIONS",
    "MEMORY_ENTRY_ID_PATTERN",
    "MEMORY_PROVENANCE_COVERAGE",
    "MEMORY_PROVENANCE_EFFECTS",
    "MEMORY_PROVENANCE_ORIGINS",
    "MEMORY_PROVENANCE_SCHEMA_VERSION",
    "AuthorityVersion",
    "MemoryProvenanceBatch",
    "is_memory_entry_id",
    "normalize_memory_provenance_batches",
]

