shared_files.minicode/pipeline_engine.py:
"""Pipeline Engine - Task execution orchestration.

Deepened work chain:
  Raw Input -> Intent Parser -> Task Object -> Pipeline -> Execution -> Result

The Pipeline Engine:
- Breaks a TaskObject into executable Steps
- Orchestrates step execution with dependency resolution
- Handles constraints, retries, fallbacks
- Produces a structured Result
"""

from __future__ import annotations

import time
from dataclasses import dataclass, field
from enum import Enum
from typing import Any, Callable

from minicode.task_object import TaskObject, TaskState, ConstraintType
from minicode.cybernetic_supervisor import CyberneticSupervisor
from minicode.decision_audit import get_auditor, DecisionType, DecisionOutcome
from minicode.logging_config import get_logger
from minicode.progress_controller import ProgressController, ProgressSignal
from minicode.verification_controller import VerificationController

logger = get_logger("pipeline_engine")


class StepType(str, Enum):
    ANALYZE = "analyze"
    PLAN = "plan"
    READ = "read"
    GENERATE = "generate"
    MODIFY = "modify"
    VERIFY = "verify"
    REVIEW = "review"
    DOCUMENT = "document"
    COMMIT = "commit"
    NOTIFY = "notify"


class StepState(str, Enum):
    PENDING = "pending"
    RUNNING = "running"
    COMPLETED = "completed"
    FAILED = "failed"
    SKIPPED = "skipped"
    RETRYING = "retrying"


@dataclass
class Step:
    """A single executable step in a pipeline."""
    id: str
    type: StepType
    description: str
    handler: str = ""
    params: dict[str, Any] = field(default_factory=dict)
    depends_on: list[str] = field(default_factory=list)
    max_retries: int = 1
    timeout_seconds: float = 60.0
    state: StepState = StepState.PENDING
    result: Any = None
    error: str = ""
    execution_time_ms: float = 0.0
    retry_count: int = 0

    def to_dict(self) -> dict[str, Any]:
        return {
            "id": self.id, "type": self.type.value, "description": self.description,
            "handler": self.handler, "params": self.params,
            "depends_on": self.depends_on, "max_retries": self.max_retries,
            "timeout_seconds": self.timeout_seconds,
            "state": self.state.value, "result": self.result,
            "error": self.error, "execution_time_ms": self.execution_time_ms,
            "retry_count": self.retry_count,
        }


@dataclass
class PipelinePlan:
    """Execution plan for a TaskObject."""
    id: str
    task_id: str
    steps: list[Step] = field(default_factory=list)
    created_at: float = field(default_factory=time.time)

    def to_dict(self) -> dict[str, Any]:
        return {
            "id": self.id, "task_id": self.task_id,
            "steps": [s.to_dict() for s in self.steps],
            "created_at": self.created_at,
        }

    def get_step(self, step_id: str) -> Step | None:
        for step in self.steps:
            if step.id == step_id:
                return step
        return None

    def get_ready_steps(self) -> list[Step]:
        completed = {s.id for s in self.steps if s.state in (StepState.COMPLETED, StepState.SKIPPED)}
        return [s for s in self.steps
                if s.state == StepState.PENDING
                and all(d in completed for d in s.depends_on)]

    def is_complete(self) -> bool:
        return all(s.state in (StepState.COMPLETED, StepState.SKIPPED, StepState.FAILED)
                   for s in self.steps)

    def has_failures(self) -> bool:
        return any(s.state == StepState.FAILED for s in self.steps)


@dataclass
class PipelineResult:
    """Result of pipeline execution."""
    task_id: str
    plan_id: str
    success: bool
    completed_steps: list[str] = field(default_factory=list)
    failed_steps: list[str] = field(default_factory=list)
    outputs: dict[str, Any] = field(default_factory=dict)
    summary: str = ""
    total_time_ms: float = 0.0
    error: str = ""

    def to_dict(self) -> dict[str, Any]:
        return {
            "task_id": self.task_id, "plan_id": self.plan_id,
            "success": self.success, "completed_steps": self.completed_steps,
            "failed_steps": self.failed_steps, "outputs": self.outputs,
            "summary": self.summary, "total_time_ms": self.total_time_ms,
            "error": self.error,
        }


class StepPlanner:
    """Plans execution steps from a TaskObject."""

    def plan(self, task: TaskObject) -> PipelinePlan:
        plan_id = f"plan-{task.id}"
        steps: list[Step] = []
        intent_type = task.parsed_intent.intent_type.value if task.parsed_intent else ""
        action_type = task.parsed_intent.action_type.value if task.parsed_intent else ""

        steps.append(Step(
            id="analyze", type=StepType.ANALYZE,
            description="Analyze task requirements and context",
            handler="analyze_task",
        ))

        if task.relevant_files:
            steps.append(Step(
                id="read_files", type=StepType.READ,
                description=f"Read relevant files: {', '.join(task.relevant_files[:3])}",
                handler="read_file", params={"paths": task.relevant_files},
                depends_on=["analyze"],
            ))

        steps.append(Step(
            id="plan", type=StepType.PLAN,
            description="Plan implementation approach",
            handler="plan_approach",
            depends_on=["analyze"] + (["read_files"] if task.relevant_files else []),
        ))

        if action_type == "create":
            steps.append(Step(
                id="generate", type=StepType.GENERATE,
                description="Generate new code/content",
                handler="generate_code",
                depends_on=["plan"],
            ))
        elif action_type in ("update", "delete"):
            steps.append(Step(
                id="modify", type=StepType.MODIFY,
                description="Modify existing code/files",
                handler="modify_code",
                depends_on=["plan"],
            ))
        elif action_type in ("read", "analyze"):
            steps.append(Step(
                id="analyze_deep", type=StepType.ANALYZE,
                description="Deep analysis of code/content",
                handler="deep_analyze",
                depends_on=["plan"],
            ))
        elif action_type == "execute":
            steps.append(Step(
                id="execute", type=StepType.VERIFY,
                description="Execute command/test",
                handler="execute_command",
                depends_on=["plan"],
            ))

        has_test = any(c.type == ConstraintType.TEST_REQUIRED for c in task.constraints)
        if has_test or intent_type in ("code", "test"):
            work_step = "generate" if action_type == "create" else "modify" if action_type in ("update", "delete") else "analyze_deep"
            steps.append(Step(
                id="verify", type=StepType.VERIFY,
                description="Verify correctness with tests",
                handler="run_tests",
                depends_on=[work_step],
            ))

        has_review = any(c.type == ConstraintType.REQUIRES_REVIEW for c in task.constraints)
        if has_review:
            work_step = "generate" if action_type == "create" else "modify"
            steps.append(Step(
                id="review", type=StepType.REVIEW,
                description="Review output quality",
                handler="review_output",
                depends_on=[work_step],
            ))

        if intent_type in ("code", "document"):
            work_step = "generate" if action_type == "create" else "modify" if action_type in ("update", "delete") else "analyze_deep"
            dep = [work_step]
            if any(s.id == "verify" for s in steps):
                dep.append("verify")
            steps.append(Step(
                id="document", type=StepType.DOCUMENT,
                description="Update documentation",
                handler="update_docs",
                depends_on=dep,
            ))

        final_deps = [s.id for s in steps if s.id not in ("analyze", "read_files")]
        steps.append(Step(
            id="notify", type=StepType.NOTIFY,
            description="Notify user of result",
            handler="notify_user",
            depends_on=final_deps[-1:] if final_deps else ["plan"],
        ))

        logger.debug("Planned %d steps for task %s", len(steps), task.id)
        return PipelinePlan(id=plan_id, task_id=task.id, steps=steps)


class StepExecutor:
    """Executes individual steps."""

    def __init__(self):
        self._handlers: dict[str, Callable[..., Any]] = {}
        self._verification_controller = VerificationController()
        self._register_default_handlers()

    def _register_default_handlers(self) -> None:
        self._handlers["analyze_task"] = self._handle_analyze
        self._handlers["read_file"] = self._handle_read
        self._handlers["plan_approach"] = self._handle_plan
        self._handlers["generate_code"] = self._handle_generate
        self._handlers["modify_code"] = self._handle_modify
        self._handlers["deep_analyze"] = self._handle_analyze
        self._handlers["execute_command"] = self._handle_execute
        self._handlers["run_tests"] = self._handle_verify
        self._handlers["review_output"] = self._handle_review
        self._handlers["update_docs"] = self._handle_document
        self._handlers["notify_user"] = self._handle_notify

    def register_handler(self, name: str, handler: Callable[..., Any]) -> None:
        self._handlers[name] = handler

    def execute(self, step: Step, task: TaskObject) -> tuple[bool, Any]:
        handler = self._handlers.get(step.handler)
        if not handler:
            return False, f"No handler registered for: {step.handler}"

        step.state = StepState.RUNNING
        start = time.time()

        try:
            result = handler(step, task)
            step.execution_time_ms = (time.time() - start) * 1000
            step.state = StepState.COMPLETED
            step.result = result
            return True, result
        except Exception as e:
            step.execution_time_ms = (time.time() - start) * 1000
            step.error = str(e)
            step.retry_count += 1

            if step.retry_count < step.max_retries:
                step.state = StepState.RETRYING
                logger.warning("Step %s failed, retrying (%d/%d): %s",
                               step.id, step.retry_count, step.max_retries, e)
                return self.execute(step, task)
            else:
                step.state = StepState.FAILED
                logger.error("Step %s failed after %d retries: %s",
                             step.id, step.retry_count, e)
                return False, str(e)

    def _handle_analyze(self, step: Step, task: TaskObject) -> dict[str, Any]:
        return {"intent": task.parsed_intent.to_dict() if task.parsed_intent else {},
                "files": task.relevant_files, "constraints": [c.to_dict() for c in task.constraints]}

    def _handle_read(self, step: Step, task: TaskObject) -> dict[str, Any]:
        paths = step.params.get("paths", [])
        return {"files_read": len(paths), "paths": paths}

    def _handle_plan(self, step: Step, task: TaskObject) -> dict[str, Any]:
        return {"approach": f"Plan for {task.title}", "steps_planned": len(task.expected_outputs)}

    def _handle_generate(self, step: Step, task: TaskObject) -> dict[str, Any]:
        return {"generated": True, "output_type": "code", "files": task.relevant_files}

    def _handle_modify(self, step: Step, task: TaskObject) -> dict[str, Any]:
        return {"modified": True, "files": task.relevant_files}

    def _handle_execute(self, step: Step, task: TaskObject) -> dict[str, Any]:
        return {"executed": True, "task": task.title}

    def _handle_verify(self, step: Step, task: TaskObject) -> dict[str, Any]:
        plan = self._verification_controller.plan_for_task(task)
        return {
            "verified": plan.mode.value == "none",
            "tests_passed": None,
            "verification_plan": plan.to_dict(),
        }

    def _handle_review(self, step: Step, task: TaskObject) -> dict[str, Any]:
        return {"reviewed": True, "issues_found": 0}

    def _handle_document(self, step: Step, task: TaskObject) -> dict[str, Any]:
        return {"documented": True, "docs_updated": True}

    def _handle_notify(self, step: Step, task: TaskObject) -> dict[str, Any]:
        return {"notified": True, "result": task.result_summary}


class PipelineEngine:
    """Orchestrates full pipeline execution."""

    def __init__(self):
        self.planner = StepPlanner()
        self.executor = StepExecutor()
        self._audit = get_auditor()
        self._progress_controller = ProgressController()
        self._supervisor = CyberneticSupervisor()

    def run(self, task: TaskObject) -> PipelineResult:
        plan = self.planner.plan(task)
        return self.execute(task, plan)

    def execute(self, task: TaskObject, plan: PipelinePlan) -> PipelineResult:
        task.set_state(TaskState.RUNNING)
        start = time.time()

        self._audit.record(
            DecisionType.ROUTING,
            reasoning=f"Pipeline execution for task {task.id}",
            selected_option=plan.id,
            input_context={"task_id": task.id, "steps": len(plan.steps)},
        )

        try:
            while not plan.is_complete():
                ready = plan.get_ready_steps()
                if not ready:
                    break
                for step in ready:
                    success, result = self.executor.execute(step, task)
                    if not success:
                        break

            completed = [s.id for s in plan.steps if s.state == StepState.COMPLETED]
            failed = [s.id for s in plan.steps if s.state == StepState.FAILED]
            outputs = {s.id: s.result for s in plan.steps if s.result is not None}

            if plan.has_failures():
                task.set_state(TaskState.FAILED)
                task.error_message = failed[0] if failed else "Unknown failure"
            else:
                task.set_state(TaskState.COMPLETED)
                task.result_summary = f"Completed {len(completed)}/{len(plan.steps)} steps"

            total_time = (time.time() - start) * 1000
            success = not plan.has_failures()
            verify_result = outputs.get("verify") if isinstance(outputs.get("verify"), dict) else {}
            tests_passed = verify_result.get("tests_passed") if verify_result else None
            progress_decision = self._progress_controller.decide(ProgressSignal(
                total_steps=len(plan.steps),
                completed_steps=len(completed),
                failed_steps=len(failed),
                tool_calls=len(completed) + len(failed),
                tool_errors=len(failed),
                output_changed=bool(outputs),
                tests_passed=tests_passed,
                elapsed_seconds=total_time / 1000,
                max_steps=len(plan.steps),
            ))
            outputs["progress_control"] = progress_decision.to_dict()
            supervisor_snapshots = [
                self._supervisor.snapshot_from_decision("progress", outputs["progress_control"])
            ]
            if isinstance(verify_result, dict) and isinstance(verify_result.get("verification_plan"), dict):
                supervisor_snapshots.append(
                    self._supervisor.snapshot_from_decision(
                        "verification",
                        verify_result["verification_plan"],
                    )
                )
            outputs["cybernetic_supervisor"] = self._supervisor.report(supervisor_snapshots).to_dict()

            self._audit.complete_decision(
                DecisionOutcome.SUCCESS if success else DecisionOutcome.FAILURE,
                total_time,
                task.result_summary,
                task.error_message,
            )

            return PipelineResult(
                task_id=task.id, plan_id=plan.id, success=success,
                completed_steps=completed, failed_steps=failed,
                outputs=outputs, summary=task.result_summary, total_time_ms=total_time,
                error=task.error_message,
            )
        except Exception as e:
            task.set_state(TaskState.FAILED)
            task.error_message = str(e)
            total_time = (time.time() - start) * 1000
            return PipelineResult(
                task_id=task.id, plan_id=plan.id, success=False,
                error=str(e), total_time_ms=total_time,
            )


_engine: PipelineEngine | None = None


def get_pipeline_engine() -> PipelineEngine:
    global _engine
    if _engine is None:
        _engine = PipelineEngine()
    return _engine


def process_task(raw_input: str) -> tuple[TaskObject, PipelinePlan, PipelineResult]:
    from minicode.intent_parser import parse_intent
    from minicode.task_object import build_task

    intent = parse_intent(raw_input)
    task = build_task(intent, raw_input)
    engine = get_pipeline_engine()
    result = engine.run(task)
    return task, engine.planner.plan(task), result

shared_files.minicode/predictive_controller.py:
"""Predictive Controller based on Engineering Cybernetics.

钱学森工程控制论核心原理:
- 预测控制：基于系统模型预测未来状态，提前调整控制
- 前馈-反馈复合控制：结合预测和反馈实现最优控制
- 滚动优化：在预测时域内滚动优化控制策略

This module implements:
1. Exponential smoothing time series prediction
2. Moving average trend prediction
3. Multi-horizon forecasting
4. Predictive action recommendation
"""
from __future__ import annotations

import time
from collections import deque
from dataclasses import dataclass, field
from enum import Enum
from typing import Any


class PredictionHorizon(Enum):
    """Prediction time horizon."""
    SHORT = "short"       # 1-3 steps ahead
    MEDIUM = "medium"     # 3-10 steps ahead
    LONG = "long"         # 10-50 steps ahead


@dataclass
class PredictionResult:
    """Result of a prediction."""
    metric_name: str
    predicted_value: float
    confidence: float
    prediction_horizon: PredictionHorizon
    trend_direction: str  # "up", "down", "stable"
    predicted_at: float = field(default_factory=time.time)
    actual_value: float | None = None
    error: float | None = None


@dataclass
class PredictiveAction:
    """Recommended action based on prediction."""
    action_type: str
    urgency: float          # 0.0 - 1.0
    metric_name: str
    predicted_issue: str
    recommended_action: str
    expected_benefit: str
    deadline_steps: int = 3


class ExponentialSmoother:
    """Exponential smoothing for time series prediction.

    指数平滑预测:
    对历史数据加权平均，近期数据权重更高。
    """

    def __init__(self, alpha: float = 0.3):
        self.alpha = alpha
        self._forecast: float = 0.0
        self._initialized: bool = False
        self._mae: float = 0.0

    def update(self, actual: float) -> float:
        if not self._initialized:
            self._forecast = actual
            self._initialized = True
            return self._forecast

        error = abs(actual - self._forecast)
        self._mae = 0.9 * self._mae + 0.1 * error

        self._forecast = self.alpha * actual + (1 - self.alpha) * self._forecast
        return self._forecast

    def predict(self, steps_ahead: int = 1) -> float:
        return self._forecast

    def get_confidence(self) -> float:
        if self._mae < 0.01:
            return 0.95
        return max(0.1, 1.0 - self._mae * 2)

    def reset(self) -> None:
        self._forecast = 0.0
        self._initialized = False
        self._mae = 0.0


class MovingAveragePredictor:
    """Moving average trend predictor.

    移动平均趋势预测:
    通过不同时间窗口的移动平均判断趋势方向。
    """

    def __init__(self, window_sizes: tuple[int, int, int] = (5, 10, 20)):
        self._windows: dict[int, deque[float]] = {w: deque(maxlen=w) for w in window_sizes}
        self._all_values: deque[float] = deque(maxlen=100)

    def add_value(self, value: float) -> None:
        for window in self._windows.values():
            window.append(value)
        self._all_values.append(value)

    def predict_trend(self) -> str:
        if len(self._all_values) < 3:
            return "stable"

        short_avg = self._get_average(5)
        medium_avg = self._get_average(10)
        long_avg = self._get_average(20)

        if short_avg is None or medium_avg is None or long_avg is None:
            return "stable"

        if short_avg > medium_avg > long_avg:
            return "up"
        elif short_avg < medium_avg < long_avg:
            return "down"
        return "stable"

    def predict_value(self, steps_ahead: int = 1) -> float | None:
        if len(self._all_values) < 2:
            return None

        trend = self.predict_trend()
        recent = list(self._all_values)[-10:]

        if len(recent) < 2:
            return recent[-1] if recent else None

        recent_slope = (recent[-1] - recent[0]) / (len(recent) - 1)

        if trend == "up":
            slope_multiplier = 1.2
        elif trend == "down":
            slope_multiplier = 1.2
        else:
            slope_multiplier = 0.5

        predicted = recent[-1] + recent_slope * steps_ahead * slope_multiplier
        return predicted

    def _get_average(self, window_size: int) -> float | None:
        window = self._windows.get(window_size)
        if not window or len(window) < window_size * 0.5:
            return None
        return sum(window) / len(window)

    def reset(self) -> None:
        for window in self._windows.values():
            window.clear()
        self._all_values.clear()


class PredictiveController:
    """Predictive controller for proactive system management.

    预测控制器（超前控制）:
    ┌─────────────────────────────────────────────────────────────┐
    │  历史数据 ─→ 预测模型 ─→ 未来状态预测 ─→ 预防性控制动作     │
    │                       ↓                                      │
    │                 风险预警 + 优化建议                          │
    └─────────────────────────────────────────────────────────────┘

    Features:
    - Multi-metric prediction
    - Trend detection and extrapolation
    - Predictive action recommendation
    - Confidence-based filtering
    """

    def __init__(self, max_history: int = 100):
        self._predictors: dict[str, dict[str, Any]] = {}
        self._prediction_history: list[PredictionResult] = []
        self._max_history = max_history
        self._max_pred_history = 200

        self._init_metrics()

    def _init_metrics(self) -> None:
        metrics = [
            "response_time",
            "error_rate",
            "context_usage",
            "cpu_usage",
            "memory_usage",
            "throughput",
            "stability_score",
            "performance_score",
        ]
        for metric in metrics:
            self._predictors[metric] = {
                "exp_smoother": ExponentialSmoother(alpha=0.3),
                "ma_predictor": MovingAveragePredictor(),
                "last_prediction": None,
                "prediction_count": 0,
            }

    def update(self, metric_name: str, value: float) -> None:
        if metric_name not in self._predictors:
            self._predictors[metric_name] = {
                "exp_smoother": ExponentialSmoother(alpha=0.3),
                "ma_predictor": MovingAveragePredictor(),
                "last_prediction": None,
                "prediction_count": 0,
            }

        predictor = self._predictors[metric_name]
        predictor["exp_smoother"].update(value)
        predictor["ma_predictor"].add_value(value)

    def predict(self, metric_name: str, horizon: PredictionHorizon = PredictionHorizon.SHORT) -> PredictionResult | None:
        if metric_name not in self._predictors:
            return None

        predictor = self._predictors[metric_name]

        steps_ahead = {
            PredictionHorizon.SHORT: 3,
            PredictionHorizon.MEDIUM: 7,
            PredictionHorizon.LONG: 20,
        }.get(horizon, 3)

        exp_prediction = predictor["exp_smoother"].predict(steps_ahead)
        ma_prediction = predictor["ma_predictor"].predict_value(steps_ahead)

        if ma_prediction is not None:
            predicted_value = exp_prediction * 0.4 + ma_prediction * 0.6
        else:
            predicted_value = exp_prediction

        confidence = predictor["exp_smoother"].get_confidence()

        trend = predictor["ma_predictor"].predict_trend()

        result = PredictionResult(
            metric_name=metric_name,
            predicted_value=predicted_value,
            confidence=confidence,
            prediction_horizon=horizon,
            trend_direction=trend,
        )

        predictor["last_prediction"] = result
        predictor["prediction_count"] += 1

        self._prediction_history.append(result)
        if len(self._prediction_history) > self._max_pred_history:
            self._prediction_history.pop(0)

        return result

    def predict_all(self, horizon: PredictionHorizon = PredictionHorizon.SHORT) -> list[PredictionResult]:
        results = []
        for metric_name in self._predictors:
            result = self.predict(metric_name, horizon)
            if result:
                results.append(result)
        return results

    def generate_predictive_actions(self) -> list[PredictiveAction]:
        actions = []

        for metric_name, predictor in self._predictors.items():
            if predictor["last_prediction"] is None:
                continue

            prediction = predictor["last_prediction"]
            if prediction.confidence < 0.5:
                continue

            action = self._assess_prediction(metric_name, prediction)
            if action:
                actions.append(action)

        actions.sort(key=lambda a: a.urgency, reverse=True)
        return actions

    def record_actual(self, metric_name: str, actual_value: float) -> None:
        for pred in reversed(self._prediction_history):
            if pred.metric_name == metric_name and pred.actual_value is None:
                pred.actual_value = actual_value
                pred.error = abs(pred.predicted_value - actual_value)
                break

    def get_prediction_accuracy(self) -> dict[str, float]:
        accuracy: dict[str, list[float]] = {}

        for pred in self._prediction_history:
            if pred.error is not None:
                if pred.metric_name not in accuracy:
                    accuracy[pred.metric_name] = []

                error_ratio = pred.error / max(abs(pred.predicted_value), 0.01)
                accuracy[pred.metric_name].append(max(0.0, 1.0 - error_ratio))

        return {
            metric: sum(errors) / len(errors) if errors else 0.0
            for metric, errors in accuracy.items()
        }

    def get_prediction_summary(self) -> dict[str, Any]:
        summary: dict[str, Any] = {
            "predictions": {},
            "trends": {},
            "accuracy": self.get_prediction_accuracy(),
        }

        for metric_name, predictor in self._predictors.items():
            if predictor["last_prediction"]:
                pred = predictor["last_prediction"]
                summary["predictions"][metric_name] = {
                    "value": pred.predicted_value,
                    "confidence": pred.confidence,
                    "trend": pred.trend_direction,
                }
                summary["trends"][metric_name] = pred.trend_direction

        return summary

    def _assess_prediction(self, metric_name: str, prediction: PredictionResult) -> PredictiveAction | None:
        thresholds = {
            "response_time": {"high": 45.0, "low": 5.0},
            "error_rate": {"high": 3.0, "low": 0.0},
            "context_usage": {"high": 0.85, "low": 0.0},
            "cpu_usage": {"high": 0.9, "low": 0.0},
            "memory_usage": {"high": 0.9, "low": 0.0},
            "throughput": {"high": 10.0, "low": 0.5},
            "stability_score": {"high": 1.0, "low": 0.5},
            "performance_score": {"high": 1.0, "low": 0.5},
        }

        if metric_name not in thresholds:
            return None

        thresh = thresholds[metric_name]

        if prediction.predicted_value > thresh["high"] and prediction.trend_direction == "up":
            urgency = min(1.0, (prediction.predicted_value - thresh["high"]) / thresh["high"])

            actions_map = {
                "response_time": ("reduce_concurrency", "减少并发任务", "降低响应延迟", 2),
                "error_rate": ("enable_safe_mode", "启用安全模式", "防止错误扩散", 1),
                "context_usage": ("trigger_compaction", "触发上下文压缩", "释放上下文空间", 2),
                "cpu_usage": ("throttle_tasks", "节流任务", "降低CPU使用率", 2),
                "memory_usage": ("trigger_gc", "触发内存回收", "释放内存", 2),
            }

            if metric_name in actions_map:
                action_type, recommended, benefit, deadline = actions_map[metric_name]
                return PredictiveAction(
                    action_type=action_type,
                    urgency=urgency,
                    metric_name=metric_name,
                    predicted_issue=f"{metric_name} 预测值 {prediction.predicted_value:.2f} 将超过阈值 {thresh['high']:.2f}",
                    recommended_action=recommended,
                    expected_benefit=benefit,
                    deadline_steps=deadline,
                )

        if metric_name in ("stability_score", "performance_score"):
            if prediction.predicted_value < thresh["low"] and prediction.trend_direction == "down":
                urgency = min(1.0, (thresh["low"] - prediction.predicted_value) / thresh["low"])
                return PredictiveAction(
                    action_type="intervention_required",
                    urgency=urgency,
                    metric_name=metric_name,
                    predicted_issue=f"{metric_name} 预测将降至 {prediction.predicted_value:.2f}",
                    recommended_action="启动干预机制",
                    expected_benefit="防止性能进一步下降",
                    deadline_steps=3,
                )

        return None

    def reset(self) -> None:
        for metric_name in self._predictors:
            self._predictors[metric_name]["exp_smoother"].reset()
            self._predictors[metric_name]["ma_predictor"].reset()
            self._predictors[metric_name]["last_prediction"] = None
            self._predictors[metric_name]["prediction_count"] = 0
        self._prediction_history = []

shared_files.minicode/pricing.py:
"""Versioned, deterministic model-cost observations.

This module is deliberately independent from the Dashboard, RunJournal, and
the legacy TUI cost tracker.  A catalog quote is an observation computed from
canonical usage and an immutable rate card; it is not a provider invoice.

Production rates were retrieved from the linked first-party model pages on
2026-07-17.  Rates are USD per one million text tokens.  OpenAI Chat
Completions reports ``prompt_tokens`` inclusive of ``cached_tokens``, so the
uncached input component is ``input - cache_read``.
"""

from __future__ import annotations

import os
import re
from collections.abc import Mapping
from dataclasses import dataclass, field
from decimal import Decimal, ROUND_HALF_EVEN, localcontext
from types import MappingProxyType
from typing import Literal


CATALOG_ID = "minicode-pricing-2026-07-17-v1"
CATALOG_VERSION = 1
CURRENCY = "USD"
COST_VERSION = 1

_NANO_USD_PER_USD = Decimal("1000000000")
_TOKENS_PER_MILLION = Decimal("1000000")
_NANO_USD_PER_RATE_TOKEN = _NANO_USD_PER_USD / _TOKENS_PER_MILLION
_WHOLE_NANO_USD = Decimal("1")
_MAX_TOKEN_COUNT = 1_000_000_000
_MAX_AMOUNT_NANO_USD = 1_000_000_000_000_000_000
_SAFE_MODEL_KEY_RE = re.compile(r"^[a-z0-9][a-z0-9._/-]{0,127}$")
_MODEL_OPERATION_ID_RE = re.compile(r"^modelop_[0-9a-f]{32}$")

BucketSemantics = Literal[
    "input_includes_cache_read",
    "input_excludes_cache_buckets",
]
QuoteStatus = Literal["priced", "unavailable"]
QuoteQuality = Literal[
    "provider_usage_catalog_rate",
    "estimated_usage_catalog_rate",
    "unavailable",
]
UnavailableReason = Literal[
    "usage_unavailable",
    "model_unpriced",
    "pricing_incomplete",
    "token_semantics_unsupported",
    "invalid_usage",
    "pricing_failed",
]

_COMPONENT_KEYS = (
    "inputNanoUsd",
    "outputNanoUsd",
    "cacheReadNanoUsd",
    "cacheCreationNanoUsd",
)


@dataclass(frozen=True, slots=True)
class ModelPrice:
    """One immutable model rate card entry."""

    catalog_model_key: str
    aliases: tuple[str, ...]
    input_usd_per_million: Decimal | None
    output_usd_per_million: Decimal | None
    cache_read_usd_per_million: Decimal | None
    cache_creation_usd_per_million: Decimal | None
    token_bucket_semantics: BucketSemantics
    not_applicable_buckets: frozenset[str]
    provider: str
    source_url: str
    retrieved_on: str
    rate_unit: str
    cache_billing_note: str

    def __post_init__(self) -> None:
        object.__setattr__(self, "aliases", tuple(self.aliases))
        object.__setattr__(
            self,
            "not_applicable_buckets",
            frozenset(self.not_applicable_buckets),
        )
        if not _SAFE_MODEL_KEY_RE.fullmatch(self.catalog_model_key):
            raise ValueError("catalog model key is not a safe canonical key")
        for alias in self.aliases:
            if not _SAFE_MODEL_KEY_RE.fullmatch(alias):
                raise ValueError("catalog alias is not an exact safe key")
        if "default" in {self.catalog_model_key, *self.aliases}:
            raise ValueError("default pricing is forbidden")
        if not self.not_applicable_buckets <= {
            "cache_read",
            "cache_creation",
        }:
            raise ValueError("unknown not-applicable token bucket")


@dataclass(frozen=True, slots=True)
class PricingCatalog:
    """Immutable versioned catalog with an exact-match index."""

    catalog_id: str
    catalog_version: int
    currency: str
    entries: tuple[ModelPrice, ...]
    _index: Mapping[str, ModelPrice] = field(init=False, repr=False, compare=False)

    def __post_init__(self) -> None:
        entries = tuple(self.entries)
        index: dict[str, ModelPrice] = {}
        for entry in entries:
            for key in (entry.catalog_model_key, *entry.aliases):
                if key in index:
                    raise ValueError("duplicate catalog model key or alias")
                index[key] = entry
        object.__setattr__(self, "entries", entries)
        object.__setattr__(self, "_index", MappingProxyType(index))

    def exact_entry(self, key: str) -> ModelPrice | None:
        """Return an entry only for an exact, case-sensitive key or alias."""
        return self._index.get(key)


@dataclass(frozen=True, slots=True)
class CostQuote:
    """A safe canonical quote ready to become a ``model.costed`` payload."""

    status: QuoteStatus
    quality: QuoteQuality
    currency: str
    catalog_id: str
    catalog_version: int
    catalog_model_key: str | None = None
    amount_nano_usd: int | None = None
    components: Mapping[str, int] | None = None
    reason: UnavailableReason | None = None

    def __post_init__(self) -> None:
        if self.components is not None:
            object.__setattr__(
                self,
                "components",
                MappingProxyType(dict(self.components)),
            )

    def to_event_payload(self, operation_id: str) -> dict[str, object]:
        """Project the quote to the strict persisted event contract."""
        if not _MODEL_OPERATION_ID_RE.fullmatch(operation_id):
            raise ValueError("invalid model operation id")
        payload: dict[str, object] = {
            "costVersion": COST_VERSION,
            "operationId": operation_id,
            "status": self.status,
            "quality": self.quality,
            "currency": self.currency,
            "catalogId": self.catalog_id,
        }
        if self.status == "priced":
            payload.update(
                {
                    "catalogModelKey": self.catalog_model_key,
                    "amountNanoUsd": self.amount_nano_usd,
                    "components": dict(self.components or {}),
                }
            )
        else:
            payload["reason"] = self.reason or "pricing_failed"
        return payload


PRODUCTION_CATALOG = PricingCatalog(
    catalog_id=CATALOG_ID,
    catalog_version=CATALOG_VERSION,
    currency=CURRENCY,
    entries=(
        ModelPrice(
            catalog_model_key="openai/gpt-4o",
            aliases=("gpt-4o", "gpt-4o-2024-08-06"),
            input_usd_per_million=Decimal("2.50"),
            output_usd_per_million=Decimal("10.00"),
            cache_read_usd_per_million=Decimal("1.25"),
            cache_creation_usd_per_million=None,
            token_bucket_semantics="input_includes_cache_read",
            not_applicable_buckets=frozenset({"cache_creation"}),
            provider="OpenAI",
            source_url="https://developers.openai.com/api/docs/models/gpt-4o",
            retrieved_on="2026-07-17",
            rate_unit="USD per 1M text tokens",
            cache_billing_note=(
                "prompt_tokens includes cached_tokens; cache creation is not "
                "a separately billed response bucket"
            ),
        ),
        ModelPrice(
            catalog_model_key="openai/gpt-4o-mini",
            aliases=("gpt-4o-mini", "gpt-4o-mini-2024-07-18"),
            input_usd_per_million=Decimal("0.15"),
            output_usd_per_million=Decimal("0.60"),
            cache_read_usd_per_million=Decimal("0.075"),
            cache_creation_usd_per_million=None,
            token_bucket_semantics="input_includes_cache_read",
            not_applicable_buckets=frozenset({"cache_creation"}),
            provider="OpenAI",
            source_url=(
                "https://developers.openai.com/api/docs/models/gpt-4o-mini"
            ),
            retrieved_on="2026-07-17",
            rate_unit="USD per 1M text tokens",
            cache_billing_note=(
                "prompt_tokens includes cached_tokens; cache creation is not "
                "a separately billed response bucket"
            ),
        ),
    ),
)


def _unavailable(
    catalog: PricingCatalog,
    reason: UnavailableReason,
) -> CostQuote:
    return CostQuote(
        status="unavailable",
        quality="unavailable",
        currency=catalog.currency,
        catalog_id=catalog.catalog_id,
        catalog_version=catalog.catalog_version,
        reason=reason,
    )


def _actual_model_identity(model: object) -> str | None:
    if isinstance(model, str):
        return model

    explicit = getattr(model, "catalog_model_key", None)
    if isinstance(explicit, str):
        return explicit

    model_type = type(model)
    if not (
        model_type.__module__ == "minicode.openai_adapter"
        and model_type.__name__ == "OpenAIModelAdapter"
    ):
        return None

    runtime = getattr(model, "runtime", None)
    if not isinstance(runtime, Mapping):
        return None
    if runtime.get("_openrouter_headers") or runtime.get("_openrouter_params"):
        return None
    base_url = (
        os.environ.get("OPENAI_BASE_URL", "")
        or os.environ.get("OPENAI_API_BASE", "")
        or runtime.get("openaiBaseUrl", "")
        or "https://api.openai.com"
    )
    if not isinstance(base_url, str):
        return None
    if base_url.rstrip("/") != "https://api.openai.com":
        return None
    runtime_model = runtime.get("model")
    return runtime_model if isinstance(runtime_model, str) else None


def _usage_value(usage: object, camel_name: str, snake_name: str) -> object:
    if isinstance(usage, Mapping):
        return usage.get(camel_name)
    return getattr(usage, snake_name, None)


def _token_value(value: object, *, optional: bool) -> int | None:
    if value is None and optional:
        return None
    if (
        not isinstance(value, int)
        or isinstance(value, bool)
        or value < 0
        or value > _MAX_TOKEN_COUNT
    ):
        raise ValueError("invalid token bucket")
    return value


def _component_nano_usd(tokens: int, rate: Decimal) -> int:
    if not isinstance(rate, Decimal) or not rate.is_finite() or rate < 0:
        raise ArithmeticError("invalid catalog rate")
    with localcontext() as context:
        context.prec = 50
        amount = (
            Decimal(tokens) * rate * _NANO_USD_PER_RATE_TOKEN
        ).quantize(_WHOLE_NANO_USD, rounding=ROUND_HALF_EVEN)
    value = int(amount)
    if value < 0 or value > _MAX_AMOUNT_NANO_USD:
        raise OverflowError("cost component outside canonical range")
    return value


def _priced_bucket(
    *,
    token_value: int | None,
    rate: Decimal | None,
    bucket_name: str,
    not_applicable: frozenset[str],
) -> tuple[int, Decimal] | UnavailableReason:
    if bucket_name in not_applicable:
        if token_value in {None, 0}:
            return 0, Decimal("0")
        return "token_semantics_unsupported"
    if rate is None:
        if token_value == 0:
            return 0, Decimal("0")
        return "pricing_incomplete"
    if token_value is None:
        return "pricing_incomplete"
    return token_value, rate


def _quote_model_cost(
    *,
    model: object,
    usage: object,
    catalog: PricingCatalog,
) -> CostQuote:
    identity = _actual_model_identity(model)
    entry = catalog.exact_entry(identity) if isinstance(identity, str) else None
    if entry is None:
        return _unavailable(catalog, "model_unpriced")

    source = _usage_value(usage, "source", "source")
    if source == "unavailable" or usage is None:
        return _unavailable(catalog, "usage_unavailable")
    if source not in {"provider", "estimated"}:
        return _unavailable(catalog, "invalid_usage")

    raw_input_tokens = _usage_value(usage, "inputTokens", "input_tokens")
    raw_output_tokens = _usage_value(usage, "outputTokens", "output_tokens")
    if raw_input_tokens is None or raw_output_tokens is None:
        return _unavailable(catalog, "usage_unavailable")
    try:
        input_tokens = _token_value(raw_input_tokens, optional=False)
        output_tokens = _token_value(raw_output_tokens, optional=False)
        cache_read_tokens = _token_value(
            _usage_value(usage, "cacheReadTokens", "cache_read_tokens"),
            optional=True,
        )
        cache_creation_tokens = _token_value(
            _usage_value(usage, "cacheCreationTokens", "cache_creation_tokens"),
            optional=True,
        )
    except ValueError:
        return _unavailable(catalog, "invalid_usage")
    if input_tokens is None or output_tokens is None:
        return _unavailable(catalog, "usage_unavailable")
    if entry.input_usd_per_million is None or entry.output_usd_per_million is None:
        return _unavailable(catalog, "pricing_incomplete")

    cache_read = _priced_bucket(
        token_value=cache_read_tokens,
        rate=entry.cache_read_usd_per_million,
        bucket_name="cache_read",
        not_applicable=entry.not_applicable_buckets,
    )
    cache_creation = _priced_bucket(
        token_value=cache_creation_tokens,
        rate=entry.cache_creation_usd_per_million,
        bucket_name="cache_creation",
        not_applicable=entry.not_applicable_buckets,
    )
    for bucket in (cache_read, cache_creation):
        if isinstance(bucket, str):
            return _unavailable(catalog, bucket)

    cache_read_count, cache_read_rate = cache_read
    cache_creation_count, cache_creation_rate = cache_creation
    if entry.token_bucket_semantics == "input_includes_cache_read":
        if cache_read_count > input_tokens:
            return _unavailable(catalog, "invalid_usage")
        uncached_input_tokens = input_tokens - cache_read_count
    elif entry.token_bucket_semantics == "input_excludes_cache_buckets":
        uncached_input_tokens = input_tokens
    else:
        return _unavailable(catalog, "token_semantics_unsupported")

    components = {
        "inputNanoUsd": _component_nano_usd(
            uncached_input_tokens, entry.input_usd_per_million
        ),
        "outputNanoUsd": _component_nano_usd(
            output_tokens, entry.output_usd_per_million
        ),
        "cacheReadNanoUsd": _component_nano_usd(
            cache_read_count, cache_read_rate
        ),
        "cacheCreationNanoUsd": _component_nano_usd(
            cache_creation_count, cache_creation_rate
        ),
    }
    if tuple(components) != _COMPONENT_KEYS:
        raise AssertionError("canonical component schema changed")
    total = sum(components.values())
    if total > _MAX_AMOUNT_NANO_USD:
        raise OverflowError("canonical total outside supported range")
    return CostQuote(
        status="priced",
        quality=(
            "provider_usage_catalog_rate"
            if source == "provider"
            else "estimated_usage_catalog_rate"
        ),
        currency=catalog.currency,
        catalog_id=catalog.catalog_id,
        catalog_version=catalog.catalog_version,
        catalog_model_key=entry.catalog_model_key,
        amount_nano_usd=total,
        components=components,
    )


def quote_model_cost(
    *,
    model: object,
    usage: object,
    catalog: PricingCatalog = PRODUCTION_CATALOG,
) -> CostQuote:
    """Quote one completed model call without leaking unresolved identity.

    All resolution, malformed-object, and arithmetic failures are converted to
    a fixed low-cardinality unavailable result.  Callers may therefore treat
    pricing as best-effort observation only.
    """
    try:
        return _quote_model_cost(model=model, usage=usage, catalog=catalog)
    except BaseException:  # noqa: BLE001 - hostile observation must be isolated
        try:
            return _unavailable(catalog, "pricing_failed")
        except BaseException:  # noqa: BLE001 - even a hostile catalog is isolated
            return CostQuote(
                status="unavailable",
                quality="unavailable",
                currency=CURRENCY,
                catalog_id=CATALOG_ID,
                catalog_version=CATALOG_VERSION,
                reason="pricing_failed",
            )


def pricing_failure_event_payload(operation_id: str) -> dict[str, object]:
    """Return the fixed fail-closed event when observation itself breaks."""
    return _unavailable(PRODUCTION_CATALOG, "pricing_failed").to_event_payload(
        operation_id
    )


def project_model_cost_event(
    *,
    model: object,
    usage: object,
    operation_id: str,
) -> dict[str, object]:
    """Resolve, quote, and project one successful model call."""
    return quote_model_cost(model=model, usage=usage).to_event_payload(operation_id)

shared_files.minicode/project_facts.py:
"""Deterministic project facts observed from execution traces.

Project facts (confirmed dependencies, build commands) are not lessons: they
are stable, re-derivable truths about the workspace. Persisting them as
Memory entries mixed lessons with inventory and pushed low-information
claims through the approval queue. This store keeps them separate:

- written as plain JSON under ``.mini-code-memory/project_facts.json``;
- guarded by the same cooperative store lock as the Memory store;
- injected into prompts as a short static block, no approval needed.

Only facts whose truth is deterministic (read from manifests/imports) belong
here. Anything requiring interpretation stays in the reflection pipeline.
"""

from __future__ import annotations

import hashlib
import json
import logging
import os
import re
import tempfile
import time
from collections.abc import Iterator
from contextlib import contextmanager
from dataclasses import asdict, dataclass, field
from pathlib import Path
from typing import Any

from minicode.memory import assess_memory_safety, sanitize_for_persistence
from minicode.memory_store import MemoryStoreConflict, MemoryStoreCoordinator
from minicode.memory_write_contract import ProjectFactsEffect

logger = logging.getLogger(__name__)

MAX_FACTS = 200
MAX_NAME_CHARS = 120
RENDER_MAX_BYTES = 2_000
MAX_WRITE_RECEIPTS = 128

_DEPENDENCY_NAME_RE = re.compile(
    r"^@?[A-Za-z0-9][A-Za-z0-9._+\-]*"
    r"(?:(?:[/@:])[A-Za-z0-9][A-Za-z0-9._+\-]*){0,7}$"
)
_MEMORY_OPERATION_ID_RE = re.compile(r"^memoryop_[0-9a-f]{32}$")


def project_facts_payload_digest(
    names: list[str],
    provenance: dict[str, Any],
) -> str:
    encoded = json.dumps(
        {
            "schema": "project_facts_write_v1",
            "dependencies": names,
            "provenance": provenance,
        },
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
        allow_nan=False,
    ).encode()
    return hashlib.sha256(encoded).hexdigest()


@dataclass(frozen=True, slots=True)
class ProjectFactsWritePlan:
    """Sanitized deterministic input to one Project Facts observation."""

    names: tuple[str, ...]
    provenance: dict[str, Any]
    payload_digest: str


@dataclass(frozen=True, slots=True)
class ProjectFactsOperationReceipt:
    """Content-free proof retained for one idempotent facts write."""

    operation_id: str
    payload_digest: str


def prepare_project_facts_write(
    names: list[str],
    provenance: dict[str, Any] | None = None,
) -> ProjectFactsWritePlan | None:
    """Validate, sanitize and bind one dependency observation."""
    validated: list[str] = []
    for name in names:
        if not str(name or "").strip():
            continue
        safe_name = _safe_dependency_name(name)
        if not safe_name:
            return None
        validated.append(safe_name)
    clean = sorted(set(validated))
    if not clean:
        return None
    sanitized_provenance = sanitize_for_persistence(dict(provenance or {}))
    safe_provenance = (
        sanitized_provenance
        if isinstance(sanitized_provenance, dict)
        else {}
    )
    return ProjectFactsWritePlan(
        names=tuple(clean),
        provenance=safe_provenance,
        payload_digest=project_facts_payload_digest(clean, safe_provenance),
    )


def _validated_write_receipts(data: dict[str, Any]) -> list[dict[str, str]]:
    raw_receipts = data.get("write_receipts", [])
    if not isinstance(raw_receipts, list) or len(raw_receipts) > MAX_WRITE_RECEIPTS:
        raise MemoryStoreConflict("Project Facts write receipts are invalid")
    receipts: list[dict[str, str]] = []
    seen: set[str] = set()
    for raw in raw_receipts:
        if not isinstance(raw, dict) or set(raw) != {
            "operation_id",
            "payload_digest",
        }:
            raise MemoryStoreConflict("Project Facts write receipt is invalid")
        operation_id = raw.get("operation_id")
        payload_digest = raw.get("payload_digest")
        if (
            not isinstance(operation_id, str)
            or _MEMORY_OPERATION_ID_RE.fullmatch(operation_id) is None
            or not isinstance(payload_digest, str)
            or re.fullmatch(r"[0-9a-f]{64}", payload_digest) is None
            or operation_id in seen
        ):
            raise MemoryStoreConflict("Project Facts write receipt is invalid")
        seen.add(operation_id)
        receipts.append(
            {
                "operation_id": operation_id,
                "payload_digest": payload_digest,
            }
        )
    return receipts


def _safe_dependency_name(value: Any) -> str:
    """Return one prompt-safe dependency identifier or fail closed."""
    name = str(sanitize_for_persistence(str(value or ""))).strip()[:MAX_NAME_CHARS]
    if (
        not name
        or "[REDACTED" in name
        or _DEPENDENCY_NAME_RE.fullmatch(name) is None
        or not assess_memory_safety(name, source="project_fact").allowed
    ):
        return ""
    return name


@dataclass
class ProjectFact:
    kind: str  # "dependency" | "build_command" (extensible)
    name: str
    first_seen: float
    last_seen: float
    occurrences: int = 1
    status: str = "active"
    provenance: list[dict[str, Any]] = field(default_factory=list)
    retracted_at: float | None = None
    retraction_reason: str = ""


class ProjectFactsStore:
    """Small append/merge store for deterministic project facts."""

    def __init__(self, workspace: str | Path, *, timeout: float = 5.0) -> None:
        self._root = Path(workspace) / ".mini-code-memory"
        self._path = self._root / "project_facts.json"
        self._coordinator = MemoryStoreCoordinator(self._root, timeout=timeout)

    # ── Read ───────────────────────────────────────────────────────

    def snapshot(self, *, strict: bool = False) -> dict[str, ProjectFact]:
        """Return the current facts keyed by ``kind:name`` (best effort)."""
        data = self._load(strict=strict)
        facts: dict[str, ProjectFact] = {}
        for raw in data.get("facts", []):
            if not isinstance(raw, dict):
                continue
            sanitized_raw = sanitize_for_persistence(raw)
            if not isinstance(sanitized_raw, dict):
                continue
            raw = sanitized_raw
            kind = str(raw.get("kind", "")).strip()[:40]
            name = (
                _safe_dependency_name(raw.get("name", ""))
                if kind == "dependency"
                else str(raw.get("name", "")).strip()[:MAX_NAME_CHARS]
            )
            if not kind or not name:
                continue
            try:
                fact = ProjectFact(
                    kind=kind,
                    name=name,
                    first_seen=float(raw.get("first_seen", 0.0) or 0.0),
                    last_seen=float(raw.get("last_seen", 0.0) or 0.0),
                    occurrences=max(1, int(raw.get("occurrences", 1) or 1)),
                    status=(
                        str(raw.get("status", "active"))
                        if str(raw.get("status", "active")) in {"active", "retracted"}
                        else "retracted"
                    ),
                    provenance=[
                        dict(item)
                        for item in raw.get("provenance", [])[:16]
                        if isinstance(item, dict)
                    ] if isinstance(raw.get("provenance", []), list) else [],
                    retracted_at=(
                        float(raw["retracted_at"])
                        if raw.get("retracted_at") is not None
                        else None
                    ),
                    retraction_reason=str(raw.get("retraction_reason", ""))[:240],
                )
            except (TypeError, ValueError):
                continue
            facts[f"{kind}:{name}"] = fact
        return facts

    def render_markdown(self, max_bytes: int = RENDER_MAX_BYTES) -> str:
        """Render a bounded, stable-ordered prompt block."""
        facts = self.snapshot()
        if not facts:
            return ""
        dependencies = sorted(
            (
                fact.name
                for fact in facts.values()
                if fact.kind == "dependency" and fact.status == "active"
            )
        )
        lines: list[str] = []
        if dependencies:
            shown = ", ".join(dependencies[:60])
            if len(dependencies) > 60:
                shown += f", (+{len(dependencies) - 60} more)"
            lines.append(f"- Confirmed dependencies: {shown}")
        if not lines:
            return ""
        block = "## Project Facts\n\n" + "\n".join(lines)
        if len(block.encode("utf-8")) <= max_bytes:
            return block
        return (
            "## Project Facts\n\n"
            f"- Confirmed dependencies: {len(dependencies)} tracked in "
            f"{self._path.name}"
        )

    # ── Write ──────────────────────────────────────────────────────

    @contextmanager
    def operation_receipt_guard(
        self,
        operation_id: str,
    ) -> Iterator[ProjectFactsOperationReceipt | None]:
        """Hold Project Facts authority while exposing one strict receipt.

        The caller must acquire the canonical Memory lock before entering this
        guard.  Keeping both locks until a legacy Pipeline envelope is written
        removes the inspect-then-bind race without pretending the two authority
        files form one transaction: this context never writes Project Facts.
        """
        if (
            not isinstance(operation_id, str)
            or _MEMORY_OPERATION_ID_RE.fullmatch(operation_id) is None
        ):
            raise ValueError("Memory operation ID is invalid")
        with self._coordinator.transaction():
            receipts = _validated_write_receipts(self._load(strict=True))
            prior = next(
                (
                    receipt
                    for receipt in receipts
                    if receipt["operation_id"] == operation_id
                ),
                None,
            )
            yield (
                None
                if prior is None
                else ProjectFactsOperationReceipt(
                    operation_id=prior["operation_id"],
                    payload_digest=prior["payload_digest"],
                )
            )

    def observe_dependencies(
        self,
        names: list[str],
        *,
        provenance: dict[str, Any] | None = None,
    ) -> int:
        """Merge newly confirmed dependency names; return added count."""
        prepared = prepare_project_facts_write(names, provenance)
        if prepared is None:
            return 0
        clean = list(prepared.names)
        safe_provenance = prepared.provenance
        try:
            with self._coordinator.transaction():
                receipts = _validated_write_receipts(self._load(strict=True))
                facts = self.snapshot(strict=True)
                self._require_capacity(facts, clean)
                added, _updated = self._merge_dependencies(
                    facts,
                    clean,
                    safe_provenance,
                )
                self._save(facts, write_receipts=receipts)
        except Exception as exc:  # noqa: BLE001 - facts are advisory
            logger.warning("ProjectFactsStore: observe failed safely: %s", exc)
            return 0
        return added

    def observe_dependencies_once(
        self,
        names: list[str],
        *,
        operation_id: str,
        provenance: dict[str, Any] | None = None,
    ) -> ProjectFactsEffect:
        """Merge once within the retained 128-operation replay window."""
        if (
            not isinstance(operation_id, str)
            or _MEMORY_OPERATION_ID_RE.fullmatch(operation_id) is None
        ):
            raise ValueError("Memory operation ID is invalid")
        prepared = prepare_project_facts_write(names, provenance)
        if prepared is None:
            return ProjectFactsEffect(status="skipped")
        clean = list(prepared.names)
        safe_provenance = prepared.provenance
        payload_digest = prepared.payload_digest

        with self._coordinator.transaction():
            receipts = _validated_write_receipts(self._load(strict=True))
            prior = next(
                (
                    receipt
                    for receipt in receipts
                    if receipt["operation_id"] == operation_id
                ),
                None,
            )
            if prior is not None:
                if prior["payload_digest"] != payload_digest:
                    raise MemoryStoreConflict(
                        "Project Facts operation payload changed"
                    )
                return ProjectFactsEffect(status="replayed")

            facts = self.snapshot(strict=True)
            self._require_capacity(facts, clean)
            added, updated = self._merge_dependencies(
                facts,
                clean,
                safe_provenance,
            )
            receipts.append(
                {
                    "operation_id": operation_id,
                    "payload_digest": payload_digest,
                }
            )
            self._save(
                facts,
                write_receipts=receipts[-MAX_WRITE_RECEIPTS:],
            )
        return ProjectFactsEffect(
            status="committed",
            added_count=added,
            updated_count=updated,
        )

    @staticmethod
    def _merge_dependencies(
        facts: dict[str, ProjectFact],
        names: list[str],
        provenance: dict[str, Any],
    ) -> tuple[int, int]:
        now = time.time()
        added = 0
        updated = 0
        for name in names:
            key = f"dependency:{name}"
            existing = facts.get(key)
            if existing is None:
                facts[key] = ProjectFact(
                    kind="dependency",
                    name=name,
                    first_seen=now,
                    last_seen=now,
                    provenance=[provenance] if provenance else [],
                )
                added += 1
                continue
            existing.last_seen = now
            existing.occurrences += 1
            existing.status = "active"
            existing.retracted_at = None
            existing.retraction_reason = ""
            if provenance:
                existing.provenance = (
                    existing.provenance + [provenance]
                )[-16:]
            updated += 1
        return added, updated

    @staticmethod
    def _require_capacity(
        facts: dict[str, ProjectFact],
        names: list[str],
    ) -> None:
        resulting_keys = set(facts)
        resulting_keys.update(f"dependency:{name}" for name in names)
        if len(facts) > MAX_FACTS or len(resulting_keys) > MAX_FACTS:
            raise MemoryStoreConflict("Project Facts capacity exceeded")

    def retract_dependency(
        self,
        name: str,
        *,
        reason: str,
        provenance: dict[str, Any] | None = None,
    ) -> bool:
        """Retract a fact while retaining an auditable tombstone."""
        normalized = str(name or "").strip()[:MAX_NAME_CHARS]
        if not normalized:
            return False
        sanitized_provenance = sanitize_for_persistence(dict(provenance or {}))
        safe_provenance = (
            sanitized_provenance
            if isinstance(sanitized_provenance, dict)
            else {}
        )
        with self._coordinator.transaction():
            facts = self.snapshot(strict=True)
            fact = facts.get(f"dependency:{normalized}")
            if fact is None:
                return False
            fact.status = "retracted"
            fact.retracted_at = time.time()
            fact.retraction_reason = str(reason or "retracted")[:240]
            if safe_provenance:
                fact.provenance = (fact.provenance + [safe_provenance])[-16:]
            self._save(facts)
        return True

    # ── Storage ────────────────────────────────────────────────────

    def _load(self, *, strict: bool = False) -> dict[str, Any]:
        if self._root.is_symlink() or self._path.is_symlink():
            if strict:
                raise MemoryStoreConflict("Project Facts path is unsafe")
            return {}
        try:
            with open(self._path, "r", encoding="utf-8") as handle:
                data = json.load(handle)
            if isinstance(data, dict):
                return data
            if strict:
                raise MemoryStoreConflict("Project Facts authority is invalid")
            return {}
        except FileNotFoundError:
            return {}
        except (OSError, ValueError) as error:
            if strict:
                raise MemoryStoreConflict(
                    "Project Facts authority is unreadable"
                ) from error
            return {}

    def _save(
        self,
        facts: dict[str, ProjectFact],
        *,
        write_receipts: list[dict[str, str]] | None = None,
    ) -> None:
        if self._root.is_symlink() or self._path.is_symlink():
            raise OSError("project facts path is a symbolic link")
        self._root.mkdir(parents=True, exist_ok=True, mode=0o700)
        if self._root.is_symlink() or self._path.is_symlink():
            raise OSError("project facts path is a symbolic link")
        ordered = sorted(facts.values(), key=lambda fact: (fact.kind, fact.name))
        if len(facts) > MAX_FACTS:
            raise MemoryStoreConflict("Project Facts capacity exceeded")
        receipts = (
            _validated_write_receipts(self._load(strict=True))
            if write_receipts is None
            else write_receipts
        )
        sanitized_payload = sanitize_for_persistence(
            {
                "last_updated": time.time(),
                "facts": [asdict(fact) for fact in ordered],
                "write_receipts": receipts[-MAX_WRITE_RECEIPTS:],
            }
        )
        payload = json.dumps(
            sanitized_payload,
            ensure_ascii=False,
            sort_keys=True,
        )
        descriptor, temporary = tempfile.mkstemp(
            dir=str(self._root), prefix=".project-facts-", suffix=".tmp"
        )
        try:
            with os.fdopen(descriptor, "w", encoding="utf-8") as handle:
                handle.write(payload)
                handle.flush()
                os.fsync(handle.fileno())
            os.chmod(temporary, 0o600)
            os.replace(temporary, self._path)
        except OSError:
            try:
                os.unlink(temporary)
            except FileNotFoundError:
                pass
            raise


__all__ = [
    "ProjectFact",
    "ProjectFactsOperationReceipt",
    "ProjectFactsStore",
    "ProjectFactsWritePlan",
    "prepare_project_facts_write",
    "project_facts_payload_digest",
]

shared_files.minicode/project_memory_deletion.py:
"""Workspace-local authority for deleting one Project Memory identity."""

from __future__ import annotations

import hashlib
import hmac
import json
from datetime import datetime, timezone
from pathlib import Path
from typing import Callable

import minicode.memory as memory_module
from minicode.deletion_store import (
    DeletionLedger,
    DeletionRecord,
    DeletionStoreBusy,
    DeletionStoreUnavailable,
)
from minicode.memory import MemoryEntry, MemoryManager, MemoryScope, MemoryTier
from minicode.memory_approval import (
    _PUBLIC_CATEGORIES,
    MEMORY_ID_RE,
    MemoryApprovalAuthority,
    MemoryApprovalError,
)
from minicode.memory_store import (
    MemoryStoreBusy,
    MemoryStoreConflict,
    MemoryStoreUnavailable,
)

_APPROVAL_STATUSES = frozenset({"pending", "approved", "rejected"})
_LIFECYCLE_STATUSES = memory_module._VALID_LIFECYCLE_STATUSES


class ProjectMemoryDeletionError(RuntimeError):
    """One fixed-code Project Memory deletion failure."""

    def __init__(self, code: str) -> None:
        super().__init__(code)
        self.code = code


def _utc_now() -> datetime:
    return datetime.now(timezone.utc)


def _iso_time(value: datetime) -> str:
    if not isinstance(value, datetime) or value.tzinfo is None:
        raise ProjectMemoryDeletionError("deletion_unavailable")
    return value.astimezone(timezone.utc).isoformat(timespec="milliseconds").replace(
        "+00:00", "Z"
    )


def _hash_payload(payload: object) -> str:
    encoded = json.dumps(
        payload,
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
        allow_nan=False,
        default=repr,
    ).encode("utf-8")
    return hashlib.sha256(encoded).hexdigest()


class ProjectMemoryDeletionAuthority:
    """Preview/delete authority for exactly one current-Workspace Project item."""

    def __init__(
        self,
        workspace: str | Path,
        *,
        data_dir: str | Path | None = None,
        clock: Callable[[], datetime] = _utc_now,
        store_timeout: float = 5.0,
    ) -> None:
        self.workspace = Path(workspace).expanduser().resolve()
        configured_data_dir = (
            Path(memory_module.MINI_CODE_DIR)
            if data_dir is None
            else Path(data_dir)
        )
        self.data_dir = configured_data_dir.expanduser().resolve(strict=False)
        self._clock = clock
        self._store_timeout = store_timeout
        self._reader = MemoryApprovalAuthority(
            self.workspace,
            clock=clock,
            store_timeout=store_timeout,
        )
        self._ledger = DeletionLedger(
            self.workspace,
            data_dir=self.data_dir,
            clock=clock,
            timeout=store_timeout,
        )

    @staticmethod
    def _validate_id(memory_id: object) -> str:
        if not isinstance(memory_id, str) or MEMORY_ID_RE.fullmatch(memory_id) is None:
            raise ProjectMemoryDeletionError("invalid_id")
        return memory_id

    @staticmethod
    def _validate_revision(value: object) -> str:
        from minicode.conversation_deletion import DELETION_REVISION_RE

        if not isinstance(value, str) or DELETION_REVISION_RE.fullmatch(value) is None:
            raise ProjectMemoryDeletionError("invalid_revision")
        return value

    def _read_entries_and_audit(
        self,
        memory_id: str,
    ) -> tuple[list[MemoryEntry], list[dict[str, object]], dict[str, object] | None]:
        snapshot = self._reader.read_scope_snapshot(MemoryScope.PROJECT)
        entries = list(snapshot.entries)
        if len(entries) > 1_000 or len({entry.id for entry in entries}) != len(entries):
            raise MemoryApprovalError("memory_approval_failed")

        audit_records = [dict(record) for record in snapshot.approval_audit]

        raw_target: dict[str, object] | None = None
        raw_by_id = [
            item for item in snapshot.raw_entries if item.get("id") == memory_id
        ]
        if len(raw_by_id) > 1:
            raise MemoryApprovalError("memory_approval_failed")
        raw_target = dict(raw_by_id[0]) if raw_by_id else None
        return entries, audit_records, raw_target

    def _plan(
        self,
        memory_id: str,
        *,
        fence: DeletionRecord | None = None,
    ) -> tuple[dict[str, object], list[MemoryEntry], list[dict[str, object]]]:
        entries, audit, raw_target = self._read_entries_and_audit(memory_id)
        target_matches = [entry for entry in entries if entry.id == memory_id]
        if len(target_matches) > 1:
            raise ProjectMemoryDeletionError("deletion_unavailable")
        target = target_matches[0] if target_matches else None
        audit_matches = [record for record in audit if record.get("entry_id") == memory_id]
        invalid_audit = any(
            not isinstance(record.get("entry_id"), str) for record in audit
        )
        backlinks = [
            (entry, count)
            for entry in entries
            if (
                count := memory_module._memory_entry_relationships(entry).count(
                    memory_id
                )
            )
        ]
        backlink_count = sum(count for _, count in backlinks)
        if target is None and not audit_matches and not backlinks and fence is None:
            raise ProjectMemoryDeletionError("deletion_target_not_found")

        diagnostics: list[dict[str, str]] = []
        category = "unknown"
        tier = "unknown"
        lifecycle = "unknown"
        approval = "unknown"
        if target is not None:
            category = target.category
            tier = target.tier.value
            lifecycle = target.lifecycle_status
            approval = target.approval_status
            raw_category = raw_target.get("category", category) if raw_target else category
            raw_tier = raw_target.get("tier", tier) if raw_target else tier
            raw_lifecycle = (
                raw_target.get("lifecycle_status", lifecycle)
                if raw_target
                else lifecycle
            )
            raw_approval = (
                raw_target.get("approval_status", approval)
                if raw_target
                else approval
            )
            if (
                raw_category not in _PUBLIC_CATEGORIES
                or raw_tier not in {item.value for item in MemoryTier}
                or raw_lifecycle not in _LIFECYCLE_STATUSES
                or raw_approval not in _APPROVAL_STATUSES
            ):
                diagnostics.append({"code": "memory_metadata_invalid"})
                category = tier = lifecycle = approval = "unknown"
        if invalid_audit:
            diagnostics.append({"code": "memory_audit_invalid"})

        status = "unavailable" if diagnostics else "partial" if fence else "ready"
        canonical = {
            "target": _hash_payload(target.to_dict()) if target is not None else None,
            "audit": sorted(_hash_payload(record) for record in audit_matches),
            "backlinks": sorted(
                [
                    entry.id,
                    count,
                    _hash_payload(entry.to_dict()),
                ]
                for entry, count in backlinks
            ),
            "diagnostics": [item["code"] for item in diagnostics],
            "fence": ["absent"],
        }
        revision = (
            fence.deletion_revision
            if fence is not None
            else "delrev_" + _hash_payload(canonical)
        )
        preview = {
            "schemaVersion": 1,
            "generatedAt": _iso_time(self._clock()),
            "mode": "read-write",
            "kind": "project-memory",
            "target": {
                "memoryId": memory_id,
                "scope": "project",
                "category": category,
                "tier": tier,
                "lifecycleStatus": lifecycle,
                "approvalStatus": approval,
            },
            "status": status,
            "deletionRevision": revision,
            "affected": {
                "entries": int(target is not None),
                "approvalAuditRecords": len(audit_matches),
                "backlinks": backlink_count,
            },
            "blockers": [],
            "diagnostics": diagnostics,
        }
        return preview, entries, audit

    def _receipt_preview(
        self, memory_id: str, receipt: DeletionRecord
    ) -> dict[str, object]:
        return {
            "schemaVersion": 1,
            "generatedAt": _iso_time(self._clock()),
            "mode": "read-write",
            "kind": "project-memory",
            "target": {
                "memoryId": memory_id,
                "scope": "project",
                "category": "unknown",
                "tier": "unknown",
                "lifecycleStatus": "unknown",
                "approvalStatus": "unknown",
            },
            "status": "completed",
            "deletionRevision": receipt.deletion_revision,
            "affected": {"entries": 0, "approvalAuditRecords": 0, "backlinks": 0},
            "blockers": [],
            "diagnostics": [],
        }

    def snapshot(self, target_id: str) -> dict[str, object]:
        memory_id = self._validate_id(target_id)
        try:
            receipt = self._ledger.read_receipt("project-memory", memory_id)
            if receipt is not None:
                return self._receipt_preview(memory_id, receipt)
            fence = self._ledger.read_fence("project-memory", memory_id)
            preview, _, _ = self._plan(memory_id, fence=fence)
            return preview
        except ProjectMemoryDeletionError:
            raise
        except (DeletionStoreBusy, MemoryStoreBusy) as error:
            raise ProjectMemoryDeletionError("deletion_store_busy") from error
        except (
            DeletionStoreUnavailable,
            MemoryApprovalError,
            MemoryStoreConflict,
            MemoryStoreUnavailable,
            OSError,
            ValueError,
            TypeError,
            json.JSONDecodeError,
        ) as error:
            raise ProjectMemoryDeletionError("deletion_unavailable") from error
        except BaseException as error:
            raise ProjectMemoryDeletionError("deletion_unavailable") from error

    def _result(
        self,
        memory_id: str,
        revision: str,
        *,
        status: str,
        deleted: dict[str, int],
        remaining: dict[str, int],
        diagnostic: str | None = None,
    ) -> dict[str, object]:
        return {
            "schemaVersion": 1,
            "generatedAt": _iso_time(self._clock()),
            "mode": "read-write",
            "kind": "project-memory",
            "target": {"memoryId": memory_id, "scope": "project"},
            "status": status,
            "deletionRevision": revision,
            "deleted": deleted,
            "remaining": remaining,
            "diagnostics": ([{"code": diagnostic}] if diagnostic else []),
        }

    def delete(self, target_id: str, deletion_revision: str) -> dict[str, object]:
        memory_id = self._validate_id(target_id)
        requested = self._validate_revision(deletion_revision)
        existing_fence = False
        try:
            with self._ledger.coordination():
                receipt = self._ledger.read_receipt("project-memory", memory_id)
                if receipt is not None:
                    if not hmac.compare_digest(receipt.deletion_revision, requested):
                        raise ProjectMemoryDeletionError("deletion_target_not_found")
                    return self._result(
                        memory_id,
                        requested,
                        status="already_absent",
                        deleted={"entries": 0, "approvalAuditRecords": 0, "backlinks": 0},
                        remaining={"entries": 0, "approvalAuditRecords": 0, "backlinks": 0},
                    )
                fence = self._ledger.read_fence("project-memory", memory_id)
                existing_fence = fence is not None
                if fence is None:
                    preview, _, _ = self._plan(memory_id)
                    if not hmac.compare_digest(str(preview["deletionRevision"]), requested):
                        raise ProjectMemoryDeletionError("deletion_revision_stale")
                    if preview["status"] != "ready":
                        raise ProjectMemoryDeletionError("deletion_unavailable")
                    fence = self._ledger.start("project-memory", memory_id, requested)
                elif not hmac.compare_digest(fence.deletion_revision, requested):
                    raise ProjectMemoryDeletionError("deletion_revision_stale")

            manager = MemoryManager(
                project_root=self.workspace,
                store_timeout=self._store_timeout,
                readonly_load=True,
            )
            deleted = {"entries": 0, "approvalAuditRecords": 0, "backlinks": 0}

            def commit() -> dict[str, object]:
                nonlocal deleted
                current_fence = self._ledger.read_fence("project-memory", memory_id)
                if current_fence is None:
                    with self._ledger.coordination():
                        completed = self._ledger.read_receipt(
                            "project-memory", memory_id
                        )
                    if completed is not None and hmac.compare_digest(
                        completed.deletion_revision, requested
                    ):
                        return self._result(
                            memory_id,
                            requested,
                            status="already_absent",
                            deleted={
                                "entries": 0,
                                "approvalAuditRecords": 0,
                                "backlinks": 0,
                            },
                            remaining={
                                "entries": 0,
                                "approvalAuditRecords": 0,
                                "backlinks": 0,
                            },
                        )
                current, _, _ = self._plan(
                    memory_id,
                    fence=current_fence if existing_fence else None,
                )
                if not existing_fence and not hmac.compare_digest(
                    str(current["deletionRevision"]), requested
                ):
                    with self._ledger.coordination():
                        self._ledger.abandon("project-memory", memory_id)
                    raise ProjectMemoryDeletionError("deletion_revision_stale")
                if current["status"] == "unavailable":
                    raise ProjectMemoryDeletionError("deletion_unavailable")

                memory_file = manager.memories[MemoryScope.PROJECT]
                records = manager.approval_audit[MemoryScope.PROJECT]
                kept_records = [
                    record for record in records if record.get("entry_id") != memory_id
                ]
                deleted["approvalAuditRecords"] = len(records) - len(kept_records)
                manager.approval_audit[MemoryScope.PROJECT] = kept_records
                for entry in memory_file.entries:
                    deleted["backlinks"] += (
                        memory_module._remove_memory_relationship_reference(
                            entry,
                            memory_id,
                        )
                    )
                deleted["entries"] = int(memory_file.delete_entry(memory_id))
                if any(int(value) for value in deleted.values()):
                    # memory.json is the single authority for entries and
                    # approval audit. Commit both mutations together; the
                    # Markdown/audit files are best-effort projections only.
                    manager._save_scope(MemoryScope.PROJECT)

                verification, _, _ = self._plan(memory_id, fence=current_fence)
                remaining = dict(verification["affected"])
                if any(int(value) for value in remaining.values()):
                    return self._result(
                        memory_id,
                        requested,
                        status="partial",
                        deleted=deleted,
                        remaining=remaining,
                        diagnostic="deletion_retry_required",
                    )
                with self._ledger.coordination():
                    self._ledger.complete("project-memory", memory_id, requested)
                return self._result(
                    memory_id,
                    requested,
                    status="completed",
                    deleted=deleted,
                    remaining={"entries": 0, "approvalAuditRecords": 0, "backlinks": 0},
                )

            # Deletion can turn previously resolved same-scope edges into
            # dangling references. Hold the complete ordered authority fence
            # while validating and cleaning every relationship representation.
            # This low-frequency management operation favors correctness over
            # the ordinary single-scope write fast path.
            return manager.coordinated_write(tuple(MemoryScope), commit)
        except ProjectMemoryDeletionError:
            raise
        except (DeletionStoreBusy, MemoryStoreBusy) as error:
            raise ProjectMemoryDeletionError("deletion_store_busy") from error
        except (MemoryStoreConflict,) as error:
            raise ProjectMemoryDeletionError("deletion_write_conflict") from error
        except (
            DeletionStoreUnavailable,
            MemoryApprovalError,
            MemoryStoreUnavailable,
        ) as error:
            raise ProjectMemoryDeletionError("deletion_unavailable") from error
        except BaseException:
            if self._ledger.read_fence("project-memory", memory_id) is not None:
                try:
                    remaining_preview, _, _ = self._plan(
                        memory_id,
                        fence=self._ledger.read_fence("project-memory", memory_id),
                    )
                    remaining = dict(remaining_preview["affected"])
                except BaseException:
                    remaining = {"entries": 1, "approvalAuditRecords": 1, "backlinks": 1}
                return self._result(
                    memory_id,
                    requested,
                    status="partial",
                    deleted={"entries": 0, "approvalAuditRecords": 0, "backlinks": 0},
                    remaining=remaining,
                    diagnostic="deletion_retry_required",
                )
            raise ProjectMemoryDeletionError("deletion_failed")


