        required_params=["query"], optional_params=["scope", "filters", "limit", "case_sensitive"],
        error_codes={
            "INVALID_QUERY": "The search query is invalid",
            "NO_RESULTS": "No results found for the query",
            "SEARCH_FAILED": "Search operation failed",
        },
    )


_registry: ProtocolRegistry | None = None


def get_protocol_registry() -> ProtocolRegistry:
    global _registry
    if _registry is None:
        _registry = ProtocolRegistry()
        _registry.register_definition(_create_file_operation_protocol())
        _registry.register_definition(_create_code_analysis_protocol())
        _registry.register_definition(_create_web_access_protocol())
        _registry.register_definition(_create_command_exec_protocol())
        _registry.register_definition(_create_search_query_protocol())
    return _registry

shared_files.minicode/recovery_control.py:
"""Turn-local recovery guard for denied actions and failed-tool loops.

The permission layer remains the execution authority.  This module only
prevents the model from spending more tool calls on an action that the same
Turn has already proved to be denied, and enforces a smaller local failure
budget than the Turn's disaster ceiling.  A direct invocation is deliberately
a different shape from a shell-wrapped invocation so legitimate recovery stays
available.
"""

from __future__ import annotations

import json
import os
import re
import shlex
from collections import Counter, deque
from dataclasses import dataclass
from typing import Any, Mapping


_SHELL_EXECUTABLES = {
    "bash",
    "cmd",
    "powershell",
    "pwsh",
    "sh",
    "zsh",
}
_TEST_TARGET_RE = re.compile(
    r"(?<![a-z0-9_])tests(?:[./][a-z0-9_.*:\-\[\]]+)+",
    re.IGNORECASE,
)
_PERMISSION_DENIED_PREFIX = "error[permission_denied]:"


@dataclass(frozen=True, slots=True)
class SuppressedAction:
    fingerprint: str
    message: str


@dataclass(frozen=True, slots=True)
class RecoveryStop:
    reason_code: str
    message: str
    permission_denials: int
    suppressed_attempts: int
    consecutive_failed_steps: int
    user_action_required: bool


def _stable_projection(value: object) -> str:
    try:
        return json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
    except (TypeError, ValueError):
        return repr(value)


def _command_fingerprint(tool_input: Mapping[str, Any]) -> str:
    command = str(tool_input.get("command") or "").strip()
    args = tool_input.get("args")
    normalized_args = [str(value) for value in args] if isinstance(args, list) else []
    parsed_command: list[str] = []
    if not normalized_args and command:
        try:
            parsed_command = shlex.split(command)
        except ValueError:
            parsed_command = []
    executable = os.path.basename(
        parsed_command[0] if parsed_command else command
    ).casefold()
    command_args = normalized_args or parsed_command[1:]
    control_flags = {"-c", "-lc", "-command", "/c", "/command"}
    raw_shell_snippet = not normalized_args and any(
        character in command for character in "|&;<>()$`"
    )
    explicit_shell_wrapper = executable in _SHELL_EXECUTABLES and any(
        value.casefold() in control_flags for value in command_args
    )
    if not explicit_shell_wrapper and not raw_shell_snippet:
        return "run_command:direct:" + _stable_projection(tool_input)

    if raw_shell_snippet and not explicit_shell_wrapper:
        payload = command
    else:
        control_index = next(
            (
                index
                for index, value in enumerate(command_args)
                if value.casefold() in control_flags
            ),
            -1,
        )
        payload = " ".join(command_args[control_index + 1 :]).strip()
    for _ in range(3):
        try:
            tokens = shlex.split(payload)
        except ValueError:
            break
        if (
            len(tokens) >= 3
            and os.path.basename(tokens[0]).casefold() in _SHELL_EXECUTABLES
            and tokens[1].casefold() in control_flags
        ):
            payload = " ".join(tokens[2:]).strip()
            continue
        break
    payload = re.sub(
        r"^\s*cd\s+(?:\"[^\"]*\"|'[^']*'|[^;&]+?)\s*(?:&&|;)\s*",
        "",
        payload,
        flags=re.IGNORECASE,
    )
    payload = re.sub(r"\s+", " ", payload).strip().casefold()
    runner = (
        "unittest"
        if "unittest" in payload
        else "pytest"
        if "pytest" in payload
        else "shell"
    )
    targets = sorted(set(match.casefold() for match in _TEST_TARGET_RE.findall(payload)))
    if targets:
        return f"run_command:shell-wrapper:{runner}:{'|'.join(targets)}"
    return "run_command:shell-wrapper:" + payload


def action_fingerprint(call: Mapping[str, Any]) -> str:
    """Project a tool request into a stable denial-equivalence class."""
    tool_name = str(call.get("toolName") or "")
    tool_input = call.get("input")
    if not isinstance(tool_input, dict):
        tool_input = {}
    if tool_name == "run_command":
        return _command_fingerprint(tool_input)
    if tool_name in {"edit_file", "modify_file", "patch_file", "write_file"}:
        return "file_edit:" + str(tool_input.get("path") or "")
    return f"{tool_name}:{_stable_projection(tool_input)}"


class RecoveryGuard:
    """Suppress denied equivalents and bound failed recovery for one Turn."""

    def __init__(self) -> None:
        self._denied: Counter[str] = Counter()
        self._suppressed: Counter[str] = Counter()
        self._consecutive_failed_steps = 0
        self._recent_failed_steps: deque[bool] = deque(maxlen=10)
        self._strategy_switch_issued = False
        self._pending_stop: RecoveryStop | None = None
        # Command executions fail for their own reasons (missing paths, wrong
        # cwd, bad module names) without any permission denial, and an
        # unrelated success in the same step (e.g. a read_file) must not
        # reset that failure streak — the benchmark showed retries spanning
        # dozens of model calls when it did.
        self._consecutive_command_failures = 0
        self._command_switch_issued = False

    def suppression_for(self, call: Mapping[str, Any]) -> SuppressedAction | None:
        fingerprint = action_fingerprint(call)
        if self._denied[fingerprint] < 1:
            return None
        self._suppressed[fingerprint] += 1
        tool_name = str(call.get("toolName") or "tool")
        if tool_name == "run_command":
            guidance = (
                "error[repeated_blocked_action]: Equivalent denied action "
                "suppressed before execution. Do not "
                "add bash/zsh wrappers, pipes, redirections, cd, sudo, or other "
                "privilege escalation. Use one materially different direct "
                "run_command request with an explicit executable, args, and an "
                "in-workspace cwd."
            )
        else:
            guidance = (
                "error[repeated_blocked_action]: Equivalent denied action "
                "suppressed before execution. Do not repeat the same denied "
                "target through another direct tool; to still make the "
                'change, delegate it through task with agent_type="workflow" '
                "(the central scheduler owns authorized writes), or use a "
                "materially different authorized approach."
            )
        return SuppressedAction(fingerprint=fingerprint, message=guidance)

    def observe(self, call: Mapping[str, Any], *, ok: bool, output: str) -> None:
        if not ok and output.casefold().startswith(_PERMISSION_DENIED_PREFIX):
            self._denied[action_fingerprint(call)] += 1
        if str(call.get("toolName") or "") == "run_command":
            if ok:
                self._consecutive_command_failures = 0
                self._command_switch_issued = False
            else:
                self._consecutive_command_failures += 1

    def denial_count(self, call: Mapping[str, Any]) -> int:
        """Return prior permission denials for this equivalence class."""
        return self._denied[action_fingerprint(call)]

    @property
    def consecutive_failed_steps(self) -> int:
        return self._consecutive_failed_steps

    def complete_step(self, executed_outcomes: list[bool]) -> str | None:
        """Observe one model step and optionally require a strategy switch.

        Suppressed calls are intentionally excluded.  Permission repetition has
        its own tighter circuit, while this budget covers distinct real tool
        failures.  Any real success is treated as progress and resets the
        consecutive-failure budget.  The command-failure circuit is evaluated
        independently of step success: a failing command streak must not be
        masked by unrelated successes in the same step.
        """
        if not executed_outcomes or self._pending_stop is not None:
            return None
        if self._consecutive_command_failures >= 5:
            self._pending_stop = self._general_failure_stop(
                reason_code="consecutive_command_failures"
            )
            return None
        command_nudge: str | None = None
        if (
            self._consecutive_command_failures >= 3
            and not self._command_switch_issued
        ):
            command_nudge = self._issue_command_switch_nudge()

        failed_step = not any(executed_outcomes)
        self._recent_failed_steps.append(failed_step)
        if not failed_step:
            self._consecutive_failed_steps = 0
            self._strategy_switch_issued = False
            return command_nudge

        self._consecutive_failed_steps += 1
        if self._consecutive_failed_steps >= 5:
            self._pending_stop = self._general_failure_stop(
                reason_code="consecutive_tool_failures"
            )
            return None
        if (
            len(self._recent_failed_steps) == self._recent_failed_steps.maxlen
            and sum(self._recent_failed_steps) >= 8
        ):
            self._pending_stop = self._general_failure_stop(
                reason_code="failure_window_exhausted"
            )
            return None
        if (
            self._consecutive_failed_steps == 3
            and not self._strategy_switch_issued
        ):
            self._strategy_switch_issued = True
            return (
                "error[strategy_switch_required]: Three consecutive tool steps "
                "failed. Do not retry the same approach. Re-observe the available "
                "evidence and choose materially different tools or inputs. Two "
                "more failed steps will open the recovery circuit."
            )
        return command_nudge

    def _issue_command_switch_nudge(self) -> str:
        self._command_switch_issued = True
        return (
            "error[command_strategy_switch_required]: Three command "
            "executions have failed in a row (permission denials or "
            "execution errors). Do not try another spelling of the same "
            "command. Re-check the file layout, the working directory, and "
            "the module paths against the repository before running "
            "anything; then issue at most one corrected direct command, or "
            "report the blocker honestly. Two more failed commands will "
            "open the recovery circuit."
        )

    def _general_failure_stop(self, *, reason_code: str) -> RecoveryStop:
        return RecoveryStop(
            reason_code=reason_code,
            message=(
                "error[recovery_exhausted]: Recovery circuit opened after the "
                "strategy switch failed to produce progress. Stop retrying and "
                "report the blocker with the evidence already observed."
            ),
            permission_denials=sum(self._denied.values()),
            suppressed_attempts=sum(self._suppressed.values()),
            consecutive_failed_steps=self._consecutive_failed_steps,
            user_action_required=True,
        )

    def stop_decision(self) -> RecoveryStop | None:
        """Return a pending general stop or an exhausted denial circuit."""
        if self._pending_stop is not None:
            return self._pending_stop
        if not self._suppressed:
            return None
        suppressed_attempts = max(self._suppressed.values())
        if suppressed_attempts < 2:
            return None
        return RecoveryStop(
            reason_code="repeated_denied_action",
            message=(
                "error[recovery_exhausted]: Recovery circuit opened after "
                "repeated equivalent denied actions. No further equivalent "
                "tool requests were executed. Use a materially different "
                "authorized approach or ask the user to resolve the blocker."
            ),
            permission_denials=sum(self._denied.values()),
            suppressed_attempts=suppressed_attempts,
            consecutive_failed_steps=self._consecutive_failed_steps,
            user_action_required=True,
        )

shared_files.minicode/reflection_claim_selection.py:
"""Deterministic persistable-claim selection and conservative arbitration helpers."""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any

from minicode.reflection_evidence import TaskEvidence
from minicode.reflection_synthesis import (
    ClaimValidationResult,
    ReflectionCandidate,
    ReflectionClaim,
    ReflectionValueDecision,
)


@dataclass(frozen=True, order=True)
class EvidenceChainKey:
    """Non-text identity material for one structured evidence chain."""

    error_ids: tuple[str, ...] = ()
    recovery_ids: tuple[str, ...] = ()
    verification_ids: tuple[str, ...] = ()
    decision_event_ids: tuple[str, ...] = ()
    source_event_ids: tuple[str, ...] = ()


@dataclass
class ClaimSuppressionResult:
    kept_claims: list[ReflectionClaim] = field(default_factory=list)
    suppressed_claims: list[ReflectionClaim] = field(default_factory=list)
    suppression_reason_codes: dict[str, str] = field(default_factory=dict)


@dataclass
class PersistableClaimEvaluation:
    """Four-stage claim view plus final branch-selection diagnostics."""

    candidate_claims: list[ReflectionClaim] = field(default_factory=list)
    valid_claims: list[ReflectionClaim] = field(default_factory=list)
    value_accepted_claims: list[ReflectionClaim] = field(default_factory=list)
    persistable_claims: list[ReflectionClaim] = field(default_factory=list)
    rejected_claims: list[ReflectionClaim] = field(default_factory=list)
    suppressed_claims: list[ReflectionClaim] = field(default_factory=list)
    selection_source: str = "rule"
    selection_reason: str = "rule_mode"
    rule_regression: bool = False
    gap_fill_success: bool = False
    suppression_reason_codes: dict[str, str] = field(default_factory=dict)

    @classmethod
    def from_pipeline(
        cls,
        candidate: ReflectionCandidate,
        validation: ClaimValidationResult,
        value_decision: ReflectionValueDecision,
        *,
        selection_source: str,
        selection_reason: str,
        suppression: ClaimSuppressionResult | None = None,
        rule_regression: bool = False,
        gap_fill_success: bool = False,
    ) -> PersistableClaimEvaluation:
        accepted_ids = set(value_decision.accepted_claim_ids)
        value_accepted = [
            claim
            for claim in validation.valid_claims
            if value_decision.accepted and claim.claim_id in accepted_ids
        ]
        suppressed = list(suppression.suppressed_claims) if suppression else []
        suppressed_ids = {claim.claim_id for claim in suppressed}
        return cls(
            candidate_claims=list(candidate.claims),
            valid_claims=list(validation.valid_claims),
            value_accepted_claims=value_accepted,
            persistable_claims=[
                claim
                for claim in value_accepted
                if claim.claim_id not in suppressed_ids
            ],
            rejected_claims=list(validation.rejected_claims),
            suppressed_claims=suppressed,
            selection_source=selection_source,
            selection_reason=selection_reason,
            rule_regression=rule_regression,
            gap_fill_success=gap_fill_success,
            suppression_reason_codes=(
                dict(suppression.suppression_reason_codes)
                if suppression
                else {}
            ),
        )

    def to_diagnostics(self) -> dict[str, Any]:
        return {
            "candidate_claim_ids": [claim.claim_id for claim in self.candidate_claims],
            "valid_claim_ids": [claim.claim_id for claim in self.valid_claims],
            "value_accepted_claim_ids": [
                claim.claim_id for claim in self.value_accepted_claims
            ],
            "persistable_claim_ids": [
                claim.claim_id for claim in self.persistable_claims
            ],
            "rejected_claim_ids": [claim.claim_id for claim in self.rejected_claims],
            "suppressed_claim_ids": [
                claim.claim_id for claim in self.suppressed_claims
            ],
            "selection_source": self.selection_source,
            "selection_reason": self.selection_reason,
            "rule_regression": self.rule_regression,
            "gap_fill_success": self.gap_fill_success,
            "suppression_reason_codes": dict(self.suppression_reason_codes),
        }


def build_evidence_chain_key(
    claim: ReflectionClaim,
    evidence: TaskEvidence,
) -> EvidenceChainKey:
    """Build a stable key without statement or semantic-key material."""
    evidence_ids = set(claim.evidence_ids)
    error_ids = set(claim.related_error_ids)
    recovery_ids = set(claim.related_recovery_ids)
    verification_ids = set(claim.verification_ids)

    for item in evidence.errors:
        if evidence_ids.intersection(item.source_event_ids):
            error_ids.add(item.error_id)
    for item in evidence.recoveries:
        if evidence_ids.intersection(item.event_ids) or item.recovery_id in recovery_ids:
            recovery_ids.add(item.recovery_id)
            error_ids.update(item.related_error_ids)
    for item in evidence.verification:
        if evidence_ids.intersection(item.event_ids):
            verification_ids.add(item.verification_id)

    decision_event_ids = {
        event_id
        for item in evidence.decisions
        for event_id in item.event_ids
        if event_id in evidence_ids
    }
    return EvidenceChainKey(
        error_ids=tuple(sorted(error_ids)),
        recovery_ids=tuple(sorted(recovery_ids)),
        verification_ids=tuple(sorted(verification_ids)),
        decision_event_ids=tuple(sorted(decision_event_ids)),
        source_event_ids=tuple(sorted(evidence_ids)),
    )


def _same_evidence_chain(left: EvidenceChainKey, right: EvidenceChainKey) -> bool:
    if left.error_ids and right.error_ids:
        return bool(set(left.error_ids).intersection(right.error_ids))
    if left.recovery_ids and right.recovery_ids:
        return bool(set(left.recovery_ids).intersection(right.recovery_ids))
    if left.verification_ids and right.verification_ids:
        return bool(set(left.verification_ids).intersection(right.verification_ids))
    return False


def _claim_priority(claim: ReflectionClaim, evidence: TaskEvidence) -> int:
    key = build_evidence_chain_key(claim, evidence)
    passed_verification_ids = {
        item.verification_id
        for item in evidence.verification
        if item.result == "passed"
    }
    has_passed_verification = bool(
        set(key.verification_ids).intersection(passed_verification_ids)
    )
    if (
        claim.claim_type == "root_cause"
        and claim.epistemic_status == "confirmed"
        and key.error_ids
        and key.recovery_ids
        and has_passed_verification
        and key.decision_event_ids
    ):
        return 4
    if (
        claim.claim_type == "recovery"
        and claim.epistemic_status == "confirmed"
        and key.error_ids
        and key.recovery_ids
        and has_passed_verification
    ):
        return 3
    if claim.claim_type == "error_pattern":
        return 2
    if claim.claim_type == "warning":
        return 1
    return 0


def suppress_redundant_llm_claims(
    valid_claims: list[ReflectionClaim],
    evidence: TaskEvidence,
) -> ClaimSuppressionResult:
    """Suppress only deterministic redundancy among Validator-valid LLM claims."""
    claims = list(valid_claims)
    keys = {
        claim.claim_id: build_evidence_chain_key(claim, evidence)
        for claim in claims
    }
    priorities = {
        claim.claim_id: _claim_priority(claim, evidence)
        for claim in claims
    }
    suppressed: dict[str, str] = {}

    ordered = sorted(
        enumerate(claims),
        key=lambda item: (-priorities[item[1].claim_id], item[0]),
    )
    for _index, stronger in ordered:
        if stronger.claim_id in suppressed:
            continue
        stronger_priority = priorities[stronger.claim_id]
        for weaker in claims:
            if weaker.claim_id == stronger.claim_id or weaker.claim_id in suppressed:
                continue
            if not _same_evidence_chain(
                keys[stronger.claim_id], keys[weaker.claim_id]
            ):
                continue
            weaker_priority = priorities[weaker.claim_id]
            reason: str | None = None
            if stronger_priority == 4 and weaker.claim_type in {
                "recovery",
                "error_pattern",
                "warning",
            }:
                reason = "subsumed_by_confirmed_root_cause"
            elif stronger_priority == 3 and weaker.claim_type in {
                "error_pattern",
                "warning",
            }:
                reason = "subsumed_by_verified_recovery"
            elif (
                stronger.claim_type == weaker.claim_type == "error_pattern"
                and stronger_priority == weaker_priority
            ):
                reason = "duplicate_error_pattern_same_chain"
            elif (
                stronger.claim_type == weaker.claim_type == "warning"
                and stronger_priority == weaker_priority
            ):
                reason = "duplicate_warning_same_chain"
            if reason:
                suppressed[weaker.claim_id] = reason

    return ClaimSuppressionResult(
        kept_claims=[claim for claim in claims if claim.claim_id not in suppressed],
        suppressed_claims=[claim for claim in claims if claim.claim_id in suppressed],
        suppression_reason_codes=suppressed,
    )


def _claim_covers(
    expected: ReflectionClaim,
    actual: ReflectionClaim,
    evidence: TaskEvidence,
) -> bool:
    if expected.semantic_key == actual.semantic_key:
        return True
    expected_key = build_evidence_chain_key(expected, evidence)
    actual_key = build_evidence_chain_key(actual, evidence)
    if (
        expected.claim_type == actual.claim_type
        and expected_key.decision_event_ids
        and set(expected_key.decision_event_ids).intersection(
            actual_key.decision_event_ids
        )
    ):
        return True
    if not _same_evidence_chain(expected_key, actual_key):
        return False
    if expected.claim_type == actual.claim_type:
        return True
    return _claim_priority(actual, evidence) >= _claim_priority(expected, evidence)


def detect_rule_regression(
    rule_persistable_claims: list[ReflectionClaim],
    llm_persistable_claims: list[ReflectionClaim],
    evidence: TaskEvidence,
) -> bool:
    """Flag deterministic loss of an already durable Rule claim."""
    return any(
        not any(
            _claim_covers(rule_claim, llm_claim, evidence)
            for llm_claim in llm_persistable_claims
        )
        for rule_claim in rule_persistable_claims
    )


__all__ = [
    "ClaimSuppressionResult",
    "EvidenceChainKey",
    "PersistableClaimEvaluation",
    "build_evidence_chain_key",
    "detect_rule_regression",
    "suppress_redundant_llm_claims",
]

