def get_reflection_prompt(version: ReflectionPromptVersion) -> str:
    if version == "baseline":
        prompt = LLM_REFLECTION_BASELINE_SYSTEM_PROMPT
    elif version in {"calibrated", "calibrated_verbose"}:
        prompt = LLM_REFLECTION_CALIBRATED_VERBOSE_SYSTEM_PROMPT
    else:
        prompt = LLM_REFLECTION_CALIBRATED_COMPACT_SYSTEM_PROMPT
    return prompt + (
        "\nCopy task_summary and outcome verbatim from their const values in "
        "required_output_schema.properties. Do not summarize or rewrite them."
    )


def get_reflection_output_schema(version: ReflectionPromptVersion) -> dict[str, Any]:
    schema = (
        _BASELINE_OUTPUT_SCHEMA
        if version == "baseline"
        else _CALIBRATED_OUTPUT_SCHEMA
    )
    return copy.deepcopy(schema)


def reflection_prompt_hash(version: ReflectionPromptVersion) -> str:
    payload = get_reflection_prompt(version) + json.dumps(
        get_reflection_output_schema(version),
        ensure_ascii=False,
        separators=(",", ":"),
        sort_keys=True,
    )
    return hashlib.sha256(payload.encode("utf-8")).hexdigest()[:16]


def reflection_output_schema_version(version: ReflectionPromptVersion) -> int:
    return 1 if version == "baseline" else 2


class LLMReflectionSynthesizer:
    """Generate one untrusted candidate through a no-tools client."""

    def __init__(
        self,
        client: StructuredGenerationClient,
        config: ReflectionLLMConfig,
    ) -> None:
        self._client = client
        self._config = config

    def synthesize(
        self,
        task_description: str,
        evidence: TaskEvidence,
    ) -> ReflectionCandidate:
        attempt = self.attempt(task_description, evidence)
        if not attempt.success or attempt.candidate is None:
            raise LLMSynthesisFailure(attempt)
        return attempt.candidate

    def attempt(
        self,
        task_description: str,
        evidence: TaskEvidence,
        *,
        agent_budget: Any | None = None,
        event_sink: Any | None = None,
        cancellation_token: Any | None = None,
        deadline_monotonic: float | None = None,
        recovery_context: RecoveryLessonContext | None = None,
    ) -> LLMSynthesisAttempt:
        started = time.perf_counter()
        checkpoint_model_call(
            cancellation_token=cancellation_token,
            deadline_monotonic=deadline_monotonic,
        )
        try:
            context_payload = None
            if recovery_context is not None:
                if type(recovery_context) is not RecoveryLessonContext:
                    raise LLMInputError("recovery context must be typed runtime metadata")
                context_payload = recovery_context.to_payload(evidence)
            envelope = build_llm_evidence_envelope(
                task_description,
                evidence,
                self._config,
            )
        except Exception:
            return LLMSynthesisAttempt(
                success=False,
                failure_code="input_envelope_error",
                latency_ms=(time.perf_counter() - started) * 1_000,
            )
        if envelope.input_truncated:
            return LLMSynthesisAttempt(
                success=False,
                failure_code="input_truncated",
                latency_ms=(time.perf_counter() - started) * 1_000,
                input_truncated=True,
                input_safety_status=envelope.safety_status,
            )
        if envelope.safety_status != "safe":
            return LLMSynthesisAttempt(
                success=False,
                failure_code="input_safety_rejected",
                latency_ms=(time.perf_counter() - started) * 1_000,
                input_safety_status=envelope.safety_status,
            )

        output_schema = get_reflection_output_schema(self._config.prompt_version)
        # These two fields belong to the host, not to model summarization.
        # The parser has always required exact equality; expose that contract
        # in the request rather than asking the model to guess the wording.
        output_schema["properties"]["task_summary"]["const"] = sanitize_evidence_text(
            task_description, 200
        )
        output_schema["properties"]["outcome"]["const"] = evidence.outcome
        request_payload = {
            "task_evidence": envelope.payload,
            "required_output_schema": output_schema,
        }
        system_prompt = get_reflection_prompt(self._config.prompt_version)
        if context_payload is not None:
            request_payload["recovery_episode_context"] = context_payload
            system_prompt += "\n\n" + RECOVERY_LESSON_SYSTEM_INSTRUCTIONS
        user_payload = json.dumps(
            request_payload,
            ensure_ascii=False,
            separators=(",", ":"),
            sort_keys=True,
        )
        if context_payload is not None and (
            len(user_payload.encode("utf-8")) > self._config.max_input_bytes
        ):
            # The dedicated path counts the entire user JSON, including the
            # context and schema, before reserving budget or contacting a model.
            # Ordinary reflection retains its existing envelope limit.
            return LLMSynthesisAttempt(
                success=False,
                failure_code="recovery_context_size_exceeded",
                latency_ms=(time.perf_counter() - started) * 1_000,
                input_safety_status=envelope.safety_status,
            )
        messages = [
            {
                "role": "system",
                "content": system_prompt,
            },
            {"role": "user", "content": user_payload},
        ]
        operation_id = new_model_operation_id()
        model_identity = self._model_identity()
        request_started = time.monotonic()
        reservation = None
        try:
            if agent_budget is not None:
                reservation = agent_budget.reserve_model_call(
                    self._estimate_message_tokens(messages),
                    preserve_model_calls=1,
                )
        except AgentBudgetExceeded:
            return LLMSynthesisAttempt(
                success=False,
                failure_code="agent_budget_exhausted",
                latency_ms=(time.perf_counter() - started) * 1_000,
                input_safety_status=envelope.safety_status,
            )
        emit_event_safely(
            event_sink,
            "model.started",
            payload={
                "operationId": operation_id,
                "purpose": "memory_reflection",
            },
        )
        try:
            response = self._generate_json(
                messages,
                cancellation_token=cancellation_token,
                deadline_monotonic=deadline_monotonic,
            )
        except TurnCancellationRequested:
            self._settle_failed_budget(agent_budget, reservation)
            self._emit_model_failure(
                event_sink, operation_id, request_started, "interrupted"
            )
            raise
        except ModelCallDeadlineExceeded:
            self._settle_failed_budget(
                agent_budget, reservation, charge_estimate=True
            )
            self._emit_model_failure(
                event_sink, operation_id, request_started, "timeout"
            )
            raise
        except TimeoutError:
            self._settle_failed_budget(
                agent_budget, reservation, charge_estimate=True
            )
            self._emit_model_failure(
                event_sink, operation_id, request_started, "timeout"
            )
            return LLMSynthesisAttempt(
                success=False,
                failure_code="provider_timeout",
                latency_ms=(time.perf_counter() - started) * 1_000,
                input_safety_status=envelope.safety_status,
                model_called=True,
            )
        except Exception:
            self._settle_failed_budget(
                agent_budget, reservation, charge_estimate=True
            )
            self._emit_model_failure(
                event_sink, operation_id, request_started, "provider_error"
            )
            return LLMSynthesisAttempt(
                success=False,
                failure_code="provider_error",
                latency_ms=(time.perf_counter() - started) * 1_000,
                input_safety_status=envelope.safety_status,
                model_called=True,
            )

        usage_source = response.usage_source
        if usage_source == "unavailable" and (
            isinstance(response.input_tokens, int)
            or isinstance(response.output_tokens, int)
        ):
            usage_source = "estimated"
        usage = project_model_usage(
            ModelUsage(
                input_tokens=response.input_tokens,
                output_tokens=response.output_tokens,
                cache_read_tokens=response.cache_read_tokens,
                cache_creation_tokens=response.cache_creation_tokens,
                source=usage_source,
            )
        )
        try:
            cost_payload = project_model_cost_event(
                model=model_identity,
                usage=usage,
                operation_id=operation_id,
            )
        except BaseException:  # noqa: BLE001 - observation stays optional
            cost_payload = pricing_failure_event_payload(operation_id)
        try:
            record_budgeted_model_call(
                agent_budget,
                model=model_identity,
                usage=usage,
                reservation=reservation,
                cost_payload=cost_payload,
            )
        except Exception:
            self._settle_failed_budget(agent_budget, reservation)
        completed_payload: dict[str, object] = {
            "operationId": operation_id,
            "purpose": "memory_reflection",
            "resultType": "assistant",
            "contentPresent": bool(response.text),
            "toolCallCount": len(response.tool_calls or []),
            "usage": usage,
        }
        duration_ms = project_model_duration_ms(
            request_started, time.monotonic()
        )
        if duration_ms is not None:
            completed_payload["durationMs"] = duration_ms
        emit_event_safely(
            event_sink,
            "model.completed",
            payload=completed_payload,
        )
        cost_payload["purpose"] = "memory_reflection"
        emit_event_safely(event_sink, "model.costed", payload=cost_payload)

        latency_ms = response.latency_ms
        if latency_ms is None:
            latency_ms = (time.perf_counter() - started) * 1_000
        base_attempt = {
            "latency_ms": latency_ms,
            "input_tokens": response.input_tokens,
            "output_tokens": response.output_tokens,
            "cache_read_tokens": response.cache_read_tokens,
            "cache_creation_tokens": response.cache_creation_tokens,
            "usage_source": response.usage_source,
            "estimated_cost_usd": response.estimated_cost_usd,
            "input_truncated": envelope.input_truncated,
            "input_safety_status": envelope.safety_status,
            "model_called": True,
            "stop_reason": response.stop_reason,
            "reasoning_present": response.reasoning_present,
        }
        if response.stop_reason in {"length", "max_tokens"}:
            # Even valid JSON cannot establish completion when the provider
            # explicitly reports truncation. Keep it out of all admission paths.
            return LLMSynthesisAttempt(
                success=False,
                failure_code="output_limit_reached",
                **base_attempt,
            )
        if response.tool_calls:
            return LLMSynthesisAttempt(
                success=False,
                failure_code="tool_call_rejected",
                **base_attempt,
            )
        try:
            candidate = parse_llm_candidate(
                response.text,
                task_description,
                evidence,
                self._config,
            )
        except LLMCandidateParseError as exc:
            return LLMSynthesisAttempt(
                success=False,
                failure_code=exc.code,
                failure_detail_code=exc.detail_code,
                output_safety_status=(
                    "rejected" if exc.code == "unsafe_output" else "not_scanned"
                ),
                **base_attempt,
            )
        return LLMSynthesisAttempt(
            success=True,
            candidate=candidate,
            output_safety_status="safe",
            **base_attempt,
        )

    def _generate_json(
        self,
        messages: list[dict[str, str]],
        *,
        cancellation_token: Any | None,
        deadline_monotonic: float | None,
    ) -> StructuredGenerationResponse:
        kwargs: dict[str, Any] = {
            "timeout_seconds": self._config.timeout_seconds,
            "max_output_tokens": self._config.max_output_tokens,
        }
        try:
            parameters = inspect.signature(
                self._client.generate_json
            ).parameters.values()
            accepts_kwargs = any(
                parameter.kind == inspect.Parameter.VAR_KEYWORD
                for parameter in parameters
            )
            names = {parameter.name for parameter in parameters}
            if accepts_kwargs or "cancellation_token" in names:
                kwargs["cancellation_token"] = cancellation_token
            if accepts_kwargs or "deadline_monotonic" in names:
                kwargs["deadline_monotonic"] = deadline_monotonic
        except (TypeError, ValueError):
            pass
        return self._client.generate_json(messages, **kwargs)

    def _model_identity(self) -> str:
        return str(
            self._config.model
            or getattr(self._client, "model_id", "")
            or "reflection-model"
        )

    @staticmethod
    def _estimate_message_tokens(messages: list[dict[str, str]]) -> int:
        try:
            from minicode.context_manager import estimate_messages_tokens

            return estimate_messages_tokens(messages)
        except Exception:  # noqa: BLE001 - estimate is advisory
            return max(
                1,
                sum(len(message.get("content", "")) for message in messages)
                // 4,
            )

    @staticmethod
    def _settle_failed_budget(
        agent_budget: Any,
        reservation: Any,
        *,
        charge_estimate: bool = False,
    ) -> None:
        settle = getattr(agent_budget, "fail_model_call", None)
        if callable(settle):
            settle(reservation, charge_estimate=charge_estimate)

    @staticmethod
    def _emit_model_failure(
        event_sink: Any,
        operation_id: str,
        started_at: float,
        failure_kind: str,
    ) -> None:
        payload: dict[str, object] = {
            "operationId": operation_id,
            "purpose": "memory_reflection",
            "failureKind": failure_kind,
        }
        duration_ms = project_model_duration_ms(started_at, time.monotonic())
        if duration_ms is not None:
            payload["durationMs"] = duration_ms
        emit_event_safely(event_sink, "model.failed", payload=payload)


