def _utc_now() -> datetime:
    return datetime.now(timezone.utc)


def _platform_name() -> str:
    return os.name


def _iso_time(value: datetime) -> str:
    if value.tzinfo is None:
        value = value.replace(tzinfo=timezone.utc)
    return value.astimezone(timezone.utc).isoformat(timespec="milliseconds").replace(
        "+00:00", "Z"
    )


def _datetime_ms(value: object) -> int:
    if not isinstance(value, datetime):
        raise RunJournalValidationError("Run clock is invalid.")
    if value.tzinfo is None:
        value = value.replace(tzinfo=timezone.utc)
    milliseconds = int(value.astimezone(timezone.utc).timestamp() * 1000)
    if not 0 <= milliseconds <= 99_999_999_999_999:
        raise RunJournalValidationError("Run clock is out of range.")
    return milliseconds


def _parse_time(value: str) -> datetime:
    if not isinstance(value, str) or not _ISO_UTC_RE.fullmatch(value):
        raise ValueError("invalid UTC timestamp")
    parsed = datetime.fromisoformat(value.removesuffix("Z") + "+00:00")
    if parsed.tzinfo is None or parsed.utcoffset() != timedelta(0):
        raise ValueError("invalid UTC timestamp")
    return parsed


def stable_workspace_id(workspace: str | Path) -> str:
    """Return the stable workspace ID shared with Dashboard projections."""
    resolved = Path(workspace).expanduser().resolve()
    return "ws_" + hashlib.sha256(str(resolved).encode("utf-8")).hexdigest()[:16]


def _redact_text(value: str, *, max_chars: int) -> str:
    redacted = _BEARER_RE.sub("Bearer [REDACTED]", value)
    redacted = _KEY_TOKEN_RE.sub("[REDACTED]", redacted)
    redacted = _ASSIGNMENT_RE.sub(
        lambda match: f"{match.group(1)}{match.group(2)}[REDACTED]", redacted
    )
    if len(redacted) > max_chars:
        return redacted[:max_chars].rstrip() + "…"
    return redacted


def _normalized_key(value: str) -> str:
    return re.sub(r"[^a-z0-9]", "", value.casefold())


def _sanitize_payload_value(value: Any, *, depth: int = 0) -> Any:
    if depth > _MAX_PAYLOAD_DEPTH:
        raise RunJournalValidationError("Event payload is too deeply nested.")
    if value is None or isinstance(value, bool):
        return value
    if isinstance(value, int):
        return value
    if isinstance(value, float):
        if not math.isfinite(value):
            raise RunJournalValidationError("Event payload contains a non-finite number.")
        return value
    if isinstance(value, str):
        if len(value) > _MAX_PAYLOAD_STRING_CHARS:
            raise RunJournalValidationError("Event payload contains an oversized string.")
        return _redact_text(value, max_chars=_MAX_PAYLOAD_STRING_CHARS)
    if isinstance(value, dict):
        if len(value) > _MAX_PAYLOAD_ITEMS:
            raise RunJournalValidationError("Event payload contains too many fields.")
        sanitized: dict[str, Any] = {}
        for key, nested in value.items():
            if not isinstance(key, str) or not key or len(key) > 64:
                raise RunJournalValidationError("Event payload contains an invalid key.")
            safe_key = _redact_text(key, max_chars=64)
            sanitized[safe_key] = (
                "[REDACTED]"
                if _normalized_key(key) in _SENSITIVE_KEYS
                else _sanitize_payload_value(nested, depth=depth + 1)
            )
        return sanitized
    if isinstance(value, list):
        if len(value) > _MAX_PAYLOAD_ITEMS:
            raise RunJournalValidationError("Event payload contains too many items.")
        return [
            _sanitize_payload_value(item, depth=depth + 1) for item in value
        ]
    raise RunJournalValidationError("Event payload contains an unsupported value.")


def _sanitize_payload(payload: Mapping[str, Any] | None) -> dict[str, Any]:
    if payload is None:
        return {}
    if not isinstance(payload, dict):
        raise RunJournalValidationError("Event payload must be a JSON object.")
    sanitized = _sanitize_payload_value(payload)
    encoded = json.dumps(
        sanitized,
        ensure_ascii=False,
        allow_nan=False,
        separators=(",", ":"),
    ).encode("utf-8")
    if len(encoded) > _MAX_EVENT_BYTES:
        raise RunJournalValidationError("Event payload exceeds the byte limit.")
    return sanitized


def _sanitize_event_payload(event_type: str, payload: Mapping[str, Any] | None) -> dict[str, Any]:
    sanitized = _sanitize_payload(payload)
    if event_type == CONCURRENT_TOOL_TERMINAL_EVENT_TYPE:
        normalized_terminal = normalize_concurrent_tool_terminal(sanitized)
        if normalized_terminal is None:
            raise RunJournalValidationError(
                "Concurrent tool terminal payload is invalid."
            )
        return normalized_terminal
    if event_type == "mcp.runtime.observed":
        normalized = normalize_mcp_runtime_payload(sanitized)
        if normalized is None:
            raise RunJournalValidationError("MCP runtime payload is invalid.")
        return normalized
    if event_type in PERMISSION_EVENT_TYPES:
        normalized_permission = normalize_permission_event_payload(
            event_type, sanitized
        )
        if normalized_permission is None:
            raise RunJournalValidationError("Permission event payload is invalid.")
        return normalized_permission
    if event_type == SUBAGENT_EVENT_TYPE:
        normalized_subagent = normalize_subagent_payload(sanitized)
        if normalized_subagent is None:
            raise RunJournalValidationError("Sub-agent event payload is invalid.")
        return normalized_subagent
    if event_type == VERIFICATION_EVENT_TYPE:
        normalized_verification = normalize_verification_payload(sanitized)
        if normalized_verification is None:
            raise RunJournalValidationError(
                "Verification event payload is invalid."
            )
        return normalized_verification
    if event_type == MEMORY_PERSISTENCE_FAILURE_EVENT_TYPE:
        normalized_memory_failure = normalize_memory_persistence_failure(sanitized)
        if normalized_memory_failure is None:
            raise RunJournalValidationError(
                "Memory persistence failure payload is invalid."
            )
        return normalized_memory_failure
    return sanitized


def _sanitize_metadata(metadata: Mapping[str, Any] | None) -> dict[str, str]:
    if metadata is None:
        return {}
    if not isinstance(metadata, dict) or len(metadata) > _MAX_METADATA_ITEMS:
        raise RunJournalValidationError("Run metadata is invalid.")
    sanitized: dict[str, str] = {}
    for key, value in metadata.items():
        if key not in _ALLOWED_METADATA_KEYS or not isinstance(value, str):
            raise RunJournalValidationError("Run metadata contains an unsupported field.")
        if len(value) > _MAX_METADATA_VALUE_CHARS:
            raise RunJournalValidationError("Run metadata value is too long.")
        sanitized[key] = _redact_text(value, max_chars=_MAX_METADATA_VALUE_CHARS)
    return sanitized


def _normalize_rendered_memory_ids(entry_ids: object) -> tuple[str, ...]:
    """Validate a bounded set of opaque Memory entry IDs, content-free."""
    if not isinstance(entry_ids, (list, tuple)):
        raise RunJournalValidationError("Rendered Memory IDs must be a list.")
    deduped = tuple(dict.fromkeys(entry_ids))
    if len(deduped) > _MAX_RENDERED_MEMORY_IDS:
        raise RunJournalValidationError("Too many rendered Memory IDs.")
    for entry_id in deduped:
        if not is_memory_entry_id(entry_id):
            raise RunJournalValidationError("Rendered Memory ID is invalid.")
    return deduped


def _normalize_rendered_memory_versions(
    versions: object,
    *,
    max_versions: int = _MAX_RENDERED_MEMORY_VERSIONS,
) -> tuple[tuple[str, str], ...]:
    """Validate bounded `(entry_id, authority_digest)` materializations."""
    if not isinstance(versions, (list, tuple)):
        raise RunJournalValidationError(
            "Rendered Memory versions must be a list."
        )
    normalized: list[tuple[str, str]] = []
    seen: set[tuple[str, str]] = set()
    for raw_version in versions:
        if not isinstance(raw_version, (list, tuple)) or len(raw_version) != 2:
            raise RunJournalValidationError(
                "Rendered Memory version is invalid."
            )
        entry_id, digest = raw_version
        if (
            not is_memory_entry_id(entry_id)
            or not isinstance(digest, str)
            or not _MEMORY_AUTHORITY_DIGEST_RE.fullmatch(digest)
        ):
            raise RunJournalValidationError(
                "Rendered Memory version is invalid."
            )
        version = (entry_id, digest)
        if version not in seen:
            seen.add(version)
            normalized.append(version)
    if len(normalized) > max_versions:
        raise RunJournalValidationError("Too many rendered Memory versions.")
    return tuple(normalized)


def _normalize_memory_provenance_actor(
    actor_kind: object,
    subagent_id: object,
) -> "RunMemoryProvenanceActor":
    if not isinstance(actor_kind, str) or actor_kind not in _MEMORY_PROVENANCE_ACTOR_KINDS:
        raise RunJournalValidationError("Memory provenance actor kind is invalid.")
    if actor_kind == "run_root":
        if subagent_id is not None:
            raise RunJournalValidationError(
                "Run-root Memory provenance cannot name a sub-agent."
            )
        return RunMemoryProvenanceActor(kind=actor_kind)
    if not isinstance(subagent_id, str) or not _SUBAGENT_ID_RE.fullmatch(subagent_id):
        raise RunJournalValidationError("Memory provenance sub-agent ID is invalid.")
    return RunMemoryProvenanceActor(
        kind=actor_kind,
        subagent_id=subagent_id,
    )


def _memory_provenance_record_to_dict(
    record: "RunMemoryProvenanceRecord",
) -> dict[str, object]:
    actor: dict[str, object] = {"kind": record.actor.kind}
    if record.actor.subagent_id is not None:
        actor["subagentId"] = record.actor.subagent_id
    return {"actor": actor, "batch": record.batch.to_dict()}


def _memory_provenance_record_from_dict(
    value: object,
) -> "RunMemoryProvenanceRecord":
    if not isinstance(value, dict) or set(value) != {"actor", "batch"}:
        raise ValueError("invalid Memory provenance record")
    raw_actor = value.get("actor")
    if not isinstance(raw_actor, dict):
        raise ValueError("invalid Memory provenance actor")
    fields = set(raw_actor)
    if fields == {"kind"}:
        actor = _normalize_memory_provenance_actor(raw_actor.get("kind"), None)
    elif fields == {"kind", "subagentId"}:
        actor = _normalize_memory_provenance_actor(
            raw_actor.get("kind"),
            raw_actor.get("subagentId"),
        )
    else:
        raise ValueError("invalid Memory provenance actor")
    return RunMemoryProvenanceRecord(
        actor=actor,
        batch=MemoryProvenanceBatch.from_dict(value.get("batch")),
    )


def _memory_provenance_identity_overlaps(
    left: MemoryProvenanceBatch,
    right: MemoryProvenanceBatch,
) -> bool:
    return bool(
        left.receipt_id is not None
        and left.receipt_id == right.receipt_id
    ) or bool(
        left.context_operation_id is not None
        and left.context_operation_id == right.context_operation_id
    )


def _is_bounded_partial_replay(
    prior: "RunMemoryProvenanceRecord",
    batch: MemoryProvenanceBatch,
    materializations: set[tuple[str, str]],
) -> bool:
    """Recognize a retry of a batch previously truncated at the Run cap.

    Once coverage is partial, payload outside the bounded projection cannot
    be distinguished or trusted.  The representable prefix and every scalar
    operation identity must still match exactly.
    """
    prior_batch = prior.batch
    return (
        prior_batch.coverage == "partial"
        and prior_batch.effect == batch.effect
        and prior_batch.origin == batch.origin
        and prior_batch.receipt_id == batch.receipt_id
        and prior_batch.context_operation_id == batch.context_operation_id
        and prior_batch.authority_versions
        == tuple(
            version
            for version in batch.authority_versions
            if version in materializations
        )
        and len(prior_batch.authority_versions) < len(batch.authority_versions)
    )


def _memory_provenance_storage(effect: object) -> tuple[str, str]:
    if not isinstance(effect, str) or effect not in MEMORY_PROVENANCE_EFFECTS:
        raise RunJournalValidationError("Memory provenance effect is invalid.")
    if effect == "rendered":
        return _RENDERED_MEMORY_VERSION_FILE, "Rendered"
    return _WRITTEN_MEMORY_VERSION_FILE, "Written"


