    def record_memory_provenance(
        self,
        run_id: str,
        batch: MemoryProvenanceBatch,
        *,
        actor_kind: str = "run_root",
        subagent_id: str | None = None,
    ) -> None:
        """Append one actor-bound, content-free Memory provenance batch.

        Capacity exhaustion is represented durably as partial coverage.  The
        prefix that fits is committed atomically instead of raising an error
        that an observation-only caller could accidentally swallow.
        """
        self._validate_run_id(run_id)
        if not isinstance(batch, MemoryProvenanceBatch):
            raise RunJournalValidationError(
                "Memory provenance batch is invalid."
            )
        actor = _normalize_memory_provenance_actor(actor_kind, subagent_id)
        filename, label = _memory_provenance_storage(batch.effect)
        mutex = self._writer_mutexes.get(run_id)
        if mutex is None:
            raise RunJournalOwnershipError(
                "This process does not own the Run writer."
            )
        with mutex:
            run_dir = self._run_directory(run_id, must_exist=True)
            self._require_writer(run_id, run_dir)
            run, _ = self._read_run(run_id)
            if run is None:
                raise RunJournalNotFoundError("Run was not found.")
            if run.status in TERMINAL_STATUSES:
                raise RunJournalTransitionError(
                    f"A terminal Run cannot accept {label.lower()} Memory provenance."
                )
            existing = self._read_memory_version_sidecar(
                run_dir,
                filename,
                label,
            )
            records = list(existing.records if existing is not None else ())
            materializations = list(
                existing.materializations if existing is not None else ()
            )
            known = set(materializations)
            for prior in records:
                if prior.actor != actor:
                    continue
                if prior.batch == batch:
                    return
                if _memory_provenance_identity_overlaps(prior.batch, batch):
                    if _is_bounded_partial_replay(prior, batch, known):
                        return
                    raise RunJournalMemoryProvenanceConflictError(
                        "Memory provenance operation identity was reused."
                    )

            accepted: list[tuple[str, str]] = []
            truncated = False
            for version in batch.authority_versions:
                if version in known:
                    accepted.append(version)
                    continue
                if len(materializations) >= _MAX_MEMORY_MATERIALIZATIONS_PER_RUN:
                    truncated = True
                    continue
                materializations.append(version)
                known.add(version)
                accepted.append(version)

            stored_batch: MemoryProvenanceBatch | None = batch
            if truncated:
                stored_batch = (
                    replace(
                        batch,
                        authority_versions=tuple(accepted),
                        coverage="partial",
                    )
                    if accepted
                    else None
                )
            record_overflow = len(records) >= MAX_MEMORY_PROVENANCE_BATCHES
            if stored_batch is not None and not record_overflow:
                records.append(
                    RunMemoryProvenanceRecord(actor=actor, batch=stored_batch)
                )

            if existing is None:
                coverage = (
                    stored_batch.coverage
                    if stored_batch is not None and not record_overflow
                    else "partial"
                )
            elif (
                existing.coverage == "complete"
                and stored_batch is not None
                and stored_batch.coverage == "complete"
                and not truncated
                and not record_overflow
            ):
                coverage = "complete"
            elif (
                existing.coverage == "unknown"
                and stored_batch is not None
                and stored_batch.coverage == "unknown"
                and not materializations
                and not record_overflow
            ):
                coverage = "unknown"
            else:
                coverage = "partial"

            updated = _MemoryVersionSidecar(
                schema_version=_MEMORY_MATERIALIZATION_SIDECAR_VERSION,
                effect=batch.effect,
                materializations=tuple(materializations),
                records=tuple(records),
                coverage=coverage,
            )
            if existing == updated:
                return
            self._write_memory_version_sidecar(
                run_dir,
                updated,
                filename,
                label,
            )

    def get_memory_provenance(
        self,
        run_id: str,
        effect: str,
    ) -> RunMemoryProvenanceSnapshot:
        """Read one strict, content-free provenance snapshot and coverage."""
        self._validate_run_id(run_id)
        filename, label = _memory_provenance_storage(effect)
        run, _ = self._read_run(run_id)
        if run is None:
            raise RunJournalNotFoundError("Run was not found.")
        run_dir = self._run_directory(run_id, must_exist=True)
        sidecar = self._read_memory_version_sidecar(
            run_dir,
            filename,
            label,
        )
        terminal_gaps = self._terminal_memory_provenance_gaps(run_id)
        if sidecar is None:
            return RunMemoryProvenanceSnapshot(
                effect=effect,
                materializations=(),
                records=(),
                coverage="unknown",
            )
        coverage = sidecar.coverage
        if effect in terminal_gaps and coverage == "complete":
            coverage = "partial" if sidecar.materializations else "unknown"
        return RunMemoryProvenanceSnapshot(
            effect=effect,
            materializations=sidecar.materializations,
            records=sidecar.records,
            coverage=coverage,
        )

    def _terminal_memory_provenance_gaps(self, run_id: str) -> frozenset[str]:
        """Read the terminal closure marker that dominates sidecar coverage.

        The marker is written in the same durable lifecycle event that makes
        a Run terminal.  Therefore a persistently failing optional sidecar
        cannot leave an older prefix looking complete after finalization.
        A malformed marker fails closed for both effects.
        """
        events, _diagnostics = self._read_events(run_id)
        terminal_types = {
            LIFECYCLE_EVENT_FOR_STATUS[status]
            for status in TERMINAL_STATUSES
        }
        for event in reversed(events):
            if event.type not in terminal_types:
                continue
            if "memoryProvenanceGaps" not in event.payload:
                return frozenset()
            raw_gaps = event.payload.get("memoryProvenanceGaps")
            if (
                not isinstance(raw_gaps, list)
                or len(raw_gaps) > len(MEMORY_PROVENANCE_EFFECTS)
                or any(
                    not isinstance(effect, str)
                    or effect not in MEMORY_PROVENANCE_EFFECTS
                    for effect in raw_gaps
                )
            ):
                return frozenset(MEMORY_PROVENANCE_EFFECTS)
            return frozenset(raw_gaps)
        return frozenset()

    def _record_memory_versions(
        self,
        run_id: str,
        versions: list[tuple[str, str]] | tuple[tuple[str, str], ...],
        *,
        effect: str,
    ) -> None:
        """Compatibility writer for version projection without provenance."""
        self._validate_run_id(run_id)
        normalized = _normalize_rendered_memory_versions(versions)
        if not normalized:
            return
        filename, label = _memory_provenance_storage(effect)
        mutex = self._writer_mutexes.get(run_id)
        if mutex is None:
            raise RunJournalOwnershipError(
                "This process does not own the Run writer."
            )
        with mutex:
            run_dir = self._run_directory(run_id, must_exist=True)
            self._require_writer(run_id, run_dir)
            run, _ = self._read_run(run_id)
            if run is None:
                raise RunJournalNotFoundError("Run was not found.")
            if run.status in TERMINAL_STATUSES:
                raise RunJournalTransitionError(
                    f"A terminal Run cannot accept {label.lower()} Memory versions."
                )
            existing = self._read_memory_version_sidecar(
                run_dir,
                filename,
                label,
            )
            materializations = list(
                existing.materializations if existing is not None else ()
            )
            known = set(materializations)
            truncated = False
            for version in normalized:
                if version in known:
                    continue
                if len(materializations) >= _MAX_MEMORY_MATERIALIZATIONS_PER_RUN:
                    truncated = True
                    continue
                materializations.append(version)
                known.add(version)
            coverage = "partial"
            updated = _MemoryVersionSidecar(
                schema_version=_MEMORY_MATERIALIZATION_SIDECAR_VERSION,
                effect=effect,
                materializations=tuple(materializations),
                records=existing.records if existing is not None else (),
                coverage=(
                    coverage
                    if truncated
                    or existing is None
                    or existing.schema_version
                    == _LEGACY_MEMORY_MATERIALIZATION_SIDECAR_VERSION
                    or tuple(materializations)
                    != existing.materializations
                    else existing.coverage
                ),
            )
            if existing == updated:
                return
            self._write_memory_version_sidecar(
                run_dir,
                updated,
                filename,
                label,
            )

    def record_scheduler_commit_ready(
        self,
        run_id: str,
        ready: SchedulerCommitReady,
    ) -> bool:
        """Write one immutable scheduler COMMIT_READY authorization.

        ``True`` means this call created the durable record. ``False`` means
        the exact same value was already present; any different binding for
        the workflow is rejected rather than overwritten.
        """
        self._validate_run_id(run_id)
        if not isinstance(ready, SchedulerCommitReady):
            raise RunJournalValidationError(
                "Scheduler commit-ready value is invalid."
            )
        mutex = self._writer_mutexes.get(run_id)
        if mutex is None:
            raise RunJournalOwnershipError("This process does not own the Run writer.")
        with mutex:
            run_dir = self._run_directory(run_id, must_exist=True)
            self._require_writer(run_id, run_dir)
            record, _ = self._read_run(run_id)
            if record is None:
                raise RunJournalNotFoundError("Run was not found.")
            if record.status in TERMINAL_STATUSES:
                raise RunJournalTransitionError(
                    "A terminal Run cannot accept scheduler commit-ready records."
                )
            try:
                return SchedulerAuditJournal(run_dir).write_commit_ready(ready)
            except SchedulerAuditValidationError as exc:
                raise RunJournalValidationError(
                    "Scheduler commit-ready value is invalid."
                ) from exc
            except SchedulerAuditStorageError as exc:
                raise RunJournalStorageError(
                    "Scheduler commit-ready storage is unavailable."
                ) from exc

    def get_scheduler_commit_ready(
        self,
        run_id: str,
        workflow_id: str,
    ) -> SchedulerCommitReady | None:
        """Read one exact scheduler COMMIT_READY authorization."""
        self._validate_run_id(run_id)
        record, _ = self._read_run(run_id)
        if record is None:
            raise RunJournalNotFoundError("Run was not found.")
        run_dir = self._run_directory(run_id, must_exist=True)
        try:
            return SchedulerAuditJournal(run_dir).get_commit_ready(workflow_id)
        except SchedulerAuditValidationError as exc:
            raise RunJournalValidationError("Workflow ID is invalid.") from exc
        except SchedulerAuditStorageError as exc:
            raise RunJournalStorageError(
                "Scheduler commit-ready storage is unavailable."
            ) from exc

    def record_scheduler_audit(
        self,
        run_id: str,
        audit: SchedulerAudit,
    ) -> None:
        """Seal one scheduler-owned audit while this process owns the Run.

        The audit is content-bearing and therefore lives in a dedicated
        sidecar instead of the parent event stream or sub-agent journal.
        """
        self._validate_run_id(run_id)
        if not isinstance(audit, SchedulerAudit):
            raise RunJournalValidationError("Scheduler audit value is invalid.")
        mutex = self._writer_mutexes.get(run_id)
        if mutex is None:
            raise RunJournalOwnershipError("This process does not own the Run writer.")
        with mutex:
            run_dir = self._run_directory(run_id, must_exist=True)
            self._require_writer(run_id, run_dir)
            record, _ = self._read_run(run_id)
            if record is None:
                raise RunJournalNotFoundError("Run was not found.")
            if record.status in TERMINAL_STATUSES:
                raise RunJournalTransitionError(
                    "A terminal Run cannot accept scheduler audits."
                )
            try:
                SchedulerAuditJournal(run_dir).write(audit)
            except SchedulerAuditValidationError as exc:
                raise RunJournalValidationError(
                    "Scheduler audit value is invalid."
                ) from exc
            except SchedulerAuditStorageError as exc:
                raise RunJournalStorageError(
                    "Scheduler audit storage is unavailable."
                ) from exc

    def get_scheduler_audit(
        self,
        run_id: str,
        workflow_id: str,
    ) -> SchedulerAudit | None:
        """Read one sealed scheduler audit, including canonical artifacts."""
        self._validate_run_id(run_id)
        record, _ = self._read_run(run_id)
        if record is None:
            raise RunJournalNotFoundError("Run was not found.")
        run_dir = self._run_directory(run_id, must_exist=True)
        try:
            return SchedulerAuditJournal(run_dir).get(workflow_id)
        except SchedulerAuditValidationError as exc:
            raise RunJournalValidationError("Workflow ID is invalid.") from exc
        except SchedulerAuditStorageError as exc:
            raise RunJournalStorageError(
                "Scheduler audit storage is unavailable."
            ) from exc

    def list_scheduler_audits(
        self,
        run_id: str,
    ) -> tuple[SchedulerAuditSummary, ...]:
        """List bounded, content-free summaries for sealed scheduler audits."""
        self._validate_run_id(run_id)
        record, _ = self._read_run(run_id)
        if record is None:
            raise RunJournalNotFoundError("Run was not found.")
        run_dir = self._run_directory(run_id, must_exist=True)
        try:
            return SchedulerAuditJournal(run_dir).list()
        except SchedulerAuditStorageError as exc:
            raise RunJournalStorageError(
                "Scheduler audit storage is unavailable."
            ) from exc

    def open_subagent_journal(self, run_id: str) -> SubagentRunJournal:
        """Open the bounded sidecar journal owned by one Run directory.

        The journal is intentionally outside the parent event stream: readers
        that require exactly one ``task.outcome`` per Run must not see nested
        loop lifecycle events. Retention removes it together with the Run.
        """
        self._validate_run_id(run_id)
        record, _ = self._read_run(run_id)
        if record is None:
            raise RunJournalNotFoundError("Run was not found.")
        run_dir = self._run_directory(run_id, must_exist=True)
        return SubagentRunJournal(run_dir)

    def list_subagent_runs(
        self, run_id: str
    ) -> tuple[SubagentRunSummary, ...]:
        """Read bounded sub-agent Run summaries for one parent Run."""
        return self.open_subagent_journal(run_id).list_runs()

    def list_subagent_events(self, run_id: str, subagent_id: str):
        """Read one sub-agent's bounded event stream."""
        return self.open_subagent_journal(run_id).list_events(subagent_id)

    def _terminal_coordination(
        self, run_id: str, run_dir: Path
    ) -> dict[str, int] | None:
        """Split one terminal Run's tokens: parent's own vs sub-agent totals.

        Parent model calls are the only ``model.completed`` events in this
        stream (sub-agents write to the sidecar journal), so their usage
        sums are exactly the parent's own coordination cost.  Sub-agent
        totals come from the sidecar's attributed finish records.  Best
        effort: any read failure simply omits the section.
        """
        try:
            events, _ = self._read_events(run_id)
            parent_input = 0
            parent_output = 0
            parent_seen = False
            for event in events:
                if event.type != "model.completed":
                    continue
                usage = event.payload.get("usage")
                if not isinstance(usage, dict):
                    continue
                input_tokens = usage.get("inputTokens")
                output_tokens = usage.get("outputTokens")
                if isinstance(input_tokens, int) and not isinstance(
                    input_tokens, bool
                ):
                    parent_input += max(0, input_tokens)
                    parent_seen = True
                if isinstance(output_tokens, int) and not isinstance(
                    output_tokens, bool
                ):
                    parent_output += max(0, output_tokens)
                    parent_seen = True
            subagent_input = 0
            subagent_output = 0
            subagent_seen = False
            for summary in SubagentRunJournal(run_dir).list_runs():
                if summary.input_tokens is None or summary.output_tokens is None:
                    continue
                subagent_input += summary.input_tokens
                subagent_output += summary.output_tokens
                subagent_seen = True
        except Exception:  # noqa: BLE001 - terminal telemetry is optional
            return None
        if not parent_seen and not subagent_seen:
            return None
        return {
            "parentInputTokens": parent_input,
            "parentOutputTokens": parent_output,
            "subagentInputTokens": subagent_input,
            "subagentOutputTokens": subagent_output,
        }

    def transition(
        self,
        run_id: str,
        status: str,
        *,
        reason: str | None = None,
        memory_provenance_gaps: tuple[str, ...] = (),
    ) -> RunRecord:
        """Apply a legal lifecycle transition; repeated terminal state is idempotent."""
        self._validate_run_id(run_id)
        if status not in RUN_STATUSES:
            raise RunJournalValidationError("Run status is invalid.")
        if (
            not isinstance(memory_provenance_gaps, tuple)
            or len(memory_provenance_gaps) > len(MEMORY_PROVENANCE_EFFECTS)
            or any(
                not isinstance(effect, str)
                or effect not in MEMORY_PROVENANCE_EFFECTS
                for effect in memory_provenance_gaps
            )
            or len(set(memory_provenance_gaps)) != len(memory_provenance_gaps)
        ):
            raise RunJournalValidationError(
                "Memory provenance terminal gaps are invalid."
            )
        if memory_provenance_gaps and status not in TERMINAL_STATUSES:
            raise RunJournalValidationError(
                "Memory provenance gaps require a terminal transition."
            )
        record, _ = self._read_run(run_id)
        if record is None:
            raise RunJournalNotFoundError("Run was not found.")
        if record.status == status and status in TERMINAL_STATUSES:
            return record
        if status not in _ALLOWED_TRANSITIONS.get(record.status, frozenset()):
            raise RunJournalTransitionError(
                f"Run cannot transition from {record.status} to {status}."
            )
        mutex = self._writer_mutexes.get(run_id)
        if mutex is None:
            raise RunJournalOwnershipError("This process does not own the Run writer.")
        with mutex:
            run_dir = self._run_directory(run_id, must_exist=True)
            self._require_writer(run_id, run_dir)
            current, _ = self._read_run(run_id)
            if current is None:
                raise RunJournalNotFoundError("Run was not found.")
            if current.status == status and status in TERMINAL_STATUSES:
                return current
            if status not in _ALLOWED_TRANSITIONS.get(current.status, frozenset()):
                raise RunJournalTransitionError(
                    f"Run cannot transition from {current.status} to {status}."
                )
            payload = {"summary": reason} if reason else None
            if status in TERMINAL_STATUSES:
                coordination = self._terminal_coordination(run_id, run_dir)
                if coordination is not None:
                    payload = {**(payload or {}), "coordination": coordination}
                if memory_provenance_gaps:
                    payload = {
                        **(payload or {}),
                        "memoryProvenanceGaps": list(
                            sorted(memory_provenance_gaps)
                        ),
                    }
            event = self._new_event(
                current,
                LIFECYCLE_EVENT_FOR_STATUS[status],
                sequence=current.last_sequence + 1,
                payload=payload,
            )
            # Event first, then an atomic metadata checkpoint.  If checkpointing
            # fails, readers still recover the transition from the durable event.
            self._append_event_line(run_dir, event)
            checkpoint = replace(
                current,
                status=status,
                started_at=(
                    event.timestamp if status == "running" else current.started_at
                ),
                completed_at=(
                    event.timestamp
                    if status in TERMINAL_STATUSES
                    else current.completed_at
                ),
                updated_at=event.timestamp,
                last_sequence=event.sequence,
                event_count=current.event_count + 1,
                error_count=current.error_count + int(status == "failed"),
            )
            self._write_metadata(run_dir, checkpoint)
            if status in TERMINAL_STATUSES:
                self._release_writer(run_id, run_dir)
            self._refresh_index_best_effort()
            return checkpoint

    def list_events(
        self,
        run_id: str,
        *,
        limit: int | str | None = None,
        cursor: str | None = None,
    ) -> EventPage:
        self._validate_run_id(run_id)
        page_limit = self._page_limit(limit, default=_DEFAULT_EVENT_LIMIT)
        record, _ = self._read_run(run_id)
        if record is None:
            raise RunJournalNotFoundError("Run was not found.")
        events, event_diagnostics = self._read_events(run_id)
        after_sequence = 0
        if cursor not in (None, ""):
            try:
                values = self._decode_cursor("run_events", cursor)
                if (
                    len(values) != 2
                    or values[0] != run_id
                    or isinstance(values[1], bool)
                    or not isinstance(values[1], int)
                    or values[1] < 0
                ):
                    raise ValueError("invalid event cursor")
                after_sequence = values[1]
            except ValueError as exc:
                raise RunJournalValidationError("Cursor is invalid.") from exc
        remaining = [event for event in events if event.sequence > after_sequence]
        items = remaining[:page_limit]
        has_more = len(remaining) > page_limit
        diagnostics = tuple(event_diagnostics[:_MAX_DIAGNOSTICS])
        return EventPage(
            items=tuple(items),
            limit=page_limit,
            has_more=has_more,
            next_cursor=(
                self._encode_cursor("run_events", [run_id, items[-1].sequence])
                if has_more and items
                else None
            ),
            diagnostics=diagnostics,
        )

    def enforce_retention(self, *, now: datetime | None = None) -> RetentionResult:
        """Explicitly remove eligible terminal Runs under configured bounds."""
        if not self._runs_root.exists():
            return RetentionResult(deleted_count=0)
        reference = now if now is not None else self._clock()
        if not isinstance(reference, datetime):
            raise RunJournalValidationError("Retention time is invalid.")
        if reference.tzinfo is None:
            reference = reference.replace(tzinfo=timezone.utc)
        reference = reference.astimezone(timezone.utc)
        diagnostics: list[dict[str, str]] = []
        candidates: list[tuple[RunRecord, Path, int]] = []
        try:
            root = self._runs_root.resolve(strict=True)
            if self._runs_root.is_symlink() or not root.is_relative_to(self._data_root):
                raise OSError("unsafe retention root")
            entries, entries_limited = self._bounded_run_entries(root)
        except Exception:
            return RetentionResult(
                deleted_count=0,
                diagnostics=(
                    self._diagnostic(
                        "retention_root_unsafe", "Run retention storage is unsafe."
                    ),
                ),
            )

        if entries_limited:
            diagnostics.append(
                self._diagnostic(
                    "retention_scan_limited",
                    "Run retention reached the configured scan limit.",
                )
            )
        for entry in entries:
            if not _RUN_ID_RE.fullmatch(entry.name):
                continue
            if entry.is_symlink():
                diagnostics.append(
                    self._diagnostic(
                        "retention_path_unsafe",
                        "A Run retention path was rejected.",
                    )
                )
                continue
            record, _ = self._read_run(entry.name)
            if record is None:
                continue
            try:
                size = self._directory_size(entry)
            except OSError:
                diagnostics.append(
                    self._diagnostic(
                        "retention_path_unsafe",
                        "A Run retention path was rejected.",
                    )
                )
                continue
            candidates.append((record, entry, size))

        terminal_candidates: list[tuple[RunRecord, Path, int]] = []
        for item in candidates:
            record, directory, _size = item
            if record.status not in TERMINAL_STATUSES:
                continue
            if record.source in _CURATOR_RECEIPT_SOURCES:
                try:
                    receipt = self._read_curator_receipt(directory)
                except RunJournalStorageError:
                    diagnostics.append(
                        self._diagnostic(
                            "curator_receipt_invalid",
                            "A pending curator receipt could not be verified.",
                        )
                    )
                    # Fail closed: retention must not destroy a potentially
                    # undelivered durable completion obligation.
                    continue
                if (
                    receipt is None
                    and record.curator_outbox_version is not None
                ):
                    diagnostics.append(
                        self._diagnostic(
                            "curator_receipt_missing",
                            "An expected curator receipt is missing.",
                        )
                    )
                    continue
                if (
                    receipt is not None
                    and receipt[0] != curator_completion_id(record.id)
                ):
                    diagnostics.append(
                        self._diagnostic(
                            "curator_receipt_invalid",
                            "A pending curator receipt has the wrong identity.",
                        )
                    )
                    continue
                if (
                    receipt is not None
                    and (
                        receipt[1] in {"pending", "delivering"}
                        or (receipt[1] == "recorded" and receipt[3] == 3)
                    )
                ):
                    continue
            terminal_candidates.append(item)
        terminal = sorted(
            terminal_candidates,
            key=lambda item: (
                _parse_time(item[0].completed_at or item[0].updated_at),
                item[0].id,
            ),
        )
        selected: dict[str, tuple[RunRecord, Path, int]] = {}
        if self.terminal_max_age is not None:
            cutoff = reference - self.terminal_max_age
            for item in terminal:
                if _parse_time(item[0].completed_at or item[0].updated_at) < cutoff:
                    selected[item[0].id] = item

        remaining_count = len(candidates) - len(selected)
        if remaining_count > self.max_runs:
            for item in terminal:
                if remaining_count <= self.max_runs:
                    break
                if item[0].id not in selected:
                    selected[item[0].id] = item
                    remaining_count -= 1

        if self.max_total_bytes is not None:
            remaining_bytes = sum(item[2] for item in candidates) - sum(
                item[2] for item in selected.values()
            )
            if remaining_bytes > self.max_total_bytes:
                for item in terminal:
                    if remaining_bytes <= self.max_total_bytes:
                        break
                    if item[0].id not in selected:
                        selected[item[0].id] = item
                        remaining_bytes -= item[2]

        deleted = 0
        for record, directory, _ in sorted(
            selected.values(),
            key=lambda item: (
                _parse_time(item[0].completed_at or item[0].updated_at),
                item[0].id,
            ),
        ):
            mutation_lock_acquired = False
            try:
                self._acquire_run_mutation_lock(directory)
                mutation_lock_acquired = True
                self._validate_retention_directory(record.id, directory, root)
                shutil.rmtree(directory)
                deleted += 1
            except Exception:
                diagnostics.append(
                    self._diagnostic(
                        "retention_delete_failed",
                        "An eligible Run could not be removed.",
                    )
                )
            finally:
                if mutation_lock_acquired and directory.exists():
                    self._release_run_mutation_lock(directory)
        if deleted:
            self._refresh_index_best_effort()
        return RetentionResult(
            deleted_count=deleted,
            diagnostics=tuple(diagnostics[:_MAX_DIAGNOSTICS]),
        )

    def enforce_retention_if_due(self) -> RetentionResult:
        """Bound production Run growth without scanning every payload each Run.

        Directory names are checked on every terminal lifecycle, while the
        more expensive byte/age scan runs every eight Runs or whenever the
        configured count bound (plus a small bounded margin) is crossed.
        """

        if not self._runs_root.exists():
            return RetentionResult(deleted_count=0)
        try:
            root = self._runs_root.resolve(strict=True)
            if self._runs_root.is_symlink() or not root.is_relative_to(
                self._data_root
            ):
                raise OSError("unsafe retention root")
            entries, limited = self._bounded_run_entries(root)
        except Exception:
            return self.enforce_retention()
        count = len(entries)
        count_margin = min(7, max(0, self.max_runs // 10))
        if (
            limited
            or count > self.max_runs + count_margin
            or (count > 0 and count % 8 == 0)
        ):
            return self.enforce_retention()
        return RetentionResult(deleted_count=0)

    def _ensure_storage_root(self) -> None:
        self._data_root.mkdir(parents=True, exist_ok=True, mode=0o700)
        current = self._data_root.resolve(strict=True)
        if current != self._data_root or not current.is_dir():
            raise RunJournalStorageError("RunJournal storage root is unsafe.")
        for name in ("dashboard", "workspaces", self.workspace_id, "runs"):
            target = current / name
            if target.is_symlink():
                raise RunJournalStorageError("RunJournal storage root is unsafe.")
            try:
                target.mkdir(mode=0o700, exist_ok=True)
            except OSError as exc:
                raise RunJournalStorageError(
                    "RunJournal storage root is unsafe."
                ) from exc
            resolved = target.resolve(strict=True)
            if (
                resolved.parent != current
                or not resolved.is_relative_to(self._data_root)
                or not resolved.is_dir()
            ):
                raise RunJournalStorageError("RunJournal storage root is unsafe.")
            current = resolved

    @staticmethod
    def _directory_size(directory: Path) -> int:
        if directory.is_symlink():
            raise OSError("symlinked Run directory")
        total = 0
        for root, directory_names, filenames in os.walk(directory, followlinks=False):
            root_path = Path(root)
            directory_names[:] = [
                name for name in directory_names if not (root_path / name).is_symlink()
            ]
            for filename in filenames:
                path = root_path / filename
                if path.is_symlink():
                    continue
                total += path.stat().st_size
        return total

    @staticmethod
    def _bounded_run_entries(root: Path) -> tuple[list[Path], bool]:
        entries: list[Path] = []
        limited = False
        for entry in root.iterdir():
            if not _RUN_ID_RE.fullmatch(entry.name):
                continue
            if len(entries) >= _MAX_RUNS_SCANNED:
                limited = True
                break
            entries.append(entry)
        entries.sort(key=lambda item: item.name)
        return entries, limited

    @staticmethod
    def _validate_retention_directory(run_id: str, directory: Path, root: Path) -> None:
        if (
            not _RUN_ID_RE.fullmatch(run_id)
            or directory.name != run_id
            or directory.parent != root
            or directory.is_symlink()
        ):
            raise OSError("unsafe retention path")
        resolved = directory.resolve(strict=True)
        if not resolved.is_relative_to(root) or not resolved.is_dir():
            raise OSError("unsafe retention path")

    def _run_directory(self, run_id: str, *, must_exist: bool) -> Path:
        candidate = self._runs_root / run_id
        if not must_exist:
            return candidate
        if not self._runs_root.exists() or self._runs_root.is_symlink():
            raise RunJournalStorageError("RunJournal storage root is unsafe.")
        root = self._runs_root.resolve(strict=True)
        if candidate.is_symlink():
            raise RunJournalStorageError("Run directory is unsafe.")
        resolved = candidate.resolve(strict=True)
        if not resolved.is_relative_to(root) or not resolved.is_dir():
            raise RunJournalStorageError("Run directory is unsafe.")
        return resolved

    def _create_writer_lock(self, run_dir: Path, token: str) -> None:
        path = run_dir / ".writer.lock"
        flags = os.O_WRONLY | os.O_CREAT | os.O_EXCL
        if hasattr(os, "O_NOFOLLOW"):
            flags |= os.O_NOFOLLOW
        fd = os.open(path, flags, 0o600)
        try:
            payload = json.dumps(
                {
                    "schemaVersion": SCHEMA_VERSION,
                    "writerId": token,
                    "pid": os.getpid(),
                    "createdAt": _iso_time(self._clock()),
                },
                separators=(",", ":"),
            ).encode("utf-8")
            if os.write(fd, payload) != len(payload):
                raise OSError("short writer lock write")
            os.fsync(fd)
        finally:
            os.close(fd)

    def _require_writer(self, run_id: str, run_dir: Path) -> None:
        owner = self._writers.get(run_id)
        if owner is None or owner[1] != os.getpid():
            raise RunJournalOwnershipError("This process does not own the Run writer.")
        path = run_dir / ".writer.lock"
        try:
            if path.is_symlink() or path.stat().st_size > _MAX_METADATA_BYTES:
                raise OSError("unsafe writer lock")
            parsed = json.loads(path.read_text(encoding="utf-8"))
        except Exception as exc:
            raise RunJournalOwnershipError("Run writer ownership could not be verified.") from exc
        if (
            not isinstance(parsed, dict)
            or parsed.get("writerId") != owner[0]
            or parsed.get("pid") != os.getpid()
        ):
            raise RunJournalOwnershipError("This process does not own the Run writer.")

    def _release_writer(self, run_id: str, run_dir: Path) -> None:
        self._require_writer(run_id, run_dir)
        try:
            (run_dir / ".writer.lock").unlink()
            self._fsync_directory(run_dir)
        finally:
            self._writers.pop(run_id, None)
            self._writer_mutexes.pop(run_id, None)

    def _new_event(
        self,
        record: RunRecord,
        event_type: str,
        *,
        sequence: int,
        timestamp: str | None = None,
        step: int | None = None,
        payload: Mapping[str, Any] | None = None,
    ) -> RunEvent:
        if event_type not in EVENT_TYPES:
            raise RunJournalValidationError("Event type is invalid.")
        if isinstance(sequence, bool) or not isinstance(sequence, int) or sequence < 1:
            raise RunJournalValidationError("Event sequence is invalid.")
        if step is not None and (
            isinstance(step, bool)
            or not isinstance(step, int)
            or step < 0
            or step > 1_000_000
        ):
            raise RunJournalValidationError("Event step is invalid.")
        return RunEvent(
            schema_version=SCHEMA_VERSION,
            event_id=f"evt_{uuid.uuid4().hex}",
            sequence=sequence,
            timestamp=timestamp or _iso_time(self._clock()),
            workspace_id=record.workspace_id,
            session_id=record.session_id,
            run_id=record.id,
            type=event_type,
            step=step,
            payload=_sanitize_event_payload(event_type, payload),
        )

    def _append_event_line(self, run_dir: Path, event: RunEvent) -> None:
        encoded = (
            json.dumps(
                event.to_dict(),
                ensure_ascii=False,
                allow_nan=False,
                separators=(",", ":"),
            )
            + "\n"
        ).encode("utf-8")
        if len(encoded) > _MAX_EVENT_BYTES:
            raise RunJournalValidationError("Event exceeds the byte limit.")
        path = run_dir / "events.ndjson"
        if path.exists():
            if path.is_symlink() or path.stat().st_size + len(encoded) > _MAX_RUN_EVENT_FILE_BYTES:
                raise RunJournalStorageError("Run event storage limit was reached.")
            if path.stat().st_size:
                with path.open("rb") as handle:
                    handle.seek(-1, os.SEEK_END)
                    if handle.read(1) != b"\n":
                        raise RunJournalStorageError(
                            "Run event file has an incomplete final record."
                        )
        flags = os.O_WRONLY | os.O_CREAT | os.O_APPEND
        if hasattr(os, "O_NOFOLLOW"):
            flags |= os.O_NOFOLLOW
        fd = os.open(path, flags, 0o600)
        try:
            if os.write(fd, encoded) != len(encoded):
                raise OSError("short event write")
            os.fsync(fd)
        finally:
            os.close(fd)

    def _write_metadata(self, run_dir: Path, record: RunRecord) -> None:
        encoded = (
            json.dumps(
                record.to_dict(),
                ensure_ascii=False,
                allow_nan=False,
                sort_keys=True,
                indent=2,
            )
            + "\n"
        ).encode("utf-8")
        if len(encoded) > _MAX_METADATA_BYTES:
            raise RunJournalStorageError("Run metadata exceeds the byte limit.")
        fd, temporary = tempfile.mkstemp(prefix=".metadata-", suffix=".tmp", dir=run_dir)
        try:
            with os.fdopen(fd, "wb") as handle:
                handle.write(encoded)
                handle.flush()
                os.fsync(handle.fileno())
            os.replace(temporary, run_dir / "metadata.json")
            self._fsync_directory(run_dir)
        except Exception:
            try:
                os.unlink(temporary)
            except FileNotFoundError:
                pass
            raise

    def _write_user_signal(
        self,
        run_dir: Path,
        record: RunUserSignal,
    ) -> None:
        encoded = (
            json.dumps(
                record.to_dict(),
                ensure_ascii=False,
                allow_nan=False,
                sort_keys=True,
                separators=(",", ":"),
            )
            + "\n"
        ).encode("utf-8")
        if len(encoded) > _MAX_USER_SIGNAL_BYTES:
            raise RunJournalStorageError("User signal exceeds the byte limit.")
        fd, temporary = tempfile.mkstemp(
            prefix=".user-signal-",
            suffix=".tmp",
            dir=run_dir,
        )
        target = run_dir / _USER_SIGNAL_FILE
        try:
            with os.fdopen(fd, "wb") as handle:
                if _platform_name() == "posix":
                    os.fchmod(handle.fileno(), 0o600)
                handle.write(encoded)
                handle.flush()
                os.fsync(handle.fileno())
            os.link(temporary, target, follow_symlinks=False)
            os.unlink(temporary)
            self._fsync_directory(run_dir)
        except FileExistsError as error:
            try:
                os.unlink(temporary)
            except FileNotFoundError:
                pass
            raise RunJournalStorageError(
                "User signal storage changed during write."
            ) from error
        except OSError as error:
            try:
                os.unlink(temporary)
            except FileNotFoundError:
                pass
            raise RunJournalStorageError(
                "User signal storage is unavailable."
            ) from error

    @staticmethod
    def _acquire_run_mutation_lock(run_dir: Path) -> None:
        try:
            (run_dir / _USER_SIGNAL_LOCK).mkdir(mode=0o700)
        except FileExistsError as error:
            raise RunJournalStorageError(
                "Run mutation storage is busy."
            ) from error
        except OSError as error:
            raise RunJournalStorageError(
                "Run mutation storage is unavailable."
            ) from error

    @staticmethod
    def _release_run_mutation_lock(run_dir: Path) -> None:
        try:
            (run_dir / _USER_SIGNAL_LOCK).rmdir()
        except OSError:
            pass

    def _read_user_signal(self, run_dir: Path) -> RunUserSignal | None:
        path = run_dir / _USER_SIGNAL_FILE
        try:
            before = os.lstat(path)
        except FileNotFoundError:
            return None
        except OSError as error:
            raise RunJournalStorageError(
                "User signal storage is unavailable."
            ) from error
        if (
            stat.S_ISLNK(before.st_mode)
            or not stat.S_ISREG(before.st_mode)
            or before.st_size <= 0
            or before.st_size > _MAX_USER_SIGNAL_BYTES
        ):
            raise RunJournalStorageError("User signal storage is unsafe.")
        flags = os.O_RDONLY
        if hasattr(os, "O_NOFOLLOW"):
            flags |= os.O_NOFOLLOW
        try:
            fd = os.open(path, flags)
            try:
                after = os.fstat(fd)
                if (
                    after.st_dev != before.st_dev
                    or after.st_ino != before.st_ino
                    or not stat.S_ISREG(after.st_mode)
                    or after.st_size != before.st_size
                ):
                    raise OSError("user signal changed during read")
                raw = os.read(fd, _MAX_USER_SIGNAL_BYTES + 1)
            finally:
                os.close(fd)
            if len(raw) != before.st_size:
                raise OSError("short user signal read")
            return RunUserSignal.from_dict(json.loads(raw.decode("utf-8")))
        except (OSError, UnicodeDecodeError, json.JSONDecodeError, ValueError) as error:
            raise RunJournalStorageError(
                "User signal storage is unsafe."
            ) from error

    def _write_curator_receipt(
        self,
        run_dir: Path,
        *,
        completion_id: str,
        state: str,
        prepared_at_ms: int,
    ) -> None:
        if (
            not isinstance(completion_id, str)
            or re.fullmatch(r"[0-9a-f]{64}", completion_id) is None
            or state not in _CURATOR_RECEIPT_STATES
            or isinstance(prepared_at_ms, bool)
            or not isinstance(prepared_at_ms, int)
            or not 0 <= prepared_at_ms <= 99_999_999_999_999
            or (state == "inactive" and prepared_at_ms != 0)
            or (state != "inactive" and prepared_at_ms == 0)
        ):
            raise RunJournalValidationError(
                "Curator completion receipt is invalid."
            )
        encoded = (
            json.dumps(
                {
                    "schemaVersion": _CURATOR_OUTBOX_VERSION,
                    "completionId": completion_id,
                    "state": state,
                    "preparedAtMs": prepared_at_ms,
                },
                sort_keys=True,
                separators=(",", ":"),
            )
            + "\n"
        ).encode("utf-8")
        if len(encoded) > _MAX_CURATOR_RECEIPT_BYTES:
            raise RunJournalStorageError(
                "Curator completion receipt exceeds the byte limit."
            )
        target = run_dir / _CURATOR_RECEIPT_FILE
        try:
            existing = os.lstat(target)
        except FileNotFoundError:
            existing = None
        except OSError as error:
            raise RunJournalStorageError(
                "Curator completion receipt is unavailable."
            ) from error
        if existing is not None and (
            stat.S_ISLNK(existing.st_mode)
            or not stat.S_ISREG(existing.st_mode)
        ):
            raise RunJournalStorageError(
                "Curator completion receipt is unsafe."
            )
        fd, temporary = tempfile.mkstemp(
            prefix=".curator-receipt-",
            suffix=".tmp",
            dir=run_dir,
        )
        try:
            with os.fdopen(fd, "wb") as handle:
                if _platform_name() == "posix":
                    os.fchmod(handle.fileno(), 0o600)
                handle.write(encoded)
                handle.flush()
                os.fsync(handle.fileno())
            os.replace(temporary, target)
            self._fsync_directory(run_dir)
        except OSError as error:
            try:
                os.unlink(temporary)
            except FileNotFoundError:
                pass
            raise RunJournalStorageError(
                "Curator completion receipt is unavailable."
            ) from error

    def _read_curator_receipt(
        self,
        run_dir: Path,
    ) -> tuple[str, str, int, int] | None:
        path = run_dir / _CURATOR_RECEIPT_FILE
        try:
            before = os.lstat(path)
        except FileNotFoundError:
            return None
        except OSError as error:
            raise RunJournalStorageError(
                "Curator completion receipt is unavailable."
            ) from error
        if (
            stat.S_ISLNK(before.st_mode)
            or not stat.S_ISREG(before.st_mode)
            or before.st_size <= 0
            or before.st_size > _MAX_CURATOR_RECEIPT_BYTES
        ):
            raise RunJournalStorageError(
                "Curator completion receipt is unsafe."
            )
        flags = os.O_RDONLY | getattr(os, "O_CLOEXEC", 0)
        flags |= getattr(os, "O_NOFOLLOW", 0)
        try:
            descriptor = os.open(path, flags)
            try:
                after = os.fstat(descriptor)
                if (
                    not stat.S_ISREG(after.st_mode)
                    or after.st_dev != before.st_dev
                    or after.st_ino != before.st_ino
                    or after.st_size != before.st_size
                ):
                    raise OSError("curator receipt changed during read")
                raw = os.read(descriptor, _MAX_CURATOR_RECEIPT_BYTES + 1)
            finally:
                os.close(descriptor)
            if len(raw) != before.st_size:
                raise OSError("short curator receipt read")
            payload = json.loads(raw.decode("utf-8"))
        except (OSError, UnicodeDecodeError, json.JSONDecodeError) as error:
            raise RunJournalStorageError(
                "Curator completion receipt is unsafe."
            ) from error
        if not isinstance(payload, dict):
            raise RunJournalStorageError(
                "Curator completion receipt is unsafe."
            )
        completion_id = payload.get("completionId")
        state = payload.get("state")
        schema_version = payload.get("schemaVersion")
        prepared_at_ms = payload.get("preparedAtMs", 0)
        expected_fields = (
            {"schemaVersion", "completionId", "state"}
            if schema_version == 1
            else {
                "schemaVersion",
                "completionId",
                "state",
                "preparedAtMs",
            }
        )
        if (
            isinstance(schema_version, bool)
            or schema_version not in _READABLE_CURATOR_RECEIPT_VERSIONS
            or set(payload) != expected_fields
            or not isinstance(completion_id, str)
            or re.fullmatch(r"[0-9a-f]{64}", completion_id) is None
            or state not in _CURATOR_RECEIPT_STATES
            or (schema_version == 1 and state == "delivering")
            or (schema_version in {1, 2} and state == "settled")
            or isinstance(prepared_at_ms, bool)
            or not isinstance(prepared_at_ms, int)
            or not 0 <= prepared_at_ms <= 99_999_999_999_999
            or (
                schema_version in {2, _CURATOR_OUTBOX_VERSION}
                and (
                    (state == "inactive" and prepared_at_ms != 0)
                    or (state != "inactive" and prepared_at_ms == 0)
                )
            )
        ):
            raise RunJournalStorageError(
                "Curator completion receipt is unsafe."
            )
        return completion_id, state, prepared_at_ms, schema_version

    def _acknowledge_curator_receipt_locked(
        self,
        run_dir: Path,
        completion_id: str,
    ) -> bool:
        receipt = self._read_curator_receipt(run_dir)
        if receipt is None or receipt[0] != completion_id:
            return False
        if receipt[1] in {"inactive", "pending"}:
            return False
        if receipt[1] in {"recorded", "settled"}:
            return True
        self._write_curator_receipt(
            run_dir,
            completion_id=completion_id,
            state="recorded",
            prepared_at_ms=receipt[2] or _datetime_ms(self._clock()),
        )
        return True

    def _begin_curator_receipt_delivery_locked(
        self,
        run_dir: Path,
        completion_id: str,
    ) -> bool:
        receipt = self._read_curator_receipt(run_dir)
        if receipt is None or receipt[0] != completion_id:
            return False
        if receipt[1] == "inactive":
            return False
        if receipt[1] == "settled" or (
            receipt[1] == "recorded" and receipt[3] < 3
        ):
            return False
        if receipt[1] in {"delivering", "recorded"}:
            return True
        self._write_curator_receipt(
            run_dir,
            completion_id=completion_id,
            state="delivering",
            prepared_at_ms=receipt[2] or _datetime_ms(self._clock()),
        )
        return True

    def _settle_curator_receipt_locked(
        self,
        run_dir: Path,
        completion_id: str,
    ) -> bool:
        receipt = self._read_curator_receipt(run_dir)
        if receipt is None or receipt[0] != completion_id:
            return False
        if receipt[1] == "settled":
            return True
        if receipt[1] != "recorded":
            return False
        self._write_curator_receipt(
            run_dir,
            completion_id=completion_id,
            state="settled",
            prepared_at_ms=receipt[2] or _datetime_ms(self._clock()),
        )
        return True

    def _write_memory_id_sidecar(
        self,
        run_dir: Path,
        entry_ids: tuple[str, ...],
        *,
        filename: str,
        label: str,
    ) -> None:
        encoded = (
            json.dumps(
                {"schemaVersion": SCHEMA_VERSION, "entryIds": list(entry_ids)},
                ensure_ascii=False,
                allow_nan=False,
                sort_keys=True,
                separators=(",", ":"),
            )
            + "\n"
        ).encode("utf-8")
        if len(encoded) > _MAX_RENDERED_MEMORY_BYTES:
            raise RunJournalStorageError(f"{label} Memory IDs exceed the byte limit.")
        fd, temporary = tempfile.mkstemp(
            prefix=f".memory-{filename}-",
            suffix=".tmp",
            dir=run_dir,
        )
        target = run_dir / filename
        try:
            with os.fdopen(fd, "wb") as handle:
                if _platform_name() == "posix":
                    os.fchmod(handle.fileno(), 0o600)
                handle.write(encoded)
                handle.flush()
                os.fsync(handle.fileno())
            os.link(temporary, target, follow_symlinks=False)
            os.unlink(temporary)
            self._fsync_directory(run_dir)
        except FileExistsError:
            try:
                os.unlink(temporary)
            except FileNotFoundError:
                pass
            # Only one retrieval happens per turn, so a second write attempt
            # is tolerated only when the existing target is a safe file with
            # identical content; anything else (a symlink, a mismatch) is a
            # genuine storage problem, not a benign retry.
            if self._read_memory_id_sidecar(run_dir, filename, label) != entry_ids:
                raise RunJournalStorageError(
                    f"{label} Memory ID storage changed during write."
                )
        except OSError as error:
            try:
                os.unlink(temporary)
            except FileNotFoundError:
                pass
            raise RunJournalStorageError(
                f"{label} Memory ID storage is unavailable."
            ) from error

    def _write_memory_version_sidecar(
        self,
        run_dir: Path,
        sidecar: _MemoryVersionSidecar,
        filename: str,
        label: str,
    ) -> None:
        if (
            sidecar.schema_version != _MEMORY_MATERIALIZATION_SIDECAR_VERSION
            or sidecar.effect != label.lower()
            or sidecar.coverage not in MEMORY_PROVENANCE_COVERAGE
            or len(sidecar.materializations)
            > _MAX_MEMORY_MATERIALIZATIONS_PER_RUN
            or len(sidecar.records) > MAX_MEMORY_PROVENANCE_BATCHES
        ):
            raise RunJournalStorageError(
                f"{label} Memory versions cannot be encoded safely."
            )
        encoded = (
            json.dumps(
                {
                    "schemaVersion": sidecar.schema_version,
                    "digestSchema": _MEMORY_AUTHORITY_DIGEST_SCHEMA,
                    "kind": sidecar.effect,
                    "coverage": sidecar.coverage,
                    "materializations": [
                        {
                            "entryId": entry_id,
                            "authorityDigest": digest,
                        }
                        for entry_id, digest in sidecar.materializations
                    ],
                    "provenance": [
                        _memory_provenance_record_to_dict(record)
                        for record in sidecar.records
                    ],
                },
                ensure_ascii=False,
                allow_nan=False,
                sort_keys=True,
                separators=(",", ":"),
            )
            + "\n"
        ).encode("utf-8")
        if len(encoded) > _MAX_RENDERED_MEMORY_VERSION_BYTES:
            raise RunJournalStorageError(
                f"{label} Memory versions exceed the byte limit."
            )
        fd, temporary = tempfile.mkstemp(
            prefix=f".memory-{label.lower()}-versions-",
            suffix=".tmp",
            dir=run_dir,
        )
        target = run_dir / filename
        try:
            with os.fdopen(fd, "wb") as handle:
                if _platform_name() == "posix":
                    os.fchmod(handle.fileno(), 0o600)
                handle.write(encoded)
                handle.flush()
                os.fsync(handle.fileno())
            os.replace(temporary, target)
            self._fsync_directory(run_dir)
        except OSError as error:
            try:
                os.unlink(temporary)
            except FileNotFoundError:
                pass
            raise RunJournalStorageError(
                f"{label} Memory version storage is unavailable."
            ) from error

    def _read_memory_version_sidecar(
        self,
        run_dir: Path,
        filename: str,
        label: str,
    ) -> _MemoryVersionSidecar | None:
        path = run_dir / filename
        try:
            before = os.lstat(path)
        except FileNotFoundError:
            return None
        except OSError as error:
            raise RunJournalStorageError(
                f"{label} Memory version storage is unavailable."
            ) from error
        if (
            stat.S_ISLNK(before.st_mode)
            or not stat.S_ISREG(before.st_mode)
            or before.st_size <= 0
            or before.st_size > _MAX_RENDERED_MEMORY_VERSION_BYTES
        ):
            raise RunJournalStorageError(
                f"{label} Memory version storage is unsafe."
            )
        flags = os.O_RDONLY
        if hasattr(os, "O_NOFOLLOW"):
            flags |= os.O_NOFOLLOW
        try:
            fd = os.open(path, flags)
            try:
                after = os.fstat(fd)
                if (
                    after.st_dev != before.st_dev
                    or after.st_ino != before.st_ino
                    or not stat.S_ISREG(after.st_mode)
                    or after.st_size != before.st_size
                ):
                    raise OSError(
                        "rendered Memory versions changed during read"
                    )
                raw = os.read(fd, _MAX_RENDERED_MEMORY_VERSION_BYTES + 1)
            finally:
                os.close(fd)
            if len(raw) != before.st_size:
                raise OSError("short rendered Memory version read")
            decoded = json.loads(raw.decode("utf-8"))
        except (OSError, UnicodeDecodeError, json.JSONDecodeError) as error:
            raise RunJournalStorageError(
                f"{label} Memory version storage is unsafe."
            ) from error
        if not isinstance(decoded, dict):
            raise RunJournalStorageError(
                f"{label} Memory version storage is unsafe."
            )
        schema_version = decoded.get("schemaVersion")
        if isinstance(schema_version, bool) or not isinstance(
            schema_version,
            int,
        ):
            raise RunJournalStorageError(
                f"{label} Memory version storage is unsafe."
            )
        if schema_version == _LEGACY_MEMORY_MATERIALIZATION_SIDECAR_VERSION:
            expected_fields = {
                "schemaVersion",
                "digestSchema",
                "kind",
                "materializations",
            }
        elif schema_version == _MEMORY_MATERIALIZATION_SIDECAR_VERSION:
            expected_fields = {
                "schemaVersion",
                "digestSchema",
                "kind",
                "coverage",
                "materializations",
                "provenance",
            }
        else:
            raise RunJournalStorageError(
                f"{label} Memory version storage is unsafe."
            )
        if (
            set(decoded) != expected_fields
            or decoded.get("digestSchema")
            != _MEMORY_AUTHORITY_DIGEST_SCHEMA
            or decoded.get("kind") != label.lower()
            or not isinstance(decoded.get("materializations"), list)
        ):
            raise RunJournalStorageError(
                f"{label} Memory version storage is unsafe."
            )
        versions: list[tuple[str, str]] = []
        for materialization in decoded["materializations"]:
            if (
                not isinstance(materialization, dict)
                or set(materialization) != {"entryId", "authorityDigest"}
            ):
                raise RunJournalStorageError(
                    f"{label} Memory version storage is unsafe."
                )
            versions.append(
                (
                    materialization.get("entryId"),
                    materialization.get("authorityDigest"),
                )
            )
        try:
            normalized = _normalize_rendered_memory_versions(
                versions,
                max_versions=(
                    _MAX_RENDERED_MEMORY_VERSIONS
                    if schema_version
                    == _LEGACY_MEMORY_MATERIALIZATION_SIDECAR_VERSION
                    else _MAX_MEMORY_MATERIALIZATIONS_PER_RUN
                ),
            )
            if (
                schema_version == _MEMORY_MATERIALIZATION_SIDECAR_VERSION
                and len(normalized) != len(versions)
            ):
                raise ValueError("duplicate Memory materialization")
            if schema_version == _LEGACY_MEMORY_MATERIALIZATION_SIDECAR_VERSION:
                return _MemoryVersionSidecar(
                    schema_version=schema_version,
                    effect=label.lower(),
                    materializations=normalized,
                    records=(),
                    coverage="partial",
                )

            coverage = decoded.get("coverage")
            raw_records = decoded.get("provenance")
            if (
                not isinstance(coverage, str)
                or coverage not in MEMORY_PROVENANCE_COVERAGE
                or not isinstance(raw_records, list)
                or len(raw_records) > MAX_MEMORY_PROVENANCE_BATCHES
            ):
                raise ValueError("invalid Memory provenance envelope")
            records = tuple(
                _memory_provenance_record_from_dict(value)
                for value in raw_records
            )
            materialization_set = set(normalized)
            seen_records: set[RunMemoryProvenanceRecord] = set()
            for index, record in enumerate(records):
                if (
                    record.batch.effect != label.lower()
                    or not set(record.batch.authority_versions).issubset(
                        materialization_set
                    )
                    or record in seen_records
                ):
                    raise ValueError("invalid Memory provenance projection")
                for prior in records[:index]:
                    if (
                        prior.actor == record.actor
                        and prior.batch != record.batch
                        and _memory_provenance_identity_overlaps(
                            prior.batch,
                            record.batch,
                        )
                    ):
                        raise ValueError("conflicting Memory provenance identity")
                seen_records.add(record)
            if coverage == "unknown" and normalized:
                raise ValueError("unknown Memory provenance has materializations")
            if coverage == "complete":
                covered = {
                    version
                    for record in records
                    if record.batch.coverage == "complete"
                    for version in record.batch.authority_versions
                }
                if (
                    not records
                    or any(
                        record.batch.coverage != "complete"
                        for record in records
                    )
                    or covered != materialization_set
                ):
                    raise ValueError("incomplete Memory provenance projection")
            return _MemoryVersionSidecar(
                schema_version=schema_version,
                effect=label.lower(),
                materializations=normalized,
                records=records,
                coverage=coverage,
            )
        except (RunJournalValidationError, TypeError, ValueError) as error:
            raise RunJournalStorageError(
                f"{label} Memory version storage is unsafe."
            ) from error

    def _read_memory_id_sidecar(
        self, run_dir: Path, filename: str, label: str
    ) -> tuple[str, ...] | None:
        path = run_dir / filename
        try:
            before = os.lstat(path)
        except FileNotFoundError:
            return None
        except OSError as error:
            raise RunJournalStorageError(
                f"{label} Memory ID storage is unavailable."
            ) from error
        if (
            stat.S_ISLNK(before.st_mode)
            or not stat.S_ISREG(before.st_mode)
            or before.st_size <= 0
            or before.st_size > _MAX_RENDERED_MEMORY_BYTES
        ):
            raise RunJournalStorageError(f"{label} Memory ID storage is unsafe.")
        flags = os.O_RDONLY
        if hasattr(os, "O_NOFOLLOW"):
            flags |= os.O_NOFOLLOW
        try:
            fd = os.open(path, flags)
            try:
                after = os.fstat(fd)
                if (
                    after.st_dev != before.st_dev
                    or after.st_ino != before.st_ino
                    or not stat.S_ISREG(after.st_mode)
                    or after.st_size != before.st_size
                ):
                    raise OSError("memory ID sidecar changed during read")
                raw = os.read(fd, _MAX_RENDERED_MEMORY_BYTES + 1)
            finally:
                os.close(fd)
            if len(raw) != before.st_size:
                raise OSError("short memory ID sidecar read")
            decoded = json.loads(raw.decode("utf-8"))
        except (OSError, UnicodeDecodeError, json.JSONDecodeError) as error:
            raise RunJournalStorageError(
                f"{label} Memory ID storage is unsafe."
            ) from error
        if (
            not isinstance(decoded, dict)
            or set(decoded) != {"schemaVersion", "entryIds"}
            or decoded.get("schemaVersion") != SCHEMA_VERSION
        ):
            raise RunJournalStorageError(f"{label} Memory ID storage is unsafe.")
        try:
            return _normalize_rendered_memory_ids(decoded.get("entryIds"))
        except RunJournalValidationError as error:
            raise RunJournalStorageError(
                f"{label} Memory ID storage is unsafe."
            ) from error

    @staticmethod
    def _fsync_directory(directory: Path) -> None:
        flags = os.O_RDONLY
        if hasattr(os, "O_DIRECTORY"):
            flags |= os.O_DIRECTORY
        try:
            fd = os.open(directory, flags)
        except OSError:
            return
        try:
            os.fsync(fd)
        finally:
            os.close(fd)

    def _read_run(self, run_id: str) -> tuple[RunRecord | None, list[dict[str, str]]]:
        if not self._runs_root.exists():
            return None, []
        try:
            run_dir = self._run_directory(run_id, must_exist=True)
            record = self._read_metadata(run_dir)
            if record.id != run_id or record.workspace_id != self.workspace_id:
                raise ValueError("Run identity mismatch")
        except FileNotFoundError:
            return None, []
        except Exception:
            return None, [self._diagnostic("run_read_failed", "A Run record could not be read.")]
        events, diagnostics = self._read_events(run_id)
        return self._reconcile_record(record, events), diagnostics

    def _read_metadata(self, run_dir: Path) -> RunRecord:
        path = run_dir / "metadata.json"
        if path.is_symlink():
            raise RunJournalStorageError("Run metadata is unsafe.")
        resolved = path.resolve(strict=True)
        if not resolved.is_relative_to(run_dir) or resolved.stat().st_size > _MAX_METADATA_BYTES:
            raise RunJournalStorageError("Run metadata is unsafe.")
        parsed = json.loads(resolved.read_text(encoding="utf-8"))
        return RunRecord.from_dict(parsed)

    def _read_events(self, run_id: str) -> tuple[list[RunEvent], list[dict[str, str]]]:
        try:
            run_dir = self._run_directory(run_id, must_exist=True)
        except FileNotFoundError:
            return [], []
        path = run_dir / "events.ndjson"
        if not path.exists():
            return [], [self._diagnostic("events_missing", "Run events are unavailable.")]
        if path.is_symlink():
            return [], [self._diagnostic("events_unsafe", "Run events could not be read safely.")]
        try:
            resolved = path.resolve(strict=True)
            if not resolved.is_relative_to(run_dir):
                raise OSError("event file escapes Run directory")
        except Exception:
            return [], [self._diagnostic("events_unsafe", "Run events could not be read safely.")]

        events: list[RunEvent] = []
        diagnostics: list[dict[str, str]] = []
        total = 0
        last_sequence = 0
        lifecycle_status: str | None = None
        try:
            with resolved.open("rb") as handle:
                while True:
                    raw_line = handle.readline(_MAX_EVENT_BYTES + 1)
                    if not raw_line:
                        break
                    total += len(raw_line)
                    if len(raw_line) > _MAX_EVENT_BYTES:
                        diagnostics.append(
                            self._diagnostic(
                                "event_oversized",
                                "An oversized Run event was ignored.",
                            )
                        )
                        break
                    if (
                        total > _MAX_RUN_EVENT_FILE_BYTES
                        or len(events) >= _MAX_EVENTS_PER_RUN
                    ):
                        diagnostics.append(self._diagnostic("events_limited", "Run events reached the read limit."))
                        break
                    if not raw_line.endswith(b"\n"):
                        diagnostics.append(self._diagnostic("partial_final_event", "An incomplete final Run event was ignored."))
                        break
                    try:
                        parsed = json.loads(raw_line.decode("utf-8"))
                        event = RunEvent.from_dict(parsed)
                        if (
                            event.run_id != run_id
                            or event.workspace_id != self.workspace_id
                            or event.sequence <= last_sequence
                        ):
                            raise ValueError("event identity or sequence mismatch")
                        candidate_status = _STATUS_FOR_LIFECYCLE_EVENT.get(event.type)
                        if not events and (
                            event.type != "run.queued" or event.sequence != 1
                        ):
                            raise ValueError("Run must start with run.queued")
                        if candidate_status is not None:
                            if lifecycle_status is None:
                                if candidate_status != "queued":
                                    raise ValueError("invalid initial lifecycle event")
                            elif candidate_status not in _ALLOWED_TRANSITIONS.get(
                                lifecycle_status, frozenset()
                            ):
                                raise ValueError("invalid lifecycle transition")
                    except Exception:
                        diagnostics.append(self._diagnostic("event_invalid", "A malformed Run event was skipped."))
                        continue
                    events.append(event)
                    last_sequence = event.sequence
                    if candidate_status is not None:
                        lifecycle_status = candidate_status
        except OSError:
            return [], [self._diagnostic("events_read_failed", "Run events could not be read.")]
        return events, diagnostics[:_MAX_DIAGNOSTICS]

    @staticmethod
    def _reconcile_record(record: RunRecord, events: list[RunEvent]) -> RunRecord:
        if not events:
            return replace(record, last_sequence=0, event_count=0, error_count=0)
        status = record.status
        started_at: str | None = None
        completed_at: str | None = None
        lifecycle_status: str | None = None
        for event in events:
            for candidate_status, candidate_type in LIFECYCLE_EVENT_FOR_STATUS.items():
                if event.type == candidate_type:
                    lifecycle_status = candidate_status
                    if candidate_status == "running":
                        started_at = event.timestamp
                    if candidate_status in TERMINAL_STATUSES:
                        completed_at = event.timestamp
                    break
        if lifecycle_status is not None:
            status = lifecycle_status
        return replace(
            record,
            status=status,
            started_at=started_at,
            completed_at=completed_at,
            updated_at=events[-1].timestamp,
            last_sequence=events[-1].sequence,
            event_count=len(events),
            error_count=sum(1 for event in events if event.type.endswith(".failed")),
        )

    def _refresh_index_best_effort(self) -> None:
        lock = self._runs_root / ".index.lock"
        acquired = False
        try:
            deadline = time.monotonic() + 0.5
            while True:
                try:
                    lock.mkdir(mode=0o700)
                    acquired = True
                    break
                except FileExistsError:
                    if time.monotonic() >= deadline:
                        return
                    time.sleep(0.01)
            entries, _ = self._bounded_run_entries(self._runs_root)
            run_ids = [
                entry.name
                for entry in entries
                if not entry.is_symlink() and entry.is_dir()
            ]
            payload = {
                "schemaVersion": SCHEMA_VERSION,
                "workspaceId": self.workspace_id,
                "updatedAt": _iso_time(self._clock()),
                "runIds": run_ids,
            }
            fd, temporary = tempfile.mkstemp(prefix=".index-", suffix=".tmp", dir=self._runs_root)
            try:
                with os.fdopen(fd, "w", encoding="utf-8") as handle:
                    json.dump(payload, handle, separators=(",", ":"))
                    handle.write("\n")
                    handle.flush()
                    os.fsync(handle.fileno())
                os.replace(temporary, self._runs_root / "index.json")
                self._fsync_directory(self._runs_root)
            except Exception:
                try:
                    os.unlink(temporary)
                except FileNotFoundError:
                    pass
                raise
        except Exception:
            return
        finally:
            if acquired:
                try:
                    lock.rmdir()
                except OSError:
                    pass

    @staticmethod
    def _validate_run_id(run_id: str) -> None:
        if not isinstance(run_id, str) or not _RUN_ID_RE.fullmatch(run_id):
            raise RunJournalValidationError("Run ID is invalid.")

    @staticmethod
    def _page_limit(value: int | str | None, *, default: int) -> int:
        if value in (None, ""):
            return default
        if isinstance(value, bool):
            raise RunJournalValidationError("Page limit is invalid.")
        try:
            parsed = int(value)
        except (TypeError, ValueError) as exc:
            raise RunJournalValidationError("Page limit is invalid.") from exc
        if parsed < 1 or parsed > _MAX_PAGE_LIMIT:
            raise RunJournalValidationError("Page limit is invalid.")
        return parsed

    @staticmethod
    def _encode_cursor(kind: str, values: list[object]) -> str:
        raw = json.dumps([kind, *values], separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    @staticmethod
    def _decode_cursor(kind: str, cursor: str) -> list[object]:
        if (
            not isinstance(cursor, str)
            or not 1 <= len(cursor) <= _MAX_CURSOR_CHARS
            or not _CURSOR_RE.fullmatch(cursor)
        ):
            raise ValueError("invalid cursor")
        try:
            padded = cursor + "=" * (-len(cursor) % 4)
            decoded = base64.b64decode(padded, altchars=b"-_", validate=True)
            payload = json.loads(decoded.decode("utf-8"))
        except (binascii.Error, UnicodeDecodeError, json.JSONDecodeError) as exc:
            raise ValueError("invalid cursor") from exc
        if not isinstance(payload, list) or not payload or payload[0] != kind or len(payload) > 8:
            raise ValueError("invalid cursor")
        return payload[1:]

    @staticmethod
    def _diagnostic(code: str, message: str) -> dict[str, str]:
        return {
            "source": "runs",
            "code": code,
            "message": _redact_text(message, max_chars=_MAX_DIAGNOSTIC_CHARS),
        }

