"""Read-only, bounded inventory of MiniCode persistence.

This module is the single persistence-health authority.  It deliberately does
not construct storage managers because several existing managers acquire write
locks, create roots, perform retention, or recover data while loading.
"""

from __future__ import annotations

import hashlib
import json
import os
import re
import stat
from dataclasses import dataclass, field
from datetime import datetime, timezone
from pathlib import Path
from typing import Callable, Final, Literal

from minicode.config import MINI_CODE_DIR


SCHEMA_VERSION: Final = 1
MAX_DIRECTORY_ENTRIES: Final = 25_000
MAX_PARSED_FILE_BYTES: Final = 2 * 1024 * 1024
MAX_RESPONSE_BYTES: Final = 256 * 1024
MAX_SAFE_INTEGER: Final = (2**53) - 1
MAX_DIAGNOSTICS: Final = 64
MAX_WORKSPACE_NAME_CHARS: Final = 160

StoreStatus = Literal["live", "partial", "unavailable", "error"]
Scope = Literal["workspace", "user", "local", "configuration", "process"]
Durability = Literal["persistent", "process-local", "source"]
ResetDisposition = Literal["planned", "excluded", "not-applicable"]

_WORKSPACE_ID_RE = re.compile(r"^ws_[0-9a-f]{16}$")
_TIMESTAMP_RE = re.compile(
    r"^[0-9]{4}-[0-9]{2}-[0-9]{2}T"
    r"[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{3}Z$"
)

_LIVE_MESSAGE = "The bounded read-only scan completed."
_PARTIAL_MESSAGE = "Some persisted facts could not be verified safely."
_UNAVAILABLE_MESSAGE = "This store could not be inspected safely."
_PROCESS_MESSAGE = "Process-local state is not a disk persistence fact."
_ALLOWED_MESSAGES = {
    None,
    _LIVE_MESSAGE,
    _PARTIAL_MESSAGE,
    _UNAVAILABLE_MESSAGE,
    _PROCESS_MESSAGE,
}

_DIAGNOSTIC_MESSAGES: Final = {
    "scan_limited": "The directory entry budget was reached.",
    "root_unsafe": "A configured storage root was not a regular directory.",
    "entry_unsafe": "A symbolic link or special entry was rejected.",
    "read_failed": "A persisted file could not be read safely.",
    "oversized_file": "A file exceeded the bounded parsing limit.",
    "invalid_json": "A persisted JSON document was malformed.",
    "invalid_record": "A persisted record failed bounded validation.",
    "index_drift": "Canonical records and their index did not agree.",
    "orphan_reference": "A cross-store reference had no matching record.",
    "temporary_artifact": "A temporary or backup artifact remains on disk.",
    "legacy_source": "A legacy source exists but was not parsed for record counts.",
    "active_writer": "An active-writer marker is present.",
}


@dataclass(frozen=True, slots=True)
class _StoreSpec:
    id: str
    scope: Scope
    durability: Durability
    reset_disposition: ResetDisposition


_STORE_SPECS: Final = (
    _StoreSpec("sessions", "workspace", "persistent", "planned"),
    _StoreSpec("conversation-turns", "workspace", "persistent", "planned"),
    _StoreSpec("run-journal", "workspace", "persistent", "planned"),
    _StoreSpec("deletion-coordination", "workspace", "persistent", "planned"),
    _StoreSpec("memory-user", "user", "persistent", "excluded"),
    _StoreSpec("memory-project", "workspace", "persistent", "planned"),
    _StoreSpec("memory-local", "local", "persistent", "planned"),
    _StoreSpec("memory-approval-user", "user", "persistent", "excluded"),
    _StoreSpec("memory-approval-project", "workspace", "persistent", "planned"),
    _StoreSpec("memory-approval-local", "local", "persistent", "planned"),
    _StoreSpec("memory-pipeline-state", "workspace", "persistent", "planned"),
    _StoreSpec("tool-results", "workspace", "persistent", "planned"),
    _StoreSpec("permissions", "user", "persistent", "excluded"),
    _StoreSpec("configuration", "configuration", "source", "excluded"),
    _StoreSpec("mcp-configuration", "configuration", "source", "excluded"),
    _StoreSpec("user-profile", "user", "source", "excluded"),
    _StoreSpec("project-profile", "configuration", "source", "excluded"),
    _StoreSpec("skills-user", "user", "source", "excluded"),
    _StoreSpec("skills-project", "configuration", "source", "excluded"),
    _StoreSpec("user-runtime-artifacts", "user", "persistent", "excluded"),
    _StoreSpec(
        "workspace-runtime-artifacts",
        "configuration",
        "source",
        "excluded",
    ),
    _StoreSpec("permission-broker", "process", "process-local", "not-applicable"),
    _StoreSpec(
        "mcp-current-registry",
        "process",
        "process-local",
        "not-applicable",
    ),
    _StoreSpec("gateway-runtime", "process", "process-local", "not-applicable"),
    _StoreSpec("working-memory", "process", "process-local", "not-applicable"),
)
_STORE_BY_ID: Final = {spec.id: spec for spec in _STORE_SPECS}


@dataclass(slots=True)
class _ScanBudget:
    limit: int
    used: int = 0
    exhausted: bool = False

    def consume(self) -> bool:
        if self.used >= self.limit:
            self.exhausted = True
            return False
        self.used += 1
        return True


@dataclass(slots=True)
class _ScanResult:
    status: StoreStatus = "live"
    record_count: int | None = 0
    byte_count: int | None = 0
    updated_at: datetime | None = None
    diagnostics: list[str] = field(default_factory=list)
    identities: set[str] = field(default_factory=set, repr=False)
    references: set[str] = field(default_factory=set, repr=False)
    audit_references: set[str] = field(default_factory=set, repr=False)
    active_fence: bool = field(default=False, repr=False)

    def add_bytes(self, value: int) -> None:
        if self.byte_count is None:
            return
        if isinstance(value, bool) or not isinstance(value, int) or value < 0:
            self.degrade("invalid_record")
            return
        self.byte_count = min(MAX_SAFE_INTEGER, self.byte_count + value)

    def add_records(self, value: int = 1) -> None:
        if self.record_count is None:
            return
        if isinstance(value, bool) or not isinstance(value, int) or value < 0:
            self.degrade("invalid_record")
            return
        self.record_count = min(MAX_SAFE_INTEGER, self.record_count + value)

    def observe_mtime(self, value: float) -> None:
        try:
            observed = datetime.fromtimestamp(value, tz=timezone.utc)
        except (OSError, OverflowError, ValueError):
            self.degrade("invalid_record")
            return
        if observed < datetime(1970, 1, 1, tzinfo=timezone.utc):
            self.degrade("invalid_record")
            return
        if self.updated_at is None or observed > self.updated_at:
            self.updated_at = observed

    def degrade(self, code: str, *, unavailable: bool = False) -> None:
        if code not in _DIAGNOSTIC_MESSAGES:
            code = "read_failed"
        if code not in self.diagnostics:
            self.diagnostics.append(code)
        if unavailable:
            self.status = "unavailable"
            self.record_count = None
            self.byte_count = None
            self.updated_at = None
        elif self.status == "live":
            self.status = "partial"


class PersistenceHealthContractError(ValueError):
    """A health snapshot violated the closed public contract."""


def _exact_int(value: object) -> bool:
    return (
        isinstance(value, int)
        and not isinstance(value, bool)
        and 0 <= value <= MAX_SAFE_INTEGER
    )


def _valid_timestamp(value: object, *, nullable: bool = False) -> bool:
    if value is None:
        return nullable
    if not isinstance(value, str) or _TIMESTAMP_RE.fullmatch(value) is None:
        return False
    try:
        parsed = datetime.fromisoformat(value.removesuffix("Z") + "+00:00")
    except ValueError:
        return False
    return (
        parsed.tzinfo is not None
        and parsed.utcoffset() is not None
        and parsed.utcoffset().total_seconds() == 0
        and _iso_time(parsed) == value
    )


def _exact_keys(value: object, keys: set[str]) -> bool:
    return isinstance(value, dict) and set(value) == keys


def validate_persistence_health_snapshot(
    payload: object,
) -> dict[str, object]:
    """Validate and return one exact schema-v1 snapshot."""
    top_keys = {
        "schemaVersion",
        "generatedAt",
        "mode",
        "status",
        "workspace",
        "summary",
        "stores",
        "maintenancePlan",
        "diagnostics",
    }
    if not _exact_keys(payload, top_keys):
        raise PersistenceHealthContractError("invalid data-health contract")
    assert isinstance(payload, dict)
    if (
        payload["schemaVersion"] != SCHEMA_VERSION
        or isinstance(payload["schemaVersion"], bool)
        or payload["mode"] != "read-only"
        or payload["status"] not in {"live", "partial", "unavailable", "error"}
        or not _valid_timestamp(payload["generatedAt"])
    ):
        raise PersistenceHealthContractError("invalid data-health contract")

    workspace = payload["workspace"]
    if (
        not _exact_keys(workspace, {"id", "name"})
        or not isinstance(workspace["id"], str)
        or _WORKSPACE_ID_RE.fullmatch(workspace["id"]) is None
        or not isinstance(workspace["name"], str)
        or not 1 <= len(workspace["name"]) <= MAX_WORKSPACE_NAME_CHARS
        or any(character in workspace["name"] for character in ("/", "\\", "\x00"))
    ):
        raise PersistenceHealthContractError("invalid data-health workspace")

    summary = payload["summary"]
    if not _exact_keys(
        summary,
        {"storeCount", "knownRecordCount", "knownByteCount", "issueCount"},
    ) or not all(_exact_int(value) for value in summary.values()):
        raise PersistenceHealthContractError("invalid data-health summary")

    stores = payload["stores"]
    if not isinstance(stores, list) or len(stores) > len(_STORE_SPECS):
        raise PersistenceHealthContractError("invalid data-health stores")
    store_keys = {
        "id",
        "scope",
        "durability",
        "status",
        "recordCount",
        "byteCount",
        "updatedAt",
        "resetDisposition",
        "message",
    }
    seen: set[str] = set()
    for store in stores:
        if not _exact_keys(store, store_keys):
            raise PersistenceHealthContractError("invalid data-health store")
        store_id = store["id"]
        spec = _STORE_BY_ID.get(store_id) if isinstance(store_id, str) else None
        if (
            spec is None
            or store_id in seen
            or store["scope"] != spec.scope
            or store["durability"] != spec.durability
            or store["resetDisposition"] != spec.reset_disposition
            or store["status"] not in {"live", "partial", "unavailable", "error"}
            or store["message"] not in _ALLOWED_MESSAGES
            or not _valid_timestamp(store["updatedAt"], nullable=True)
        ):
            raise PersistenceHealthContractError("invalid data-health store")
        seen.add(store_id)
        for count_field in ("recordCount", "byteCount"):
            if store[count_field] is not None and not _exact_int(store[count_field]):
                raise PersistenceHealthContractError("invalid data-health count")
        if spec.durability == "process-local" and (
            store["recordCount"] is not None
            or store["byteCount"] is not None
            or store["updatedAt"] is not None
            or store["status"] != "live"
            or store["message"] != _PROCESS_MESSAGE
        ):
            raise PersistenceHealthContractError("invalid process-local store")

    plan = payload["maintenancePlan"]
    if (
        not _exact_keys(
            plan,
            {
                "status",
                "destructiveActionsAvailable",
                "eligibleStoreIds",
                "excludedStoreIds",
                "blockers",
            },
        )
        or plan["status"] != "planning"
        or plan["destructiveActionsAvailable"] is not False
        or not isinstance(plan["eligibleStoreIds"], list)
        or not isinstance(plan["excludedStoreIds"], list)
        or not isinstance(plan["blockers"], list)
    ):
        raise PersistenceHealthContractError("invalid maintenance plan")
    for store_list_field in ("eligibleStoreIds", "excludedStoreIds"):
        values = plan[store_list_field]
        if len(values) != len(set(values)) or any(
            value not in seen for value in values
        ):
            raise PersistenceHealthContractError("invalid maintenance stores")
    expected_eligible = [
        store["id"] for store in stores if store["resetDisposition"] == "planned"
    ]
    expected_excluded = [
        store["id"] for store in stores if store["resetDisposition"] == "excluded"
    ]
    if (
        plan["eligibleStoreIds"] != expected_eligible
        or plan["excludedStoreIds"] != expected_excluded
    ):
        raise PersistenceHealthContractError("invalid maintenance stores")
    for blocker in plan["blockers"]:
        if (
            not _exact_keys(blocker, {"code", "storeId"})
            or blocker["code"] not in {"store_not_live", "active_maintenance_fence"}
            or blocker["storeId"] not in expected_eligible
            or (
                blocker["code"] == "active_maintenance_fence"
                and blocker["storeId"] != "deletion-coordination"
            )
        ):
            raise PersistenceHealthContractError("invalid maintenance blocker")

    diagnostics = payload["diagnostics"]
    if not isinstance(diagnostics, list) or len(diagnostics) > MAX_DIAGNOSTICS:
        raise PersistenceHealthContractError("invalid diagnostics")
    for diagnostic in diagnostics:
        if (
            not _exact_keys(diagnostic, {"storeId", "code", "message"})
            or diagnostic["storeId"] not in seen
            or not isinstance(diagnostic["code"], str)
            or not re.fullmatch(r"[a-z][a-z0-9_]{0,63}", diagnostic["code"])
            or not isinstance(diagnostic["message"], str)
            or not 1 <= len(diagnostic["message"]) <= 160
            or any(
                marker in diagnostic["message"].casefold()
                for marker in ("secret", "token", "password", "/users/", "\\users\\")
            )
        ):
            raise PersistenceHealthContractError("invalid diagnostic")

    if summary["storeCount"] != len(stores):
        raise PersistenceHealthContractError("invalid store count")
    known_records = sum(
        store["recordCount"] for store in stores if store["recordCount"] is not None
    )
    known_bytes = sum(
        store["byteCount"] for store in stores if store["byteCount"] is not None
    )
    issue_count = sum(store["status"] != "live" for store in stores)
    if (
        summary["knownRecordCount"] != min(known_records, MAX_SAFE_INTEGER)
        or summary["knownByteCount"] != min(known_bytes, MAX_SAFE_INTEGER)
        or summary["issueCount"] != issue_count
    ):
        raise PersistenceHealthContractError("invalid summary totals")
    try:
        encoded = json.dumps(
            payload,
            ensure_ascii=False,
            allow_nan=False,
            separators=(",", ":"),
        ).encode("utf-8")
    except (TypeError, ValueError) as error:
        raise PersistenceHealthContractError("invalid response encoding") from error
    if len(encoded) > MAX_RESPONSE_BYTES:
        raise PersistenceHealthContractError("data-health response too large")
    return payload


def _iso_time(value: datetime) -> str:
    if not isinstance(value, datetime) or value.tzinfo is None:
        raise ValueError("clock must return an aware datetime")
    return (
        value.astimezone(timezone.utc)
        .isoformat(timespec="milliseconds")
        .replace("+00:00", "Z")
    )


def _workspace_id(workspace: Path) -> str:
    return "ws_" + hashlib.sha256(str(workspace).encode("utf-8")).hexdigest()[:16]


def _safe_workspace_name(workspace: Path) -> str:
    value = workspace.name.strip()
    if (
        not value
        or len(value) > MAX_WORKSPACE_NAME_CHARS
        or any(character in value for character in ("/", "\\", "\x00"))
    ):
        return "Workspace"
    return value


class PersistenceHealthReader:
    """Inspect only fixed persistence roots for one startup Workspace."""

    def __init__(
        self,
        workspace: str | Path,
        *,
        data_dir: str | Path | None = None,
        clock: Callable[[], datetime] = lambda: datetime.now(timezone.utc),
        max_directory_entries: int = MAX_DIRECTORY_ENTRIES,
        max_parsed_file_bytes: int = MAX_PARSED_FILE_BYTES,
    ) -> None:
        if (
            not _exact_int(max_directory_entries)
            or not 1 <= max_directory_entries <= MAX_DIRECTORY_ENTRIES
            or not _exact_int(max_parsed_file_bytes)
            or not 1 <= max_parsed_file_bytes <= MAX_PARSED_FILE_BYTES
        ):
            raise ValueError("invalid persistence health budget")
        self.workspace = Path(workspace).expanduser().resolve()
        self.data_dir = Path(
            data_dir if data_dir is not None else MINI_CODE_DIR
        ).expanduser()
        self._clock = clock
        self._budget = _ScanBudget(max_directory_entries)
        self._max_file_bytes = max_parsed_file_bytes
        self._workspace_id = _workspace_id(self.workspace)

    @staticmethod
    def _is_temporary_name(name: str) -> bool:
        return (
            name.endswith(".tmp") or name.endswith(".bak") or name.endswith(".backup")
        )

    @staticmethod
    def _path_under(anchor: Path, target: Path) -> bool:
        try:
            target.relative_to(anchor)
            return True
        except ValueError:
            return False

    def _safe_chain(self, anchor: Path, target: Path) -> str:
        """Classify a fixed path without following a symlink below its anchor."""
        if not self._path_under(anchor, target):
            return "unsafe"
        parts = target.relative_to(anchor).parts
        candidates = (
            anchor,
            *(anchor.joinpath(*parts[:index]) for index in range(1, len(parts) + 1)),
        )
        for index, candidate in enumerate(candidates):
            try:
                info = os.lstat(candidate)
            except FileNotFoundError:
                return "missing"
            except OSError:
                return "error"
            if stat.S_ISLNK(info.st_mode):
                return "unsafe"
            if index < len(candidates) - 1 and not stat.S_ISDIR(info.st_mode):
                return "unsafe"
        return "present"

    def _directory_entries(
        self,
        root: Path,
        *,
        anchor: Path,
        result: _ScanResult,
    ) -> list[os.DirEntry[str]]:
        state = self._safe_chain(anchor, root)
        if state == "missing":
            return []
        if state in {"unsafe", "error"}:
            result.degrade("root_unsafe", unavailable=True)
            return []
        try:
            info = os.lstat(root)
            if not stat.S_ISDIR(info.st_mode):
                result.degrade("root_unsafe", unavailable=True)
                return []
            entries: list[os.DirEntry[str]] = []
            with os.scandir(root) as scanner:
                for entry in scanner:
                    if not self._budget.consume():
                        result.degrade("scan_limited")
                        break
                    entries.append(entry)
            return entries
        except OSError:
            result.degrade("read_failed", unavailable=True)
            return []

    def _read_file(
        self,
        path: Path,
        *,
        anchor: Path,
        result: _ScanResult,
        max_bytes: int | None = None,
    ) -> bytes | None:
        parse_limit = (
            self._max_file_bytes
            if max_bytes is None
            else min(self._max_file_bytes, max_bytes)
        )
        state = self._safe_chain(anchor, path)
        if state == "missing":
            return None
        if state in {"unsafe", "error"}:
            result.degrade("entry_unsafe")
            return None
        descriptor = -1
        try:
            path_info = os.lstat(path)
            if not stat.S_ISREG(path_info.st_mode):
                result.degrade("entry_unsafe")
                return None
            result.add_bytes(path_info.st_size)
            result.observe_mtime(path_info.st_mtime)
            if path_info.st_size > parse_limit:
                result.degrade("oversized_file")
                return None
            flags = os.O_RDONLY | getattr(os, "O_CLOEXEC", 0)
            flags |= getattr(os, "O_NOFOLLOW", 0)
            descriptor = os.open(path, flags)
            descriptor_info = os.fstat(descriptor)
            current_info = os.lstat(path)
            if (
                not stat.S_ISREG(descriptor_info.st_mode)
                or not stat.S_ISREG(current_info.st_mode)
                or descriptor_info.st_dev != current_info.st_dev
                or descriptor_info.st_ino != current_info.st_ino
                or descriptor_info.st_size != current_info.st_size
            ):
                result.degrade("entry_unsafe")
                return None
            chunks: list[bytes] = []
            remaining = parse_limit + 1
            while remaining > 0:
                chunk = os.read(descriptor, min(remaining, 64 * 1024))
                if not chunk:
                    break
                chunks.append(chunk)
                remaining -= len(chunk)
            data = b"".join(chunks)
            if len(data) > parse_limit:
                result.degrade("oversized_file")
                return None
            return data
        except OSError:
            result.degrade("read_failed")
            return None
        finally:
            if descriptor >= 0:
                try:
                    os.close(descriptor)
                except OSError:
                    pass

    def _stat_file(
        self,
        path: Path,
        *,
        anchor: Path,
        result: _ScanResult,
    ) -> bool:
        """Count one fixed regular file without reading any file content."""
        state = self._safe_chain(anchor, path)
        if state == "missing":
            return False
        if state in {"unsafe", "error"}:
            result.degrade("entry_unsafe")
            return False
        try:
            path_info = os.lstat(path)
        except OSError:
            result.degrade("read_failed")
            return False
        if not stat.S_ISREG(path_info.st_mode):
            result.degrade("entry_unsafe")
            return False
        result.add_bytes(path_info.st_size)
        result.observe_mtime(path_info.st_mtime)
        return True

    def _read_json(
        self,
        path: Path,
        *,
        anchor: Path,
        result: _ScanResult,
        max_bytes: int | None = None,
    ) -> object | None:
        raw = self._read_file(
            path,
            anchor=anchor,
            result=result,
            max_bytes=max_bytes,
        )
        if raw is None:
            return None
        try:
            return json.loads(raw.decode("utf-8", errors="strict"))
        except (UnicodeDecodeError, json.JSONDecodeError):
            result.degrade("invalid_json")
            return None

    def _workspace_matches(self, value: object) -> bool:
        if not isinstance(value, str) or not 1 <= len(value) <= 4_096:
            return False
        try:
            normalized = os.path.normcase(os.path.abspath(os.path.expanduser(value)))
        except (OSError, ValueError):
            return False
        return normalized == os.path.normcase(str(self.workspace))

    def _scan_sessions(self) -> _ScanResult:
        result = _ScanResult()
        index_path = self.data_dir / "sessions_index.json"
        raw_index = self._read_json(index_path, anchor=self.data_dir, result=result)
        indexed_ids: set[str] = set()
        all_indexed_ids: set[str] = set()
        if raw_index is not None:
            if not isinstance(raw_index, dict):
                result.degrade("invalid_record")
            else:
                for session_id, metadata in raw_index.items():
                    valid_identity = (
                        isinstance(session_id, str)
                        and re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9_-]{0,127}", session_id)
                        and isinstance(metadata, dict)
                        and metadata.get("session_id") == session_id
                    )
                    if valid_identity:
                        all_indexed_ids.add(session_id)
                        if self._workspace_matches(metadata.get("workspace")):
                            indexed_ids.add(session_id)
                    elif isinstance(metadata, dict) and self._workspace_matches(
                        metadata.get("workspace")
                    ):
                        result.degrade("invalid_record")

        sessions_root = self.data_dir / "sessions"
        entries = self._directory_entries(
            sessions_root, anchor=self.data_dir, result=result
        )
        base_ids: set[str] = set()
        generations: dict[str, int] = {}
        for entry in entries:
            if entry.name == "deltas":
                try:
                    if entry.is_symlink() or not entry.is_dir(follow_symlinks=False):
                        result.degrade("entry_unsafe")
                except OSError:
                    result.degrade("read_failed")
                continue
            match = re.fullmatch(
                r"([A-Za-z0-9][A-Za-z0-9_-]{0,127})\.json",
                entry.name,
            )
            if match is None:
                if self._is_temporary_name(entry.name):
                    result.degrade("temporary_artifact")
                elif entry.name not in {".DS_Store"}:
                    result.degrade("entry_unsafe")
                continue
            session_id = match.group(1)
            if session_id not in all_indexed_ids:
                # The Session base root is shared by Workspaces. Without the
                # canonical index, ownership cannot be established without
                # reading a possibly foreign Session body.
                result.degrade("index_drift")
                continue
            if session_id not in indexed_ids:
                continue
            parsed = self._read_json(
                Path(entry.path), anchor=self.data_dir, result=result
            )
            if parsed is None:
                continue
            generation = (
                parsed.get("persistence_generation", 0)
                if isinstance(parsed, dict)
                else None
            )
            if (
                not isinstance(parsed, dict)
                or parsed.get("session_id") != session_id
                or not self._workspace_matches(parsed.get("workspace"))
            ):
                if isinstance(parsed, dict) and self._workspace_matches(
                    parsed.get("workspace")
                ):
                    result.degrade("invalid_record")
                continue
            if (
                isinstance(generation, bool)
                or not isinstance(generation, int)
                or not 0 <= generation <= (2**31) - 1
            ):
                result.degrade("invalid_record")
                continue
            base_ids.add(session_id)
            generations[session_id] = generation

        owned_ids = base_ids | indexed_ids
        result.record_count = len(owned_ids)
        result.identities = owned_ids
        if base_ids != indexed_ids and (base_ids or indexed_ids):
            result.degrade("index_drift")

        deltas_root = sessions_root / "deltas"
        delta_sessions = self._directory_entries(
            deltas_root, anchor=self.data_dir, result=result
        )
        for entry in delta_sessions:
            if entry.name not in owned_ids:
                continue
            try:
                if entry.is_symlink() or not entry.is_dir(follow_symlinks=False):
                    result.degrade("entry_unsafe")
                    continue
            except OSError:
                result.degrade("read_failed")
                continue
            delta_entries = self._directory_entries(
                Path(entry.path), anchor=self.data_dir, result=result
            )
            for delta_entry in delta_entries:
                if re.fullmatch(r"delta_[0-9]{4,8}\.json", delta_entry.name) is None:
                    result.degrade(
                        "temporary_artifact"
                        if self._is_temporary_name(delta_entry.name)
                        else "entry_unsafe"
                    )
                    continue
                parsed = self._read_json(
                    Path(delta_entry.path), anchor=self.data_dir, result=result
                )
                if parsed is None:
                    continue
                generation = (
                    parsed.get("persistence_generation", 0)
                    if isinstance(parsed, dict)
                    else None
                )
                if (
                    not isinstance(parsed, dict)
                    or parsed.get("session_id", entry.name) != entry.name
                    or isinstance(generation, bool)
                    or not isinstance(generation, int)
                    or generation != generations.get(entry.name, generation)
                ):
                    result.degrade("invalid_record")
        return result

    def _scan_turns(self) -> _ScanResult:
        result = _ScanResult()
        root = self.data_dir / "dashboard" / "workspaces" / self._workspace_id / "turns"
        for entry in self._directory_entries(root, anchor=self.data_dir, result=result):
            if re.fullmatch(r"\.turn_[0-9a-f]{32}\.lease", entry.name) is not None:
                try:
                    if entry.is_symlink() or not entry.is_file(follow_symlinks=False):
                        result.degrade("entry_unsafe")
                except OSError:
                    result.degrade("read_failed")
                continue
            match = re.fullmatch(r"(turn_[0-9a-f]{32})\.json", entry.name)
            if match is None:
                if self._is_temporary_name(entry.name):
                    result.degrade("temporary_artifact")
                else:
                    result.degrade("entry_unsafe")
                continue
            parsed = self._read_json(
                Path(entry.path), anchor=self.data_dir, result=result
            )
            if (
                not isinstance(parsed, dict)
                or parsed.get("schemaVersion") != 1
                or isinstance(parsed.get("schemaVersion"), bool)
                or parsed.get("turnId") != match.group(1)
                or parsed.get("workspaceId") != self._workspace_id
                or parsed.get("status")
                not in {
                    "accepted",
                    "running",
                    "cancel_requested",
                    "committing",
                    "completed",
                    "failed",
                    "interrupted",
                    "cancelled",
                }
            ):
                if parsed is not None:
                    result.degrade("invalid_record")
                continue
            result.add_records()
            result.identities.add(match.group(1))
        return result

    def _scan_runs(self) -> _ScanResult:
        result = _ScanResult()
        root = self.data_dir / "dashboard" / "workspaces" / self._workspace_id / "runs"
        entries = self._directory_entries(root, anchor=self.data_dir, result=result)
        run_ids: set[str] = set()
        index_ids: set[str] | None = None
        for entry in entries:
            if entry.name == "index.json":
                parsed = self._read_json(
                    Path(entry.path), anchor=self.data_dir, result=result
                )
                raw_ids = parsed.get("runIds") if isinstance(parsed, dict) else None
                if (
                    isinstance(parsed, dict)
                    and parsed.get("schemaVersion") == 1
                    and not isinstance(parsed.get("schemaVersion"), bool)
                    and parsed.get("workspaceId") == self._workspace_id
                    and isinstance(raw_ids, list)
                    and all(
                        isinstance(item, str)
                        and re.fullmatch(r"run_[0-9a-f]{32}", item)
                        for item in raw_ids
                    )
                    and len(raw_ids) == len(set(raw_ids))
                ):
                    index_ids = set(raw_ids)
                elif parsed is not None:
                    result.degrade("invalid_record")
                continue
            if entry.name == ".index.lock":
                result.degrade("active_writer")
                continue
            if self._is_temporary_name(entry.name):
                result.degrade("temporary_artifact")
                continue
            if re.fullmatch(r"run_[0-9a-f]{32}", entry.name) is None:
                result.degrade("entry_unsafe")
                continue
            try:
                if entry.is_symlink() or not entry.is_dir(follow_symlinks=False):
                    result.degrade("entry_unsafe")
                    continue
            except OSError:
                result.degrade("read_failed")
                continue
            run_dir = Path(entry.path)
            metadata = self._read_json(
                run_dir / "metadata.json",
                anchor=self.data_dir,
                result=result,
            )
            if (
                not isinstance(metadata, dict)
                or metadata.get("schemaVersion") != 1
                or isinstance(metadata.get("schemaVersion"), bool)
                or metadata.get("id") != entry.name
                or metadata.get("workspaceId") != self._workspace_id
            ):
                if metadata is not None:
                    result.degrade("invalid_record")
                continue
            run_source = metadata.get("source")
            curator_outbox_version = metadata.get("curatorOutboxVersion")
            if (
                curator_outbox_version is not None
                and (
                    isinstance(curator_outbox_version, bool)
                    or curator_outbox_version not in {2, 3}
                    or run_source not in {"tui", "headless"}
                )
            ):
                result.degrade("invalid_record")
            events_raw = self._read_file(
                run_dir / "events.ndjson",
                anchor=self.data_dir,
                result=result,
            )
            if events_raw is not None:
                if events_raw and not events_raw.endswith(b"\n"):
                    result.degrade("invalid_record")
                else:
                    for line in events_raw.splitlines():
                        try:
                            event = json.loads(line.decode("utf-8", errors="strict"))
                        except (UnicodeDecodeError, json.JSONDecodeError):
                            result.degrade("invalid_json")
                            break
                        if (
                            not isinstance(event, dict)
                            or event.get("schemaVersion") != 1
                            or isinstance(event.get("schemaVersion"), bool)
                            or event.get("runId") != entry.name
                            or event.get("workspaceId") != self._workspace_id
                        ):
                            result.degrade("invalid_record")
                            break
            curator_receipt_seen = False
            children = self._directory_entries(
                run_dir, anchor=self.data_dir, result=result
            )
            for child in children:
                if child.name in {"metadata.json", "events.ndjson"}:
                    continue
                if child.name == "curator_receipt.json":
                    from minicode.curator_schedule import curator_completion_id

                    curator_receipt_seen = True
                    receipt = self._read_json(
                        Path(child.path),
                        anchor=self.data_dir,
                        result=result,
                        max_bytes=512,
                    )
                    schema = (
                        receipt.get("schemaVersion")
                        if isinstance(receipt, dict)
                        else None
                    )
                    prepared_at_ms = (
                        receipt.get("preparedAtMs")
                        if isinstance(receipt, dict)
                        else None
                    )
                    state = (
                        receipt.get("state")
                        if isinstance(receipt, dict)
                        else None
                    )
                    legacy_valid = (
                        schema == 1
                        and not isinstance(schema, bool)
                        and set(receipt)
                        == {"schemaVersion", "completionId", "state"}
                        and state in {"inactive", "pending", "recorded"}
                    ) if isinstance(receipt, dict) else False
                    v2_valid = (
                        schema == 2
                        and not isinstance(schema, bool)
                        and set(receipt)
                        == {
                            "schemaVersion",
                            "completionId",
                            "state",
                            "preparedAtMs",
                        }
                        and curator_outbox_version == 2
                        and state
                        in {"inactive", "pending", "delivering", "recorded"}
                        and not isinstance(prepared_at_ms, bool)
                        and isinstance(prepared_at_ms, int)
                        and 0 <= prepared_at_ms <= 99_999_999_999_999
                        and (
                            (state == "inactive" and prepared_at_ms == 0)
                            or (state != "inactive" and prepared_at_ms > 0)
                        )
                    ) if isinstance(receipt, dict) else False
                    current_valid = (
                        schema == 3
                        and not isinstance(schema, bool)
                        and set(receipt)
                        == {
                            "schemaVersion",
                            "completionId",
                            "state",
                            "preparedAtMs",
                        }
                        and (
                            curator_outbox_version in {2, 3}
                            or (
                                curator_outbox_version is None
                                and metadata.get("status") == "queued"
                                and state == "inactive"
                            )
                        )
                        and state
                        in {
                            "inactive",
                            "pending",
                            "delivering",
                            "recorded",
                            "settled",
                        }
                        and not isinstance(prepared_at_ms, bool)
                        and isinstance(prepared_at_ms, int)
                        and 0 <= prepared_at_ms <= 99_999_999_999_999
                        and (
                            (state == "inactive" and prepared_at_ms == 0)
                            or (state != "inactive" and prepared_at_ms > 0)
                        )
                    ) if isinstance(receipt, dict) else False
                    if (
                        not isinstance(receipt, dict)
                        or not (legacy_valid or v2_valid or current_valid)
                        or run_source not in {"tui", "headless"}
                        or receipt.get("completionId")
                        != curator_completion_id(entry.name)
                    ):
                        if receipt is not None:
                            result.degrade("invalid_record")
                    continue
                if child.name == ".writer.lock":
                    if self._stat_file(
                        Path(child.path), anchor=self.data_dir, result=result
                    ):
                        result.degrade("active_writer")
                    continue
                result.degrade(
                    "temporary_artifact"
                    if self._is_temporary_name(child.name)
                    else "entry_unsafe"
                )
            if curator_outbox_version in {2, 3} and not curator_receipt_seen:
                result.degrade("invalid_record")
            run_ids.add(entry.name)
            result.add_records()
        if index_ids is not None and index_ids != run_ids:
            result.degrade("index_drift")
        elif index_ids is None and run_ids:
            result.degrade("index_drift")
        result.identities = run_ids
        return result

    def _memory_root(self, scope: str) -> tuple[Path, Path]:
        if scope == "user":
            return self.data_dir / "memory", self.data_dir
        if scope == "project":
            return self.workspace / ".mini-code-memory", self.workspace
        return self.workspace / ".mini-code-memory-local", self.workspace

    def _scan_memory(self, scope: str) -> _ScanResult:
        result = _ScanResult()
        root, anchor = self._memory_root(scope)
        entries = self._directory_entries(root, anchor=anchor, result=result)
        names = {entry.name for entry in entries}
        memory_path = root / "memory.json"
        parsed = self._read_json(memory_path, anchor=anchor, result=result)
        if parsed is not None:
            raw_entries = parsed.get("entries") if isinstance(parsed, dict) else None
            if (
                not isinstance(parsed, dict)
                or parsed.get("scope", scope) != scope
                or not isinstance(raw_entries, list)
            ):
                result.degrade("invalid_record")
            else:
                for entry in raw_entries:
                    entry_id = entry.get("id") if isinstance(entry, dict) else None
                    content = entry.get("content") if isinstance(entry, dict) else None
                    related = (
                        entry.get("related_to", []) if isinstance(entry, dict) else None
                    )
                    if (
                        not isinstance(entry, dict)
                        or not isinstance(entry_id, str)
                        or not 1 <= len(entry_id) <= 160
                        or entry.get("scope", scope) != scope
                        or not isinstance(content, str)
                        or not isinstance(related, list)
                        or any(not isinstance(item, str) for item in related)
                    ):
                        result.degrade("invalid_record")
                        continue
                    result.add_records()
                    result.identities.add(entry_id)
                    result.references.update(related)
        elif "MEMORY.md" in names:
            result.record_count = None
            result.degrade("legacy_source")
        if "MEMORY.md" in names:
            self._stat_file(root / "MEMORY.md", anchor=anchor, result=result)
        for entry in entries:
            if entry.name in {
                "memory.json",
                "MEMORY.md",
                "approval_audit.json",
                "pipeline_state.json",
                "curator_schedule.json",
            }:
                continue
            if entry.name in {
                ".curator-schedule.lock",
                ".curator-execution.lock",
                ".curator-delivery.lock",
                ".conversation-commit.lock",
                ".conversation-turn-state.lock",
            }:
                # Scheduling uses content-free advisory-lock files beside its
                # authority. Validate them as regular contained files without
                # presenting them as user Memory records.
                self._stat_file(Path(entry.path), anchor=anchor, result=result)
                continue
            if self._is_temporary_name(entry.name):
                self._stat_file(Path(entry.path), anchor=anchor, result=result)
                result.degrade("temporary_artifact")
            elif entry.name not in {".DS_Store"}:
                result.degrade("entry_unsafe")
        return result

    def _scan_memory_audit(self, scope: str) -> _ScanResult:
        result = _ScanResult()
        root, anchor = self._memory_root(scope)
        path = root / "approval_audit.json"
        parsed = self._read_json(path, anchor=anchor, result=result)
        if parsed is None:
            return result
        records = parsed.get("records") if isinstance(parsed, dict) else None
        if (
            not isinstance(parsed, dict)
            or parsed.get("scope", scope) != scope
            or not isinstance(records, list)
        ):
            result.degrade("invalid_record")
            return result
        for record in records:
            entry_id = record.get("entry_id") if isinstance(record, dict) else None
            if not isinstance(record, dict) or not isinstance(entry_id, str):
                result.degrade("invalid_record")
                continue
            result.add_records()
            result.audit_references.add(entry_id)
        return result

    def _scan_deletion_coordination(self) -> _ScanResult:
        result = _ScanResult()
        root = (
            self.data_dir
            / "dashboard"
            / "workspaces"
            / self._workspace_id
            / "deletions"
        )
        for entry in self._directory_entries(root, anchor=self.data_dir, result=result):
            if entry.name == "coordination.lock":
                self._stat_file(Path(entry.path), anchor=self.data_dir, result=result)
                continue
            if self._is_temporary_name(entry.name):
                self._stat_file(Path(entry.path), anchor=self.data_dir, result=result)
                result.degrade("temporary_artifact")
                continue
            if (
                re.fullmatch(
                    r"(conversation|project-memory)-[0-9a-f]{64}\.(fence|receipt)\.json",
                    entry.name,
                )
                is None
            ):
                result.degrade("entry_unsafe")
                continue
            parsed = self._read_json(
                Path(entry.path), anchor=self.data_dir, result=result
            )
            if (
                not isinstance(parsed, dict)
                or parsed.get("schemaVersion") != 1
                or isinstance(parsed.get("schemaVersion"), bool)
                or parsed.get("kind") not in {"conversation", "project-memory"}
                or parsed.get("status") not in {"in_progress", "completed"}
            ):
                if parsed is not None:
                    result.degrade("invalid_record")
                continue
            result.add_records()
            if parsed.get("status") == "in_progress":
                result.active_fence = True
        return result

    def _scan_fixed_files(
        self,
        paths: tuple[tuple[Path, Path, bool], ...],
    ) -> _ScanResult:
        result = _ScanResult()
        for path, anchor, parse_json in paths:
            if parse_json:
                parsed = self._read_json(path, anchor=anchor, result=result)
                if parsed is not None:
                    if isinstance(parsed, (dict, list)):
                        result.add_records()
                    else:
                        result.degrade("invalid_record")
            else:
                if self._stat_file(path, anchor=anchor, result=result):
                    result.add_records()
        return result

    def _scan_memory_pipeline_state(self) -> _ScanResult:
        from minicode.curator_schedule import (
            MAX_CURATOR_SCHEDULE_BYTES,
            validate_curator_schedule_payload,
        )

        result = self._scan_fixed_files(
            (
                (
                    self.workspace / ".mini-code-memory" / "pipeline_state.json",
                    self.workspace,
                    True,
                ),
            )
        )
        schedule_path = (
            self.workspace / ".mini-code-memory" / "curator_schedule.json"
        )
        schedule = self._read_json(
            schedule_path,
            anchor=self.workspace,
            result=result,
            max_bytes=MAX_CURATOR_SCHEDULE_BYTES,
        )
        if schedule is not None:
            try:
                validate_curator_schedule_payload(schedule)
            except Exception:
                result.degrade("invalid_record")
            else:
                result.add_records()
        return result

    def _scan_file_tree(
        self,
        root: Path,
        *,
        anchor: Path,
        allowed_depth: int,
        required_name: str | None = None,
    ) -> _ScanResult:
        result = _ScanResult()

        def visit(directory: Path, depth: int) -> None:
            for entry in self._directory_entries(
                directory, anchor=anchor, result=result
            ):
                try:
                    if entry.is_symlink():
                        result.degrade("entry_unsafe")
                        continue
                    if entry.is_dir(follow_symlinks=False):
                        if depth < allowed_depth:
                            visit(Path(entry.path), depth + 1)
                        continue
                    if not entry.is_file(follow_symlinks=False):
                        result.degrade("entry_unsafe")
                        continue
                except OSError:
                    result.degrade("read_failed")
                    continue
                if required_name is not None and entry.name != required_name:
                    continue
                if self._stat_file(Path(entry.path), anchor=anchor, result=result):
                    result.add_records()

        visit(root, 0)
        return result

    def _scan_store_map(self) -> dict[str, _ScanResult]:
        results: dict[str, _ScanResult] = {
            "sessions": self._scan_sessions(),
            "conversation-turns": self._scan_turns(),
            "run-journal": self._scan_runs(),
            "deletion-coordination": self._scan_deletion_coordination(),
        }
        for scope in ("user", "project", "local"):
            results[f"memory-{scope}"] = self._scan_memory(scope)
            results[f"memory-approval-{scope}"] = self._scan_memory_audit(scope)

        all_memory_ids = set().union(
            *(
                results[f"memory-{scope}"].identities
                for scope in ("user", "project", "local")
            )
        )
        for scope in ("user", "project", "local"):
            memory = results[f"memory-{scope}"]
            audit = results[f"memory-approval-{scope}"]
            if memory.references - all_memory_ids:
                memory.degrade("orphan_reference")
            if audit.audit_references - all_memory_ids:
                audit.degrade("orphan_reference")

        results["memory-pipeline-state"] = self._scan_memory_pipeline_state()
        results["tool-results"] = self._scan_file_tree(
            self.workspace / ".mini-code-tool-results",
            anchor=self.workspace,
            allowed_depth=0,
        )
        results["permissions"] = self._scan_fixed_files(
            ((self.data_dir / "permissions.json", self.data_dir, True),)
        )
        results["configuration"] = self._scan_fixed_files(
            (
                (self.data_dir / "settings.json", self.data_dir, True),
                (
                    self.data_dir.parent / ".claude" / "settings.json",
                    self.data_dir.parent,
                    True,
                ),
            )
        )
        results["mcp-configuration"] = self._scan_fixed_files(
            (
                (self.data_dir / "mcp.json", self.data_dir, True),
                (self.workspace / ".mcp.json", self.workspace, True),
            )
        )
        results["user-profile"] = self._scan_fixed_files(
            ((self.data_dir / "USER.md", self.data_dir, False),)
        )
        results["project-profile"] = self._scan_fixed_files(
            (
                (
                    self.workspace / ".mini-code" / "USER.md",
                    self.workspace,
                    False,
                ),
            )
        )
        user_skills = self._scan_file_tree(
            self.data_dir / "skills",
            anchor=self.data_dir,
            allowed_depth=2,
            required_name="SKILL.md",
        )
        self._merge_results(
            user_skills,
            self._scan_file_tree(
                self.data_dir.parent / ".claude" / "skills",
                anchor=self.data_dir.parent,
                allowed_depth=2,
                required_name="SKILL.md",
            ),
        )
        results["skills-user"] = user_skills
        project_skills = self._scan_file_tree(
            self.workspace / ".mini-code" / "skills",
            anchor=self.workspace,
            allowed_depth=2,
            required_name="SKILL.md",
        )
        self._merge_results(
            project_skills,
            self._scan_file_tree(
                self.workspace / ".claude" / "skills",
                anchor=self.workspace,
                allowed_depth=2,
                required_name="SKILL.md",
            ),
        )
        results["skills-project"] = project_skills
        user_artifacts = self._scan_fixed_files(
            tuple(
                (self.data_dir / name, self.data_dir, name.endswith(".json"))
                for name in (
                    "history.json",
                    "context_state.json",
                    "cybernetic_supervisor.json",
                    "minicode.log",
                    "session-store.lock",
                    "memory-store.lock",
                )
            )
        )
        for directory in ("tasks", "task_graphs", "audit"):
            nested = self._scan_file_tree(
                self.data_dir / directory,
                anchor=self.data_dir,
                allowed_depth=1,
            )
            self._merge_results(user_artifacts, nested)
        self._merge_results(
            user_artifacts,
            self._scan_file_tree(
                self.data_dir / "bin",
                anchor=self.data_dir,
                allowed_depth=1,
            ),
        )
        results["user-runtime-artifacts"] = user_artifacts
        results["workspace-runtime-artifacts"] = self._scan_fixed_files(
            (
                (
                    self.workspace / ".mini-code" / "cron.json",
                    self.workspace,
                    True,
                ),
            )
        )
        for store_id in (
            "permission-broker",
            "mcp-current-registry",
            "gateway-runtime",
            "working-memory",
        ):
            results[store_id] = _ScanResult(
                status="live",
                record_count=None,
                byte_count=None,
                updated_at=None,
            )
        return results

    @staticmethod
    def _merge_results(target: _ScanResult, source: _ScanResult) -> None:
        if target.record_count is not None and source.record_count is not None:
            target.add_records(source.record_count)
        elif source.record_count is None:
            target.record_count = None
        if target.byte_count is not None and source.byte_count is not None:
            target.add_bytes(source.byte_count)
        elif source.byte_count is None:
            target.byte_count = None
        if source.updated_at is not None and (
            target.updated_at is None or source.updated_at > target.updated_at
        ):
            target.updated_at = source.updated_at
        for diagnostic in source.diagnostics:
            target.degrade(
                diagnostic,
                unavailable=source.status == "unavailable",
            )

    def snapshot(self) -> dict[str, object]:
        self._budget = _ScanBudget(self._budget.limit)
        generated_at = _iso_time(self._clock())
        results = self._scan_store_map()
        stores: list[dict[str, object]] = []
        diagnostics: list[dict[str, str]] = []
        for spec in _STORE_SPECS:
            process_local = spec.durability == "process-local"
            result = results[spec.id]
            message = (
                _PROCESS_MESSAGE
                if process_local
                else _LIVE_MESSAGE
                if result.status == "live"
                else _UNAVAILABLE_MESSAGE
                if result.status == "unavailable"
                else _PARTIAL_MESSAGE
            )
            stores.append(
                {
                    "id": spec.id,
                    "scope": spec.scope,
                    "durability": spec.durability,
                    "status": result.status,
                    "recordCount": result.record_count,
                    "byteCount": result.byte_count,
                    "updatedAt": (
                        _iso_time(result.updated_at)
                        if result.updated_at is not None
                        else None
                    ),
                    "resetDisposition": spec.reset_disposition,
                    "message": message,
                }
            )
            for code in result.diagnostics:
                if len(diagnostics) >= MAX_DIAGNOSTICS:
                    break
                diagnostics.append(
                    {
                        "storeId": spec.id,
                        "code": code,
                        "message": _DIAGNOSTIC_MESSAGES[code],
                    }
                )
        known_record_count = sum(
            store["recordCount"] for store in stores if store["recordCount"] is not None
        )
        known_byte_count = sum(
            store["byteCount"] for store in stores if store["byteCount"] is not None
        )
        issue_count = sum(store["status"] != "live" for store in stores)
        blockers = [
            {"code": "store_not_live", "storeId": store["id"]}
            for store in stores
            if store["resetDisposition"] == "planned" and store["status"] != "live"
        ]
        deletion_result = results["deletion-coordination"]
        if deletion_result.active_fence:
            blockers.append(
                {
                    "code": "active_maintenance_fence",
                    "storeId": "deletion-coordination",
                }
            )
        payload: dict[str, object] = {
            "schemaVersion": SCHEMA_VERSION,
            "generatedAt": generated_at,
            "mode": "read-only",
            "status": (
                "live"
                if issue_count == 0
                else "unavailable"
                if all(store["status"] == "unavailable" for store in stores)
                else "partial"
            ),
            "workspace": {
                "id": _workspace_id(self.workspace),
                "name": _safe_workspace_name(self.workspace),
            },
            "summary": {
                "storeCount": len(stores),
                "knownRecordCount": min(known_record_count, MAX_SAFE_INTEGER),
                "knownByteCount": min(known_byte_count, MAX_SAFE_INTEGER),
                "issueCount": issue_count,
            },
            "stores": stores,
            "maintenancePlan": {
                "status": "planning",
                "destructiveActionsAvailable": False,
                "eligibleStoreIds": [
                    spec.id
                    for spec in _STORE_SPECS
                    if spec.reset_disposition == "planned"
                ],
                "excludedStoreIds": [
                    spec.id
                    for spec in _STORE_SPECS
                    if spec.reset_disposition == "excluded"
                ],
                "blockers": blockers,
            },
            "diagnostics": diagnostics,
        }
        return validate_persistence_health_snapshot(payload)


__all__ = [
    "MAX_DIRECTORY_ENTRIES",
    "MAX_PARSED_FILE_BYTES",
    "MAX_RESPONSE_BYTES",
    "PersistenceHealthContractError",
    "PersistenceHealthReader",
    "SCHEMA_VERSION",
    "validate_persistence_health_snapshot",
]

shared_files.minicode/subagent_supervisor.py:
"""Parent-side supervisor for subprocess-isolated ``general`` sub-agents.

The supervisor owns the hard boundary the in-process backend cannot provide:
it spawns ``minicode.subagent_worker`` as a detached process group, watches
the parent's deadline and cancellation token, and on either one kills the
whole group instead of waiting for a stuck provider call to return.

Terminal-state rule: exactly one decision wins. Once a kill is issued the
outcome is ``timed_out``/``cancelled`` and any result file the child managed
to write is deliberately ignored — a killed process must not overwrite the
terminal state with a late success.
"""
from __future__ import annotations

import json
import os
import shutil
import signal
import subprocess
import sys
import tempfile
import time
from collections.abc import Mapping, Sequence
from dataclasses import dataclass
from pathlib import Path

DEFAULT_COMMAND: tuple[str, ...] = (
    sys.executable,
    "-m",
    "minicode.subagent_worker",
)

_WORKER_STATUSES = frozenset(
    {"completed", "failed", "deadline_exceeded", "budget_exceeded", "error"}
)

# The worker bounds its own payload well below this; the cap only guards the
# parent against reading an unbounded file from a compromised or buggy child.
_MAX_RESULT_BYTES = 1_000_000
_MAX_LOG_TAIL_CHARS = 2_000


@dataclass(frozen=True, slots=True)
class SubagentProcessOutcome:
    """Single terminal state of one supervised sub-agent process."""

    status: str
    result: Mapping[str, object] | None
    error: str | None
    duration_ms: int
    pid: int | None


def _windows_creationflags() -> int:
    # CREATE_NEW_PROCESS_GROUP isolates the child's console Ctrl handlers
    # from the parent. It exists only on Windows; keep the lookup portable.
    return int(getattr(subprocess, "CREATE_NEW_PROCESS_GROUP", 0))


def _kill_process_tree(process: subprocess.Popen, *, grace_seconds: float) -> None:
    """Terminate the child group, escalate, and make a bounded reap attempt."""
    grace_seconds = max(0.0, float(grace_seconds))
    if os.name == "posix":
        # start_new_session=True made the child a process-group leader. Signal
        # the group even if its leader already exited: descendants may still be
        # holding pipes/PTYs open after the direct process has terminated.
        try:
            os.killpg(process.pid, signal.SIGTERM)
        except OSError:
            pass
        deadline = time.monotonic() + grace_seconds
        while time.monotonic() < deadline:
            try:
                os.killpg(process.pid, 0)
            except OSError:
                break
            time.sleep(min(0.02, max(0.001, deadline - time.monotonic())))
        try:
            os.killpg(process.pid, signal.SIGKILL)
        except OSError:
            pass
    else:
        # Windows has no portable killpg equivalent. CREATE_NEW_PROCESS_GROUP
        # keeps control handling isolated; terminate/kill safely reap the direct
        # child. Embedders that need recursive Windows cleanup should use a Job.
        if process.poll() is None:
            try:
                process.terminate()
            except OSError:
                pass
            try:
                process.wait(timeout=grace_seconds)
            except (OSError, subprocess.TimeoutExpired):
                if process.poll() is None:
                    try:
                        process.kill()
                    except OSError:
                        pass
    try:
        process.wait(timeout=grace_seconds + 5.0)
    except (OSError, subprocess.TimeoutExpired):  # pragma: no cover - defensive reap
        pass


def _read_result_file(result_path) -> dict[str, object] | None:
    try:
        if not result_path.is_file() or result_path.is_symlink():
            return None
        if result_path.stat().st_size > _MAX_RESULT_BYTES:
            return None
        raw = json.loads(result_path.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return None
    return raw if isinstance(raw, dict) else None


def _log_tail(log_path) -> str:
    try:
        if not log_path.is_file():
            return ""
        data = log_path.read_bytes()[-_MAX_LOG_TAIL_CHARS * 4 :]
        return data.decode("utf-8", errors="replace")[-_MAX_LOG_TAIL_CHARS:]
    except OSError:
        return ""


def _cancellation_requested(cancellation_token: object | None) -> bool:
    if cancellation_token is None:
        return False
    checker = getattr(cancellation_token, "raise_if_requested", None)
    if callable(checker):
        try:
            checker()
        except Exception:
            return True
        return False
    requested = getattr(cancellation_token, "is_requested", None)
    if callable(requested):
        try:
            return bool(requested())
        except Exception:  # noqa: BLE001 - observation never kills the child
            return False
    return False


def run_subagent_process(
    request: Mapping[str, object],
    *,
    deadline_monotonic: float | None = None,
    cancellation_token: object | None = None,
    command: Sequence[str] | None = None,
    poll_interval_seconds: float = 0.05,
    kill_grace_seconds: float = 1.0,
) -> SubagentProcessOutcome:
    """Run one sub-agent worker process and return its single terminal state.

    ``command`` replaces the default ``python -m minicode.subagent_worker``
    argv (``--request``/``--result`` paths are appended); it exists for tests
    and embedders that need a different interpreter or wrapper.
    """
    started_at = time.monotonic()
    workdir_path = Path(tempfile.mkdtemp(prefix="minicode-subagent-"))
    request_path = workdir_path / "request.json"
    result_path = workdir_path / "result.json"
    stdout_path = workdir_path / "stdout.log"
    stderr_path = workdir_path / "stderr.log"

    def finish(
        status: str,
        *,
        result: Mapping[str, object] | None = None,
        error: str | None = None,
        pid: int | None = None,
    ) -> SubagentProcessOutcome:
        return SubagentProcessOutcome(
            status=status,
            result=result,
            error=error,
            duration_ms=int((time.monotonic() - started_at) * 1000),
            pid=pid,
        )

    try:
        request_path.write_text(
            json.dumps(dict(request), ensure_ascii=False),
            encoding="utf-8",
        )
        argv = list(command or DEFAULT_COMMAND) + [
            "--request",
            str(request_path),
            "--result",
            str(result_path),
        ]
        with (
            open(stdout_path, "wb") as stdout_file,
            open(stderr_path, "wb") as stderr_file,
        ):
            try:
                process: subprocess.Popen[bytes] = subprocess.Popen(
                    argv,
                    stdin=subprocess.DEVNULL,
                    stdout=stdout_file,
                    stderr=stderr_file,
                    start_new_session=os.name == "posix",
                    creationflags=_windows_creationflags(),
                )
            except OSError as exc:
                return finish(
                    "spawn_failed",
                    error=f"{type(exc).__name__}: {exc}",
                )

            killed_for: str | None = None
            while True:
                if _cancellation_requested(cancellation_token):
                    killed_for = "cancelled"
                elif (
                    isinstance(deadline_monotonic, (int, float))
                    and time.monotonic() >= float(deadline_monotonic)
                ):
                    killed_for = "timed_out"
                if killed_for is not None:
                    _kill_process_tree(process, grace_seconds=kill_grace_seconds)
                    return finish(
                        killed_for,
                        error=(
                            "sub-agent process killed: "
                            + (
                                "parent turn cancellation requested"
                                if killed_for == "cancelled"
                                else "task deadline exceeded"
                            )
                        ),
                        pid=process.pid,
                    )
                if process.poll() is not None:
                    break
                time.sleep(poll_interval_seconds)

            # The child exited on its own; its result file is the outcome.
            result = _read_result_file(result_path)
            if result is None:
                tail = _log_tail(stderr_path).strip()
                detail = f"worker exited {process.returncode} without a result"
                if tail:
                    detail += f"; stderr tail: {tail}"
                return finish("result_missing", error=detail, pid=process.pid)
            status = result.get("status")
            if status not in _WORKER_STATUSES:
                return finish(
                    "result_invalid",
                    error=f"worker result status is invalid: {status!r}",
                    pid=process.pid,
                )
            error = result.get("error")
            return finish(
                str(status),
                result=result,
                error=error if isinstance(error, str) else None,
                pid=process.pid,
            )
    finally:
        shutil.rmtree(workdir_path, ignore_errors=True)


__all__ = [
    "DEFAULT_COMMAND",
    "SubagentProcessOutcome",
    "run_subagent_process",
]

shared_files.minicode/task_object.py:
"""Task Object - Stable task representation layer.

Deepened work chain:
  Raw Input -> Intent Parser -> Task Object -> Pipeline -> Execution -> Result
"""

from __future__ import annotations

import time
import uuid
from dataclasses import dataclass, field
from enum import Enum
from typing import Any

from minicode.intent_parser import ParsedIntent
from minicode.logging_config import get_logger

logger = get_logger("task_object")


class TaskState(str, Enum):
    DRAFT = "draft"
    PLANNED = "planned"
    RUNNING = "running"
    PAUSED = "paused"
    COMPLETED = "completed"
    FAILED = "failed"
    CANCELLED = "cancelled"


class ConstraintType(str, Enum):
    MUST_INCLUDE = "must_include"
    MUST_NOT_MODIFY = "must_not_modify"
    MAX_TOKENS = "max_tokens"
    TIMEOUT = "timeout"
    REQUIRES_REVIEW = "requires_review"
    TEST_REQUIRED = "test_required"
    BACKUP_REQUIRED = "backup_required"


@dataclass
class Constraint:
    type: ConstraintType
    target: str = ""
    value: Any = None
    reason: str = ""

    def to_dict(self) -> dict[str, Any]:
        return {"type": self.type.value, "target": self.target,
                "value": self.value, "reason": self.reason}


@dataclass
class ExpectedOutput:
    type: str = ""
    path: str = ""
    format: str = ""
    validation: str = ""
    examples: list[str] = field(default_factory=list)

    def to_dict(self) -> dict[str, Any]:
        return {"type": self.type, "path": self.path, "format": self.format,
                "validation": self.validation, "examples": self.examples}


@dataclass
class TaskObject:
    id: str = field(default_factory=lambda: str(uuid.uuid4())[:8])
    created_at: float = field(default_factory=time.time)
    updated_at: float = field(default_factory=time.time)
    raw_input: str = ""
    parsed_intent: ParsedIntent | None = None
    title: str = ""
    description: str = ""
    goal: str = ""
    relevant_files: list[str] = field(default_factory=list)
    relevant_code: list[str] = field(default_factory=list)
    context_notes: list[str] = field(default_factory=list)
    constraints: list[Constraint] = field(default_factory=list)
    expected_outputs: list[ExpectedOutput] = field(default_factory=list)
    state: TaskState = TaskState.DRAFT
    plan_id: str = ""
    result_summary: str = ""
    error_message: str = ""
    tags: list[str] = field(default_factory=list)
    priority: int = 0
    estimated_effort: str = "moderate"

    def to_dict(self) -> dict[str, Any]:
        return {
            "id": self.id, "created_at": self.created_at, "updated_at": self.updated_at,
            "raw_input": self.raw_input,
            "parsed_intent": self.parsed_intent.to_dict() if self.parsed_intent else None,
            "title": self.title, "description": self.description, "goal": self.goal,
            "relevant_files": self.relevant_files, "relevant_code": self.relevant_code,
            "context_notes": self.context_notes,
            "constraints": [c.to_dict() for c in self.constraints],
            "expected_outputs": [o.to_dict() for o in self.expected_outputs],
            "state": self.state.value, "plan_id": self.plan_id,
            "result_summary": self.result_summary, "error_message": self.error_message,
            "tags": self.tags, "priority": self.priority,
            "estimated_effort": self.estimated_effort,
        }

    def add_constraint(self, type: ConstraintType, target: str = "", value: Any = None, reason: str = "") -> None:
        self.constraints.append(Constraint(type=type, target=target, value=value, reason=reason))
        self.updated_at = time.time()

    def add_expected_output(self, type: str, path: str = "", format: str = "", validation: str = "") -> None:
        self.expected_outputs.append(ExpectedOutput(type=type, path=path, format=format, validation=validation))
        self.updated_at = time.time()

    def set_state(self, state: TaskState) -> None:
        self.state = state
        self.updated_at = time.time()

    def is_read_only(self) -> bool:
        return self.parsed_intent.is_read_only() if self.parsed_intent else False

    def requires_write(self) -> bool:
        return not self.is_read_only()


class TaskBuilder:
    def build(self, intent: ParsedIntent, raw_input: str = "") -> TaskObject:
        task = TaskObject(raw_input=raw_input or intent.raw_input, parsed_intent=intent)
        task.title = self._generate_title(intent)
        task.goal = self._generate_goal(intent)
        task.description = self._generate_description(intent)
        task.relevant_files = intent.entities.get("files", [])
        task.estimated_effort = intent.complexity_hint
        task.priority = self._calculate_priority(intent)
        task.tags = [intent.intent_type.value, intent.action_type.value] + intent.keywords[:3]
        self._add_default_constraints(task, intent)
        self._add_expected_outputs(task, intent)
        logger.debug("Built TaskObject %s: %s", task.id, task.title)
        return task

    def _generate_title(self, intent: ParsedIntent) -> str:
        return f"{intent.action_type.value} {intent.intent_type.value}: {' '.join(intent.keywords[:3])}".strip()

    def _generate_goal(self, intent: ParsedIntent) -> str:
        return intent.raw_input[:120]

    def _generate_description(self, intent: ParsedIntent) -> str:
        lines = [f"Intent: {intent.intent_type.value} / {intent.action_type.value}",
                 f"Confidence: {intent.confidence:.2f}"]
        for key in ("files", "functions", "classes"):
            if intent.entities.get(key):
                lines.append(f"{key.capitalize()}: {', '.join(intent.entities[key])}")
        return "\n".join(lines)

    def _calculate_priority(self, intent: ParsedIntent) -> int:
        base = 50
        if intent.intent_type.value in ("debug", "system"):
            base += 20
        if intent.complexity_hint == "complex":
            base += 10
        if intent.confidence < 0.5:
            base -= 10
        return max(0, min(100, base))

    def _add_default_constraints(self, task: TaskObject, intent: ParsedIntent) -> None:
        if intent.is_read_only():
            task.add_constraint(ConstraintType.MUST_NOT_MODIFY, reason="Read-only intent")
        if intent.is_code_related() and intent.action_type.value in ("create", "update"):
            task.add_constraint(ConstraintType.TEST_REQUIRED, reason="Code modification requires tests")
        if intent.action_type.value in ("delete", "update"):
            task.add_constraint(ConstraintType.BACKUP_REQUIRED, reason="Destructive action")

    def _add_expected_outputs(self, task: TaskObject, intent: ParsedIntent) -> None:
        itype, action = intent.intent_type.value, intent.action_type.value
        if itype == "code" and action == "create":
            task.add_expected_output(type="code_block", validation="Valid runnable code")
        elif itype == "debug":
            task.add_expected_output(type="explanation", validation="Identify root cause")
        elif itype == "explain":
            task.add_expected_output(type="explanation", validation="Clear and accurate")
        elif itype == "search":
            task.add_expected_output(type="file_list", validation="Relevant files with context")
        elif itype == "review":
            task.add_expected_output(type="review_comments", validation="Issues with severity")


_builder: TaskBuilder | None = None


def get_task_builder() -> TaskBuilder:
    global _builder
    if _builder is None:
        _builder = TaskBuilder()
    return _builder


def build_task(intent: ParsedIntent, raw_input: str = "") -> TaskObject:
    return get_task_builder().build(intent, raw_input)

shared_files.minicode/task_tracker.py:
"""Lightweight task tracking for multi-step agent execution.

Provides simple todo/task tracking that integrates with the agent loop
to show progress during long multi-step operations.
"""

from __future__ import annotations

import json
import time
from dataclasses import dataclass, field
from enum import Enum

from minicode.config import MINI_CODE_DIR


class TaskStatus(str, Enum):
    """Task status enum."""

    PENDING = "pending"
    IN_PROGRESS = "in_progress"
    COMPLETED = "completed"
    CANCELLED = "cancelled"
    FAILED = "failed"


@dataclass
class Task:
    """A single task item."""

    id: str
    description: str
    status: TaskStatus = TaskStatus.PENDING
    created_at: float = field(default_factory=time.time)
    updated_at: float = field(default_factory=time.time)
    completed_at: float | None = None
    error: str | None = None

    def complete(self) -> None:
        self.status = TaskStatus.COMPLETED
        self.completed_at = time.time()
        self.updated_at = time.time()

    def fail(self, error: str) -> None:
        self.status = TaskStatus.FAILED
        self.error = error
        self.updated_at = time.time()

    def cancel(self) -> None:
        self.status = TaskStatus.CANCELLED
        self.updated_at = time.time()

    def start(self) -> None:
        self.status = TaskStatus.IN_PROGRESS
        self.updated_at = time.time()


@dataclass
class TaskList:
    """A list of tasks for tracking multi-step progress."""

    title: str = ""
    tasks: list[Task] = field(default_factory=list)
    created_at: float = field(default_factory=time.time)
    updated_at: float = field(default_factory=time.time)

    @property
    def total(self) -> int:
        return len(self.tasks)

    @property
    def completed_count(self) -> int:
        return sum(1 for task in self.tasks if task.status == TaskStatus.COMPLETED)

    @property
    def pending_count(self) -> int:
        return sum(1 for task in self.tasks if task.status == TaskStatus.PENDING)

    @property
    def in_progress_count(self) -> int:
        return sum(1 for task in self.tasks if task.status == TaskStatus.IN_PROGRESS)

    @property
    def failed_count(self) -> int:
        return sum(1 for task in self.tasks if task.status == TaskStatus.FAILED)

    @property
    def progress_percentage(self) -> float:
        if self.total == 0:
            return 0.0
        return (self.completed_count / self.total) * 100

    @property
    def is_complete(self) -> bool:
        return all(
            task.status in (TaskStatus.COMPLETED, TaskStatus.CANCELLED, TaskStatus.FAILED)
            for task in self.tasks
        )

    def add_task(self, description: str) -> Task:
        task = Task(id=str(len(self.tasks) + 1), description=description)
        self.tasks.append(task)
        self.updated_at = time.time()
        return task

    def get_task(self, task_id: str) -> Task | None:
        for task in self.tasks:
            if task.id == task_id:
                return task
        return None

    def mark_completed(self, task_id: str) -> bool:
        task = self.get_task(task_id)
        if task:
            task.complete()
            self.updated_at = time.time()
            return True
        return False

    def mark_failed(self, task_id: str, error: str) -> bool:
        task = self.get_task(task_id)
        if task:
            task.fail(error)
            self.updated_at = time.time()
            return True
        return False

    def get_current_task(self) -> Task | None:
        for task in self.tasks:
            if task.status in (TaskStatus.PENDING, TaskStatus.IN_PROGRESS):
                return task
        return None

    def get_next_pending(self) -> Task | None:
        for task in self.tasks:
            if task.status == TaskStatus.PENDING:
                return task
        return None


class TaskManager:
    """Manages task lists for the current session."""

    def __init__(self):
        self.active_list: TaskList | None = None
        self.history: list[TaskList] = []

    def create_list(self, title: str) -> TaskList:
        if self.active_list:
            self.history.append(self.active_list)
        self.active_list = TaskList(title=title)
        return self.active_list

    def add_task(self, description: str) -> Task | None:
        if not self.active_list:
            self.active_list = TaskList(title="Tasks")
        return self.active_list.add_task(description)

    def complete_task(self, task_id: str) -> bool:
        if not self.active_list:
            return False
        return self.active_list.mark_completed(task_id)

    def fail_task(self, task_id: str, error: str) -> bool:
        if not self.active_list:
            return False
        return self.active_list.mark_failed(task_id, error)

    def get_status(self) -> str:
        if not self.active_list:
            return "No active tasks"

        tl = self.active_list
        status_parts = []

        if tl.title:
            status_parts.append(f"📋 {tl.title}")

        status_parts.append(f"{tl.completed_count}/{tl.total} done ({tl.progress_percentage:.0f}%)")

        if tl.in_progress_count > 0:
            current = tl.get_current_task()
            if current:
                status_parts.append(f"→ {current.description[:50]}")

        if tl.failed_count > 0:
            status_parts.append(f"⚠ {tl.failed_count} failed")

        return " | ".join(status_parts)

    def format_details(self) -> str:
        if not self.active_list:
            return "No active task list."

        tl = self.active_list
        lines = [
            f"Task List: {tl.title or 'Untitled'}",
            f"Progress: {tl.completed_count}/{tl.total} completed ({tl.progress_percentage:.0f}%)",
            "",
        ]

        for task in tl.tasks:
            status_icon = {
                TaskStatus.PENDING: "○",
                TaskStatus.IN_PROGRESS: "◐",
                TaskStatus.COMPLETED: "●",
                TaskStatus.FAILED: "✗",
                TaskStatus.CANCELLED: "⊘",
            }.get(task.status, "?")
            lines.append(f"  {status_icon} [{task.id}] {task.description}")
            if task.status == TaskStatus.FAILED and task.error:
                lines.append(f"      Error: {task.error}")

        lines.append("")
        lines.append(f"Total: {tl.total} | Done: {tl.completed_count} | Pending: {tl.pending_count}")

        if tl.failed_count > 0:
            lines.append(f"Failed: {tl.failed_count}")

        return "\n".join(lines)

    def auto_detect_tasks(self, user_input: str) -> list[str] | None:
        import re

        lines = user_input.strip().split("\n")

        numbered = []
        for line in lines:
            match = re.match(r"^\d+[\.\)]\s+(.+)", line.strip())
            if match:
                numbered.append(match.group(1))

        if len(numbered) >= 2:
            return numbered

        bullets = []
        for line in lines:
            match = re.match(r"^[-*•]\s+(.+)", line.strip())
            if match:
                bullets.append(match.group(1))

        if len(bullets) >= 2:
            return bullets

        if "," in user_input and len(lines) == 1:
            steps = [s.strip() for s in user_input.split(",") if s.strip()]
            if len(steps) >= 3:
                sequential_words = ["then", "next", "after", "finally", "last"]
                has_sequence = any(word in user_input.lower() for word in sequential_words)
                if has_sequence:
                    return steps

        return None

    def create_from_input(self, user_input: str, title: str = "") -> TaskList | None:
        tasks = self.auto_detect_tasks(user_input)
        if not tasks:
            return None

        task_list = self.create_list(title or "Auto-detected tasks")
        for task_desc in tasks:
            task_list.add_task(task_desc)
        return task_list

    def clear(self) -> None:
        if self.active_list:
            self.history.append(self.active_list)
            self.active_list = None


def format_task_update(task: Task, status: TaskStatus) -> str:
    icons = {
        TaskStatus.PENDING: "○",
        TaskStatus.IN_PROGRESS: "◐",
        TaskStatus.COMPLETED: "✓",
        TaskStatus.FAILED: "✗",
        TaskStatus.CANCELLED: "⊘",
    }
    icon = icons.get(status, "?")
    return f"{icon} Task {task.id}: {task.description}"


def should_show_task_progress(task_list: TaskList | None) -> bool:
    if not task_list:
        return False
    return not task_list.is_complete and task_list.total > 1


def format_task_progress_bar(task_list: TaskList, width: int = 30) -> str:
    if task_list.total == 0:
        return " " * width

    filled = int(width * task_list.progress_percentage / 100)
    empty = width - filled
    bar = "█" * filled + "░" * empty
    return f"[{bar}] {task_list.progress_percentage:.0f}%"


def save_task_list(task_list: TaskList, session_id: str) -> None:
    tasks_dir = MINI_CODE_DIR / "tasks"
    tasks_dir.mkdir(parents=True, exist_ok=True)

    task_file = tasks_dir / f"{session_id}.json"
    data = {
        "title": task_list.title,
        "created_at": task_list.created_at,
        "updated_at": task_list.updated_at,
        "tasks": [
            {
                "id": t.id,
                "description": t.description,
                "status": t.status.value,
                "created_at": t.created_at,
                "updated_at": t.updated_at,
                "completed_at": t.completed_at,
                "error": t.error,
            }
            for t in task_list.tasks
        ],
    }
    task_file.write_text(json.dumps(data, indent=2, ensure_ascii=False), encoding="utf-8")


def load_task_list(session_id: str) -> TaskList | None:
    task_file = MINI_CODE_DIR / "tasks" / f"{session_id}.json"
    if not task_file.exists():
        return None

    try:
        data = json.loads(task_file.read_text(encoding="utf-8"))
        task_list = TaskList(
            title=data.get("title", ""),
            created_at=data.get("created_at", time.time()),
            updated_at=data.get("updated_at", time.time()),
        )
        for task_data in data.get("tasks", []):
            task = Task(
                id=task_data["id"],
                description=task_data["description"],
                status=TaskStatus(task_data.get("status", "pending")),
                created_at=task_data.get("created_at", time.time()),
                updated_at=task_data.get("updated_at", time.time()),
                completed_at=task_data.get("completed_at"),
                error=task_data.get("error"),
            )
            task_list.tasks.append(task)
        return task_list
    except (json.JSONDecodeError, KeyError):
        return None

