"""Strict loopback HTTP adapter for Dashboard deletion authorities."""

from __future__ import annotations

import json
import math
import re
from typing import Any, Protocol
from urllib.parse import urlsplit

from minicode.conversation_deletion import (
    DELETION_REVISION_RE,
    SESSION_ID_RE,
    ConversationDeletionAuthority,
    ConversationDeletionError,
)
from minicode.memory_approval import MEMORY_ID_RE
from minicode.permission_approval import is_loopback_gateway_host
from minicode.project_memory_deletion import (
    ProjectMemoryDeletionAuthority,
    ProjectMemoryDeletionError,
)


DELETION_MAX_REQUEST_BODY_BYTES = 1_024
_CONVERSATION_PATH_RE = re.compile(r"^/api/v1/sessions/([^/]+)/deletion$")
_MEMORY_PATH_RE = re.compile(r"^/api/v1/memory/project/([^/]+)/deletion$")

_ERROR_STATUS = {
    "invalid_request": 400,
    "invalid_id": 400,
    "invalid_revision": 400,
    "deletion_target_not_found": 404,
    "deletion_revision_stale": 409,
    "deletion_target_busy": 409,
    "deletion_write_conflict": 409,
    "deletion_store_busy": 503,
    "deletion_unavailable": 503,
    "deletion_failed": 500,
}
_ERROR_MESSAGES = {
    "invalid_request": "Deletion request is invalid.",
    "invalid_id": "Deletion target ID is invalid.",
    "invalid_revision": "Deletion revision is invalid.",
    "deletion_target_not_found": "Deletion target was not found.",
    "deletion_revision_stale": "Deletion preview is stale.",
    "deletion_target_busy": "Deletion target is still active.",
    "deletion_write_conflict": "Deletion target changed during deletion.",
    "deletion_store_busy": "Deletion store is temporarily busy.",
    "deletion_unavailable": "Deletion is temporarily unavailable.",
    "deletion_failed": "Deletion failed.",
}


class _DeletionHandler(Protocol):
    path: str
    headers: Any
    rfile: Any
    server: Any

    def _send_json(self, payload: dict[str, Any], status: int = 200) -> None: ...
    def _dashboard_read_model(self) -> Any: ...


class _InvalidRequest(ValueError):
    pass


def _strict_object(pairs: list[tuple[str, object]]) -> dict[str, object]:
    result: dict[str, object] = {}
    for key, value in pairs:
        if key in result:
            raise _InvalidRequest("duplicate JSON field")
        result[key] = value
    return result


def _send_error(handler: _DeletionHandler, code: str) -> None:
    safe_code = code if code in _ERROR_STATUS else "deletion_failed"
    handler._send_json(
        {
            "ok": False,
            "error": {
                "code": safe_code,
                "message": _ERROR_MESSAGES[safe_code],
            },
        },
        status=_ERROR_STATUS[safe_code],
    )


def _accepts_json(handler: _DeletionHandler) -> None:
    values = handler.headers.get_all("Accept", [])
    if not values:
        return
    if len(values) != 1 or len(values[0]) > 1_024:
        raise _InvalidRequest("invalid Accept")
    accepted = False
    for item in values[0].split(","):
        parts = [part.strip().casefold() for part in item.split(";")]
        media_type = parts[0]
        quality = 1.0
        quality_seen = False
        if not media_type:
            raise _InvalidRequest("invalid Accept")
        for parameter in parts[1:]:
            if not parameter.startswith("q=") or quality_seen:
                raise _InvalidRequest("invalid Accept")
            quality_seen = True
            try:
                quality = float(parameter.removeprefix("q="))
            except ValueError as error:
                raise _InvalidRequest("invalid Accept") from error
            if not math.isfinite(quality) or not 0 <= quality <= 1:
                raise _InvalidRequest("invalid Accept")
        if media_type in {"application/json", "*/*"} and quality > 0:
            accepted = True
    if not accepted:
        raise _InvalidRequest("JSON is not accepted")


def _content_length(handler: _DeletionHandler) -> int:
    values = handler.headers.get_all("Content-Length", [])
    if len(values) != 1 or re.fullmatch(r"[0-9]+", values[0] or "") is None:
        raise _InvalidRequest("invalid content length")
    length = int(values[0])
    if length <= 0 or length > DELETION_MAX_REQUEST_BODY_BYTES:
        raise _InvalidRequest("invalid content length")
    return length


def _content_type(handler: _DeletionHandler) -> None:
    values = handler.headers.get_all("Content-Type", [])
    if len(values) != 1 or handler.headers.get_content_type() != "application/json":
        raise _InvalidRequest("invalid content type")
    charset = handler.headers.get_content_charset()
    if charset is not None and charset.lower().replace("_", "-") != "utf-8":
        raise _InvalidRequest("invalid charset")
    params = handler.headers.get_params(header="Content-Type") or []
    if any(key.casefold() != "charset" for key, _ in params[1:]):
        raise _InvalidRequest("invalid content type parameter")


def _origin(handler: _DeletionHandler) -> None:
    values = handler.headers.get_all("Origin", [])
    if not values:
        return
    hosts = handler.headers.get_all("Host", [])
    if len(values) != 1 or len(values[0]) > 512 or len(hosts) != 1:
        raise _InvalidRequest("invalid origin")
    origin = urlsplit(values[0])
    host = urlsplit("//" + hosts[0])
    try:
        origin_port = origin.port
        host_port = host.port
    except ValueError as error:
        raise _InvalidRequest("invalid origin") from error
    if (
        origin.scheme != "http"
        or origin.username is not None
        or origin.password is not None
        or origin.path not in {"", "/"}
        or origin.query
        or origin.fragment
        or not isinstance(origin.hostname, str)
        or not isinstance(host.hostname, str)
        or origin.hostname.casefold() != host.hostname.casefold()
        or origin_port != host_port
        or not is_loopback_gateway_host(origin.hostname)
    ):
        raise _InvalidRequest("cross-origin request")


def _route(path: str) -> tuple[str, str]:
    conversation = _CONVERSATION_PATH_RE.fullmatch(path)
    if conversation is not None:
        target = conversation.group(1)
        if SESSION_ID_RE.fullmatch(target) is None:
            raise ConversationDeletionError("invalid_id")
        return "conversation", target
    memory = _MEMORY_PATH_RE.fullmatch(path)
    if memory is not None:
        target = memory.group(1)
        if MEMORY_ID_RE.fullmatch(target) is None:
            raise ProjectMemoryDeletionError("invalid_id")
        return "project-memory", target
    raise _InvalidRequest("invalid deletion path")


def _loopback(handler: _DeletionHandler) -> None:
    address = getattr(handler.server, "server_address", ("", 0))
    host = address[0] if isinstance(address, tuple) and address else ""
    if not isinstance(host, str) or not is_loopback_gateway_host(host):
        raise ProjectMemoryDeletionError("deletion_unavailable")


def _authority(handler: _DeletionHandler, kind: str) -> Any:
    _loopback(handler)
    read_model = handler._dashboard_read_model()
    if kind == "conversation":
        authority = getattr(handler.server, "conversation_deletion_authority", None)
        if authority is None:
            authority = ConversationDeletionAuthority(
                read_model.workspace,
                data_dir=read_model.data_dir,
            )
            setattr(handler.server, "conversation_deletion_authority", authority)
        return authority
    authority = getattr(handler.server, "project_memory_deletion_authority", None)
    if authority is None:
        authority = ProjectMemoryDeletionAuthority(
            read_model.workspace,
            data_dir=read_model.data_dir,
        )
        setattr(handler.server, "project_memory_deletion_authority", authority)
    return authority


def serve_deletion_preview(handler: _DeletionHandler, path: str) -> None:
    try:
        if "?" in handler.path:
            raise _InvalidRequest("query is not allowed")
        _accepts_json(handler)
        kind, target = _route(path)
        handler._send_json(_authority(handler, kind).snapshot(target))
    except _InvalidRequest:
        _send_error(handler, "invalid_request")
    except (ConversationDeletionError, ProjectMemoryDeletionError) as error:
        _send_error(handler, error.code)
    except BaseException:  # noqa: BLE001 - never expose authority internals
        _send_error(handler, "deletion_failed")


def serve_deletion_request(handler: _DeletionHandler, path: str) -> None:
    try:
        if "?" in handler.path:
            raise _InvalidRequest("query is not allowed")
        if any(
            handler.headers.get_all(name, [])
            for name in (
                "X-HTTP-Method-Override",
                "X-Method-Override",
                "X-HTTP-Method",
            )
        ):
            raise _InvalidRequest("method override is not allowed")
        _accepts_json(handler)
        _content_type(handler)
        _origin(handler)
        kind, target = _route(path)
        raw = handler.rfile.read(_content_length(handler))
        data = json.loads(
            raw.decode("utf-8", errors="strict"), object_pairs_hook=_strict_object
        )
        if not isinstance(data, dict) or set(data) != {"deletionRevision"}:
            raise _InvalidRequest("invalid fields")
        revision = data.get("deletionRevision")
        if not isinstance(revision, str) or DELETION_REVISION_RE.fullmatch(revision) is None:
            raise ConversationDeletionError("invalid_revision")
        handler._send_json(_authority(handler, kind).delete(target, revision))
    except (UnicodeDecodeError, json.JSONDecodeError, _InvalidRequest):
        _send_error(handler, "invalid_request")
    except (ConversationDeletionError, ProjectMemoryDeletionError) as error:
        _send_error(handler, error.code)
    except BaseException:  # noqa: BLE001 - never expose authority internals
        _send_error(handler, "deletion_failed")


def is_deletion_path(path: str) -> bool:
    return bool(
        _CONVERSATION_PATH_RE.fullmatch(path)
        or _MEMORY_PATH_RE.fullmatch(path)
        or (
            path.startswith("/api/v1/sessions/") and path.endswith("/deletion")
        )
        or (
            path.startswith("/api/v1/memory/project/")
            and path.endswith("/deletion")
        )
    )


__all__ = [
    "DELETION_MAX_REQUEST_BODY_BYTES",
    "is_deletion_path",
    "serve_deletion_preview",
    "serve_deletion_request",
]

shared_files.minicode/web/event_stream.py:
"""Bounded process-local SSE invalidation transport for the Dashboard.

The stream samples one existing :class:`DashboardChangeFeed` and publishes only
opaque resource invalidations.  Persisted Dashboard data remains authoritative
and is never copied into this transport.
"""

from __future__ import annotations

import json
import re
import threading
import uuid
from collections import deque
from collections.abc import Callable, Mapping
from dataclasses import dataclass
from datetime import datetime, timezone
from typing import Any

from minicode.web.change_feed import DashboardChangeFeed


RESOURCE_NAMES = (
    "runs",
    "sessions",
    "turns",
    "memory",
    "skills",
    "connections",
    "permissions",
)
RESOURCE_STATUSES = frozenset({"live", "partial", "unavailable", "error"})
HEARTBEAT_FRAME = b": heartbeat\n\n"
_REVISION_RE = re.compile(r"rev_[0-9a-f]{64}")
_EVENT_ID_RE = re.compile(r"evt_([0-9a-f]{32})_([0-9a-f]{16})")
_MAX_EVENT_ID_CHARS = 64
_MAX_EVENT_BYTES = 4 * 1024


def _utc_now() -> datetime:
    return datetime.now(timezone.utc)


def _iso_time(value: datetime) -> str:
    if not isinstance(value, datetime) or value.tzinfo is None:
        raise ValueError("clock must return an aware datetime")
    return value.astimezone(timezone.utc).isoformat(timespec="milliseconds").replace(
        "+00:00", "Z"
    )


@dataclass(frozen=True, slots=True)
class _StoredEvent:
    sequence: int
    frame: bytes


class InvalidEventCursor(ValueError):
    """Raised before subscription when Last-Event-ID is syntactically invalid."""


class EventStreamBusy(RuntimeError):
    """Raised before subscription when the bounded client budget is full."""


class DashboardEventSubscription:
    """A bounded cursor over one shared Dashboard event ring."""

    def __init__(
        self,
        stream: DashboardEventStream,
        *,
        cursor: int,
        initial_frames: tuple[bytes, ...],
    ) -> None:
        self._stream = stream
        self._cursor = cursor
        self._initial_frames = deque(initial_frames)
        self._closed = False

    def next_batch(
        self,
        *,
        timeout: float | None = None,
        limit: int = 32,
    ) -> tuple[bytes, ...]:
        """Return replay/live frames or one content-free heartbeat comment."""
        if isinstance(limit, bool) or not isinstance(limit, int) or not 1 <= limit <= 64:
            raise ValueError("batch limit must be between 1 and 64")
        if timeout is not None and (
            isinstance(timeout, bool)
            or not isinstance(timeout, (int, float))
            or timeout < 0
        ):
            raise ValueError("timeout must be a non-negative number")
        return self._stream._next_batch(self, timeout=timeout, limit=limit)

    def close(self) -> None:
        """Release this subscription. Repeated close calls are harmless."""
        self._stream._close_subscription(self)


class DashboardEventStream:
    """Own one sampler, one bounded event ring, and all SSE subscriptions."""

    def __init__(
        self,
        change_feed: DashboardChangeFeed,
        *,
        clock: Callable[[], datetime] = _utc_now,
        ring_size: int = 256,
        max_subscribers: int = 8,
        heartbeat_seconds: float = 15.0,
        sampler_wait: Callable[[threading.Event, float], bool] | None = None,
    ) -> None:
        if isinstance(ring_size, bool) or not isinstance(ring_size, int):
            raise ValueError("ring_size must be an integer")
        if not 1 <= ring_size <= 1_024:
            raise ValueError("ring_size must be between 1 and 1024")
        if isinstance(max_subscribers, bool) or not isinstance(max_subscribers, int):
            raise ValueError("max_subscribers must be an integer")
        if not 1 <= max_subscribers <= 64:
            raise ValueError("max_subscribers must be between 1 and 64")
        if isinstance(heartbeat_seconds, bool) or not isinstance(
            heartbeat_seconds, (int, float)
        ):
            raise ValueError("heartbeat_seconds must be a number")
        if not 0.1 <= float(heartbeat_seconds) <= 60.0:
            raise ValueError("heartbeat_seconds must be between 0.1 and 60")

        self._change_feed = change_feed
        self._clock = clock
        self._ring: deque[_StoredEvent] = deque(maxlen=ring_size)
        self._max_subscribers = max_subscribers
        self._heartbeat_seconds = float(heartbeat_seconds)
        self._sampler_wait = sampler_wait or (
            lambda stop, seconds: stop.wait(seconds)
        )
        self._epoch = uuid.uuid4().hex
        self._stream_id = f"stream_{self._epoch}"
        self._sequence = 0
        self._baseline: dict[str, tuple[str, str]] | None = None
        self._condition = threading.Condition(threading.RLock())
        self._stop = threading.Event()
        self._first_sample_done = threading.Event()
        self._sampler: threading.Thread | None = None
        self._started = False
        self._closed = False
        self._subscriptions: set[DashboardEventSubscription] = set()

    def start(self) -> None:
        """Start the sole sampler thread exactly once."""
        with self._condition:
            if self._closed:
                return
            if not self._started:
                self._started = True
                sampler = threading.Thread(
                    target=self._sample_loop,
                    name="minicode-dashboard-event-sampler",
                    daemon=True,
                )
                self._sampler = sampler
                sampler.start()
        self._first_sample_done.wait(timeout=5)

    def subscribe(
        self, last_event_id: str | None = None
    ) -> DashboardEventSubscription:
        """Open one bounded subscriber at the current stream position."""
        with self._condition:
            if self._closed:
                raise RuntimeError("event stream is closed")
            if len(self._subscriptions) >= self._max_subscribers:
                raise EventStreamBusy("event stream subscriber limit reached")
            if last_event_id is None:
                cursor = self._sequence
                initial_frames = (self._ready_frame(cursor),)
            else:
                epoch, cursor = self._parse_cursor(last_event_id)
                if epoch != self._epoch:
                    cursor = self._sequence
                    initial_frames = (self._reset_frame("stream_restarted"),)
                elif cursor > self._sequence or self._cursor_is_too_old(cursor):
                    cursor = self._sequence
                    initial_frames = (self._reset_frame("replay_unavailable"),)
                else:
                    initial_frames = ()
            subscription = DashboardEventSubscription(
                self,
                cursor=cursor,
                initial_frames=initial_frames,
            )
            self._subscriptions.add(subscription)
            return subscription

    @staticmethod
    def _parse_cursor(value: str) -> tuple[str, int]:
        if (
            not isinstance(value, str)
            or not value
            or len(value) > _MAX_EVENT_ID_CHARS
        ):
            raise InvalidEventCursor("event cursor is invalid")
        match = _EVENT_ID_RE.fullmatch(value)
        if match is None:
            raise InvalidEventCursor("event cursor is invalid")
        return match.group(1), int(match.group(2), 16)

    def _cursor_is_too_old(self, cursor: int) -> bool:
        return bool(self._ring) and cursor < self._ring[0].sequence - 1

    def _ready_frame(self, sequence: int) -> bytes:
        return self._event_frame(
            "stream.ready",
            sequence,
            {
                "schemaVersion": 2,
                "type": "stream.ready",
                "streamId": self._stream_id,
                "generatedAt": _iso_time(self._clock()),
                "retryMs": 2_000,
            },
            retry_ms=2_000,
        )

    def _reset_frame(self, reason: str) -> bytes:
        if reason not in {"stream_restarted", "replay_unavailable"}:
            raise ValueError("invalid stream reset reason")
        return self._event_frame(
            "stream.reset",
            self._sequence,
            {
                "schemaVersion": 2,
                "type": "stream.reset",
                "generatedAt": _iso_time(self._clock()),
                "reason": reason,
                "resources": list(RESOURCE_NAMES),
            },
            retry_ms=2_000,
        )

    def close(self) -> None:
        """Stop sampling and immediately wake every waiting subscriber."""
        with self._condition:
            if self._closed:
                return
            self._closed = True
            self._stop.set()
            for subscription in self._subscriptions:
                subscription._closed = True
                subscription._initial_frames.clear()
            self._subscriptions.clear()
            self._condition.notify_all()
            sampler = self._sampler
        if sampler is not None and sampler is not threading.current_thread():
            sampler.join(timeout=5)

    def _sample_loop(self) -> None:
        while not self._stop.is_set():
            poll_seconds = 2.0
            try:
                snapshot = self._change_feed.snapshot()
                resources, poll_seconds = self._safe_snapshot(snapshot)
                with self._condition:
                    if self._closed:
                        return
                    if self._baseline is None:
                        self._baseline = resources
                    else:
                        changed = [
                            name
                            for name in RESOURCE_NAMES
                            if self._baseline[name] != resources[name]
                        ]
                        self._baseline = resources
                        if changed:
                            self._append_changed(resources, changed)
            except Exception:
                # Sampling failures are transport-local and never become event data.
                pass
            finally:
                self._first_sample_done.set()
            if self._sampler_wait(self._stop, poll_seconds):
                return

    @staticmethod
    def _safe_snapshot(
        snapshot: Mapping[str, Any],
    ) -> tuple[dict[str, tuple[str, str]], float]:
        if not isinstance(snapshot, Mapping):
            raise ValueError("invalid change snapshot")
        schema_version = snapshot.get("schemaVersion")
        if isinstance(schema_version, bool) or schema_version != 2:
            raise ValueError("invalid change schema")
        raw_resources = snapshot.get("resources")
        if (
            not isinstance(raw_resources, Mapping)
            or list(raw_resources) != list(RESOURCE_NAMES)
        ):
            raise ValueError("invalid change resources")
        resources: dict[str, tuple[str, str]] = {}
        for name in RESOURCE_NAMES:
            raw = raw_resources[name]
            if not isinstance(raw, Mapping) or set(raw) != {"status", "revision"}:
                raise ValueError("invalid change resource")
            status = raw.get("status")
            revision = raw.get("revision")
            if status not in RESOURCE_STATUSES or not isinstance(
                revision, str
            ) or not _REVISION_RE.fullmatch(revision):
                raise ValueError("invalid change resource")
            resources[name] = (status, revision)
        poll_after_ms = snapshot.get("pollAfterMs", 2_000)
        if (
            isinstance(poll_after_ms, bool)
            or not isinstance(poll_after_ms, int)
            or not 1_000 <= poll_after_ms <= 10_000
        ):
            poll_after_ms = 2_000
        return resources, poll_after_ms / 1_000

    def _append_changed(
        self,
        resources: dict[str, tuple[str, str]],
        changed: list[str],
    ) -> None:
        self._sequence += 1
        payload = {
            "schemaVersion": 2,
            "type": "resources.changed",
            "generatedAt": _iso_time(self._clock()),
            "resources": [
                {
                    "name": name,
                    "status": resources[name][0],
                    "revision": resources[name][1],
                }
                for name in changed
            ],
        }
        frame = self._event_frame("resources.changed", self._sequence, payload)
        self._ring.append(_StoredEvent(self._sequence, frame))
        self._condition.notify_all()

    def _event_frame(
        self,
        event_type: str,
        sequence: int,
        payload: Mapping[str, object],
        *,
        retry_ms: int | None = None,
    ) -> bytes:
        data = json.dumps(
            payload,
            ensure_ascii=True,
            allow_nan=False,
            separators=(",", ":"),
        )
        if "\n" in data or "\r" in data:
            raise ValueError("SSE data must be one line")
        event_id = f"evt_{self._epoch}_{sequence:016x}"
        lines = [f"id: {event_id}", f"event: {event_type}"]
        if retry_ms is not None:
            lines.append(f"retry: {retry_ms}")
        lines.extend((f"data: {data}", "", ""))
        encoded = "\n".join(lines).encode("utf-8")
        if len(encoded) > _MAX_EVENT_BYTES:
            raise ValueError("SSE event exceeds the byte limit")
        return encoded

    def _next_batch(
        self,
        subscription: DashboardEventSubscription,
        *,
        timeout: float | None,
        limit: int,
    ) -> tuple[bytes, ...]:
        with self._condition:
            if subscription._closed:
                return ()
            if subscription._initial_frames:
                return tuple(
                    subscription._initial_frames.popleft()
                    for _ in range(min(limit, len(subscription._initial_frames)))
                )
            if self._cursor_is_too_old(subscription._cursor):
                subscription._cursor = self._sequence
                return (self._reset_frame("replay_unavailable"),)

            def available() -> bool:
                return self._closed or self._cursor_is_too_old(
                    subscription._cursor
                ) or any(
                    event.sequence > subscription._cursor for event in self._ring
                )

            wait_seconds = self._heartbeat_seconds if timeout is None else timeout
            if not available() and wait_seconds > 0:
                self._condition.wait_for(available, timeout=wait_seconds)
            if self._closed or subscription._closed:
                return ()
            if self._cursor_is_too_old(subscription._cursor):
                subscription._cursor = self._sequence
                return (self._reset_frame("replay_unavailable"),)
            events = [
                event
                for event in self._ring
                if event.sequence > subscription._cursor
            ][:limit]
            if events:
                subscription._cursor = events[-1].sequence
                return tuple(event.frame for event in events)
            return (HEARTBEAT_FRAME,)

    def _close_subscription(
        self, subscription: DashboardEventSubscription
    ) -> None:
        with self._condition:
            if subscription._closed:
                return
            subscription._closed = True
            subscription._initial_frames.clear()
            self._subscriptions.discard(subscription)
            self._condition.notify_all()


__all__ = [
    "DashboardEventStream",
    "DashboardEventSubscription",
    "EventStreamBusy",
    "InvalidEventCursor",
]

